window.POEM_DB=window.POEM_DB||{};POEM_DB["ming_017"]={"n":"成鹫","dyn":"明","poems":[{"t":"过羚羊峡","f":"古风","c":["上峡上峡行不休，一夫力挽千钧舟。","船头刺篙后摇橹，长徽短纆柔如组。","牂牁乃是百谷王，端水作腹泷水肠。","兼山习坎为束峡，譬则咽喉司吐纳。","昨宵峡口闻风雷，耳长目短心先骇。","今朝峡中豁烟雾，山色水声浑不住。","此时此景堪语谁，当境不觉旁得之。","上如龙伯大人抚长剑，截取方舆作天堑。","下如任国公子垂钜竿，坐临砥柱观狂澜。","前如五丁凿破蚕丛道，金牛奔入西山草。","后如祖龙东面挥神鞭，众石俯首争相先。","左如维摩一榻一方丈，金毛狮子纷相向。","右如陁罗千手千芙蓉，三十二相填虚空。","入如有穷射天弹九日，蔀屋宵中见营室。","出如瞿昙夜半睹明星，扶桑浴日天鸡鸣。","天鸡鸣，我当去，行遍千山万山路。","顺风顺水下峡船，相逢莫问曾经处。","行路难，行路难，莫难于瞿塘之滟滪。","何如羚羊古峡彻底清，照见行人不知数。","行人照水水照人，形影奔波漫相遇。","当从旧路复归来，石出水枯山骨露。","顺流东下会有时，回首唤山与山语。"]},{"t":"寓龙池庵日显师以风雅相质赠此以广其志","f":"七言古诗","c":["读书万卷无一得，寻行数墨知何益。","丈夫耻做文字禅，怕与时人号诗伯。","不见黄梅舂米卢，胸中一字全不识。","腰间石烂骨皮穿，倩人夜半书廊壁。","祖翁田地坦坦平，儿孙莫更栽荆棘。","我在罗浮古洞来，蒲团坐老青山色。","焚尽诗书始出门，门前大道如弦直。","南行取路过龙池，龙池之水清且碧。","春风菡萏次第花，赤梢鲤鱼长八尺。","眼中明月夺鲸鲵，夜光照见池头客。","相逢知我老诗僧，舍却摩尼问沙砾。","笑倾栲栳掷还君，莫昧圆明缀衣祴。","捩转前车戒后车，少壮及时须努力。","扑破奚囊未了绿，斩断葛藤千七百。","老僧拭目池上看，雨似盘倾雷霹雳。","金鳞透网出重关，方笑蠹鱼心眼窄。"]},{"t":"送卢雁林归里","f":"七言古诗","c":["卢生手抱玲珑玉，目送飞鸿理新曲。","日暮乡心归兴催，十指沉吟写幽独。","深情远韵谁得知，曰有东林方老师。","闻所未闻见未见，此声不似平居时。","昨日君心如止水，今似行云日千里。","止水清泠有浅深，行云去住无端倪。","卢生大笑释玉琴，曰公知我真知心。","明朝孤棹乘风去，云水迢迢何处寻。"]},{"t":"蜃楼歌","f":"古风","c":["天空海阔波不兴，浴日浴月百宝生。","海滨老人双眼明，昨宵仰见营室星。","帝命海若修乾城，六丁六甲胥效灵。","骑箕传说版筑鸣，吴刚伐柯声丁丁。","扶桑若木为栋楹，龙宫珊瑚装画屏。","天孙云锦交疏棂，空中楼阁随目成。","千尺百尺通杳冥，瑶台璇室差可京。","玉堂金马意所轻，便欲埃风予上征。","排闼直入掉臂行，云霞接足飞腾腾。","俛视下界如苍蝇，终朝仆仆昏不停。","随人啄腐还吞腥，焉知大鱼化为鹏。","六月一息九万程，何时与尔徙南溟。","伫立久视中屏营，天门乍阖鸟西倾。","繁华寂寞如转睛，重楼复道归太清。","中星熠熠云英英，谛观乃是大蛤精。","鼓吻吐气成幻形，老人自歌还自听。","鼋鼍睡熟唤不醒，醒来但见桑田变沧海，高岸为谷深为陵。","迷楼绮阁今何在，铜驼荆棘分纵横。","乾城终古长如此，何须东海访蓬瀛。"]},{"t":"用韵留别庞西牟","f":"五言律诗","c":["举世尽行役，出门胥问津。","蹉跎百年内，离合暂时人。","几欲成高蹈，今来愧隐沦。","山中有茅屋，弃置勿重陈。"]},{"t":"东林折梅送周大尊归里","f":"五言律诗","c":["与子同枯槁，花时共入林。","一枝聊折赠，相视意何深。","去住本无著，繁华岂有心。","故园春信近，行矣莫沉吟。"]},{"t":"响石","f":"五言律诗","c":["偶因传语者，识得点头谁。","真宰互相答，太虚原不知。","求声出幽谷，闻籁忆南綦。","此意难为赠，潮音长与期。"]},{"t":"白云洞雨后观瀑","f":"七言律诗","c":["曾听樵僧说此奇，今游果尔弗吾欺。","百年忆眼观不足，七十二峰来悔迟。","喧寂解当同体处，身心方是得閒时。","一条白练从何去，惟有云岩静者知。"]},{"t":"募修海潮岩","f":"七言律诗","c":["祖公一片閒田地，付与灵泉自主张。","天遣五丁开半壁，谁教七日凿中央。","上方钟鼓潮音应，万里风涛海印光。","欲识普陀真面目，逢人惟劝解空囊。"]},{"t":"北山探梅，与社中诸子订买山之约","f":"七言律诗","c":["东林满林花尽开，北山之北何如哉。","故人留客不归去，许我买山方到来。","茅店板桥好乘兴，冻云老鹤休相猜。","明年此地有宾主，一日往还能几回。"]},{"t":"将入丹霞留别同学","f":"七言律诗","c":["名山说着便精神，夜束腰包晓问津。","老去尚能誇健足，从来不信有閒身。","岭梅开日匆匆别，岳雪消时处处春。","我自不留君不去，中间得失问何人。"]},{"t":"赠刘旗峰明府","f":"七言律诗","c":["多生慧业宰官身，神武抽簪著幅巾。","北而曾为强项令，西方甘作折腰人。","俸钱买鹤清还白，净食调猿躁亦驯。","抛却簿书翻贝叶，心空从此不忧贫。"]},{"t":"弹子矶 其一","f":"七言绝句","c":["薄暮轻舟过石矶，重寻金弹没苔衣。","而今大地无征战，不用阳戈反落晖。"]},{"t":"弹子矶 其三","f":"七言绝句","c":["识得山中更有山，点头顽石未曾顽。","修罗钻入蜗牛角，碧藓苍苔处处閒。"]},{"t":"寄怀李祈年","f":"五言古诗","c":["东南有旷士，道胜无欣戚。","德容发天和，中怀渊以默。","至人宰万应，与世罕城壁。","楸枰蚤得名，樗蒲晚晦迹。","安知中所存，天君运神力。","繄余契夙心，别去山川隔。","转蓬辞本根，惊禽靡宁翼。","耿耿怀古欢，悠悠事行役。","良晤日已稀，老大况相迫。","君为椟中璞，我作他山石。","寄言攻玉者，爱此连城璧。"]},{"t":"兵后还山答邻僧见讯","f":"五言古诗","c":["此身如飞蓬，出门掉两臂。","空囊贮太虚，浮云行大地。","何物紧相随，脚底烟岚气。","违山一百日，不觉秋风至。","归来见故人，笑我须眉异。","窘步涉丘园，荆棘集如猬。","饥虎伺人餐，猰犬当路吠。","忧来不能语，猛忍风前泪。","且复入我室，还坐心如醉。","残书纷满床，大半尘埃积。","夜灯鉴孤影，形影和灯睡。","隔桥磬一声，唤醒归人寐。","多谢击磬翁，微言昨相示。","却起诵来篇，眼暗不识字。"]},{"t":"答愿海师","f":"五言古诗","c":["见面不见心，同堂异胡越。","见心不见面，闭门车合辙。","心面两相看，笑倒长天月。","当年朱氏子，伟哉信人杰。","跃跃矿中金，谓与泥沙别。","一遇紫霄翁，点金作顽铁。","摩挲成慧刀，霜锷无全缺。","杀佛不杀人，取心不取法。","持此下山来，盲龟逢跛鳖。","露刃笑相迎，问我何言说。","我亦无可言，我亦无可说。","山中茅半间，床头衣百结。","出山乞食归，入山还洗钵。","此外无馀事，请君牢结舌。"]},{"t":"客夜寒雨","f":"五言古诗","c":["重阴薄微阳，万族息群动。","夜昏闭衡门，土壁周无缝。","长襟覆短床，黑蛇蟠铁瓮。","北风如橐籥，呼吸由窗空。","渐闻檐雨声，始觉山月霿。","寒生纸帐薄，雪压庭柯重。","不眠知夜长，独起歌商颂。","高天低片云，惨澹连楹栋。","我无龟手药，久立筋骨痛。","抖擞七斤衫，枵然了无用。","自笑住山人，行李无赍送。","譬彼初生驹，从不习羁鞚。","孤蓬离本根，大地原空洞。","冷煖只自知，裘葛聊随众。","经年别旧林，日暮思群从。","石田已荒芜，茅屋今谁共。","猿鹤守穷山，宁能免饥冻。","平生学道心，念此得无梦。","何时归去来，鹿门事耕种。"]},{"t":"夏日陈牧止孝廉招游南园舟中与庞若云张直咨诸子同赋","f":"五言古诗","c":["山居寡所欢，终年破茅屋。","何物撄我情，鸣禽朝出谷。","昨夜梦殊佳，晨兴理盥沃。","故人书适至，开缄再三读。","曰有南园翁，瓜蔬招近局。","高兴发无端，客来应不速。","驾言遵枉渚，微风饱船腹。","笑语忘主宾，形骸混僧俗。","十里稻花香，山川悦心目。","人境渐以遐，仙源互开阖。","野犬吠一声，豁然见松竹。","维舟就广荫，引客登崇陆。","黑壤错丹葩，文材杂散木。","曲折避榛芜，俛仰随朴樕。","乱后旧亭榭，犹存数丛菊。","下临放生池，出入饶水族。","菱芡自浮沉，海潮遂停畜。","坐来风雨过，轻寒袭巾服。","静对溪云生，细数凫鹥浴。","不觉远烟暝，山厨具蔬簌。","雕胡盈瓦盘，藜羹胜粱肉。","茗苦井泉甘，何事醽与醁。","野人有真性，大道无可欲。","灵蛇尝欲饥，偃鼠易知足。","但愿澹无营，枯肠称饘粥。","洗钵临清流，黑甜眠曲录。","与世任平怀，无门亦无毒。","提起竹篦子，何尝有背触。","多谢贤主人，兹恐游不数。","安得半把茅，溪边深结筑。","当年折脚铛，誓愿追芳躅。"]},{"t":"曹主庙","f":"五言古诗","c":["水宿多凄风，吹碎寒江月。","月落石鼓鸣，方舟催晓发。","遥遥见峡山，不与中宿别。","一水汇百川，两峰峙双阙。","古庙俯清流，万象森罗列。","维舟入庙门，再拜读古碣。","知有汉曹娥，千秋仰遗烈。","至孝格波神，浩气昭穷发。","庙食及炎方，尸祝遍南粤。","我闻神所钦，至诚斯对越。","黍稷匪馨香，惟德乃明洁。","嗟哉彼都人，鸡豚殊灭裂。","未拜先运刀，杀牲取腥血。","洒作玉阶尘，几筵肆污蔑。","神心实好生，顾此非所悦。","胡尔默无言，茹吐两不决。","三叹独登舟，聊为知者说。"]},{"t":"呈泽萌和尚","f":"五言古诗","c":["大道日陵夷，真风自虚妄。","城市足嚣尘，山林见高尚。","翘首丹霞巅，仙凡隔天壤。","巍巍大法王，所居得无上。","云树隐楼台，祗园集龙象。","众水尽朝宗，万山互回向。","三尺龟毛拂，一枝兔角杖。","埽荡野狐踪，打破犹疑网。","孤峰啸一声，空谷传清响。","侧耳闻法音，遐心驰梦想。","昨从南海来，入山呈伎俩。","多谢火炉边，清言发深广。","大冶铸干邪，顽金先出矿。","白社许从容，青山任来往。","假我竹边楼，解我尘劳鞅。","腊尽又新年，春光正骀宕。","山中岁月长，杲日当空朗。","披衣礼法筵，一拜一瞻仰。","百年老赵州，千岁今宝掌。","愿得镇追随，主宾更无两。","迟我三十年，白首重相访。"]},{"t":"题智严师蟛蟹图","f":"五言古诗","c":["严公写蟛蟹，能事颇自得。","着意不着意，用墨不用墨。","游心入细微，落笔无痕迹。","去岁下匡庐，今年返韶石。","市朝知姓名，远近纷求索。","挥手入丹霞，相逢同作客。","问客何所长，问客何所癖。","客亦无所长，客亦无所癖。","自言写蟛蟹，变化不可测。","留心三十年，精思废寝食。","直到手忘手，方能格出格。","我闻严公言，将信将疑惑。","涤我狼尾毫，拂我鹅溪帛。","严公无留难，严公无吝惜。","为我作车螯，点缀枯芦荻。","须臾爪甲生，横行无顺逆。","海底黑波斯，跃跃上墙壁。","严公洵好道，悟取空中色。","胎卵与湿化，钜细宁拣择。","何妨写大鱼，化作垂云翼。"]},{"t":"送陈讱庵还长沙","f":"五言古诗","c":["宽行毛孔中，猛然发长笑。","土旷人亦稀，知音一何少。","客从长沙来，此意独了了。","结发读楞严，师心穷要妙。","相逢选佛场，心大志不小。","自恨出家迟，苦被红尘扰。","期我五年来，寻师入丹峤。","行矣勿复云，前期尚绵邈。","一息不相知，五年非所晓。","客去掩荆扉，空林见归鸟。"]},{"t":"有鸟行","f":"五言古诗","c":["有鸟东南来，飞上祗树枝。","不辞道路艰，但恐人我嗤。","好音骇众听，倦翼阻高飞。","故垒遥山川，千里去如遗。","独立天地间，形影相追随。","群鸦噪前林，俯仰心酸悲。","穷途计已拙，日暮将焉之。","朝来下乔木，入谷聊栖迟。","众鸟争相笑，所托一何卑。","长歌谢众鸟，自比山梁雌。","卑栖非得已，乔木诚孤危。","高巢易倾覆，远条防险巇。","虞罗咫尺閒，矰缴为谁施。","翻云覆作雨，变态时复为。","达人贵勇退，智士恒见几。","飘然云水身，去住无羁縻。","乔木不可攀，幽谷吾当归。","请言谷中乐，所乐非等夷。","谷深无炎凉，谷静无是非。","谷云共来往，谷树接差池。","谷响互相答，谷风长自吹。","渴饮谷中水，饥食谷中薇。","愿作谷中游，永与乔木辞。","无人知此意，长忆鸟窠师。"]},{"t":"送吴宗猷从伯氏芥舟之阮江受学","f":"五言古诗","c":["之子初生时，予发如髹漆。","之子入学年，予发数茎白。","去岁子能文，予发白拣黑。","今年子远游，予发无拣择。","子如哉生明，我如旁死魄。","盈虚会有期，日月不相息。","少壮贵及时，老大良可惜。","之子何所之，湖南岭之北。","之子何所为，去家亲讲席。","昨暮理琴书，今朝事行役。","再拜别二人，依恋两难释。","受命行出门，一日三记忆。","阿爷命阿儿，寸阴如尺璧。","阿母命阿儿，努力加餐食。","耿耿方寸中，悠悠行路客。","路逢白发僧，记得曾相识。","长歌送远人，怅然念今昔。","壮哉大鹏雏，高举奋六翮。","云垂鹏背轻，天高鹏路直。","行矣莫淹留，帝乡在咫尺。","当从阮江翁，并驾朝天舄。"]},{"t":"送毛希瞻广文","f":"五言古诗","c":["我爱毛安阳，高节难为匹。","一命足承欢，欣然捧郡檄。","怀古钦芳踪，千秋谁继述。","翘首铁城隅，星峰何崒嵂。","川岳毓精英，佳气殊葱郁。","爰有丹徒公，清风振群物。","彭泽赋归田，东林问遗逸。","乘兴枉篮舆，高论投胶漆。","羡君伟男儿，相随过蓬荜。","格外恕疏慵，许结王生袜。","駊騀千里驹，空群遽超忽。","驾言骋八荒，风驰还电拂。","结发对大廷，韬光丰劲翮。","昨日尚趋庭，今朝衔命出。","筮仕得儒官，亦复为亲屈。","琴书事远游，雄才居散秩。","过我旧林泉，话别还促膝。","笑指鳄湖东，扁舟去何疾。","遥遥秦岭云，望望韩江日。","云日映青毡，春风生彩笔。","到处便留题，奚囊未萧瑟。","茶山春正深，登堂讲儒术。","士习振颓纲，青衿知表率。","桃李渐成蹊，问奇争入室。","舞雩随咏归，童冠非一一。","先生胜事多，遐想聊髣髴。","倘念山中人，报我毋遗失。"]},{"t":"寄匡庐净成泽萌和尚","f":"五言古诗","c":["中岁思远游，遐心在参诣。","垂老迟出门，致远常恐泥。","翘首匡君庐，高深薄云际。","客从山中来，为我说幽邃。","曰有古栖贤，珠林盛丛桂。","玉渊澄素波，金井涵芳砌。","三峡泻奔雷，大声警聋蔽。","上接紫霄峰，下瞰湖天势。","净成人境幽，松竹环苍翠。","师王去不归，天龙森拥卫。","堂构仰象贤，箕裘须善继。","我公道眼高，頫仰无一切。","十载主丹霞，心力穷微细。","苦节挽颓纲，清操起流弊。","古道不可今，浩然拂衣袂。","大笑行出门，孤风振南裔。","华亭归兴赊，江波共摇曳。","取道入匡云，故山寻夙契。","旧业未荒芜，埙篪事耕蓺。","我本住山人，出家须出世。","生平云水心，欲往还濡滞。","去冬觐法筵，名山度残岁。","春风返旧林，百忧集如猬。","暂别去还来，法堂己虚位。","绕径菊花黄，抚景商飙厉。","怀人秋正深，望远庭阴翳。","大地鲜知音，登堂想真谛。","顽哉跃冶金，寻思旧炉韛。","愿得半把茅，老来成活计。","上与紫霄邻，近接栖贤寺。","长从郢匠游，运斤时斲鼻。","大道无异同，焉知洞与济。","寄声高卧人，容我榻边睡。","起来看远空，千峰互阴霁。","山色与溪声，句句无生偈。","明年买草鞋，春江鼓兰枻。","寻师入宝山，化城非久憩。"]},{"t":"拟补兰亭诗缺 其一","f":"五言律诗","c":["韨除属上巳，嘉会时未央。","列坐遵枉渚，俯流唼飞觞。","微酣发清啸，天籁无短长。","真宰契溟涬，陈迹归荒唐。"]},{"t":"拟补兰亭诗缺 其二","f":"五言律诗","c":["应龙行天衢，游鱼乐濠梁。","钜细各有适，高深非所量。","达人垂大观，万殊归一觞。","一觞复能几，激水流汤汤。"]},{"t":"师子颂贺新住持","f":"五言古诗","c":["大哉大法王，出为众生父。","大哉大师王，生为百兽主。","法王师子王，不隔毛头许。","谛观法王法，请听师子语。","师子初生时，周行方七步。","师子学语时，嚬呻振威怒。","师子转身时，返掷还超距。","师子独行时，彳亍无伴侣。","师子出山时，鬼神默诃护。","狮子奋迅时，波旬生恐怖。","师子踞座时，龙象如环堵。","师子蹴踏时，野干神气沮。","有耳闻未闻，有目睹未睹。","咸聆师子吼，快观师子舞。","师子舞若何，神力庄严具。","一舞入法界，再舞净法土。","三舞转法轮，四舞酬法乳。","五舞吹法螺，六舞击法鼓。","七舞布法云，八舞施法雨。","九舞转法灯，十舞弘法绪。","师子慧命长，师子法身固。","宝山大好山，午天正亭午。","徽猷振古今，威光耀寰宇。","师子复师子，记莂生补处。","千秋巩化城，天龙领八部。","万古演法音，频伽及鹦鹉。","顽牛老更顽，头角无所取。","长歌寄法筵，灯笼触露柱。","应作如是观，应作如是举。","要识师子真，须明向上句。"]},{"t":"泊王借冈候潮望旧隐马山寄怀李远霞先与远霞有约同游中宿","f":"五言古诗","c":["寒潮不久盈，水落山月吐。","停舟宿浅沙，隔岸人争渡。","渡头老树根，记得昔游处。","遥遥云水心，忽与故山遇。","山光如旧时，山人非久住。","一别四五年，重来不识路。","莫怪还山迟，新人不如故。","鸡犬杂柴扉，蟏蛸当牖户。","手植青松根，剪伐同榛莽。","吾道有成亏，不堪更回顾。","生平聚散缘，适来还适去。","来如山上云，去似草头露。","念我意中人，少壮忽迟暮。","何以驻朱颜，神仙良足慕。","言访二禺君，相期莫相负。","明朝事远游，竟夕频延伫。"]},{"t":"诟金","f":"五言古诗","c":["二气转洪钧，万象森罗列。","真赝递成褫，权实相閒设。","凿山破混沌，披沙出糠屑。","方圆随范围，色相互形轧。","初用止儿啼，渐次及耄耋。","本拟笼蚩愚，讵意混贤哲。","管鲍称贫交，取与先灭裂。","歆宁事灌园，才品判优劣。","延陵视披裘，浅深各自别。","贤者尚不免，况乃秦与越。","大道何坦夷，多岐乃颠蹶。","四皓茹汉芝，临老遂屈节。","桐江学钓鱼，羊裘趋魏阙。","北山矢高尚，中途纳败缺。","古今多圣贤，大半遭挫跌。","周旦制礼仪，交际先玉帛。","后来田舍郎，委贽晋崇秩。","太公立圜法，作俑先利穴。","龙断贱丈夫，接踵争陵夺。","竺仙教分卫，欲化悭与伐。","像季繁有徒，攀援事饕餮。","咄哉穷巷士，守株忍饥渴。","壮志渐销磨，委心就餔歠。","嗟彼屠沽流，不少豪与杰。","受恩轻许人，身名俱泯绝。","悯兹山泽臞，空瓶刺三篾。","穷巷悲回车，侯门遵磬折。","造化施权巧，世途忘丑拙。","陷阱日以深，沦胥靡穷竭。","咨尔如粪壤，胡为等芬飶。","咨尔如砒鸩，无容资作活。","投畀东海波，波臣谢污蔑。","投畀穷发乡，八荒均一闼。","堰石障狂流，泉源未消歇。","伐木尽根株，夜气生萌蘖。","愿为火传薪，愿为汤沃雪。","雪消汤迸流，薪尽火随灭。","报语造化工，永言戒覆辙。"]},{"t":"春杪登镇海楼望雨","f":"五言古诗","c":["今日天气和，好风扇明庶。","卉木待芳菲，美人恐迟暮。","良时朋侣佳，晨兴理冠屦。","言寻粤秀巅，振衣放高步。","东北有层楼，翚飞美无度。","经始自先朝，增华别新故。","乘兴穷跻攀，遥情纵瞻顾。","下瞰尉陀城，歌钟溢衢路。","四郊方殿屎，三农渴甘澍。","遥遥山上云，兀兀原头树。","云树不相知，阴晴各欣惧。","凭高逸兴生，抚景繁忧聚。","无力挽天河，眷然独延伫。"]},{"t":"答张子白来韵","f":"五言古诗","c":["出现宰官身，不执宰官法。","我爱张神君，群嚣静言压。","皂盖林閒来，干旌江介插。","盼睐及蓬蒿，光辉生带袷。","笑我山泽臞，从来见闻狭。","痼疾在烟霞，因君痛自劄。","宇下田可耕，馀生愿编甲。"]},{"t":"答杨鬯侯用前韵","f":"五言古诗","c":["有手不拈花，有口不说法。","睡起日三竿，茅茨雪低压。","高人入我庐，奇峰倚天插。","赠我貂襜褕，报之弊单袷。","鹏奋天池宽，蛙忘井泉狭。","请从中宿游，往来互针劄。","寄语选官场，青山拟黄甲。"]},{"t":"和张子白来韵","f":"五言古诗","c":["疾行不避影，却步不逃迹。","拙哉守株佣，生计日以迫。","翻身出樊笼，虚空为宇宅。","居亭不出门，宾客日三易。","赤米无宿春，青蔬有馀摘。","丰俭各随宜，彼此不相藉。","何来鸿渐逵，高飞振六翮。","见林情与依，摩空势宁隔。","分手岁云徂，相思过除夕。","怀之金石音，药我烟霞癖。","春风江上来，旌旆遥相索。","幽兴既有加，深情更无射。","寻僧续旧游，埽雪披遗碣。","般若放光明，摩挲手不释。","始知慧业人，早注传灯籍。","游戏文字禅，无莫亦无适。","不惜如意珠，相逢当面掷。","清言重百朋，古镜阔一尺。","形影自相亲，缜密无缝隙。","愿从中宿游，已蜡东山屐。","老景逼桑榆，俛仰忽不怿。","怅然赋临岐，倾倒出肝膈。","归来补破茅，为君虚一席。","刈蓍亡蓍簪，故物良可惜。","珍重千里心，神交须破格。","君如天上云，我作他山石。","云石相依违，倏忽成今昔。","隔水候双旌，开径待三益。","林閒胜事多，无劳重叹啧。"]},{"t":"冬夜姚齐州明府陪佟司马舟过大通江干夜话赋得倚松待潮生 其一","f":"五言古诗","c":["倚松待潮生，潮生松韵冷。","野岸并维舟，僧房初出定。","五马从大夫，双凫引仙令。","蹊我污莱田，入我蓬蒿径。","枯禅懒下床，逢迎失恭敬。","布席忘主宾，当机率真性。","一笑清风生，微言动幽兴。","良晤难久淹，有怀殊未罄。","挥手别江干，悠然发高咏。"]},{"t":"冬夜姚齐州明府陪佟司马舟过大通江干夜话赋得倚松待潮生 其二","f":"五言古诗","c":["倚松待潮生，潮生月华朗。","一照珠江头，复照鹅潭上。","别驾已扬舲，郎官犹驻榜。","伫立且须臾，论心到深广。","澄江无浊流，清风自高爽。","遐哉冰檗心，超然出尘鞅。","长啸独登舟，江山答馀响。"]},{"t":"爱石为达官索去诗以送之","f":"五言古诗","c":["昔有拂袖人，遗我袖中石。","盈袖琥珀光，出袖鹅黄色。","浣手方拜嘉，肃客虚前席。","馀生久索居，介友来三益。","静贮称幽閒，谛观永无射。","尘根渐以空，面目差可识。","鬼斧斲嶙峋，蜂房攒薄蚀。","嵚岑嵌太虚，磊砢削绝壁。","月落天根净，水清云脚直。","点缀石蒲清，掩映山烟碧。","愿从生公游，顽心契禅寂。","愿上米家船，奇形慊坚癖。","不愿随女娲，补天效神力。","不愿逢五丁，凿山启蚕僰。","不愿宋人愚，燕石徒衒饰。","不愿卞生痴，怀宝自贻戚。","相期携手归，劳生谢形役。","胡然中道捐，飙风来自北。","家无担石储，门有车马客。","儿童少所见，惊趋迎棨戟。","鸡犬少所见，飞走遵蓬棘。","枯禅正下床，自蹑双蜡屐。","左手结绳枢，右手招良觌。","珍重谷城公，韬光倚檐隙。","焉知排闼人，乃是朝天客。","入门周四顾，注目中唐甓。","问客何所来，问客何所索。","客言来所来，客言索所索。","私赏顽石顽，请以金钱易。","野人不识钱，惟知畏三尺。","仓皇违古欢，缱绻不能释。","良晤难久淹，前期宁再得。","陈迹当乖分，神交讵悬隔。","君心如我心，与运随转侧。","磨涅防磷缁，永言保坚白。"]},{"t":"慰吴布田并挽逝者","f":"五言古诗","c":["昔有延陵君，嬴博葬其儿。","一恸舍之去，魂气无不之。","复有西河公，泪尽明以亏。","自言已无罪，良友来箴规。","人事有今古，天性无盛衰。","哀死良何伤，达生固其宜。","善哉布田翁，种德躬耘耔。","庭际生崇兰，弱叶何葳蕤。","一花先众芳，馥郁多奇姿。","期君永岁寒，托根深不移。","胡为比芳槿，溘然朝露晞。","造物讵怜材，天心宁倒施。","春花不朝夕，百卉徒芳菲。","主人长太息，仰首天低垂。","栽培与倾覆，将信还复疑。","东樵老樵叟，刺刍来迟迟。","薤露发长歌，招魂续楚辞。","登堂人寂寞，吊影心酸悲。","孤鸾栖穗帐，独鹤鸣书帷。","残膏冷萤火，散帙萦蛛丝。","秘彼幽兰香，入室容复为。","愿言保乔木，荣枯会有时。","玉树秀三珠，取次春风吹。","远条拂云日，嘉实堪取携。","无为长戚戚，日月交奔驰。"]},{"t":"赠关东田写墨竹","f":"五言古诗","c":["粤稽古寿亭，写竹如写字。","丹砂作水墨，撑天拄平地。","家法妙不传，后来谁述继。","爰有东田公，卓然挺苗裔。","异代俨同堂，遐心得遥契。","手敏心亦灵，胆大心仍细。","写竹不写竹，用意不用意。","鹅溪绢许长，长安纸增贵。","伸纸拂素绢，落笔事游戏。","千㡧万轴馀，顷刻盈箱笥。","风晴与月露，变化穷形势。","旁观看不及，叱吒鬼神避。","还坐自观心，心王了无事。","如是写竹人，写竹亦如是。","借问寿亭翁，是同还是异。"]},{"t":"和西宁明府李雪樵见寄留别之作","f":"五言古诗","c":["西蜀有神君，高踪葛翁亚。","骑羊绥山来，如马瞿塘泻。","冻谷见阳春，南薰解炎夏。","奉檄趋郡城，下车入田舍。","许我石门游，欲往惭衰谢。","泷邑挂冠初，中宿鸣琴罢。","旧社客来稀，真风世胥诧。","感君远寄诗，报之惟劝驾。"]},{"t":"送李明府归田用郭蓺圃韵","f":"五言古诗","c":["此心如虚舟，浮名等匏系。","东门有爰居，不受臧孙祭。","散木与散人，深山托深柢。","万事由自然，四海皆兄弟。","当局早息肩，旁观争见替。","达人知止足，俗士忘聋蔽。","园绮避汉高，巢由傲尧帝。","躬耕负郭田，努力完官税。","问俗但桑麻，安居无瘴疠。","仰见古人心，俯顺时王制。","真乐只自如，烦言岂容赘。","善哉绥山翁，解组歌丛桂。","倦鸟思旧林，春光正晴霁。","老稚相扶将，攀辕情孔泥。","慈母顾复勤，十步一为憩。","焉知长往心，故作淹留计。","我本林下人，卧雪柴门闭。","云月总同情，溪山各殊势。","长携龙尾车，相与事耕蓺。","黾勉报知音，遐心得遥契。","郭子登仙俦，长歌送兰枻。","归来过弊庐，话到阳乌逝。","出君远寄诗，吟诗当分袂。","宾雁去已遥，报书怅迢递。","我闻龙门山，昔有苏汝砺。","藏书三万卷，日久蒙尘秽。","君归好卜居，云台峙天际。","开卷豁双眸，著书发灵慧。","香国盛芳菲，空谷多兰蕙。","采之持赠谁，好风远还济。","回首野棠春，清阴成广蔽。","美人去不来，芳踪畴可继。","野老甘守株，窘步防颠蹶。","驰想到蚕丛，山川未留滞。","神交如珀针，离忧宁芥蒂。","坚彼松柏操，后凋在寒岁。"]},{"t":"答李斗山明府冬日京邸见寄来韵","f":"五言古诗","c":["一九还二九，相逢不出手。","多谢意中人，寄书方外友。","日暮无好怀，抚景惭衰朽。","卧雪忽经春，东风起杨柳。","遥遥怀古欢，澹澹如玄酒。","名心即道心，无拒亦无受。","至道予所思，荣名君自有。","大业戒速成，保之为可久。"]},{"t":"和中州李沧维见奇","f":"五言古诗","c":["日色冷松杉，潭影浸衣带。","独坐烟雨中，灵光炯不昧。","客从连山来，遗我白伞盖。","帝珠交陆离，天花纷馣馤。","白雪聋市咻，黄钟杂仙呗。","一拜一沉吟，恍惚灵山会。","大李及小李，神交在天外。","姑射冰雪肌，瑩澄绝疥癞。","精凿盈素盘，岂复羡蔬粝。","珠玉忽在前，秽形埒轻壒。","报诗随长风，细响答天籁。","趋庭有异闻，嗣音慰遥嘅。"]},{"t":"祝发呈本师","f":"古风","c":["男儿爱身及肤发，平生一毛不敢拔。","蹉跎四十一回春，参差两鬓同鸡肋。","蒙师为我操慧刀，头上不与留纤毫。","一朝四大轻鸿毛，昔日缝掖今方袍。","缝掖翁，方袍子，本来面目应相似。","镜中见影不见形，莫道昨非今乃是。","请辞大众入山去，山月松风供稳睡。","但愿慧刀时在侧，不令须眉长埽地。"]},{"t":"赠梁海民","f":"七言古诗","c":["梁生两眼炅如电，忆昔与子始相见。","登堂一语发真机，使我老儒骋雄辨。","终朝旗鼓纷相当，直至闻声不见面。","月出日入方休兵，胜负未决终不平。","迦文尼父大鼓掌，何意得有苍蝇声。","从此与君成末契，眼中始识梁居士。","高论至今如昨日，君未全非我仍是。","是非君我不相知，且道谁人先出世。","我曾出世四十春，今朝方卸头上巾。","途穷舍车觅舟楫，须眉虽假面目真。","出逢亲旧不识面，故人熟视回车轮。","临岐劝我入山去，严城闹市多嚣尘。","请君弃置勿复道，此心草草难具陈。","低头负米归乎来，眼前岂有相知人。"]},{"t":"金茅山房读书歌贻吴山带","f":"七言古诗","c":["出游五岳任两足，渴饮三湘便一腹。","名山历尽能几时，且住金茅茹山蔌。","金茅山下茅半閒，主人爱客如爱山。","澹澹流水写情性，浮云来往怡心颜。","我来怜我太无学，置书引客登高阁。","病夫耳目各为主，不见精微见糟粕。","释书三起谢古人，挥手入山种灵药。","灵药初芽合作丸，大珠小珠光错落。","持来照见古人心，不令古人空寂寞。"]},{"t":"寿黄兴岐","f":"古风","c":["先生先子之所畏，忆我为儿始七岁。","大人抱我置左膝，隔坐与君论文字。","我时仅识之与无，侧耳静听无欢呼。","上客骐驎笑相许，岂知长大成蹇驴。","蹇驴畏走三城道，踯躅秋风啮秋草。","故人相见惊相识，我渐就衰君已老。","我衰不足惜，君老头还黑。","交游半作乘车人，诸生尽是文章伯。","先生两眼大如箕，世上红尘污不得。","一日读书能几回，山中甲子去复来。","诗书之外何有哉，眼前穷达皆尘埃。","青兕爵，丹砂杯，为君寿，酌君醅。","饮此不得老，日月重皑皑。","海水浅，河水清，美人更筑黄金台。"]},{"t":"答谢邺门","f":"古风","c":["谢君于我称父执，贱子今年过四十。","昨日别君穗城下，短鬓参差冠岌岌。","今朝相见秋风里，兀突山僧拥高笠。","本来面目看未真，须臾大笑转成泣。","大笑空尔为，仲尼弟子称阇黎。","涕泣勿复道，山上蓼莪山下草。","君亲未报惭万一，仰首高天看白日。","白日天上转，浮云眼中变。","自悔平生识字多，祇能读书不读典。","一朝蹴踏虚空碎，法王与我开方便。","为报东山莫鸣鼓，山僧有心良独苦。","学道无成成亦老，此身在世知无补。"]},{"t":"夜半飓风歌","f":"古风","c":["天地巨，若何许，我生其中如秬黍。","天地窄，胡偪侧，今宵无地安床席。","大风如椎椎大屋，小风如镵镵破壁。","壁间有人抱膝坐，两眼荧荧四窗黑。","床头雨声灌双耳，床脚水深盈百甓。","生衣湿透坐到乾，眠且不能行岂得。","须臾水怪纷跳踉，拥出潮头高八尺。","居人火黑鬼火青，前有长蛇后短蜮。","长蛇俟人人岂知，短蜮吹沙去无迹。","山僧老眼不忍见，仰首高天空默默。","千家夜哭鸡犬静，满地湿云钟磬寂。","钟磬钟磬如有灵，愿教打到上方日出下方晴。"]},{"t":"天然和尚七十颂","f":"古风","c":["拙哉大挠作甲子，不识太初与无始。","却教三万六千日，忙杀山僧希作佛。","岂知贤圣中所存，一朝坐老天地根。","七十年前无此人，众人道假我道真。","七十年后称寿者，众人道真我道假。","真假两不知，请问天人师。","今夕雷峰好轮月，不异匡庐夜静时。"]},{"t":"将入山留别同学","f":"古风","c":["我所之，乃在南山之南北山之北。","山中何所有，中有一室两扉无四壁。","主人默坐万山寂，外有盘盘细路通檐隙。","我自能行人不识，上有巉岩磊砢之奇石。","覆以千年之松百年之柏，下有青泉昼夜流湱湱。","大鱼长尺半，小鱼长半尺。","山雨晴，山云辟，云来无心去无迹。","山窗虚，山月白，一晕清光如太极。","山中乐事言不悉，我纵言之竟何益。","我去作居亭，君当后来客。","后来践斯境，要妙心自领。","君毋早来，早来僧未醒。","君毋晚来，晚来山已暝。","君有行，山有径。","君自呼，山自应。","停君呼，止君听，谓声在呼还在听。","若云在呼应何闻，云在听者山自静。","却笑巢许愚，洗耳临清颍。","山风畟畟松閒来，山僧耳底无些剩。"]},{"t":"石琉璃歌贻刘于石","f":"七言古诗","c":["石乎石乎胡尔奇，精英擘破混沌皮。","砗磲玛瑙难等夷，良工剖作光琉璃。","忽如初日生海底，万象森森见元始。","忽如素月悬当空，千崖万壑无异同。","忽如玉壶贮冰雪，冷照孤心消内热。","又如碧落无纤瑕，虚空自转金轮车。","石乎石乎何从得，究竟本来茫不识。","莫将石作琉璃观，莫将灯向琉璃觅。","灯石本无无亦无，无无亦无空即色。","从君乞取入山去，大放光明照昏黑。","燃灯古佛笑眼开，就中认取刘于石。"]},{"t":"寻梅歌","f":"七言古诗","c":["野水断桥下山路，东风自来僧自去。","四望无人不知处，笑倚寒皋问枯树。","枯树欲枯枯不能，化作前溪一段冰。","相逢无语秘香色，骨格神仙心老僧。","老僧踏花如踏雪，老僧见花如见月。","此时欲辩两忘言，仰首高天搔白发。"]},{"t":"送罗颢甫讲学铁城","f":"七言古诗","c":["山僧住山冷如水，春寒夜坐无衣被。","隔窗短烛分照人，明发罗君戒行李。","问君行李能几何，重等须弥轻过纸。","世人所有君独无，两脚一肩行百里。","世人所无君尽有，九象五丁驮不起。","君昔读书书笑君，蠹鱼腹里寻糠秕。","一朝糠秕发灵芽，浑沌重生圣贤死。","死者已死生者谁，俗士得皮君得髓。","六经放下无一言，直向穷荒唱宗旨。","东西南北同此心，大道为公应尔尔。","题诗寄语彼都人，谛观今日罗夫子。"]},{"t":"送林四入楚","f":"古风","c":["先生两脚如转磨，行走日多少眠坐。","昨暮东来晓西去，路指祝融峰顶过。","祝融峰顶日高高，野客山中犹爝火。","先生大笑行出门，八尺龙驹鸣駊騀。","谩从去日计归期，看我蒲团穿几个。","旁人借问客为谁，答道今日此翁前日我。"]},{"t":"下山纪游","f":"古风","c":["咄咄怪事，山僧忽作下山计。","出门咫尺忘西东，迷津觅路逢老翁。","老翁胡卢笑掩口，两脚疾行徐举手。","指予海日初出处，便是山僧下山路。","朝从小漫来，暮宿汀溪渚。","半榻孤僧迷去住，老树作风山作雨。","暮宿汀溪渚，朝上大夫山。","身如游蚁行九盘，十步一息穷跻攀。","陟层峦，登绝顶，七尺閒身万仞影。","下方视我如蟭螟，我视下方如坐井。","下高岑，历峻坂，苍松荫天无晓晚。","樵径闻歌歌渐远，南山牧客驱牛返。","牧客驱牛牛耳湿，山僧出云云在笠。","千家烟火石桥东，青山一路沿溪入。","石桥桥边逢老叟，于我先人称畏友。","四十二年重到来，蹉跎少壮成衰丑。","相见惊相识，知我行无力。","煖汤濯足安床席，大言小言纷刺刺。","西窗语未终，东窗日已白。","梦去是归僧，醒来仍作客。","归僧作客无已时，尘埃失却真须眉。","出门岐路还路岐，旧游别作新相知。","君家兄弟多好道，今昔结交非草草。","海门风雨僧初到，野寺吟诗见怀抱。","君作主中宾，我作宾中主。","同是住山人，知我下山故。","山僧十日不归去，饥杀山中大鼷鼠。","乞取市门米，煮用市门水。","担泉负米归乎来，折脚铛边冷烟起。","饭熟谁当吃饭人，山中自谙山中味。"]},{"t":"病中示诸子","f":"古风","c":["怪矣哉，怪矣哉，一团血肉辞母胎，四大假合成百骸。","饥食渴饮量腹该，长衣短褐称体裁。","生老病死相牵推，胡然衰丑胡婴孩。","四十二年寒冷灰，曾为猛火烧灵台。","灵台火灭归山隈，山门十日九不开。","终朝运水还搬柴，放下担子眠堆堆。","日之夕矣筋力颓，旦吟暮呻声喧豗。","良朋相念争相猜，问我痛痒何处来。","病僧欲语中徘徊，诸公谛听毋深骇。","要知痛痒何处来，直须死过翻身回。","怪矣哉，怪矣哉，要知痛痒何处来，直须死过翻身回。"]},{"t":"西水歌","f":"古风","c":["生愿食西江米，不愿饮西江水。","西江米多实我腹，西江水多没我屋。","我屋住山犹是可，我屋住溪淹杀我。","大陆沉，大陆沉，秋雨淫淫秋水深。","水深过胫，浸却官田十千顷。","水深至领，舟楫交加车马静。","水深灭顶，四野无人烟火冷。","老蛙行出海，大鱼入枯井。","回头相视失声色，大笑乾坤成陷阱。","问君笑胡为尔，山僧昨暮下山来，铁船独渡空江水。","前浪拍船头，后浪拍船尾。","停桡直入水晶宫，无限鱼虾跳成市。"]},{"t":"游石碣山作","f":"古风","c":["山僧住山今老朽，逢人说山不去口。","从前所闻见则否，过眼一过为刍狗。","何如此山世希有，一幅云林好心手。","周遭方广盈十亩，土肥泉滑峰棱瘦。","中有天地外无漏，山光水光昼复昼。","两两石楼如老叟，大者兀坐小回首。","大楼之左小楼右，长松低枝与石斗。","众石伛偻若奔兽，前行麋鹿后猿狖。","聚为月窟丰其蔀，仰首窥天通石腠。","散为玉衡布星斗，横数八八纵九九。","路断不断见遗构，有声无声狮子吼。","相传古寺废已久，残碑半缺成蝌蚪。","殿角生尘佛面丑，圆镜当中无净垢。","八门顶礼还抖擞，踏破前人旧窠臼。","归来大笑别良友，此山取作逋逃薮。","君心我心无避就，终当去去去莫后。","把茅盖头瓮遮牖，坐断云根观远岫。","不信名山有神守，管取洞天归两肘。","君不见藏山于泽未为固，夜半有力负之走。","窃负而逃逃者谁，字曰迹删名曰鹫。"]},{"t":"赠谢邺门五十一诗","f":"古风","c":["坐中饮酒浮大白，听我山僧歌一拍。","欲膴仕，毋识字。","要落魄，作词客。","君不见里中黄口附青云，堂上主人生白发。","借问主人姓氏谁，昔之大谢今大儿。","生来凿破混沌窍，无端下笔能吟诗。","眼前作者少满意，与我先世称相知。","先世知君非一日，临老结交交更密。","我为儿时君作宾，名分凛凛如叔侄。","大人指君为我言，此是而翁老胶漆。","我常侧耳闻高谈，八窗四壁生烟岚。","我常披卷读佳句，恍如孤月明秋潭。","当时记忆十八九，至今脱误无二三。","始知往事那可道，少壮渐衰衰复老。","更无面目干权贵，祇有诗篇供潦倒。","我去为僧君灌园，驴背相逢休草草。","草草相逢能几回，海门春色去还来。","置将世上难成事，罄取尊前未罄杯。","主人既尽杯中物，狂子狂歌歌未毕。","我年四十二，君年五十一。","从前岁月可奈何，剩有空文归石室。","得意失意祇自知，羞与时人较名实。","弹我雍门琴，操君齐客瑟。","莫更觅知音，斲鼻今无质。","莫待浊河清，龙门流汨汨。","但愿年年月月日日饮酒时，尽如今年今月与今日。","就中认取主人翁，当尊相见无相失。"]},{"t":"庐墓歌","f":"古风","c":["君不见东邻有子早当路，老大还乡失坟墓。","君不见西邻富儿作商去，封树无情宿烟雾。","从来至性多贱贫，岂必扬名方显亲。","痴人痴绝良可叹，名利教子还教人。","一朝眼光瞥堕地，骨肉相视如越秦。","何如南山老孝子，庐墓三年不见齿。","秋霜春露感至今，眼血全枯心半死。","今年寒食复明年，瓶中无酒囊无钱。","羞以山薇酌涧水，白茅藉地为几筵。","谁家椎牛祭新鬼，山前山后罗管弦。","纷纷车马盈广陌，尘埃不见陵上柏。","攀柏孤儿泣向隅，问取姓名云不忆。","道人出世未出家，莱衣上著僧袈裟。","出门负米归不即，路逢蒿里生咨嗟。","揖君借问家何处，俯首沉吟泪如雨。","荒原客散子规啼，斜日在山风在树。","因君念我泉下人，大声问天天不语。"]},{"t":"赠罗炼师","f":"古风","c":["大人先生生何年，乃在无始之始，先天之先。","尘尘刹刹万万古，天荒地老神独全。","中间要妙言不传，我纵言之玄又玄。","宇宙广广，人处一焉。","生人林林，公处一焉。","四大假合，二气循环。","凡夫百岁如土偶，婴儿十月成金仙。","当知前日罗先生，乃无极老翁之鼻祖。","今日罗先生，乃无极老翁之儿孙。","儿孙落地持门户，自辟玄风建旗鼓。","读书只读五千言，悟后明明无一语。","柱下翁，函关吏，异世同堂应见许。","何况圣人在东鲁，在西土，亦应著眼交相觑。","先生得诀早归来，万象森森日亭午。","灵台双阙回霄壤，玄牝重门锁风雨。","未雨何龙，不风何虎，却笑顽仙守三五。","十年一握九还丹，达者视之如腐鼠。","岂知大药有真传，本来妙道无今古。","长生学就即无生，元气养成为气母。","道人本是道中人，少壮蹉跎今晚暮。","底事无成奈若何，日夕空山坐枯树。","树头老眼难见人，眼中之人道中蠹。","年来始识罗先生，一日相知两相慕。","如公方是学仙人，嗤杀秦皇与汉武。"]},{"t":"李广文苍水招游长乐留别山中诸子","f":"古风","c":["吾侪生而有志在四方，胡越秦楚同一堂。","盛年负剑去乡国，纵横八荒周五岳。","君不见席不暇煖突不黔，千秋万古称圣贤。","我生恨不逢二子，负书担囊随骥尾。","骐驎局蹐同驽骀，老死枥下真可哀。","故人知我爱游走，远札招邀来谷口。","谷口秋高瓜满园，思量穷老终闭门。","今朝名山兴无那，东行路打罗浮过。","罗浮仙人为葛洪，相逢别去何匆匆。","临岐赠我双白鹤，千里高飞到长乐。","到时九月秋正寒，主人苜蓿供盘餐。","饱食登高纵归目，回首故山见茅屋。","茅屋中间有阿谁，因风寄语遥相思。","嗟哉人生岂得长麋聚，白日西驰水东去。","去矣乎，去矣乎，天生我辈无贤愚，圣贤不学皆凡夫。","凡夫圣贤何所学，觉即不迷迷不觉。","一朝臭腐化神奇，典坟丘索成糟粕。","我今垂出门，安知行路难。","百里半九十，前路何漫漫。","但须另刮一双目，别来三日还相看。"]},{"t":"望罗浮","f":"古风","c":["我闻罗浮之山其高如高人，从来可望不可亲。","又如神仙在烟雾，招之不来麾不去。","昨日下山时，山翁送我临岐路。","嘱我登罗浮，记取朱明一抔土。","中有大蝴蝶，厥名小凤凰。","两翅如车轮，文彩不可当。","更有龙葱青琅玕，叶上有符符有光。","小虫作篆比苍颉，或直或曲或短长。","飞来五色鸟，习习成文章。","青玄赤白分四方，黄者为主居中央。","种种胜妙难具详，归来举似毋相忘。","我闻山翁语，诺诺心相许。","昨暮从西来，今朝复东去。","分明罗浮在眼前，水急山高云不驻。","山灵笑我来何迟，报语山灵毋我嗤。","铁桥明月倘相待，回舟更与葛洪期。","山翁有诺不可负，肯放罗浮空手归。"]},{"t":"过蓝关谒韩文公庙","f":"楚辞体","c":["我昔读书至原道，眼中有儒无佛老。","孔门儿孙争吐气，烈日当空长杲杲。","后来更读潮州韩庙碑，始知眉山老子不吾欺。","道济溺，文起衰，古人可作非公谁。","当年天子崇佛氏，骑马鸡栖上封事。","批龙鳞，履虎尾，等荣辱，齐生死。","自断投荒不复还，一路行吟八千里。","至人履险如履夷，眼前直道平如砥。","何有于，秦岭云，蓝关云，凄凉独洒穷途泪。","呜呼噫唏，我知之矣。","孤臣去国兮誓忘家，天路险难兮不可至。","望帝乡兮云中，范驰驱兮荒裔。","灵均九辨有同情，平子四愁应不二。","今来古庙枕寒崖，松树森阴不知岁。","秋风入松作山雨，前路行人去如水。","我问行路人，谁是公知己。","当年祇有鳄潭鱼，不畏天王畏刺史。","路人问我谁，旧是尼山门弟子。","方袍高笠胡来哉，稽颡再拜汗先泚。","我公聪明见肝胆，天人默默应相契。","过门正好留衣别，登堂不用作胡礼。"]},{"t":"除夕歌","f":"古风","c":["蜡烛一寸长，照我万古心。","人寿不得如天地，何况天地终湮沉。","今年舍我去者三百六十日，去日之日，来日之日，倏忽往还成古今。","古今今古转相迫，大地茫茫同作客。","当前错过骓莫追，西方未明东方白。","人人尽道明日是明年，忘却今年今月今日与今夕。","今夕云何，岁月无多，膏火自煎烁，金石潜销磨。","一元十二会，刹那还刹那。","刹那刹那那更得，时乎时乎胡可失。","北风吹霜疾如箭，犁星既没水生骨。","东邻沽酒守庚申，南舍焚香祠太一。","山翁不知老将至，曲枕右肱舒左膝。","天鸡啼破梦中春，一道神光生白室。","大声唤起隔年人，此时正是腊月三十日。"]},{"t":"赠惟实师","f":"七言古诗","c":["三岁小儿也道得，八十老翁行不得。","斯言勘破天下人，谩向颠毛争白黑。","惟公老矣胡为哉，眼如古佛心婴孩。","自誇筋力过少壮，一日下山能几回。","下山相问何从去，攓蓬独与骷髅语。","有时聚火煅坭牛，卓午烧泉散行路。","往还十日九带星，入门洗脚翻金经。","冷钟冷磬破墙壁，世人两耳不得听。","我闻当今大禅宿，满口狐涎水漉漉。","何如此公踏实地，慧且不修宁有福。","山僧忆昨四年前，星星短发垂两肩。","与公相见发大笑，腐儒亦复谈枯禅。","须臾天昏风雨恶，头上乌纱吹折角。","发长世短可怜生，善来比丘缘剃落。","咄哉往事勿复云，眼前有道不可闻。","看公却似山中月，我作长天一片云。","片云明月何曾隔，公在山南我山北。","但愿长从老赵州，庭前勘取孤生柏。"]},{"t":"送李苍水主教化州","f":"七言古诗","c":["广文先生清洒洒，官冷心閒身未暇。","手提木铎出蓬蒿，去年东去今西下。","重来别路两经秋，正值空林初解夏。","道旁车笠走相送，班荆旧是同游者。","忆昨齐昌一访君，半载山癯寄官舍。","春风三月送归僧，梦里昔游如昨夜。","人生离合会有时，勿惜为君重劝驾。","殷勤次第说官程，四坐相看莫相讶。","西南一路入高凉，平原道直澄川泻。","只轮车上青油伞，稳坐看山如广厦。","到时日暮宿邮亭，四野孤烟起桑柘。","诸生束带出郭迎，明发斋夫催上马。","入门高坐讲道德，二帝三王无五霸。","上农播种下农穫，莫误糠秕作良稼。","大儒出矣小儒鸣，安事诗书兴教化。","闻君早得如意珠，一颗圆明大无价。","今来卖与辨州儿，罔象离朱难假借。","山僧拭目几回看，临岐休说无生话。","祇凭寄语彼都人，罄取顽金归大冶。","当知今日李先生，也向东林曾结社。"]},{"t":"留别诸子归耕西宁作","f":"楚辞体","c":["居不愿武陵溪下宅，秦人已被渔郎识。","食不愿首阳山上薇，夷叔先我曾忍饥。","从前辙迹不足蹈，出门四顾将焉归。","太行之高，牂羊牧其巅。","洞庭之深，鱼鳖潜其渊。","石室宛委，外人不得入。","猕猴聚族，长子孙于其间。","天地之大，既方且圆，尽人授宅还授田。","岂无百亩还一廛，假我暂住终馀年。","馀年百岁能几许，一身七尺如秬黍。","冬日严寒夏蒸暑，海水多风山多雨。","尘埃逼塞坏四堵，几欲奋飞无六羽。","别君去，去何所，乃在无何有之乡，广莫之野。","上无尧君，下无巢许。","居此之处谁与处，赠君不能君自取。","君自取，来何时。","君不来，长相思。","罗山旁，泷水涯。","山有木兮屋有榱，隰有菅兮椸有衣。","顽金出矿成镃基，黄犊三岁能负犁。","耕田而食得不饥，抱瓮一日灌百畦。","瓜蔬自摘还自炊，万事具足如取携。","我之乐矣君未知，君未知，姑妄言之妄听之。"]},{"t":"屈翁山归自金陵予将入泷水赋赠","f":"古风","c":["君不见至人有身无四大，乘风稳踞溟鹏背。","下览九州如历块，朝发越裳暮燕代。","君不见至人善行不任足，驰驱直入蜗牛角。","纵横游说蛮与触，三军解甲舆脱辐。","斯人人耳无大奇，致虚守静如伏雌。","中间真宰微乎微，神出鬼没不可知。","去年尽室吴江去，江边欲与鸱夷住。","高堂有母生喜惧，自刺扁舟出烟雾。","归来重理漉酒巾，黄花彩服参差新。","炙鸡秉烛招比邻，黑貂贳过墙头春。","兴来起舞醉无力，举觞遍告座中客。","此身有母难许国，自作散儒深可惜。","深可惜，未忍闻，长歌短曲聊和君。","明朝我向泷西隐，世事悠悠勿复云。"]},{"t":"麦子滋庄门外有树经冬不凋至春脱落名曰拗春木戏题以诗","f":"古风","c":["泷西雨雪寒羁孤，静观物理知盈虚。","特来问取滋庄去，门前有树青阴敷。","凌寒独立见天倪，高高枝叶深根株。","拳挛屈曲远绳墨，匠石不顾樵不苏。","何由得此老古橛，岂是散木还大樗。","主人云是拗春木，当春落叶冬生荂。","不宜城市宜山谷，多生盘石嫌沮污。","我闻斯语深叹息，草木何智人何愚。","宇宙之大含万有，繁华零落皆虚无。","至人槁心若槁木，任运辗转同辘轳。","大尽三十小廿九，六丁六甲乘隙驹。","造物小儿太轻薄，假立名字欺凡夫。","安知彼春者不以为冬，荣者不以为枯。","春拗木乎，木拗春乎，春与木两不能相知也，其待彼也夫。"]},{"t":"送僧再参天目","f":"古风","c":["尽天上日月星辰作双目，觑不破当今诸方老耆宿。","尽大地风云雷电随两足，游不遍天下名山陵与谷。","何如瞎驴开眼见主宾，跛象横行无背触。","老师老矣胡为哉，十年两度参天目。","当时亲见作家来，教餐胡饼因中毒。","至今吞吐总无端，恰是桃花正开梅子熟。","无弦琴在忆钟期，未惜腰包重结束。","一片孤云万里风，直上高峰倚竿木。","等閒会计草?钱，六六原来三十六。","去时春载阳，归来秋已肃。","铁牛渡海吃铁鞭，金翅摩空啄金栗。","中间不隔一毫端，圜是蒲团方曲录。","我本山中人，还山有茅屋。","年年尽送渡江僧，顽石明知不是玉。","但愿独坐飞云峰顶待师回，自把一枝无孔笛吹无字曲。"]},{"t":"送吴孝廉北上","f":"古风","c":["我生不能走马黄金台，年年送客空归来。","旧游通籍十八九，天閒出厩嗤驽骀。","微言欲赠不足道，含毫伸纸胡为哉。","今朝更送吴公子，轻舟晓发南风驶。","舟中有物能自鸣，匣里双龙光照水。","斗边夜气通紫垣，天路迢遥八千里。","当今薄海方太平，纵横八极无战争。","马上吟诗向燕甸，渡江渐次凉飙生。","旂亭沽酒对三略，醒前醉后高谈兵。","此日圣人思颇牧，得士如君一已足。","临轩日策三千言，据鞍射取摩天鹄。","从来世眼重科名，何妨一第惊流俗。","野老旁观知为谁，归来聊拭山中目。"]},{"t":"送邝词辉孝廉北上","f":"七言古诗","c":["忆昨与君相见时，参差短鬓如青丝。","壮心一日三上马，酒酣肝胆逢人写。","幕府从容借箸筹，吟诗共上临江楼。","时取床头三尺铁，四手摩挲两心热。","功名自断图凌烟，满堂宾客私相怜。","须臾别来各殊世，城市山林自为计。","天南雪后花正开，神鱼拨浪随风雷。","逸足追风留不住，一朝挟策出门去。","道旁饯送多嘉宾，车盖杂踏风吹尘。","独有罗浮山上客，岐路相逢莫相识。","故人下马为班荆，前川日夕君当行。","留君坐到津头月，世事茫茫勿重说。","人生遇合会有时，我虽不语君应知。","微言欲赠难草草，得意归来为君道。"]},{"t":"白莲花歌","f":"古风","c":["君不见太华万仞之孤峰，青天削出金芙蓉。","并州剪刀太犀利，截取灵根下平地。","无端化作姑射仙，冰竞玉立何卓然。","忽如高人倚长剑，三尺霜花明澰滟。","忽如洛浦鸣佩珰，凌波袜底风吹香。","忽如属国卧冰雪，玉门归去持空节。","从来太素涅不缁，泥涂验取光离离。","蜜蜂蝴蝶太无谓，终日寻香不知味。","老夫爱花今白头，儿童拍手笑不休。","拾将花片各归去，坳堂争放采莲舟。"]},{"t":"罗母祝辞","f":"古风","c":["笙歌满室宾满堂，锦绣纂组玄以黄。","嘉肴旨酒充圆方，母寿子贵悦且康。","丰功伟烈为显扬，黄麻墨敕天语香。","斓斑朱紫纷趋跄，云礽簪笏随鹓行。","世人慕此中若狂，一拜一祝一举觞。","众口共舌如鼓簧，阿母大笑不肯当。","贱子历位陈荒唐，四座听者胥望洋。","三閒茆屋半亩桑，日暮蚕绩朝提筐。","黄齑赤米亲烹湘，青松白石岁月长。","子孙贤圣母体强，男婚女嫁乐未央。","人生得此匪寻常，请为母歌歌无疆。","愿母寿，齐三光，令子秉德如圭璋。","三公不易宁韫藏，阿母闻歌出中房。","为我饮酒浮巨觥，举手揖客听无忘，此子出言言有章。"]},{"t":"留别同学诸子","f":"古风","c":["初别君，齐昌去。","再别君，泷西住。","去年支杖入罗浮，今年渡海随烟雾。","远别四五回，暂别不知数。","人生离合能几何，何况衰年各岐路。","岐路今年忆去年，多谢长篇还短篇。","寻思留语与君别，当时道尽今茫然。","不可说，不可说，重阳九日黄花发。","西风吹转只轮轻，直到南溟见孤月。"]},{"t":"渡海歌","f":"古风","c":["天地之大夫如何，谛观沧海成叵罗。","垂云大翼驾与鹅，乘风巨舰机中梭。","蛟龙戏水蛇旋涡，江豚拜浪豕涉波。","我生七尺胡足多，聚散珠转风中荷。","今朝渡海天气和，柔风吹席行蹉跎。","天空海阔无复他，眼前有景不得歌。","沧波极目殊山河，朱明回首荒烟萝。","登高望远无斧柯，老眼一日三摩挲。","白云缥缈山嵯峨，东乌西匿虚阳戈。","终朝形役暮则那，停舟见月扬纤蛾。","古镜出匣尘未磨，微光照客寝复吪。","三更隔水闻枯螺，千家海市枕灵鼍。","晓来登岸人肩摩，风景恍惚曾经过。","天涯走杀老头陀，江边笑倒春梦婆。","呵呵呵，天涯走杀老头陀，江边笑倒春梦婆。"]},{"t":"打春牛歌三阕 其一","f":"七言古诗","c":["海南无雪耕稼宜，冬耰夏穫尝先时。","青苗遍野春未及，田家洗脚休镃基。","次第东风动芳草，农忙农閒侬自知。","今年元正好风日，有酒不饮空复为。","举杯相劝醉归去，明日立春还尔期。"]},{"t":"打春牛歌三阕 其二","f":"古风","c":["春牛白，春牛黑，朝往城南暮城北。","春牛瘠，春牛肥，昨日东郊今日西。"]},{"t":"打春牛歌三阕 其三","f":"七言古诗","c":["彩鞭三尺五色丝，众手打牛牛负犁。","方相前导蒙熊皮，长官后殿饶威仪。","玉骝蹀躞行且嘶，风轻紫陌扬旌旂。","道旁观者谁与谁，八十老翁三岁儿。","众中熟视牛焉之，隙驹野马纷交驰。","绕城三匝归乎来，慎勿近前官吏笞。"]},{"t":"石钟鼓歌","f":"古风","c":["山庵有钟复有鼓，厥声可闻不可睹。","我来欲借一回看，问取灵泉老庵主。","主人手执须弥椎，共上千峰万峰去。","分明三片顽石头，觌面相逢能解语。","噌吰铛鞳盈虚空，老树作风山作雨。","风从何起雨何来，万籁消声自终古。","钟未鸣，鼓未响，灯笼触露柱。","钟乍鸣，鼓乍响，狸奴与白牯。","钟不鸣，鼓不响，木人逢石女。","千里相逢休错举，扣石三声君自取。"]},{"t":"甲子立春日奉观音大士登海潮岩夜宿岩中谩赋一章","f":"七言古诗","c":["天空海阔岩岫迥，云开月落钟磬冷。","夜长烛短光摇摇，不见孤僧见孤影。","普陀老子丈六身，伽黎璎珞金光炳。","天龙拥出万山中，师王踞坐群峰顶。","一朝顽石争点头，万古江山辟灵境。","笑杀罗浮老古锥，铁钵分身遥赴请。","蒲团坐破草鞋穿，留与人间成话柄。","无端踏上最高峰，侧耳潮音发深省。","长伸两脚得安眠，直到红轮出东岭。","无手人挝毒鼓鸣，无耳石人心自领。","借问下方闻未闻，昨宵谁梦还谁醒。"]},{"t":"归自珠崖过铁城作行路难贻诸子","f":"古风","c":["昔我来，流火月。","今我来，小春节。","昔我来，桐花结。","今我来，梅始发。","昔我来，尚炎热。","今我来，天雨雪。","昼夜如转环，日月互明灭。","草木自荣枯，寒暑无停辙。","相逢能几时，忍作三年别。","三年一别一无成，往事蹉跎为君说。","为君说，请勿欢，听我长歌行路难。","行路之难，莫难于高凉九折之长坂，珠崖万里之狂澜。","陆乘只轮车，辗转巇且艰。","黄埃壅周道，荆棘上参天。","蚖蛇窜林莽，猛虎狙伏俟人餐。","涉潺湲，陟巑岏。","南行白月至黑月，始闻波涛汹涌于暮云远树之閒。","山穷水尽见岛屿，我欲奋飞无六羽。","舟人招手上方舟，挂帆遄发随烟雾。","大浪如雪山，小浪如钟簴。","波斯跃出水晶宫，无限鱼虾相对语。","笑我住山人，却与波臣遇。","何所闻而来，何所见而去。","天空海阔行便行，野鹤閒云住非住。","来去本无心，见闻俱不取。","快矣哉，快矣哉，三年行脚今归来。","拟返朱明洞天去，旧时茅屋荒苍苔。","林间过夏谢宾客，雪时远兴寻宗雷。","香山之山南海水，彷佛珠崖无远迩。","铁船到岸见铁城，五桂嵯峨如五指。","老僧老眼未分明，策起眉毛识乡里。","里中人，谁家子，昔年未龀今齐齿。","青青者丝，何当白发垂两耳。","一则以惧，一则以喜。","踉跄赤脚登阶戺，故人恕我大无礼。","知我远方，为我居行李。","无物可相遗，无言能举似。","行路难，聊复尔。","五岳明年事远游，重来愿行长如此。"]},{"t":"赠黄元祥中秘","f":"七言古诗","c":["高歌饮酒须盛年，四座未醉翁醄然。","请与吾翁论经济，少壮粗疏老微细。","始知识力相乘除，外边不足中有馀。","颠毛豁尽齿牙脱，胸中饶有真诗书。","诗书不是空文字，风雨晦冥皆正气。","万古端州一片云，逼塞孤臣方寸地。","五羊城边垂钓翁，曾识西方隆隼公。","穆天去后无消息，惟留八骏长嘶风。","风高大野秋光早，散诞天閒随水草。","产得龙驹腹有文，取次骞腾慰衰老。","老翁事事不如人，止有耳目闻见新。","逢场笑倒笑还起，扑折一角林宗巾。","问翁笑笑胡尔为，欲语不语人知稀。","女子不嫁嫁已毕，于陵窃鈇蹠采薇。","江河日下长如此，河水待清人寿几。","分明记得少陵诗，眼中之人吾老矣。"]},{"t":"赠陆天士","f":"七言古诗","c":["男儿读书委穷达，老大无成非所惜。","陆生岂是贫贱人，离乱他乡聊寄迹。","朝烟仰给管城君，春田耕破端溪石。","菜根细嚼牙齿香，铜片不嫌头发白。","胸中泾渭自分明，眼前岁月随抛掷。","甲子从头数至今，清风明月长为客。","孟光不厌伯鸾贫，牛衣对掩王章宅。","夜半蓬窗灯火青，万卷牙签伴刀尺。","时人要识高士家，请听书声兼纺绩。","陆生陆生如命何，听我山翁歌一拍。","皇天不负苦心人，相劝及时须努力。","盈虚消息会有时，搔首衡门看潮汐。"]},{"t":"渔人得巨鳖鬻于市赎而放之戏为此诗","f":"古风","c":["我生不乐逢伏羲，网罟既设发杀机。","潜虽伏矣身亦危，绝流竭泽靡孑遗。","鱼虾蟹蛤由取携，朝市晚市肩相挤。","中有巨物非等夷，状类覆釜圆筲箕。","缩项帖尾蒙絷维，舍身判命供烹炊。","市人过之咸朵颐，磨刀霍霍争先施。","垂手入廛僧所稀，偶来乍见心酸悲。","谛观乃是大鳖龟，脱渊失水虫蚁欺。","大似大人罹世羁，壮志消磨神力衰。","扬眉吐气今低垂，大声疾呼天不知。","丹砂可点金可挥，为君聊作续命丝。","施劳伐善吾岂为，相怜同病须同归。","世人所重毛与皮，穹窿躯壳徒支离。","五管在背喙在肌，介而不武顽且痴。","不堪钻灼通幽微，吉凶悔吝惭先几。","随波逐浪能几时，俯首听命于造物之小儿。","非不枵然大也，吾为其无用而故弃之。"]},{"t":"送李生之楚从军因寄梁腾虎","f":"古风","c":["有策不肯干诸侯，有腰不愿逢督邮。","此公只合老牖下，早年当去今当留。","头上缨雄冠，腰间悬蒯缑。","借问谁家儿，恐是汉时飞将唐药师。","同室有斗民殿屎，李生李生行莫迟。","击楫过三湘，振衣登九疑。","道遇梁腾虎，谓我遥相思。","寄言兵者是凶器，圣人不得已而后用之。"]},{"t":"题百鹿图为陈母程太君寿","f":"古风","c":["赖珽写鹿工写真，天形物态通精神。","挥毫伸纸夺造化，骈踶濈角来甡甡。","数之满百不满百，纷纷尽是旁观人。","或时见首不见尾，或藏首尾微露身。","或依林隙就水草，或呈半体全体均。","或陟岑巇或幽谷，或磨老树或溪滨。","或寝或吪类以聚，或群或友情相亲。","眉毛头角分物色，琐细胪列难具陈。","苍松翠柏不知老，参天际地蟠深根。","上有嵚崟崱屴之奇峰，下有参差历陆之文茵。","耀以百花之锦，覆以五色之云。","俗眼视之如阳燄之野马，识者宝之为什袭之家珍。","装潢索我一题赞，披图眩目光鳞鳞。","问我何所见，问我何所闻。","我实见所见，我实闻所闻。","广宁城中有佳士，元龙仲举堪等伦。","北堂寿母程氏子，渊源伊洛德日新。","著雍之腊望五日，筹添八八悬帨辰。","膝下儒冠鲁缝掖，阶前兰桂流芳芬。","麻姑献酒双成舞，金桃火枣罗缤纷。","图中百鹿侑康爵，呦呦鸣和来嘉宾。","衔芝率舞诚殷勤，画图换取丝与纶。","百福百禄蚃然臻，一拜一祝聊尔云。","山人落笔为引伸，区区窃比华封人。","愿母寿，亿千春。","眼见紫茸解角三变白，坐看青海水浅扬红尘。"]},{"t":"赠陈屏甫","f":"七言古诗","c":["为僧不能成佛祖，圆顶方袍安足数。","儒不作圣玄不仙，章缝鹤氅空徒然。","何如居士现身说，火里莲花波里月。","男儿出世不出家，身虽城市心烟霞。","长生换取无生义，一日心空看及第。","自称了事老凡夫，不缁不羽不簪裾。","三教圣人管不到，兄弟一门胥好道。","埽室时翻贝叶文，晨钟晚磬声相闻。","青蚨散取布金地，十字街头作佛事。","事佛仍推屋上乌，从师拾得衣中珠。","衣珠拾得逢人卖，誓度有情归净界。","忆我初从海上来，东林偶入知宗雷。","侍儿机子求剃度，多谢檀那为證据。","大心未了现生缘，今朝弧矢还高悬。","寿佛破颜开口笑，笑道此翁正英妙。","座客谁知古佛心，山僧欲语终沉吟。","提起数珠一百八，请君会取无生法。"]},{"t":"送关广文典教琼山","f":"古风","c":["游不必京华，仕不必台阁。","君不见仲尼欲浮海，子舆劝击柝。","男儿生不逢孔孟在邹鲁，忍使昔圣今贤终寂寞。","出身但愿作儒官，振起颓风返淳朴。","一朝筮仕初得心，不惮乘桴徇木铎。","珠崖去乡二千里，白浪如山天一角。","大鹏奋翼徙南溟，回首蓬蒿笑蜩鸴。","到时桃李花正妍，独拥皋比陈绝学。","谈经论义羞雷同，直指先天觉后觉。","图中一画见天心，纸上六经皆注脚。","申韩功利等粪壤，汉儒章句仍糟粕。","诸生侧耳闻未闻，薄海同风争拔濯。","彼都贤哲曾閒生，文采风流今似昨，如海忠介之骨骰、丘文庄之淹博。","当年文献未坠地，好与时贤兴礼乐。","刺桐开，木棉落，城南更与诸生约。","椰子浆，清可酌，槟榔花，香可嚼。","舞雩归咏春正佳，到处东风似乡国。","莫道广文贫，儒门原澹泊。","莫道广文卑，閒官无束缚。","挥手重相期，勿复怅离索。","昔年此地我曾游，海阔天空纵行乐。","别无一物贮空囊，祇有清风满归橐。","世外閒人似贵人，千里一堂同作略。","长官不比老僧贫，常禄犹堪支负郭。","探囊剩有一钱看，笑杀山中老饥鹤。"]},{"t":"送李方水典教临皋","f":"七言古诗","c":["有母倚门孙绕膝，男儿俯仰事未毕。","老兄去作宦游人，山僧又是参方日。","曾闻儒者戒远游，胡为孔孟终周流。","古来贤圣且如此，我辈岂得长淹留。","吾家更有陈公案，不见新州卖柴汉。","自从獦獠入黄梅，引得儿孙恩爱断。","堂中饭熟热椀鸣，一饱各自东西行。","老兄选官予选佛，岂效儿女牵痴情。","痴情决绝孤琴悄，无弦一曲知音少。","不道珠崖道里赊，不道先生官职小。","不道广文薪俸微，不道故人相见稀。","若教官舍成窠臼，那得儒冠伴衲衣。","山僧老矣君亦老，成道成名归及早。","知恩容易报恩难，作宦参方非草草。"]},{"t":"送林梅村解元","f":"古风","c":["立身须作第一人，学佛当观第一义。","丈夫圣谛且不为，选官选佛应无异。","林君名字天下闻，贤书首荐称人瑞。","文章于尔但秕糠，传入长安曾纸贵。","岂知妙道中所存，明镜当空无一字。","六年两度上金台，世路无人知国士。","上元甲子三阶平，黄河见底麒麟至。","大人利见会有时，看君出疆还载质。","轻车熟道早登程，万里风云若平地。","去时岭上花正开，到日皇州花下醉。","春风得意远相闻，山中笑杀无名氏。","老僧老矣不出门，吟诗送客无佳思。","岐路因君赠一言，却恐贵人多忘记。","休忘记，便作南宫第一人，更有人间第一事。"]},{"t":"初入鼎湖赋事","f":"七言古诗","c":["羚羊峡束牂牁注，群峰阖辟如门户。","雾蒸霞蔚庆云深，龙降虎伏师王踞。","相闻邃古轩辕翁，此地曾来开鼓铸。","范成神鼎即登遐，留与空王作常住。","云顶老人手眼高，开辟恰当无佛处。","一区金地万山中，丹梯锁断红尘路。","钟磬出林天籁空，松杉匝地秋声聚。","磴转羊肠过九回，石横虹影凡三度。","芒鞋踏破岭头云，铁钵饶探石中乳。","隔山隐隐有人声，举头乍与孤僧遇。","手携杖笠摘茶回，相呼相唤同归去。","白犬林间不吠人，玄豹山中方泽雾。","三堂寂历四门开，百万人天拥调御。","孤峰顶上铁浮屠，多宝庄严万德具。","七层六面面一灯，灯灯相映交回互。","天花天乐下香台，设利流辉遍赡部。","夜来宝镜出匣光，高挂东山无影树。","一时龙象斫额看，争向指中寻顾兔。","无端笑倒老瞿昙，直下金轮行七步。","大家稽首大法王，不辨龙蛇与缁素。","归堂坐爱月孤明，板响钟鸣天又曙。","起来却与老僧期，策杖前峰观瀑布。","水帘朝捲风雨生，石发晴梳鱼蛤露。","坐久不知云出门，百衲惊寒毛发竖。","山穷水尽悄无人，侧耳如闻隔溪语。","绝壁闻声不可寻，断崖欲度难飞渡。","攀藤直上最高峰，始会蒲团好安措。","半閒云住半閒僧，品字柴头三橛芋。","山僧久拟谢尘绿，是处真堪送衰暮。","自信贫儿免盗憎，薄福不消神鬼护。","但须半把茅盖头，誓不因人求解悟。","归来举似阿阇黎，多谢山中好盐醋。","愿将骨董换空拳，拚与人张杂货铺。"]},{"t":"赠张秩咨","f":"七言古诗","c":["闭门天光井底黑，出门路多尘逼侧。","尘中走杀风马牛，觌面相逢莫相识。","十字街头冷眼看，齐国于陵称巨擘。","自誇学究会谈禅，不似经生数行墨。","五十长斋不出家，惯向肉边寻菜吃。","明明一个鲁诸生，被人唤作优婆塞。","忆昔与君俱盛年，吟诗压倒元与白。","参差马齿愧称兄，潦倒鸡坛过半百。","当时挥手各西东，十载生涯分主客。","腐儒几赴选官场，山僧直入无生国。","后来原是过来人，走却金乌无处觅。","壮心未遂勿复云，底事无成深可惜。","旧年不觉又新年，元旦才过又元夕。","灯市看看月正圆，现成一句真消息。","张拙秀才知不知，花开但借东风力。"]},{"t":"送琴僧归里","f":"七言古诗","c":["高僧白发垂两耳，手抱朱弦古焦尾。","自言能作水仙操，知音止有连成子。","去年为客穗城西，大声压倒城与市。","灯笼露柱暗点头，盲龟跛鳖生欢喜。","我住山中少到城，焉知世界大如此。","闻名却恨识翁迟，相见匆匆空复尔。","下榻张琴未及弹，明发扁舟戒行李。","孤灯话到定钟鸣，中庭片月照衣被。","匣中枯木解龙吟，笑我痴聋难举似。","临岐珍重老师翁，大笑抱琴归故里。","当年我亦审音人，老来失却无名指。","无弦挂壁寂无声，觌面相逢良有以。","夜深开匣共商量，一曲南薰清且驶。","归来高踞万山头，别后相思在流水。"]},{"t":"赠吴在野","f":"古风","c":["山僧亦是湖海客，年过半百头半白。","出家未办草鞋钱，烟水百城参未得。","最羡先生两脚轻，朝返江南暮江北。","从来富贵不足多，多君受福戢且那。","世途险巇山嵯峨，轻车熟道无轗轲。","长江天堑汜与沱，扁舟破浪如轻梭。","大人行乐乐奈何，辎车百万牛马驮。","还家寄傲深烟萝，笑我行脚空蹉跎。","愿随仙人张志和，钓竿诗卷青箬蓑。","与君相伴终婆娑，胡为乎瞻风拨草徒波波。"]},{"t":"送王晋予孝廉","f":"七言古诗","c":["珠崖南望天水连，四州十县凌苍烟。","山川云物钟南偏，地灵人杰佳气骈。","丘公海公相后先，千秋事业垂丹铅。","定安宗伯称比肩，文章道德无轾轩。","后来继起多象贤，风流儒雅何翩翩。","君家奕世科名联，趋庭家学推渊源。","雄才挺出牛女躔，读书万卷超言诠。","藻思逸韵如涌泉，弱毫跃跃多所宣。","文成万选誇青钱，一朝姓字人争传。","金鞍白马跨锦鞯，鹿鸣宴罢先著鞭。","朝辞五岭暮幽燕，看花直到金台边。","倾城祖饯车骈阗，骊歌唱彻还管弦。","天风吹上孝廉船，珠江日出锦帆悬。","道旁观者争垂涎，男儿得志非偶然。","旧游老我山中禅，相逢车笠私相怜。","海上白鸥曾往旋，升沉回首成天渊。","行矣努力勿复言，长安大道直如弦。","上林花发春正妍，故山容我高枕眠。","大鹏奋翼摩苍天，鹪鹩一枝聊自全。","故人许我来埽门，旧社重游还有缘。","多异山中茅数椽，期君过桥看种莲。"]},{"t":"谢胡东长惠绵被","f":"七言古诗","c":["枯禅身心冷如水，经年坐卧无衣被。","七斤破衲五条衣，虮虱安居成法喜。","今年雨雪太无端，西溪水牛冻欲死。","众中冷煖自家知，叠锦重裀畴不尔。","霜威不奈老僧何，飒飒寒风空过耳。","一个蒲团坐到明，明发天鸡鸣便起。","起来积雪拥荆扉，相过独有胡公子。","轻裘缓带不知寒，怪我生衣薄如纸。","亲裁大被絮绵花，付与空生作生理。","空生生理非等閒，明州布袋轻无比。","囊括虚空与大千，东西南北随行履。","寸丝不挂体如如，有亦不拘无则已。","多谢绨袍一片心，珍重收归还自己。","被盖囊藏过此生，寒岩枯树长相倚。"]},{"t":"罗浮采药歌","f":"七言古诗","c":["朱明老仙能辟谷，日饭胡麻茹黄独。","轻身直上铁桥行，踏破飞云云在足。","四百峰头种紫芝，千寻涧底菖蒲绿。","药名药品皆离奇，神农本草那得知。","温凉燥湿各有以，雷公炮制空复为。","相逢一一为予说，予心半信还半疑。","老仙大笑导予去，指点深山最深处。","随取随有却随无，杀人活人不知数。","倾筐不盈盈便归，归时忘却来时路。"]},{"t":"送僧归里","f":"古风","c":["伶俐衲僧世稀少，触著一了便百了。","鼻孔撩天两眼高，一緉麻鞋紧俏俏。","自誇蓦直到台山，依旧门前打之绕。","中途撞著婆子禅，指条去路令分晓。","一朝撞倒须弥卢，不道归家路绵邈。","不绵邈，新妇骑驴阿家牵，世路红尘空扰扰。"]},{"t":"初住东林周太尊缪西冷过宿","f":"古风","c":["君不见日光西没月东出，大地晴阴是何物。","良辰美景无二三，风雨晦明常六七。","白雪多从脑后生，青山半向尘中失。","人生能得几多时，知己灯边频促膝。","我惯香山三十年，我住东林才半日。","半日閒人半日忙，送往迎来非一一。","黄昏客散掩荆扉，水亭月上风萧瑟。","周生缪生兴独高，出门畏与时流匹。","孤城吹角巷无人，自抱衾裯到蓬荜。","相逢大笑腐儒禅，解道非心亦非佛。","殷勤留客话深宵，手拨寒灰煨榾柮。","一更明月二更云，半夜雨声喧蟋蟀。","微云细雨眼前过，依旧孤光生白室。","底事明明举似君，净似琉璃黑如漆。","坐到天明捲幔看，君不见月光西没日东出。"]},{"t":"赠马专城卧仙","f":"七言古诗","c":["世人相见贵揖让，山僧不识背与向。","城市纷纷事迎送，山僧不识轻与重。","沉埋日久无道力，出门每被尊官斥。","朝辞穗石不转头，暮宿莲峰未煖席。","晨钟催起懒披衣，门外传呼来贵客。","轻裘缓带光照人，蓬蒿咫尺生颜色。","贵人恕我太无礼，直到床头问顽石。","顽石真顽顽不移，多谢知音为拂拭。","主宾倾盖无几何，邀我还家欢日夕。","将军杀贼不杀生，自摘嘉蔬供饮食。","野人一饱腹便便，起坐西轩面东壁。","壁间珠玉光陆离，白者为纸黑者墨。","时人道我文字禅，岂知一字全不识。","自从出世到于今，没处藏身没踪迹。","无端觌面漫相呈，笑杀当今老诗伯。"]},{"t":"马将军杨恭人寿诗","f":"七言古诗","c":["生子当如马伏波，天南铜柱高嵯峨。","文章迈伦功盖世，显扬事业应如何。","古来将相多崛起，风云应运良有以。","山川岳渎钟瑰奇，城则陶城水文水。","水清蚌腹珠夜光，男儿七尺眉最良。","中原射策推第一，云州建节鹰初扬。","此身许国还将母，征衣取作斑衣舞。","当宁论功及所生，黄麻墨敕传天语。","天语煌煌出綍纶，华堂画锦何缤纷。","兰孙高折一枝桂，雏凤还生五色文。","东南多垒须仁将，我公久贮苍生望。","棨戟遥临瘴海边，瞻云陟屺增惆怅。","临行受命曾书绅，忠孝大义何谆谆。","矢心矢志报明主，孺慕难忘白发人。","人生有子万事足，含饴弄孙增百福。","孟母宅边佳气多，南人岭外欢声祝。","棘门有客曳长裾，将军知我狂接舆。","高歌一曲望风拜，礼虽不足心有馀。","殷勤报语登坛客，云台为尔虚前席。","翟茀不来长倚门，翘首云鹏振双翼。"]},{"t":"秋杪过新州访李方水广文兼寄潘完子","f":"七言古诗","c":["野人半生但株守，虽在人间少游走。","梦里名山草草过，虾跳何曾会出斗。","因寻獦獠到新州，满眼秋光正重九。","入城不见卖柴人，直到泽宫逢好友。","先生久病不出门，闻我远来叹希有。","登堂七发愧枚生，话到深宵月当牖。","主人就枕客亦然，珍重明朝更携手。","饱餐苜蓿高兴生，登临未敢辞衰朽。","天露峰高在眼前，龙山旧路重回首。","祖庭秋晚漫淹留，笑别官衙返南亩。","故人家住官峒头，觌面相逢良不偶。","剡溪兴尽且归去，他年未卜重来否。"]},{"t":"烧畬歌","f":"七言古诗","c":["野人赤脚走官道，踏上盐田看监灶。","灶丁烧畬不煮海，万井寒烟风浩浩。","道旁老翁知是谁，手拨畬灰归去迟。","相逢举手相劳问，自言生长升平时。","寒乡旧是煮盐户，出门咫尺无旷土。","自从斥卤变桑田，丁男始识农与圃。","盐场作田田有租，场中无盐仍追呼。","一田二税互逼迫，十年两役纷支吾。","荒年百室如悬磬，年丰谷贱为农病。","县主场官交索租，孤儿寡妇罢奔命。","今冬尽室输官仓，明年枵腹春耕忙。","新丝卖尽又新谷，空拳无计完秋粮。","城中富人巧生殖，九分出钱十取息。","娇儿稚女相随来，薄暮得钱朝雇役。","得钱未煖便纳官，归来入室摧心肝。","人生恩爱岂不重，践土食毛良独难。","田家耕田食贵米，盐户无盐啖清水。","可怜半死白头翁，回首升平如梦里。","烧畬煮灰灰作盐，持盐易米堪养廉。","殷勤致语道旁客，蓼虫习苦不知甜。","我闻老翁呜咽语，咄嗟涕泣零如雨。","九重天高唤不闻，老翁老翁徒自苦。"]},{"t":"客有遗予白鹅者贫无稻梁不给朝夕悲呜欲去乃从其志寄养于南皋处士戏为短歌以遣之","f":"古风","c":["笼中有物白皑皑，山阴道士亲送来。","入门志在饱刍豢，谁知绕室荒蒿莱。","眼看草具不肯食，高视阔步声喧豗。","邻家刈禾足饮啄，梦想飞去中徘徊。","吁嗟乎，众生所向类如此，披毛戴角良可哀。","明知难与共枯寂，恶用鹢鹢者为哉。","南皋大士发悲悯，许以豢养无嫌猜。","微躯寄托信得所，饥食渴饮樊笼开。","等閒笑向朋侪道，东林长老真长斋。"]},{"t":"虎溪竹","f":"古风","c":["德云住山不住水，孤峰绝顶无生理。","华亭住水不住山，扁舟覆没波涛閒。","东林老僧两不尔，半水半山半城市。","茅堂背郭池水边，水清水浊皆栽莲。","莲高出泥能几许，梁鹙林鹤交相觑。","主人避客如避仇，移居更卜溪水头。","溪水泠泠溪树古，树下两翁相对语。","曰公乃是东林禅，适来适去非偶然。","此溪旧名虎溪水，西去东林二三里。","昨日远公今又来，溪山还尔真奇哉。","老僧大笑谢不敏，口虽不言心蠢蠢。","痴心痴想难告人，从秋至腊今又春。","春来几日风景好，旧路重寻难草草。","良时正值朋侣佳，蹇驴出郭多同侪。","缪生杨生与郑子，胜游厌走红尘里。","相呼相唤东复东，隔溪流水桃花红。","溯洄直到曾游处，三瞻四顾不忍去。","商量劝我受清福，把茅盖头万事足。","万事足，勿复云，钓鱼老翁聋亦闻。","归来坐到东林月，四壁无人为君说。"]},{"t":"跳大王歌","f":"古风","c":["蛮乡歌舞自称善，厥声可闻不可见。","四月五月跳大王，家家刻木作鬼面。","千丑万拙由心生，头角觺觺尽奇变。","削成两耳贯双环，黑白青红随绘绚。","长缨分结顶门边，俛仰周遮任方便。","市来绛帛缝赭衣，承以素裳纫新练。","长柄牙旗短柄簦，东官草帽冈州扇。","粗缯细篾作游龙，肖首肖尾中连串。","事事具足人力齐，次第椎牛集欢宴。","大王端坐不饮酒，黄童白叟争酬劝。","酒阑酷酊齐唱歌，呕哑啁啧无分辨。","舁神入城城市空，大呼疾走看游龙。","驭龙小儿戴鬼面，一步一跌来匆匆。","左顾右盼各招手，头旋尾转相追从。","游龙舞罢抚歌板，唱歌尽是头白翁。","青葵半掩老面目，随声答响羞雷同。","须臾磨旗万舞作，朱干玉戚纷兴戎。","或击或刺冯而怒，或揖或让足而恭。","忽焉而起忽而止，一一皆与神心通。","舞罢偃旗卧金鼓，借问大王何所取。","倾筐擎出斗与升，鬼面成群更歌舞。","道旁观者不忍见，腼颜汗背交相觑。","吁嗟乎，天下尽儿戏，举世同奔波。","车毂交击人肩摩，俄而礼乐俄干戈。","五斗折腰不足道，倾筐积少看成多。","大王乃是死诸葛，含羞忍耻如之何。"]},{"t":"赠颜雪仙","f":"七言古诗","c":["严城细柳垂丝丝，门施行马罗健儿。","野人怀刺不敢入，区区梦想非翁谁。","此翁知我良不浅，笑我知翁才一面。","城中大士城外僧，神交岂待频相见。","去年过我看白莲，双眸炯炯神浩然。","今年花开客不至，几回埽径迟高贤。","朝来主人敬爱客，虎帐吹笙布重席。","穆生不饮醴亦陈，三爵为翁泻云液。","满堂欢笑胡为乎，相闻上客悬雕弧。","山僧不知老将至，大人寿考当何如。","先生神骨如孤鹤，我作秃鹙随饮啄。","先生直节如乔松，我为散木甘龙钟。","先生文章如白璧，我作珷玞还瓦砾。","先生词赋如珠玑，我乃蜣丸充佩祎。","先生可行亦可止，一片閒情托流水。","我将行脚仍蹉跎，心在空山身在市。","先生可望不可亲，长天朗月无纤尘。","我当出世难免俗，涅恐或缁磨或磷。","自写长篇遥寄祝，恕我登堂理巾服。","他时相见问生缘，六六原来三万六。"]},{"t":"反乞功","f":"七言古诗","c":["东邻女儿具瓜果，西邻女儿不举火。","金针綵线夜登楼，竹户蓬门早扃锁。","同是当时乞巧人，不信天孙巧如我。","去年绣出双鸳鸯，今年织作双凤凰。","卖与人间恐无价，重缄什袭牢深藏。","粗绘弊布阅寒暑，三旬九食甘糟糠。","始知大巧不如拙，区区畏向时流说。","天孙虽巧机杼勤，河汉年年怅离别。","寂寞何如姑射仙，万古肌肤似冰雪。","寄语东家乞巧儿，红颜薄命当知之。","不愿金针得天授，不愿瓜果萦蛛丝。","但愿长为田舍妇，挟薪戴畚无非仪。"]},{"t":"题百寿图","f":"七言古诗","c":["包羲一画开天地，仓颉之先有文字。","河图洛书圆复方，龟龙泄尽先天秘。","后来书契无真传，丹台留得青霞编。","谁能识字还识义，人间烟火真神仙。","图中字字灿可睹，六书八法无今古。","自从李相作回鸾，既寿永昌为鼻祖。","增华继起儿与孙，文章经纬推渊源。","黄麻墨敕传天语，如纶如綍皆王言。","我翁受命九稽首，钦哉天长还地久。","归来写作百寿图，锦字光芒射星斗。","主人一饮一百杯，百花对酒参差开。","百和香生青玉案，百戏齐陈锦绣堆。","百粤天高佳气郁，百尺楼头初见日。","百昌畅遂百宝生，百两盈门百庭实。","区区百寿何独然，百福百禄相周旋。","百年三万六千日，日日逢君地上仙。"]},{"t":"赠黄三曜","f":"七言古诗","c":["老僧两脚不出户，眼中之人自来去。","一日相逢笑几回，平生肝胆谁倾吐。","莫疑吾道太孤危，不见当今黄叔度。","黄生秉志非等夷，膂力方刚年更富。","十一十二通诗书，十三十四工词赋。","十五能写沧洲图，十六琴高擅名誉。","十七十八事远游，来往京华如熟路。","吴越山川入画图，袖里新诗供喜怒。","去时还是岭南人，归来学得邯郸步。","耳边闻我会杀人，入门问取无生句。","东林长老不读书，惯向人前漫抽顾。","不须白拂与乌藤，直示空拳自回互。","请君放下文字禅，一曲无弦发深趣。","诗中有画画中诗，庐陵米价青州布。","一番谛信一番疑，水尽山穷知去处。","当当借路直还家，不用旁人为指注。"]},{"t":"挽黄广思","f":"七言古诗","c":["结交可一不可二，前有难兄后难弟。","而兄于我知最深，彼此忘年仗声气。","相逢恰在闹场中，目送蜚鸿薄权贵。","老人自号黄石公，孺子可教将无同。","稠中肝胆笑相许，高谈四座生酸风。","一朝聚散如反手，旧游零落悲秋蓬。","郢人已死不足道，匠石运斤身已老。","粉碎虚空不自知，前路生涯半枯槁。","后来见弟如见兄，不堪回首伤怀抱。","羡君好善不好钱，羡君买书不买田。","三世遗编重检校，两朝文献推丹铅。","枣梨价重长安纸，缣缃擎出归经筵。","膝下佳儿今叔度，执简趋庭穷典故。","相将邺架绍箕裘，惆怅桑榆歌薤露。","手泽长留万古心，酸风摧折三珠树。","玉楼命驾弟从兄，华萼追欢向九京。","穗帐银灯吊孤影，山阳铁笛呜呜鸣。","茂陵他日求遗草，缑岭何年返晋笙。","我在东林林下住，白社先推贤地主。","溪边无复过蓝舆，池上花开怅延伫。","因君念我意中人，碧血丹心半尘土。","黄粱已熟人未醒，唤起二难相对语。"]},{"t":"蜡石歌为梁东岊作","f":"七言古诗","c":["东岊先生有奇癖，不爱黄金爱黄石。","穷山竭泽恣搜罗，转轻运重无遗力。","精粗巨细靡弗收，满床堆案如山积。","孤峰突出碍虚空，崩崖欲坠成墙壁。","袖中岩壑尽玲珑，屋角风雷轰霹雳。","中间大者如斗魁，四楞著地方且直。","从旁踞坐狮子儿，金毛翻身跳复掷。","主人一日三摩挲，尘埃净尽犹拂拭。","金光耀日冰雪寒，蜜蜡凝脂虫半蚀。","鹅王惨澹无足观，琥珀雕修差可敌。","我来见石如故人，空山回首频相忆。","当时不合错点头，持赠殷勤非所惜。","先生大力如五丁，混沌凿破天机辟。","自从师事谷城公，古道分明照颜色。","长歌短曲聊赠君，本来面目谁能识。"]},{"t":"蜜柚歌","f":"七言古诗","c":["岭南蜜柚天下无，垂枝结实如连珠。","金相玉质冰雪肤，楚江萍实胡为乎。","蔗浆茗饮渴所需，得此不复还区区。","三餐未饱七尺躯，硕果入口忘饥劬。","灵物所产非一株，人工地力分精粗。","谁当种者髯丈夫，家住凤城城西隅。","庭前累累实有馀，一摘再摘奇可居。","四座见者生觊觎，宝刀剥果如剥瓠。","金盘盛出供吾徒，大嚼小嚼姑徐徐。","便便果腹归日晡，伸纸作歌歌吴歈。","安得种此临交衢，道旁观者无贤愚，众口所嗜岂有殊。","蜜柚蜜柚名不虚，大家细味看何如。"]},{"t":"赠马敬子孝廉","f":"七言古诗","c":["弯弓射雕不射虱，拥书读礼不读律。","词流倒峡赋凌云，意气干霄虹贯日。","雄才大略非等夷，斯人岂是池中物。","昨日诵君孺慕篇，凉风在树声萧瑟。","今来识得白眉良，万里斑衣仍素韠。","山人赤脚入军门，将军于我成胶漆。","半月不来人事疏，内庭突见龙驹出。","相逢一揖问姓名，贵人许结王生袜。","羡君风度似翁閒，羡君藻思如翁疾。","羡君特达能不骄，羡君文章能继述。","云台事业相后先，钜下风流难髣髴。","我在东林懒见人，疏情不觉因君密。","莫辞有约去还来，浮生相见旋相失。","升沉回首各云泥，云去飘飘泥滑滑。"]},{"t":"送何茂才愚堂就试高凉","f":"古风","c":["男儿立志在人前，读书稽古师圣贤。","男儿置身在人后，大器晚成何不有。","愚堂先生愚不愚，得兔忘蹄还守株。","雕虫末技无足羡，只手弄丸如弄珠。","明珠擎出光照乘，不肯待沽惟待聘。","随人逐队走高凉，三年一度成熟径。","今朝结束还出门，春雨如膏路泥泞。","嗟君此去何匆匆，旧路经过仍蹭蹬。","断科使者严如师，闻风疾走休迟迟。","临岐恰好成春服，客到刚逢上巳时。","黄梅熟后理归棹，回首家园见荔枝。","中间奔走百馀日，风光到处均劳逸。","贫士囊中纸裹钱，买醉旗亭非所恤。","归来举似住山翁，笑杀东林辟支佛。","问君大笑胡为哉，闺中有女歌摽梅。","十年不字良有以，寸珠尺璧难自媒。","君不见龙藏大泽生变化，忽为霖雨为风雷。","丈夫得意会如此，也须直上燕昭台。"]},{"t":"赠马卧仙","f":"七言古诗","c":["龙骧虎步随高下，此翁岂合居林野。","中原射策先冠军，肘后骊珠光照夜。","河清海晏靖烽烟，缓带轻裘见儒雅。","西园词赋拟曹刘，东阁文章追董贾。","著书先著春秋歌，丘明公谷如尔何。","年过五十犹学易，两仪四象交森罗。","倚马千言飞露布，吹毛三尺降么么。","雄才大略谁先后，今之卧仙前伏波。","等閒事业从头数，夜半鸡声催起舞。","此心此志畴得知，上有君恩下慈母。","九重三疏叠陈情，万里归心廑孺慕。","孟母宅边频倚门，征人岭外长延伫。","羡君有母寿还童，羡君有才孝作忠。","羡君有子传家学，羡君有孙承祖风。","羡君能诗号无敌，羡君谈笑销兵戎。","丈夫立身会如此，岂能碌碌稠侣中。","将军爱我愚也直，我爱将军清且白。","两人相得非等夷，异地同堂慰岑寂。","过桥三笑仿前贤，拍案高歌忘主客。","不妨野老眼长青，请看此翁头未白。"]},{"t":"送刘东溪北上谒诠","f":"七言古诗","c":["东溪先生才品高，当今作者推风骚。","读书万卷颇自得，兴来落笔生波涛。","波涛旦夕为霖去，洒向人间作膏雨。","万方草木一时春，六月南薰吹溽暑。","东林野老懒下床，朝来忽觉清风凉。","披衣起问风来处，闻说东溪正束装。","轻装结束何所有，奚背诗囊大如斗。","生平心血为谁倾，留与苍生作粮糗。","婴儿索乳饥待餐，民胞物与应相关。","漫将诗卷酬风月，换取经纶起痌瘝。","此身只合宰天下，区区百里胡为者。","至人出处不易知，小用大用无取舍。","良庖游刃恢有馀，割牛割鸡同批虚。","一朝利器在公手，盘根错节当何如。","先生行矣时未晚，抟风直上鹏程远。","早将名字列屏风，伫见文章推补衮。","朝来墨绶暮黄扉，黑头宰相遥相思。","不须更问东林老，期君努力为所为。"]},{"t":"别钱塘姚洎韬","f":"古风","c":["山僧欲向钱塘去，逢人便问钱塘路。","识得钱塘一个人，此心光向钱塘住。","钱塘人物能几何，红尘队里肩相摩。","尘中得有姚公子，一麟已足何须多。","公子今年二十九，身长七尺才八斗。","新诗出箧珠玉光，挥毫落纸龙蛇走。","曾从定远事戎轩，斑衣万里奉晨昏。","华顶莲花见开阖，蚕丛鸟道曾攀援。","将星一夜骑箕去，凄断天风下高树。","悲歌惊起广陵涛，壮心留得西征赋。","漫携书剑下江南，殊方何地可臂骖。","细柳将军新虎帐，东林野老破茅庵。","茅庵野老睡初熟，推出枕头舒两足。","结束腰包事远游，楖?横担行彳亍。","行彳亍，路多岐，欲去未去心先疑。","殷勤借问姚公子，前途夷险谁知之。","姚君大笑向予说，大道条条直如发。","老僧能去复能来，到处名山长薇蕨。","师行秋正深，来春我当发。","两人相遇莫相期，夜夜长天共明月。"]},{"t":"留别马卧仙","f":"七言古诗","c":["山僧出世还在世，从来不作安居计。","孤云野鹤自相于，三迁四徙无拘系。","去年结社铁城东，闭门不觉成老翁。","名山笑我不归去，缄书万里来秋风。","秋风吹冷那伽定，目送飞鸿发高兴。","竿木随身别旧林，林间好友劳相赠。","但言方外本无家，不用乘秋上海槎。","藕泉泉煮莲峰茗，留君差胜赵州茶。","殷勤多谢深存注，人非麋鹿难长聚。","断蓬宛转逐浮云，落花荏苒随飞絮。","我去参方君宦游，前途各各不相谋。","选官选佛从所好，输君一着看封侯。"]},{"t":"上中宿峡","f":"古风","c":["鸡鸣点火爝枯竹，粝饭藜羹煮初熟。","稿师一饱催上船，船头见水不见天。","山高日出天未晓，水底观天见天小。","唤起同舟看远云，白衣苍狗何缤纷。","云开仰见山腰寺，古殿飞来居福地。","钟声鼓声通渺冥，聋者自聋听自听。","大呼唤转操舟汉，而辈登舟我登岸。","来程无几去程赊，中途见寺如见家。","我闻定心亭在最高处，登峰到顶休疑惧。","莫待归舟下峡时，顺水顺风留不住。"]},{"t":"初入丹霞与九译禅友夜话","f":"七言古诗","c":["耳边闻有丹霞山，如闻说食不得餐。","十年梦想如一日，无昼无夜无忙閒。","违时失候乃一出，力羸筋怯惭衰顽。","丹梯似天不可及，十步一息穷跻攀。","攀藤直上最高处，俯视万山如米聚。","山僧怪我来何迟，相逢道新不道故。","初来但觉此山高，岂知更有高高步。","请师暂洗脚板泥，上床默坐消尘虑。","明朝日出天宇清，突出孤峰待师住。"]},{"t":"登海螺岩谒澹归禅师塔","f":"七言古诗","c":["孤峰巨石如巨屋，雨脚云头互翻覆。","海螺脱壳还太虚，五丁凿破混沌腹。","何人窣堵居中间，澹公白骨归空山。","天荒地老陵谷变，一道灵光长自閒。","忆昔崧台侍欢宴，耳边闻有金台谏。","手持白简批龙鳞，相公击出文华殿。","殿前贵人侧目看，大臣小臣心胆寒。","直道难容柳下惠，赤心剖出生比干。","一朝弓剑随龙去，天子蒙尘臣谪戍。","舍身许作寺家奴，孔孟伊周留不住。","雷峰老人双眼明，杀人活人不转睛。","浩气销磨客气死，长老峰头笑一声。","笑声落在黄金地，山魈木客争回避。","十方龙象一齐来，百万人天纷布施。","山前山后天雨花，苍松翠柏浑一家。","老人入山鼓掌笑，此地不愧名丹霞。","顽石点头不解语，澹公领话频频举。","感激雄州陆大夫，两人合作一枝柱。","宾中有主主中宾，卸担何曾见一人。","平湖路上翻跟斗，螺峰归去密藏身。","藏身何处无踪迹，寻师记得三生石。","绝顶浮图舍利辉，帝珠交映千山色。","澹公澹公将无同，相随去也空合空。","石龛紧闭未岑寂，隔江更有天然翁。"]},{"t":"送九译禅友还里葬母兼订重来之约","f":"七言古诗","c":["年过三十不闻道，少壮蹉跎忽复老。","善哉之子正当时，出世不迟还不早。","生来十八解破家，自笑平生白鼻騧。","儒门澹薄收不起，章逢换取僧袈裟。","昨日潘生今九译，梵语华言明历历。","翻成一藏盌脱丘，此土西天浑不识。","东林老僧老古锥，被他唤作阿阇黎。","相逢有口但挂壁，喃喃作白称毗尼。","毗尼不入丹霞耳，未能免俗聊尔尔。","等閒拈出衣中珠，贫儿暴富还乡里。","还乡生计当何如，杯棬有恨徒区区。","荆棘丛中问封树，烟霞堆里待安居。","安居乃在夏三月，春寒过眼成炎热。","中閒冷煖谁得知，待子重来为子说。"]},{"t":"戏赠埽雪童子","f":"七言古诗","c":["主人运笔如运帚，纵横阖辟应心手。","痴奴运帚如运斤，旋风落地飏轻尘。","人生贵贱各有务，莫笑痴奴无用处。","昨夜三更风打门，雪花欺我衣裳单。","袖中两手冻欲裂，朝来作字成丑拙。","抛书拥彗下阶除，十步一跌中踟蹰。","痴奴知我主人老，相劝雪深休草草。","先生有事当服劳，长者抓枝须我曹。","受我手中敝苕帚，两脚未行先学走。","一埽再埽大地平，三番四覆天宇清。","自誇我亦有能事，何必主人擅文字。","毫端珠玉不禁寒，纸上风云冻欲乾。","小人苕帚有机用，左之右之随定动。","不似管城老秃翁，花发梦中还说梦。"]},{"t":"宿绿萝庵赠半僧万欲曙","f":"古风","c":["十步置一山，五步置一石。","先到作居亭，后来是宾客。","大家落得占便宜，何暇求田还问宅。","绿萝主人眼孔高，俯视一切如鸿毛。","黄金散尽买山水，赤脚踏破深蓬蒿。","太初一片閒田地，十戴经营成底事。","名花多自洛阳来，奇树却从玄圃至。","半僧一半不出家，懒种菩提勤种瓜。","瓜时邀我入山去，石龛一榻明秋霞。","孤峰独宿鸡犬静，松灯萝月交相映。","半句无生万念空，一声长啸千山应。","绿萝主人知我心，入山唯恐山不深。","二閒茅屋如相借，一片閒云何处寻。","无孔笛，无弦琴。","为君歌一曲，大地谁知音。","明朝策杖下山去，回首绿萝云树森。"]},{"t":"顽牛歌","f":"古风","c":["岭之南，岭之北，两片閒田明历历。","祖翁付与好儿孙，各服先畴食旧德。","春而稼，夏而穑，秉耒躬耕凭众力。","养成一队水牯牛，觲角黧奴争奉职。","鼻孔任穿牵，皮肤听鞭策。","长欃犁破陇头云，洗脚归来日西夕。","主人顾盼无重轻，刍牧随时暂休息。","把火照牛牛尾多，或寝或吪或反侧。","中有顽牛顽可怜，丰骨棱棱双眼白。","鼻孔撩天奈若何，全身浑是顽皮鞑。","不穿绳，不拽索，散诞溪山忘轨则。","牧人一见辄生嗔，懒惰无成交遍谪。","顽牛仰首鸣，主人须委悉。","我从山中来，未尝惯形役。","辜负主人恩，豢养无功绩。","虽无功，微有益。","顽不犯苗稼，顽不饕饮食。","顽能教儿孙，牵犁还负轭。","真顽无干戈，真顽无柴栅。","真顽无爱憎，真顽无拣择。","真顽无疏亲，真顽无主客。","真顽无有亦无无，无无亦无顽叵测。","要议真顽顽不顽，问取虚空须点额。","东郊春草青，西溪秋水碧。","随分纳些些，一去如遗迹。","殷勤挥手别同牢，归卧家山枕顽石。","岭南岭北谁知音，出格相看须破格。","一所栏圈半把茅，付与顽牛作家宅。","宽不宽，窄不窄，渴饮饥餐随所适。","此是顽牛得意时，头角四蹄非所惜。"]},{"t":"放鹤乞缘","f":"古风","c":["君不见西天百岁水老鹤，飞向人间随饮啄。","瀰天布网地张罗，造物小儿援弓缴。","一朝失足入樊笼，铩羽低垂任飘泊。","平生一片水云心，紫陌红尘非所乐。","西山倒景入桑榆，日暮归心在寥廓。","前途信有好山川，谁为开笼解缠缚。","大声寄语有心人，莫惜金钱早倾橐。","九皋放去一身轻，绿水青山无住着。","华表归来未有期，感恩愿比衔花雀。"]},{"t":"王梳山徵诗付选答以长歌","f":"七言古诗","c":["当今作者如建鼛，大声细响皆风骚。","分门别户相贬褒，江河日下纷滔滔。","梳山大士手眼高，俯视一切同萧蒿。","指挥搦管生风涛，青天白日神鬼号。","老吏断狱如萧曹，杀活予夺操独操。","古人定论今莫逃，俯首听命无喧嘈。","千金骏骨归方皋，老马踯躅甘栈槽。","偶来过我城东濠，笑我抱瓮痴且牢。","姑舍所学从桔槔，立言不朽洵人豪。","美人赠我金错刀，何以报之鸊鹈膏。","欲从狐貉羞敝袍，还坐自思中郁陶。","精华已竭徒餔糟，皮之不存焉用毛。","身既隐矣光亦韬，道旁苦李难报桃。","感君爱我无乃劳，感君爱我无乃劳。"]},{"t":"宿西乾山白云精舍与则己师夜话","f":"古风","c":["则公爱山有奇癖，不住仙城住韶石。","横担楖?入西乾，山色溪声明历历。","白云虚左待师来，丹嶂重开凭道力。","大刀阔斧运如风，短锸长欃铦似戟。","夹道苍松带雪删，当门古桂移根植。","多年泉石锁烟霞，一朝云树生颜色。","去冬寄我袖中书，春风有约遥相忆。","远游未办草鞋钱，开年早蜡登山屐。","屐声踏破扶溪云，欲往山南忘山北。","啼莺出谷花满林，觌面相逢忘主客。","主人爱客客且留，新月初弦在今夕。","不须欸曲话寒温，默坐蒲团共禅寂。","则公则公何快哉，月落茅檐灯照壁。","人生适意能几何，不忍坐到东方白。"]},{"t":"老僧提唱","f":"古风","c":["不愿百二如赵州，八十行脚心未休。","不愿千岁如宝掌，沧桑阅尽增惆怅。","但须一念到万年，何用三登还九上。","忆昔当初脱白时，眼空三界无龙象。","光阴强半易蹉跎，烟水百城空莽宕。","自从身入老人场，壮志潜销气凋丧。","两条寒涕镇垂膺，一緉芒鞋输少壮。","徒行一步当十步，岭长百丈如千丈。","青蔬赤饭栗棘蓬，藜羹茗饮桃花浪。","只愁信施己难消，拚此身心作回向。","百八菩提如意珠，六字洪名无尽藏。","店远村遥未抵家，水尽山穷须谛当。","钟初鸣，鸡再唱。","殷勤借问老同参，百尺竿头谁向上。"]},{"t":"题账荒图为马卧仙赋","f":"楚辞体","c":["忆昔岭南丰稔日，岁取十千开百室。","田家击鼓更吹豳，稻粱饱杀仓中物。","比年水旱成荒芜，潮田巨浸山田枯。","南亩半收愁食力，西成未足填官租。","岁之丁丑夏四月，米价高腾市舂歇。","当途仰屋心血乾，四野萧条烟火绝。","烟火绝兮白日黄，同时十郡咸开仓。","流民就食无远迩，一饱不敢嫌糟糠。","香山在昔鱼盐地，回首沧桑见凋弊。","海阔天高唤不闻，吞声欲诉凭谁济。","赖有专城马卧仙，生平爱义不爱钱。","手挹黄河润枯槁，泽被东南半壁天。","眼前菜色不忍见，解衣推食行方便。","百里欢声动地来，十万青钱一朝遍。","白头老翁黄口孙，孀妻弱子填公门。","得钱易米作饘粥，一月频来不厌烦。","当时存活不悉数，公逊硕肤无所取。","义声感激有同官，雷荐云兴作霖雨。","营中细柳县中花，交阴垂荫万千家。","青箬裹粮归蔀屋，绿荷包饭出官衙。","巨室闻风争效义，里正宿舂晨涤器。","逢人不敢唤嗟来，布席受餐俱有意。","仁人之利溥矣哉，将军竖帜登春台。","阳律一吹回冻谷，嘉禾骈实出南陔。","山中野人成久别，锦江双鲤来书札。","札中写作赈荒图，口碑传颂人中杰。","楮公授我三尺麻，毛生跃出丹山霞。","千里题诗寄铃阁，东林归兴阻天涯。","呜呼，安得天下尽如卧仙者，大法小廉不相假。","凤凰巢阁鸟栖枝，麒麟在薮牛耕野。","野人饱食太平年，策杖重来问风雅。"]},{"t":"送霍西牛讲学阳春兼寄王大士广文","f":"七言古诗","c":["山林卿相烟火仙，宋儒道学南宗禅。","谁当兼此无偏全，西牛霍子真卓然。","忆昔与君俱盛年，俯视一切徒戋戋。","浮云富贵羞垂涎，钟鸣鼎食嫌腥膻。","读书得意忘蹄筌，关闽濂洛无轾轩。","须臾别去成天渊，世衰道微如逝川。","我去为僧泉石边，君居讲肆耕砚田。","及门桃李何翩翩，春风到处花争妍。","花閒讲易玄又玄，太初一画归先天。","大儒小儒相比肩，侧耳谛听无諠填。","去岁阳春开讲筵，真风振起牛女躔。","明伦立教推后先，而翁秉铎君言诠。","诗书礼乐凭昭宣，文章道德相周旋。","时雨所化皆陶甄，顽金跃冶为龙泉。","山中野人高枕眠，临风望远心悬悬。","去冬垂手还入廛，一笑逢君初月弦。","东风解冻闻啼鹃，俶装踏上河头船。","船梢捩舵船头牵，急滩枉渚随溯沿。","琴书满戴轻便便，乘风破浪如飞鸢。","五日六日涉潺湲，舍舟登陆车骈阗。","春城百里舍苍烟，绛帐重开灯火燃。","蠹鱼跳出太极圈，古今绝学传未传。","六经四子皆尘编，寥寥斯道谁与言。","西斋王公清且贤，相逢为我道拳拳。","明日有僧来乞缘，不妨早办营斋钱。"]},{"t":"分卫榄溪信宿西园谢何赤木惠米","f":"古风","c":["人生岂能高飞似鸿鹄，千里赍粮半枵腹。","人生岂能久聚如麋鹿，白首沉埋真面目。","霜边坠叶风中萍，空界浮云天上星。","从来吾道贵无情，放身便住挥手行。","出山便作居山计，还山不免来分卫。","逢钱索钱米索米，有条援条无援例。","三年不复到西园，一朝冒雪还入门。","主人坐我池上轩，坐久细问寒与温。","昨日客从何处去，今日客从何处住。","客亦无所去，客亦无所住。","钵盂驱我出东林，吹篪鼓腹无知音。","喙长三尺藏在心，欲语不语终沉吟。","主人知我故来意，西窗话到月沉地。","年来瓶笠集如猬，彼此伤廉更伤惠。","见所未见闻未闻，无心出岫秋山云。","太仓拨出赤白军，使我冷灶生氤氲。","呜呼，安得天下尽如西园主人者，虚名实相无取舍。","由我在山还在野，日暮途穷来毁瓦。"]},{"t":"题东安明府鸣琴图","f":"七言古诗","c":["龙门百尺青玉桐，何年雕琢归良工。","七弦七轸抱明月，一弹一曲来薰风。","薰风披拂知何处，泷邑神君今召杜。","希声重理太古音，单父清徽更昭著。","垂帘堂上心独閒，据梧隐几看青山。","存神过化无远迩，片言折狱如转环。","阳春有脚靡不到，百里邻封胥再造。","暮金不入四知门，枯木龙吟写怀抱。","一徐一疾皆有情，神之听之和且平。","徵音为民角为事，大弦常缓小弦清。","初弹扎扎如机杼，再弹习习如风雨。","机杼织为重纩温，五风十雨膏禾黍。","桑麻处处年谷丰，寒者授衣饥者充。","蔀屋重阴见朝日，容光必照惟大公。","我是罗浮水老鹤，闻声起舞欢雀跃。","飞入崆峒借一枝，伫看威凤巢阿阁。","请公再鼓无弦琴，柴桑千载称知音。","蓝舆直入虎溪去，流水高山何处寻。"]},{"t":"珊瑚杖歌为林沂泽作","f":"古风","c":["沂泽老人如婴儿，自誇两脚能奔驰。","纵横八极兴不浅，恃有手上珊瑚枝。","珊瑚海底高八尺，玉润珠圆自雕饰。","赤蛇飞出水晶宫，化作文虬生两翼。","感激良工用意深，许身窃比双南金。","一朝神物归掌握，撑天拄地横古今。","拄杖子，拄杖子，一屈一伸皆至理。","直时如矢曲如弓，刚可断金柔绕指。","翁乎翁乎胡不然，顺行逆行胥任天。","珊瑚枝枝撑著月，笑杀山中枯木禅。"]},{"t":"送伍秋农下山","f":"七言古诗","c":["出家不舍田与里，住山不别城与市。","长斋不断酒与荤，参禅不离妻与子。","声闻现作居士身，青莲花发红尘里。","双林傅老襄州庞，眼中之人谁得似。","伟哉伍君非等閒，须髯苍苍修且美。","手抱无弦入鼎湖，志在高山与流水。","閒房借得木人居，僧来便问无生旨。","我亦山中躲懒人，相逢大笑无彼此。","团圞一日当三生，回首门闾频陟屺。","乘兴能来乘兴归，怅别松閒书片纸。","雨过西江水急流，指点归程无几几。","朝辞高峡暮汾江，一路山光伴行李。","同舟况有罗戒轩，正好从容谈性理。","还家倘遇旧同游，为我将心报知己。","别来饭食不如前，菜根打落当门齿。"]},{"t":"呈鼎湖契和尚","f":"古风","c":["我生不出空劫先，高谈阔论燃灯前。","我生不逢竺土仙，拈花微笑闯法筵。","我生不居兜率天，扬眉吐气弥勒边。","无端打落五浊世，低头折节诚可怜。","年过六十不称意，住山未了还入廛。","鼎湖主人知我懒，招我直上孤峰巅。","孤峰白云自舒卷，此身归宿终茫然。","自从入室领顾鉴，方知落处无中偏。","顽金钝铁出炉鞴，昔为骨鲠今如绵。","大哉大人大机用，智珠擎出圆又圆。","莲池净土云顶律，博山钟板天童禅。","一家共唱无生曲，铁笛无孔琴无弦。","小乘从旁发大笑，笑翁未了住世缘。","愿翁寿，亿千年。","众生度尽成正觉，容我湖山高处眠。"]},{"t":"赠孔徵君","f":"古风","c":["住世不必丹砂床，清心寡欲岁月长。","应世不必风云会，功成名遂身须退。","遁世不必颍水滨，良田方寸无嚣尘。","君不见墩山之下孔巢父，远溯尼山称鼻祖。","出身事业继萧曹，中年归隐称三高。","教子一经绍家学，二难矫若云中鹤。","大儿仲谋次士龙，文章道德绳乃翁。","我翁当今正黄耇，高风传遍时人口。","晚年好道礼金仙，寻僧卜筑溪桥边。","祇园布金推长者，閒来更缬东林社。","玉麈风生四座清，地炉火热蚯蚓鸣。","高谈话到日西夕，策杖归来问耕织。","运筹声与读书声，灯下儿孙笑不停。","尽道我翁真矍铄，地上行仙解行乐。","井干桐飘一叶初，我翁寿考悬雕弧。","朝来洗爵劝翁饮，沉醉风前花似锦。","醉摘花枝插鬓边，参差笑倒东林禅。","曰翁真似庞居士，了得心空须及第。","一门尽入选官场，满床牙笏卜诸郎。","留将选佛一句话，不妨独步还高誇。","墩山看似寿山高，慧炬双辉长不夜。"]},{"t":"赠区守斋","f":"七言古诗","c":["男儿守身如守城，枕戈待旦中屏营。","男儿守节如持盈，临深履薄时兢兢。","眼中相识满天下，孝廉孰有如先生。","先生自处良不薄，独立鸡群类孤鹤。","读书往往师古人，气象森森近台阁。","去年走马黄金台，手持白璧归去来。","闭门却埽谢宾客，雀罗门巷荒苍苔。","山中野人经岁别，重过书堂散愁结。","半篱霜色映黄花，四座清风解烦热。","主人自号守斋翁，笑杀满城黄口童。","黄口儿童且缄口，听我山翁说翁守。","世人所守田与庐，此翁自守惟诗书。","世人所守钱与帛，此翁自守惟清白。","世人所守逢与迎，此翁自守惟坚贞。","世人所守名与利，此翁自守惟道义。","翁之所守予所思，泰山乔岳遥相期。","相期白首长如此，若问儿童那得知。"]},{"t":"寄赠闫季庸明府闫马卧仙受业恩师","f":"古风","c":["香山老将有奇节，匣里青萍三尺雪。","自从百炼受恩多，感激良工心倍切。","当时大冶跃精金，此日上方归巨阙。","心同铁石不销磨，身老风潮岂埋没。","出匣分明见胆肝，两手摩挲五情热。","生平怀抱为知音，当阳漫与时流说。","殷勤借问报恩谁，山西夫子非等夷。","欧冶门中无钝铁，马融帐底见威仪。","文章礼乐述周孔，刑名功利皆糠秕。","有时耳提复面命，不待严父加鞭笞。","有时解衣更推食，恍惚慈母怜婴儿。","天高地厚诫罔极，日临月照均无私。","登坛未遂凌烟志，把剑还思在冶时。","我闻将军言款款，我爱将军不忘本。","閒人洞见贵人心，馀生恨识先生晚。","先生之德高且深，先生之道舒能卷。","先生之教无藩篱，先生之寿无边岸。","但愿先生百亿春，眼见玉门归定远。","酒三觞，茶七椀。","高歌文水滨，永作隐泉伴。","白发参差总不知，黄河清浊休相管。"]},{"t":"芥舟行赠吴明府","f":"七言古诗","c":["坳堂之水何漭瀁，平地无风起波浪。","陆沉直到四禅天，蛟龙鱼鳖皆惆怅。","有人砥柱居中流，就地拾芥为虚舟。","江河日下不足道，从容鼓枻登瀛洲。","瀛洲去国八千里，鹍鹏奋翮搏风起。","水激波翻顷刻间，轻舟已涉坳堂水。","岸旁观者知是谁，隔江招手来迟迟。","济川用汝作舟楫，渡河焉用狂夫为。"]},{"t":"孝女挽诗","f":"古风","c":["何须慧剑断恩爱，儿女痴情等三昧。","何须大药回死生，期颐殇夭皆刍灵。","君不见隐泉马卧仙，达天知命无拘牵。","一朝孝女委幻泡，悲吟抆泪中拳拳。","问君孝女得闻否，细说聪明不去口。","生来三岁识之无，率性因心成孝友。","移鞋扇枕奉晨昏，色笑承欢非暂偶。","四岁受姆训，五岁习女红。","六岁七岁知大义，德言工貌咸贯通。","年甫八岁齿加长，置身直与姬姜两。","蓬莱仙籍早知名，合浦明珠先去掌。","病中诀别语喃喃，宽譬爷娘免悲怆。","明知寿夭天有权，生顺死安归自然。","蜉蝣岂慕冥灵老，蕣华不羡赤松年。","呜呼，丈夫有女贤如此，莫怪痴情聊复尔。","痛哭天低白日昏，猿鹤闻声皆陨涕。","无由招得女英魂，万古湘江同逝水。","为君写作述哀词，留与人閒作青史。"]},{"t":"寄祝春州广文霍朝望","f":"古风","c":["禄不必万钟，游不必五岳。","隐不必山林，仕不必台阁。","但愿一官清且閒，不愿杨州骑白鹤。","辞尊未必官遂卑，大儒首出称宗师。","条风偃草如反掌，新雨昭苏还及时。","井田学校相表里，文章礼乐如糠秕。","先生振铎阳春去，阳春有脚留难住。","山南山北互晴阴，日出日入成朝暮。","真机寂寞天何言，万象森罗道昭著。","雪边立遍问奇人，门外栽多桃李树。","我在罗浮读道书，五云西望怅离居。","崆峒洞里春长在，甲子山中岁欲除。","问年未信冯唐老，入世偏嫌惠远疏。","新诗题破鹅溪绢，遥托云中锦鲤鱼。"]},{"t":"铁佛颂与刘念兹","f":"古风","c":["金佛不渡炉，木佛不渡火。","泥佛不渡水，真佛内里坐。","真体显真如，幻花成幻果。","识得本来人，真幻无不可。","大冶良工用意深，铸出西来古佛心。","千里万里一条铁，天上天下无知音。","偶然垂手入廛去，灵山久别惊相遇。","携手长歌归去来，青莲坐断红尘路。","红尘路上置身高，百城烟水来方袍。","相逢拂拭开生面，金光丈六生蓬蒿。","日面佛，月面佛，无我无人亦无物。","点将顽铁成精金，净檀解作波罗蜜。","由我住，由我来，百千三昧一门开。","直入千山万山去，东林回首忆宗雷。","火可寒，冰可热，古貌古心如钝铁。","不应忘却补金人，到处眉毛互厮结。"]},{"t":"自春迄夏抱疴东林承豫章熊剑文惠药得差赋此致谢兼送其行","f":"古风","c":["医王用药如用兵，多多益善还益精。","先生得此作良相，岭南岭北咸知名。","一壶高挂门如市，闹中静注轩岐经。","雷公炮制得真诀，坎离既济丹初成。","大丹皎皎如秋月，小丹熠熠如流星。","青囊药裹留不住，光芒飞出香山城。","香山城外东林叟，闻人说项心怦怦。","一朝奇穷得奇病，闭门忍痛声咿嘤。","医王过我良不偶，恍有神物通精灵。","刀圭入口生羽翼，相将御风归太清。","先生劝我且住世，假我大药希遐龄。","金匮神剂益气饮，药炉旦夕蚯蚓鸣。","参苓持赠不足惜，一诺为重千金轻。","沉疴两月如隔世，艰难万死方一生。","自笑小乘衰相具，致累大人囊橐倾。","投桃报李非所喻，天荒地老难为情。","忆昔东林开社日，主宾相得如胶青。","蹉跎十戴老将至，溪上不闻三笑声。","两年病苦同寒食，十日霖雨天冥冥。","冷烟不绩香厨火，孤影独对虚堂灯。","儿童菜色不忍见，病夫骨立中屏营。","笑谓儿曹且安隐，老夫病起初学行。","行将走遍四天下，纵横八极如掌平。","熊先生，熊先生，四海之内皆弟兄。","君如天上风，我作水中萍。","天风披拂无远迩，萍水聚散何时停。","愿得杏林兰若长相近，吾道不患无居亭。"]},{"t":"仙城寒食歌四章 其一 尉陀墓","f":"七言古诗","c":["赤帝山河一百二，不致老夫无葬地。","春城寒食野花飞，朝汉台空锦蕞废。","当年黄屋自归臣，万古苍山思越吏。","沧桑有恨银海枯，草木无情翁仲睡。","猎火烧残隧道烟，龟趺半蚀苔钱字。","道旁驻马立踟蹰，居人指点荒丘是。","王气销沉奈若何，楼船去后泉扉閟。","不须回首问婴齐，汉家陵寝同兴替。"]},{"t":"仙城寒食歌四章 其二 刘主冢","f":"七言古诗","c":["亭山山下守陵户，日久都忘陵下住。","新蒲细柳掩松楸，绿墅青苗改封树。","春犁耕破垄头云，梓宫弃掷由童竖。","玉鱼金盌出人间，白璧明珠委行路。","自从众宝尽输官，剩有阴房穴狐兔。","山前啼鸟不知名，相呼相唤归何处。","流花桥下水声哀，素馨冢畔春光妒。","衮衣玉食能几时，白草黄壤等閒度。","令人长忆古轩辕，鼎湖龙去无朝暮。"]},{"t":"仙城寒食歌四章 其三 邵武陵","f":"七言古诗","c":["亢龙宾天群龙战，潜龙跃出飞龙见。","白衣苍狗等浮云，处处从龙作宫殿。","东南半壁燕处堂，正统未亡垂一线。","百日朝廷沸似汤，十郡山河去如电。","高帝子孙隆隼公，身徇社稷无牵恋。","粤秀峰头望帝魂，直与煤山相后先。","当时藁葬汉台东，三尺荒陵枕郊甸。","四坟角立不知名，云是诸王徇国彦。","左瞻右顾冢累累，万古一丘无贵贱。","年年风雨暗清明，陌上行人泪如溅。","寻思往事问重泉，笑折山花当九献。","怅望钟山春草深，谁人更与除坛墠。"]},{"t":"仙城寒食歌四章 其四 尚公坟","f":"七言古诗","c":["海珠海水流腥血，十万生灵冤莫雪。","杜康有力不借人，入室操戈凭曲蘖。","郎君本是拔山雄，一饮千钟双耳热。","座上杀人如草菅，府中聚骨成丘垤。","承恩赐射中金钱，至尊含笑称俺达。","归来虎视故眈眈，神器妄窥狂力竭。","黄带长悬鞅望心，赭衣遽与繁华别。","烟销火灭脊原空，白骨衔冤死同穴。","孤坟快与梵宫邻，疏钟敲落城头月。","夜台沉醉酒初醒，猛然悟得无生诀。","起来若遇绵上人，从前汗马休重说。"]},{"t":"埽雪歌","f":"七言古诗","c":["棕榈作帚竹作柄，与子相依为性命。","四山冻合室悬磬，主人不出贫且病。","茅堂紧闭雪方盛，鸡犬无声烟火凊。","弹琴高歌山谷应，钟期不来谁复听。","劳君为我一埽径，当有知音许乘兴。","扁舟过我山色暝，免教窘步苦泥泞。","主人款客不失敬，儿童出入随使令。","问谁荡涤寒威净，我则前驱君后竞。"]},{"t":"题云台摩汉图赠马卧仙移镇汉中","f":"楚辞体","c":["汉家台阁齐云峙，廿八元勋列筵几。","簪缨搢笏相后先，文采风流无彼此。","阳虚新息弟与兄，附凤攀龙均济美。","名高南国推伏波，铜柱铭勋著交趾。","后来绳武谁象贤，隐泉卧仙今继起。","出身便作第一人，中原尽识无双士。","当时直节著云州，大人侧目宵人靡。","一朝移守香山城，海不扬波郊不垒。","兵民安堵如一家，远近闻风若归市。","铃阁招宾仰白眉，棘门揖客来珠履。","分题授简续风骚，闭户著书先鲁史。","宦情澹薄孝心真，去国瞻云频陟屺。","乞休三疏屡陈情，传入长安纸争贵。","年来永废蓼莪篇，壮志犹存长剑倚。","摩汉台高瞰八荒，运海风生搏万里。","帝心西顾在崤函，简书南下推廉李。","粤人欲借寇雍侯，岘首长思羊叔子。","饥氓受赈感恩多，四野壶浆戴筐篚。","口碑留在路旁人，棠荫分阴遍桑梓。","我本东林猿鹤群，笑傲烟霞聊复尔。","多君不厌野人狂，入林十载成知己。","知己去兮天路长，山中人兮吾老矣。","他年棨戟许重临，云日溪山别还似。","写将一幅摩汉图，云台回首丹青里。","行矣先生莫惮劳，千秋事业踪前轨。"]},{"t":"挽劳封君","f":"古风","c":["我爱君家江上洲，十年两度维扁舟。","蹉跎记得旧时事，梦中筑室临清流。","醒来怅望复长笑，笑问虚空曾点头。","山僧意中知有翁，翁也知有山僧否。","生平妄想类如此，法界惟心聊复尔。","欲识祗园老主人，咫尺白云千万里。","主人满盛能持盈，主人富贵能知止。","主人有子皆儒官，主人拜命垂青紫。","室中綦缟齐孟光，绕膝孙曾列雁行。","晚年行乐在山水，乘兴扶筇入醉乡。","醉乡高枕日西夕，蓬莱仙侣遥相将。","一朝羽化御风去，红尘回首空茫茫。","嗟哉，人生百岁如朝露，少壮几何忽迟暮。","陈仓有粟须饭僧，布地还应作檀度。","前人遗泽先遗安，后人种德如种树。","思翁愿了未了缘，笑指河洲在烟雾。"]},{"t":"送蔚园弟之沅江幕，因寄吴明府","f":"七言古诗","c":["东樵好友吴芥舟，雄才大略誇壮猷。","一朝受命出神武，百里快有贤君侯。","良弓射雕先射虱，庖刀割鸡方割牛。","造物于君良不薄，大才小用皆有由。","我在东林久藏拙，腊时记得春时别。","雨窗夜话墨未乾，寘书怀袖明还灭。","思君高过岭头云，思君皎若洞庭月。","思君清比玉壶冰，思君白似银盘雪。","今来汉口守庚申，来岁沅江作主人。","种得桃花千万树，江山无地不阳春。","春风鹤梦遥相忆，日暮鸰原怅别频。","到时若问乡园事，莫笑原生病且贫。"]},{"t":"青燐歌","f":"古风","c":["百金市棺裹遗体，千金买山聚蝼蚁。","椎埋探出口中珠，痴杀年年守尸鬼。","新鬼旧鬼谁主宾，有声无声如诉人。","一灵皮袋不相顾，盲风黑雨飞青燐。","青燐遍野行人绝，冷光匝地明还灭。","高低零乱逐流星，远近欹斜傍残月。","乍如腐草化流萤，又如列缺驱奔霆。","却讶平原归猎火，翻疑远浦宿渔灯。","行人伫立复四顾，北邙累累谁家墓。","无复当年秉烛游，剩有孤明照泉路。","豕负涂，鬼一车，眼前所见徒区区。","君不见苌弘热血化为璧，防风白骨曾专车。","古今变化浑如此，人鬼迭代当何如。","青燐青燐归太虚，小巫击鼓大巫驱。","笑杀小巫与大巫，不识辽东白首猪。"]},{"t":"赠陈昆垂入学","f":"七言古诗","c":["生之生也气食牛，祖父爱之如琛球。","曾从我口授章句，过目成诵如泉流。","九岁通经知大意，十岁能文先制义。","纵横日课五千言，首尾不更三两字。","我年四十为腐儒，寻行数墨遵程朱。","三日一回频刮目，廿年久别当何如。","眼前世事殊匆草，少壮看看人已老。","我来旧社种莲花，生向环桥采芹藻。","羡生作赋拟凌云，羡生逸足能超群。","羡生良才不隐世，羡生乐道长安贫。","安贫乐道良不易，前路更多难了事。","愿言努力事驰驱，莫负老僧亲授记。"]},{"t":"送吴芥舟赴沅江县","f":"七言古诗","c":["世涂仕宦如沸鼎，芥舟先生心独冷。","世情临别多惆怅，东樵老僧笑鼓掌。","旁人问我笑何事，欲语不语难为计。","默默谁知世外心，哓哓恐触时人讳。","请君听我款款陈，男儿出处各有真。","山林朝市总一辙，伊周巢许非两人。","两人相知畴可匹，芥舟选官吾选佛。","沅江岩邑大如拳，湖上官衙仅容膝。","强似山僧不出山，土壁茅茨蔽风日。","时人莫笑沅江小，四面湖光周八表。","时人莫笑沅江贫，龙宫鲛室罗百珍。","时人莫笑沅江僻，日近长安天咫尺。","时人莫笑沅江閒，弹琴隐几看青山。","我笑先生怀利器，错节盘根曾未试。","藏锋敛锷直至今，甘与铅刀同钝置。","我笑先生游兴高，六年两度陵波涛。","长风破浪理舟楫，春满洞庭如感劳。","我笑先生最潇洒，琴鹤轻车随上下。","吟诗一路出湘潭，閒看儿童骑竹马。","我笑先生清且廉，盘中苜蓿水晶盐。","移来粉署伴冰檗，清风拂拂吹紫髯。","先生行矣勿复道，眼中之人殊草草。","长歌一曲反归来，彭泽闻之应笑倒。","别后相思笑不休，笑到宦成人已老。"]},{"t":"爆竹行","f":"七言古诗","c":["东村儿童夜秉烛，小除大除忙鹿鹿。","牵衣绕膝索金钱，得钱欢喜无钱哭。","朝来分队趁市去，卖去痴呆买爆竹。","满袖携来笑不休，相呼相唤还相逐。","一声霹雳送穷神，木客山魈走回禄。","白发老僧双耳聋，渊默雷声契幽独。","出门笑问里中儿，若个旁观若当局。"]},{"t":"赠双照笑溪师","f":"七言古诗","c":["野干大作狮子吼，笑溪忍俊不开口。","赤梢跃入齑缸中，笑溪海阔天宇空。","跛驴逐队事行脚，笑溪卧游周海岳。","鸱鸮嚇鼠贪复嗔，笑溪自视何如人。","笑溪今年五十一，假我数年方七十。","两人相见将无同，浊河泯泯无清日。","一年一见一回悲，鬓边白发交参差。","眼中之人吾老矣，舍此更有知音谁。","今来且喜身犹健，中秋月照故人面。","秋月明明似昔年，故人面目随时变。","明朝日出东复西，早起溪边逢笑溪。","笑声落在无声处，天籁地籁齐不齐。","阿谁献笑吾与子，座客旁观皆助喜。","五十年前古佛身，无端混迹红尘里。","红尘紫陌眼中沙，翠竹青松锦上花。","难兄独觉弟补处，无著天亲会作家。","羡君不出大庾岭，羡君不吃云门饼。","一瓶一钵境中人，千水千山人外境。","西畴归牧驯白牛，南圃寻僧续胜游。","留客乘凉修白业，晚来坐月话通幽。","鹊巢古木人初定，钟度前溪山欲暝。","荷沼分题诗句新，竹林煮茗茶烟冷。","年年八月八风清，八景当前八咏成。","留与名山为话柄，期将眉寿作居亭。","居亭眉寿寻常事，地老天荒终及第。","笑杀当时老赵州，屈指驴年才百二。"]},{"t":"飞云绝顶鸡鸣见日歌","f":"古风","c":["人间昼短苦夜长，三竿日出方下床。","此间昼长嫌夜短，半夜鸡声昏晓判。","问君长短胡不齐，却缘见地分高低。","赤鸟初生顾兔死，觉者自觉迷自迷。","呜呼，安得石榻千万亿，纵横胪列飞云西。","登峰到顶须我友，同来高枕闻天鸡。"]},{"t":"赠陈翁寿","f":"七言古诗","c":["立身当如陈太丘，生子当如孙仲谋。","娶妻当如孟德曜，学仙当学张留侯。","我闻当今有遗逸，绛县春秋过九十。","汾江江上钓鱼回，塔坡坡畔扶筇立。","有时一饮快千觞，有时高枕傲羲皇。","有时雄谈惊四座，有时缄口如括囊。","阶下芝兰杂丛桂，元方难兄季难弟。","官山私淑管夷吾，挟策追随端木赐。","长文孝先皆象贤，风流文采何翩翩。","儒林早竖鸡坛帜，大州半刺方待年。","室中綦缟谁家子，鹿门远嗣徽音美。","悬弧设帨相后先，参差黄发齐儿齿。","我在山中今白头，翘首元龙百尺楼。","见说德星重聚里，遥知海屋更添筹。","此日葭灰吹六律，此日梅花开五出。","阳回冻谷日初长，花发华堂香满室。","祝翁不用杯与盘，祝翁不用炰与燔。","挹将东海为卮杓，挈取南山作酒尊。","我翁未醉更受爵，我翁既醉请赠言。","年年今月与今日，容我山人来叩门。"]},{"t":"题东华侄诗文集","f":"古风","c":["生子不愿为腐儒，寻行数墨成蠹鱼。","教子莫教治生产，求田问宅徒守株。","君不见渥洼龙种千里足，高视阔步陵天衢。","安能俛首随款段，血汗伏枥悲盐车。","忆我伯兄九谷子，先世分室城东居。","一朝落地为兄弟，先后雁行如贯珠。","七岁同师授章句，八岁九岁能操觚。","十岁为文学声律，弟兄唱和无时无。","大庭广众弄柔翰，满堂宾客争称誉。","伯翁我翁莞尔笑，私心相庆阳谦虚。","我年十三举博士，自誇逸足能先驱。","须臾阳九天改步，儒冠高挂归田庐。","伯兄十五始入学，一举再举登贤书。","兄年十九我十八，从此出处天渊殊。","兄方及弟两出宰，廿年不调思归与。","我年四十入山去，终老不材如大樗。","殊涂同辙各有以，盖棺事定当何如。","伯兄不死赖有子，快哉一马生三驹。","中间神骏不可测，少不相从东郡趋。","有时绕膝闻诗礼，有时出郭随蹇驴。","有时承欢郯子国，有时定省来姑苏。","孺子可教更可畏，制义帖括宁区区。","吟诗直欲祖风雅，初盛为主中晚奴。","文章寝食饱秦汉，三唐两宋皆皮肤。","而翁所学有真诀，心传口授无精粗。","小子狂简志高远，良玉未及分瑕瑜。","秋风飒飒树不静，废书读礼日月徂。","太初堂上见手泽，白门城外闻啼乌。","故园归去问封树，总角今来成丈夫。","我时卧病一百日，朝来起坐须持扶。","归人解装席未煖，闻我老病深嗟吁。","自携诗卷过桥去，行吟直到南山隅。","吟声未歇履声近，病夫下榻开绳枢。","入门再拜谁家子，谛视方知封与胡。","去日垂垂髫夹囟，归时鬑鬑微有须。","去日斑衣事儿戏，归时博带飘长裾。","人生少壮会如此，使我日暮悲穷涂。","问子来意胡为乎，袖中有物能卷舒。","琅玕出手光照席，索我落笔为点污。","我身既隐文何有，汝言可采良不诬。","开卷一唱复三叹，掩卷大声还疾呼。","九谷子，九谷子，有子如此道不孤，有子如此道不孤。"]},{"t":"挽泽萌和尚七哀歌","f":"楚辞体","c":["我所思兮在华亭，孤舟来往江波清。","龙蛇混杂双眼明，车螯缩爪虾努睛。","晚来钓得赤梢鲤，三界横身棹臂行。","呜呼，一歌兮歌一唱，满船明月空惆怅。","我所思兮在丹霞，开炉烹佛称作家。","三岩高处天雨花，狸奴白牯眼着沙。","长者峰前见宾主，石头路滑空波吒。","呜呼，再歌兮歌再歇，海螺吹落千山月。","我所思兮在栖贤，师王踞座五老前。","百鸟衔花觐法筵，千峰流水归玉渊。","一声长笑别三峡，丘壑无光山寂然。","呜呼，三歌兮歌三叠，须臾便隔僧祗劫。","我所思兮在海云，祖翁田地荒耕耘。","象王归耕耕日曛，一期建立殊功勋。","大除灯火日面佛，劝请住世徒殷勤。","呜呼，四歌兮歌四愁，鸟啼双树声啾啾。","我所思兮在怡山，欲去未到身先还。","鼓山斫额非等閒，祖庭虚席遥瞻攀。","半途息肩日西夕，清风早入仙霞关。","呜呼，五歌兮歌五噫，只屦单提谁得知。","大人大人生马驹，四蹄蹴踏无贤愚。","不动鞭影先驰驱，羞与驽骀追步趋。","房星掩曜天驷殒，渥洼接踵鸣天衢。","呜呼，六歌兮歌六匝，疋练横空风飒飒。","小人小人号顽牛，他家水草曾淹留。","朝辞主人归故丘，晚来相见西溪头。","横吹铁笛人何处，顾影惊心水自流。","呜呼，七歌兮歌七哀，何时携手归乎来。"]},{"t":"题闽僧怡山八咏","f":"七言古诗","c":["野人独钓烟波外，眼中不识乾坤大。","岁晏扁舟入海云，舟中有客名痴卖。","相逢赠我袖中诗，品题八咏穷幽奇。","恍惚怡山与神契，欲去未去心先驰。","今年别我归长庆，春江送客风尘静。","迟我名山欲问程，寻君旧话先乘兴。","十朝绀殿今何如，月夜幽钟人定初。","丹荔流霞辨生熟，长松鹤唳遥相于。","中济归僧无去住，石湖烟雨时相遇。","门临乌石笑点头，碧涧泉声引归路。","此时此景非等閒，紧俏麻鞋远近山。","凭君报语山翁道，岭外顽牛老更顽。"]},{"t":"题回舟图赠何伍菊","f":"古风","c":["苦海有船长七尺，不用施篙还挂席。","顺风能去逆风回，随流直至无生国。","华亭船子笑呵呵，满眼波涛奈若何。","从此到江吴地尽，分明隔岸越山多。","吴越山川行已惯，随缘取足随缘办。","嫩冬瓜煮鳖裙汤，新粟米炊鱼子饭。","快矣哉，快矣哉，殷勤报语老宗雷。","及早回舟归去也，莫教红日下香台。"]},{"t":"元旦掩室示诸子时年六十六","f":"古风","c":["行年未到六十六，慎勿笑人指爪曲。","而今而后吾免夫，从此馀生易知足。","去岁新年忙鹿鹿，今岁新年快幽独。","一间茅屋一个僧，一炷旃檀一寸烛。","一声清磬一卷经，一碟黄齑一椀粥。","造物于我良厚哉，同住同来受清福。","自誇有褐不须裘，何须得陇更望蜀。","当今大人不重贤，当今小人不信天。","当今学人不学律，当今禅人不会禅。","时来移气复移体，自谓古佛堪齐肩。","门庭喧喧炙手热，盲龟跛鳖争垂涎。","我欲为此自不难，面庞有血囊无钱。","汝曹脚跟未点地，二者居一随经权。","若云未能免俗聊复尔，不忍尽弃其学而学焉。"]},{"t":"谢黄汪千惠茗","f":"古风","c":["老僧长斋三十年，眼前世味皆腥膻。","清泉白石供饮漱，浓华澹薄殊天渊。","年来衰病且消渴，地炉活火时烹煎。","非无村茶及野荈，入口羞涩如戈鋋。","我闻武夷之山山九曲，三十六峰名洞天。","中间草木蕴灵气，紫茸绿叶生春前。","山人摘茶带星月，提筐归去凌朝烟。","风时火候发香味，心灵手敏通经权。","三瞻四顾方什袭，奇货可居稀入廛。","知音千里远相访，杖头罄解青蚨钱。","一朝驰入大庾岭，真香真色犹新鲜。","老僧内热唇齿燥，闻名注想空垂涎。","多谢主人黄叔度，散步行歌来日暮。","袖中分得建溪春，留与枯禅作甘露。","千顷汪波见素心，两腋清风涤烦虑。","惊起林间病渴人，相呼相唤吃茶去。"]},{"t":"寿洪母","f":"七言古诗","c":["男儿立身须及早，强仕服官亲已老。","男儿爱日在承欢，百年喜惧非一端。","何如当今洪氏子，天伦乐事谁可比。","母也圣善子明经，七闽五岭咸知名。","名动临轩身未出，安阳待捧毛生檄。","北堂设帨时未央，朱明日永兰桂芳。","儒冠采服朝戏舞，大孙鸣琴小击鼓。","门前车马如云屯，昌言美誉纷前陈。","有人拜首扬母节，贞松翠柏凌霜雪。","有人避席称母慈，养成雏凤丰羽仪。","有人赞叹颂母德，减膳分餐苏菜色。","东樵野老闻所闻，一曲长歌寄五云。","五云多处群仙宴，麻姑西姥遥相见。","河浊河清海浅深，瑶池一会到于今。","手栽庭砌三株树，拂日凌霄作天柱。","东樵拭目几回看，看取金桃受恩遇。"]},{"t":"答庞策斯兼柬冼厚光孝廉","f":"七言古诗","c":["鸡声断续鼓声咽，布被蒙头双耳热。","飞蚊扑面蚤跳踉，四壁鸣虫尽饶舌。","老夫半夜不曾眠，移床去就梅花月。","旧梦不如新梦佳，起坐空斋书咄咄。","庞君在世颇聪明，得得相寻微漏泄。","夜来梦作赤梢鱼，受侮沙虫甘涸辙。","须臾化作金翅鹏，撞破天根空月窟。","鸴鸠斥鴳笑不休，遍界苍蝇自喧聒。","梦中说梦不自知，真幻凭君为决别。","前村更有冼孝廉，方便寄声如是说。","莫怪痴人说梦多，当局者迷观者哲。"]},{"t":"挽陈逸峰","f":"古风","c":["读尽天下书，胸中无一字。","学究解谈禅，心空先及第。","前有陈尊宿，后有陈居士。","两采合一赛，非同亦非异。","在家如出家，在世如出世。","童心壮志等前尘，慧业文人任游戏。","儒冠挽取桦皮冠，制义还他第一义。","脚跟踏破不二门，闻薰直入三摩地。","自从亲见作家来，诸方拭目推宗雷。","灵山一会俨然在，睹史陀天首重回。","大笑出门留不住，分明记得来时路。","青云双塔锁千松，种松道者今何去。","珍重毗耶久默人，留得帆园末后句。","三生石上好重来，相逢更有商量处。"]},{"t":"腰石歌","f":"楚辞体","c":["圣贤现作凡夫身，獦獠岂是寻常人。","本来面目不增减，皮肉骨髓非所论。","有时量等须弥卢，有时摄入邻虚尘。","力绵体弱志不小，耸肩竖脊能负薪。","朝朝荷担入城去，道旁侧耳闻经句。","应无所住生其心，分明识得黄梅路。","槽厂无人独任春，碓嘴花开知落处。","夜半三更衣锦回，西天衣钵今南来。","米熟犹存坠腰石，相将携手出黄梅。","当时凿破混沌窍，麻绳紧系顽垒堆。","贼人赶趁猎人养，万苦千辛不肯放。","留在南华老方丈，要与儿孙为榜样。","儿孙得此多倚仗，安坐端居需供养。","前人已化空遗踪，后厨有米无人舂。","我来问讯一稽首，摩挲拂拭尘埃蒙。","絜之一肘侧五指，长短广狭依稀同。","外边方直刓圭角，中间内附如张弓。","我腰量与祖腰似，石重石轻何彼此。","试将故物横在腰，想到黄梅更舂米。","于今舂米岂无人，为法忘躯能有几。","精粗生熟不自知，妄想壁閒书半偈。","堂上人随堂下痴，野干唤作金毛狮。","冬瓜印子大如粟，面门印破矜希奇。","真龙活象匿山泽，蝇屯蚁附相师资。","二时粥饭虚信施，不辨精凿还糠秕。","石兮石兮，吾将与汝觅方便，还山有路无人见。","置身物外任点头，一笑相逢须自荐。","荐不荐，炼石补天天也穿，砥柱中流流不变。","何如侧作枕头眠，庑下佣舂非所羡。"]},{"t":"刘吟祉偕严周二子过大通赋赠","f":"古风","c":["可惜荔枝红易落，佳客不来山鸟啄。","红稀绿暗掩荆扉，茶熟香清思旧约。","何人江上驻扁舟，惊起沙边閒白鸥。","林间犬吠知有客，短墙倚望凝双眸。","闻声识客客不俗，行吟直到树边屋。","谛观乃是意中人，昨日面生今面熟。","白莲社长刘驎之，严陵周党遥相期。","馀閒更坐三生石，长日惟消百八棋。","棋罢花间陈玉馔，清斋留与山僧饭。","客来已过午钟鸣，非时未敢行方便。","高人饱食自主宾，野老傍观各任真。","谈谐坐到日西夕，有约重来莫厌频。","竹边笋，花下藕，寻常茶饭吾家有。","荔枝落尽龙眼生，嘉果还堪嘉客口。","乘兴来时及早来，莫待午堂钟板后。","临行一句更叮咛，瓶汲山泉休载酒。"]},{"t":"寿双桂天公","f":"古风","c":["震旦秪林秋近晚，双桂花开方烂熳。","阎浮变作荆棘丛，双桂清阴遍洞中。","洞中主人谁氏子，今古蟠根千岁李。","渊源家学五千言，十八破家无一字。","无端闯入杂华林，破颜微笑逢知音。","三登九上浑閒事，一见愚关便息心。","汾阳不肯保福莫，赵州八十犹行脚。","吾师出处迈前贤，流水行云无住着。","廿年寄迹古虞园，十字街头深闭门。","菩提树下恣游戏，自称獦獠真儿孙。","祖父閒田半稂莠，忍俊旁观甘袖手。","金徽玉局伴奚囊，扫荡声闻旧窠臼。","借问春秋今几何，百岁光阴强半过。","一吸西江乾到底，岂知东海有风波。","风静波恬孤月现，大通烟雨遥相见。","我住鹅潭师住城，一口金针三尺线。","鸳鸯绣出自天然，举似时人多不荐。","请师绣作优昙花，清光一道凌紫霞。","请师绣作无影树，觌面金风全体露。","请师绣作五色云，光华复旦咸氤氲。","请师绣作白伞盖，遍覆大千无内外。","我亦当时学绣人，粗缯大布不知贫。","自笑年年压金线，袖携刀尺向东邻。","何似天孙得天巧，七襄云锦人间少。","天衣裁就奉天亲，顶髻花冠长不老。","天师翁，天师翁，心灵手敏诚化工。","更凭绣作日面佛，千古万古扬宗风。"]},{"t":"白沙先生梦长髯道士手挈一囊贮罗浮山遗之纪之以诗黄子汉人奇其事继以长歌予见而复奇之赋此以广其志","f":"楚辞体","c":["道学先生生妄想，默与飞云互来往。","识神打破无极圈，钻入枕头呈伎俩。","长髯道士白沙翁，一主一宾非有两。","函盖乾坤括作囊，大地名山失高广。","四百馀峰掌握间，袖中出入供幽赏。","入囊见山出见囊，握手作拳拳作掌。","卷舒由我更由谁，授受分明如影响。","恍兮惚其中有物，惚兮恍其中无象。","日轮飞出海门东，天鸡啼破妄中妄。","何如芥子纳须弥，留与虚空为榜样。"]},{"t":"挽邓母吴太君","f":"七言古诗","c":["昔有高人吴仲书，笔花幻出真芙蕖。","兴来赠我一大轴，画工如山逊不如。","我时握手发大笑，多君厚意非区区。","山僧本是种莲者，识得莲花真与假。","真花非色亦非空，不用丹青更图画。","西方圣人老画师，万法惟心心不知。","虚空作纸须弥笔，香水之海为墨池。","写作莲花花九品，五色五光空五蕴。","有人直下便承当，垂手提携亲接引。","先生领话无几何，翻身跳出莲花涡。","一花一叶独留赠，连枝同气仙陀婆。","仙婆去后谁堪似，阿姥逢僧发欢喜。","古佛巍巍金色身，留与宝光受瞻礼。","大兴佛事非偶然，檀那不取功德天。","金银台上七宝地，一超直到燃灯前。","燃灯含笑受记莂，清净流璃贮明月。","刹那现作居士身，珍重重来为君说。","君家有凤栖梧桐，九苞养就翔高风。","阶前手植三珠树，众雏鸣和何嗈嗈。","归时踏著来时路，佛光佛寿长如故。","白莲池上笑相逢，万德庄严金色聚。","殷勤寄语女丈夫，曾见而兄领话无。","文殊不出女子定，待我罔明来更苏。"]},{"t":"送容西渡典教饶平","f":"七言古诗","c":["先生于我称世友，曾记鸡坛逐游走。","绛帐趋庭莱子衣，玄亭问字侯芭酒。","酒阑舞罢各西东，阶前老树摇悲风。","大鱼化鹏奋奇翼，鸴鸠斥鴳随飞蓬。","路旁车笠一相见，云泥惆怅何匆匆。","前年客自冈州至，闻说园林多胜事。","凿池引水种莲花，叠石为山起平地。","主人爱道不爱金，布地延僧宣妙义。","寄语能来及早来，尘世閒人閒不易。","我闻客语信还疑，琼林讵有鹪鹩枝。","山僧只合居岩谷，国士筵中实不宜。","缄书报命无可说，大笑还山弄明月。","葭苍露白正怀人，香浦秋风又离别。","琴书满戴广文船，倾城祖饯车骈阗。","摩挲老眼烟霞外，新诗遥寄水云边。","我闻饶平好山水，东去潮阳方百里。","昌黎过后寂无人，八代文章凭振起。","莫道先生官秩卑，圣朝重道先尊师。","莫道先生致身晚，白首青云兴不浅。","莫道先生斋舍清，拥书万卷当百城。","莫道先生薪俸薄，苜蓿晶盐堪细嚼。","先生行矣勿复道，济溺起衰非草草。","暂时别却好园林，直向环桥采芹藻。","芹藻何如池上花，一度繁华一枯槁。","功成名遂早归来，只恐寻僧僧已老。"]},{"t":"挽香山毛果泉","f":"楚辞体","c":["我忆东林池上水，浸地涵天清彻底。","我忆东林池上人，珠圆玉润时相亲。","果泉居士居其一，秋水为神玉为骨。","有时过我讲老庄，从容入室先升堂。","有时过我习禅定，磨破瓶砖成古镜。","有时过我出新诗，琳琅照壁光离离。","有时过我作佛事，四相三轮通二谛。","我来久住识人多，檀门熟道频波波。","三生石上见宾主，口虽不言心默许。","一朝别去两三年，水在池中月在天。","东林寂寞池水竭，天低月落琼枝折。","琼枝折兮林木空，桑榆影薄来悲风。","野人近住鹅潭上，潭上云山互相向。","一片閒云万里心，高山流水谁知音。","子期欲铸黄金贵，独抱无弦望天裔。","一弹别鹤与孤鸾，回首东林如隔世。","果泉居士知未知，黄梅路上遥相期。","种松道者今何去，乘愿重来尚未迟。"]},{"t":"郑珠江太史还京过大通话别赋此以赠","f":"古风","c":["白衣留却别大颠，玉带输将还野禅。","两人可一不可再，古今浩浩争流传。","何如珠江郑太史，早向儒门契宗旨。","金鳞跃出凤池头，亲见龙颜动欢喜。","大通古寺塪井蛙，泥涂汨没随鱼虾。","一声打鼓送官客，笑杀城中白鼻騧。","由他笑，由他骂，智珠擎出请酬价。","等閒不值半文钱，用时光照四天下。","不落有，不落空，不在西，不在东，只在当人掌握中。","何用留衣与留带，木樨花下来香风。"]},{"t":"送愿来禅友之海南","f":"古风","c":["世间不遣有名利，陌上应知无别离。","斯言脍炙今人口，聪明汨没同愚痴。","梯山航海争走险，涂穷日暮相追随。","谁能掀翻窠与臼，曰有丹霞狮子儿。","君不见南溟之水名天池，大鹏奋翼摩天飞。","鸴鸠斥鴳不敢渡，仰首大笑称希奇。","借问图南何所取，舍名与利将焉之。","翱翔蓬蒿亦已足，飞抢榆枋聊待时。","大鹏一往不回顾，抟风直上高高处。","名闻利养两不知，海阔天空随去住。","无可舍，无可取，临行记得向上句。","六月一息便归来，大知小知相对语。"]},{"t":"草圣歌赠张明府子白","f":"古风","c":["灵兔脱颖铦如锥，束身归命供指挥。","紫羊之肝青麟髓，相将水石同襟期。","楮生辗转拂玉案，借问主人何所为。","主人隐几鸣琴罢，春来公事方休假。","官船几日到珠江，山川一路明如画。","乘兴重来访旧游，藉草班荆理前话。","林间飒飒风雨生，解衣磅礡深经营。","须臾伸纸作大字，虎踞龙蟠雷乍惊。","心王运臂臂运指，巨灵赑屃随驱使。","临池飞出北溟鱼，含毫吸尽西江水。","左拿右掣妙无端，一疾一徐皆至理。","行乎其所不得不行，云傍马头生。","止乎其所不得不止，山从人面起。","鹅溪绢，剡溪纸，日与簿书堆案几。","盘根错节何有哉，慧剑一挥胥披靡。","从容阁笔为予言，我生能事聊如此。","大通野老麋鹿群，见所未见闻未闻。","置书怀袖日三复，逢人说项殊殷勤。","昔之张芝今张旭，后有大令前右军。","斯人家学溯源委，十三学书先草隶。","蕉黄米蔡等秕糠，颜筋柳骨分精髓。","撞破烟楼读父书，手泽羡君能述继。","羡君不羡才与华，羡君不羡名与位。","羡君下笔如有神，羡君能诗由夙慧。","青云送入选官场，白社归来还及第。","百千三昧何浅深，一悟了然无钜细。","君不见公孙大娘舞剑器，草圣得之通妙谛。","心灵手敏匪言传，破格超方须默契。","也不即，也不离，此是灵山亲嘱累。","慧业文人记得无，三生石上曾分袂。","归去来，归去来，峡水峡山未迢递。","留将一道无字碑，明日再来烦作记。"]},{"t":"寄怀杨鬯侯","f":"古风","c":["昆山大士才八斗，学富三冬穷二酉。","文章直出两汉前，诗篇不落三唐后。","呜驺佩玉多故人，目送飞鸿曾未有。","一朝大笑行出门，万里长风事游走。","燕昭台上不逢人，大庾岭头寻好友。","美人为政清且閒，莲幕生涯如瓮牖。","促膝朝看郭外山，篝灯夜对他乡酒。","酒酣发箧出雄文，主人赞叹何殷勤。","曰公不是池中物，相将致雨还兴云。","已有长弓穿七札，莫因鼷鼠轻千钧。","壮心未老窃自许，束书归阁中欣欣。","莼羹鲈脍罢弹铗，松膏藜火明宵分。","六经六艺如六谷，砚田一日三耕耘。","辍耕识尽天下士，但恨不识二禺君。","禺君近在中宿住，乘兴将寻读书处。","中涂邂逅郑安期，指点閒鸥在烟雾。","烟消雾霁客初来，风便潮生却归去。","溪边送客如有情，别后思君还作赋。","思君雄论如建瓴，思君意气如兰馨。","思君高怀如岳峙，思君静致如渊停。","禅心皎皎如孤月，道眼炯炯如双星。","士生斯世得如此，何能怫郁牖下终穷经。","嗟予与君同甲子，君方有用予无成。","云泥缁素各努力，沧浪可浊还可清。","洗我足，濯君缨，振衣千仞笑声声。","别峰相见一招手，须向毗卢顶上行。"]},{"t":"古剑篇赠彭艾庵","f":"古风","c":["美人腹中怀古铁，出胎犹带玄黄血。","一朝欧冶鼓洪炉，跃跃祥金成巨阙。","新硎霜锷势莫当，临敌一挥皆创伤。","主人恩爱良不薄，摩挲拂拭教深藏。","铅刀鈯斧失犀利，偷心侧目纷疑忌。","龙屈蛇信奈若何，半边夜有丰城气。","壮士得之游八闽，脱身飞出延平津。","归来依旧函玉匣，倾心竭力酬主人。","主人顾盼倍畴昔，铅刀鈯斧低颜色。","批虚导窾有馀閒，解纷排难无遗力。","从来神物难淹留，百炼聊为绕指柔。","何能郁郁久居此，眼看若辈皆封侯。","一日一揩磨，一年一淬砺。","辗转一百年，顽金成利器。","何况金石浑成日月光，天地泰交水火济。","我本山中人，望空遥盼睇。","愿君努力干霄云，旋转乾坤豁阴翳。","一道灵光迥不磨，报恩直到无穷际。"]},{"t":"闻霍西牛说家住富春山之胜跃然欲往赋此订同住之约","f":"七言古诗","c":["红尘白日分交驰，青山绿水遥相思。","年几七十人未归，高才疾足先得之。","昨宵稳卧鹅潭上，梦入崆峒自来往。","中途邂逅意中人，未问寒暄问佳况。","但言家在富春山，别有天地非严滩。","松风万壑听不尽，绝无消息到人间。","痴人妄想妄开口，深山更有深山否。","沉吟半饷方点头，君但能来山便有。"]},{"t":"屈五无极过宿话旧","f":"古风","c":["老友不堪成久别，白发纷纷牙齿缺。","我笑先生未休歇，仰首高天双眦裂。","先生笑我生计拙，火宅翻身冷如铁。","无极翁，莫重说。","明日阴晴知若何，留君话尽鹅潭月。"]},{"t":"彼美行送杨鬯侯归江南应举","f":"七言古诗","c":["苧萝彼美名西施，浣纱溪上花开时。","香风吹入锦裙带，文章五色光离离。","自矜昭质独殊众，轩车五两来何迟。","春华秋实老颜色，夫尝一日颦蛾眉。","昨夜银灯对明月，灯花爆出双琼枝。","起来拜月望牛女，秋风有约遥相思。","今岁槐黄通姓籍，明年冰泮定归期。","贫家有女贞不字，长斋绣佛空尔为。","晨钟晚磬罢歌舞，灰头土面无胭脂。","相闻相送难为赠，妆箱盈歉自应知。","环佩玎珰趋凤阁，珠玑璀璨映龙墀。","玉堂金屋深如海，荜户蓬门知是谁。","归来稽首空王道，此身长愿老茅茨。"]},{"t":"送李广文远霞司训揭阳","f":"古风","c":["臣也师也父兄也，如鼎三足车四马。","富人贵人閒道人，如行有伴居有邻。","三者缺一均不可，一之二之成彼我。","閒道人，畴不尔，富贵贫贱皆相似。","师臣父兄谁克当，揭阳先生马山李。","东樵之友孔门徒，柱下之孙崇义子。","一朝受命作儒臣，倾城祖饯车辚辚。","白鹅潭上钓鱼叟，仰首青云识故人。","临岐欲赠无可说，笑指前车看前辙。","前涂那得有閒缘，閒到为官忙不歇。","朝逢迎，暮干谒，日接诸生苛礼节。","苜蓿阑干希送钱，冷署寒毡谁立雪。","门前桃李成畏途，望风疾走争回车。","内圣外王等糟粕，出名入利交锱铢。","前车覂驾后当戒，岂效若辈徒区区。","崇义传家应不薄，两袖清风归负郭。","父肯播，子肯穫，方寸良田任开拓。","清白之后大有人，天将以子为木铎。","提聋警聩振颓风，老我閒人甘寂寞。"]},{"t":"题龚雪心白描罗汉卷","f":"楚辞体","c":["雪心老人身姓龚，自称画禅非画工。","游丝白描擅能手，千卷万轴无雷同。","昔曾见翁写罗汉，今见罗汉如见翁。","翁与罗汉一而二，伸纸挥毫事游戏。","恢恑谲怪皆有神，神运心兮心运臂。","最初幻作伟丈夫，高坐师王擎钵盂。","复次幻作老缘觉，摄受和南无住着。","复次幻作降幺么，小鬼大鬼肩相摩。","复次幻作擎宝塔，塔重塔轻无定法。","复次幻作憨长汀，儿戏场中笑不停。","复次幻作痒和子，背触翻身声洞耳。","复次幻作般舟定，合掌跏趺泯喧静。","复次幻作声闻僧，手持贝叶翻金经。","复次幻作梵宫殿，指端涌出云端现。","天上人间注目看，聋盲喑哑交钦羡。","复次幻作洛伽山，一道神光万古閒。","善财渴仰观自在，有人端坐竹林间。","复次幻作大化主，缨络严身持宝杵。","鹿苑高僧补衲衣，药炉童子烧香炷。","后来伏虎并降龙，狞貌慈颜指顾中。","虎鬼龙神各皈命，旁观仰首空瞪瞢。","受楮先生长八尺，中间钜细穷幽颐。","不分缁素及髦倪，岂辨溪山声与色。","七条衣，六环锡，行住随身俱委悉。","铁轮如意钵多罗，只手提携只手搦。","动者动，植者植，情与无情含八识。","一时摄入白毫端，万象森罗明历历。","雪心雪心将无庸，打翻跟斗还虚空。","一回开卷一回笑，笑到慈氏离天宫。"]},{"t":"观李雪樵明府新制龙尾车图式述为长歌寄邑明府姚齐州兼广其传","f":"古风","c":["近水知有龙，近山知有虎。","我住白鹅潭，自称老渔父。","问我何所见，问我何所睹。","我实无所见，我实无所睹。","七月八月天暵乾，神龙致雨涳濛閒。","屈伸垂尾搅云脚，天旋地转波涛翻。","云中隐隐见水气，逆流喷薄疑飞湍。","商量拟作激水法，心口愤悱神力殚。","曾闻西洋利玛窦，师心巧过公输般。","制器尚象无不有，玉衡平衡浑等閒。","竹木为车效龙尾，剜转汲乾沧海水。","倾湫倒峡挽天河，日浸桑田盈十里。","见所未见闻所闻，想像虚无空拟议。","古今作述谁后先，泷水神君绥山李。","生来博学早成名，作令爱民如爱子。","前年大旱草木枯，田家争水犹争珠。","神君蒿目桔槔拙，县门揭出龙车图。","鸠工庀材集众巧，运斤絜矩随奔趋。","初为轮轴持两极，循环转毂同天枢。","三围四方五斜杀，纵横不爽锱与铢。","爰命筠工剖巨竹，截钉编筏旋螺腹。","中分水道自逶迤，一脉泉原通九曲。","松膏镕液胶漆牢，周遭肉好无盈缩。","从容刳木为车墙，合体成圆用各方。","精金百炼作簨簴，卧轮旁击相低昂。","大器晚成姑小试，一夫抽水如抽汤。","中虚外直通大道，事半功倍宁荒唐。","留将榜样似同志，语大语小皆精义。","同身尺寸随短长，应运风雷起平地。","持来古寺逢老僧，妙用当前得未曾。","四大假合幻非幻，天工人代能者能。","神君大笑入帘去，为雨为霖留不住。","缄书寄语姚令公，莫放龙车宿烟雾。"]},{"t":"赠萧君荫举孝廉公车北上","f":"古风","c":["老人独钓秋江水，水浅水深清见底。","神鱼跃出蕊珠宫，无限鱼虾跳成市。","一声霹雳烧尾雷，钓鱼老翁倾两耳。","借问神鱼何处来，借问雷从何处起。","桂岭秋光花正开，锦水月明珠出胎。","美人昭质抚明镜，光辉映彻黄金台。","金台此日延国士，鹿鸣燕罢嘉宾来。","闻风髣髴识名姓，东林旧社思宗雷。","旧社相过池上客，若祖若翁推巨擘。","神交道合两忘年，觌面论心通语默。","我时搔首见二毛，即君总角方齐额。","读书万卷笔有神，眼阔如箕心似发。","须臾鼓箧过横桥，终童早擅文章伯。","念我神交祖与翁，负剑辟咡来从容。","老人谦让日三复，郎君执礼犹温恭。","生平结交满天下，过眼一过如飞蓬。","快哉三世真相识，但恨不识河池公。","河池事业在人口，宦成两袖归清风。","清白传家自今古，承先启后皆儒宗。","文孙不忝曾与祖，烟楼撞破先登庸。","之子自无需富贵，时人未免先科第。","我在鹅潭罢钓丝，注目青云起天际。","萧孝廉，莫濡滞。","直到长安看杏花，前路正多难了事。"]},{"t":"赠罗伟甫举孝廉上公车","f":"七言古诗","c":["君家兄弟吾老友，二十年前共游走。","乱离避地同鹿门，贫贱移家各株守。","大兄讲学述程朱，群季文章迈韩柳。","鸡坛竖帜不让人，莲社寻僧镇携手。","座中雄辨相发挥，肘后奇书互疑剖。","平生同学据要津，目送飞鸿未曾有。","须臾聚散等浮云，往事不堪更回首。","一年一别一相寻，壮志销磨貌衰朽。","老来匿影珠江南，枕流漱石临溪潭。","秋风吹冷破茅庵，仰天搔首霜毛毵。","故人惠我书一函，浣手拭目方开缄。","闻君柳汁湿青衫，鹿鸣宴罢控两骖。","旁观叹息真奇男，使我自笑还自惭。","旧游已贵高岩岩，刈蓍岂免忘蓍簪。","樗栎不材非楩楠，支离山泽分所甘。","长歌短曲凌烟岚，送君北上乘风帆。","长安春暖花可探，曲江酒酣乐且湛。","乘车戴笠各努力，他日相逢方细谈。"]},{"t":"赠李慕山","f":"七言古诗","c":["慕山先生清且閒，不爱市朝惟爱山。","慕山先生坚且癖，不爱苞苴惟爱石。","先生爱山夫何如，探幽选胜遵南车。","一声长啸空谷应，巨灵俛首随奔趋。","先生爱石良有以，万仞孤峰觐屏几。","玉润冰清迥不磨，天形道貌长相似。","先生早岁缨儒冠，文章声价倾长安。","逢场压倒元与白，阳春一曲知音难。","乞休林下身未老，万卷诗书恣幽讨。","攒眉不肯入东林，逐队春风踏芳草。","萼楼兄弟附青云，兰砌儿孙长凤文。","山静日长松柏古，朱霞白鹤超人群。","我亦当年同学者，归向马山曾结社。","惠远无如靖节高，三笑溪桥归去也。","廿年一别能几时，青山白首遥相思。","题诗寄语函关老，牛背奇书赠与谁。"]},{"t":"郑珠江太史特授给谏拜命日诗札见寄赋答一章遥致相期之意","f":"七言古诗","c":["南方有鸟生桂林，九苞五色何森森。","一鸣再鸣天下闻，三鸣谱作箾韶音。","翱翔直上木天去，宫商妙叶薰风琴。","重华协帝大欢喜，赓歌咨尔谐朕心。","朕心欲广求言路，衮职有阙畴当补。","手持白简出词林，拜首彤墀受温语。","退食沉吟思古人，千秋事业遥相许。","史鱼如矢不足多，岭南直道肩相摩。","曲江风度著金鉴，后来更有崔菊坡。","大声秀才动人主，百折刚峰迥不磨。","山人上书议大礼，布衣越俎光岩阿。","古今贤达信不少，超前轶后当如何。","宵衣假寐夜中饭，焚草封章坐待旦。","听鸡骑马行出门，陌路回车避台谏。","搢笏批将颔下鳞，牵衣攀折廷前槛。","大臣小臣心胆寒，远人近人拭目看。","故山猿鹤久岑寂，孤峰独立思长安。","何人手挹天河注，大地为霖复为雨。","馀波写入锦霞笺，重叠泥封封不住。","鲤鱼寄书江水流，江水春生閒白鸥。","珠江渔父今何处，翘首五云天际头。"]},{"t":"转经颂为卫母寿","f":"古风","c":["仙陀婆子太聪明，倩人代转金刚经。","大师下座行一匝，虚空合掌侧耳听。","五千四十单八卷，卷卷转毕无濡停。","婆子大笑复申请，尚馀半藏须圆成。","师王默坐不动地，雷音奋迅开疑情。","婆子领话乃稽首，龙象蹴踏皆闻声。","两重公案谁料理，卫家寿母多男子。","长斋绣佛自年年，筑室饭僧聊尔尔。","法轮转转转不休，一波未平一波起。","大通古寺老古锥，闻声见相生欢喜。","借婆帔子拜婆年，是则是矣似亦似。","似何似，高似白云山，深似沥江水。","法量高深寿量同，真经一藏从兹始。"]},{"t":"舍利浮图纪异呈邑明府姚齐州","f":"古风","c":["朱明洞天明月寺，僧有远公作佛事。","范金铸塔通幽明，供养如来真舍利。","十方诸佛现全身，八部天龙分侍卫。","九环宝顶无量光，四句伽陀最深义。","紫檀刻作须弥座，金相玉质殊坚致。","有时黑月放光明，有时白日生云气。","凡夫肉眼浑等閒，开士灵心契神异。","秋风擎出杂华林，寄向宝光无佛地。","远公杖策入罗浮，空留宝塔陵高秋。","塔高一尺魔一丈，虚堂雀鼠鸣啾啾。","钟前鼓后走胠箧，神光匿影随东流。","明灯礼佛失舍利，人天怅惘僧悲愁。","韦驮大士擎宝柱，兀立不肯回双眸。","老僧领众日祈祷，鸡鸣人定声不休。","尊天乃起运神力，澄汰恶浊成清浏。","幺么褫魄自皈命，入门稽颡轮愆尤。","宰官现身发悲悯，赖有慈父姚齐州。","饥寒切身失廉耻，罪虽可惩情可周。","殷勤提奖出首实，塔光返照莲池头。","片言折狱出郊去，手持綵棒鞭春牛。","春牛白，春牛黑，昨朝角触今犁轭。","春牛肥，春牛瘠，昔日咆哮今稼穑。","放下綵鞭一事无，弹琴隐几看春色。"]},{"t":"南海神祠古木棉花歌","f":"古风","c":["君不见南溟之水如汤盘，浴日浴月涵星垣。","闭塞地户开天门，西台庙古神赫烜。","垂衣拱手端临轩，身骑白马扬朱翻。","立马看花花正繁，木棉树老高云屯。","千尺百尺迎朝暾，赩如野火燎高原。","琼枝天际蟠昆崙，珊瑚海底撑乾坤。","其高也如此，不知几历寒与温。","榑桑若木为弟昆，月华仙桂皆儿孙。","一枝一叶含一元，一华一实归一根。","一生二，二生三，三三生万物，生生不已天何言。"]},{"t":"南海神祠古铜鼓歌","f":"七言古诗","c":["范铜作鼓叶律吕，牯牛下拜鼍起舞。","问渠拜舞何所为，自幸有皮无足取。","范成悬在海王祠，一雄一雌相耳语。","我本山中矿石精，无端跃入大火聚。","欧生倒寘古规模，不我为钟却为鼓。","大叩逢逢小咽咽，随声答响聊尔汝。","何时飞入水晶宫，潮音作风雷作雨。","回看白牯与玄鼍，皮之不存毛焉附。"]},{"t":"五星躔度歌","f":"古风","c":["大哉圆象齐方舆，仰观俯察均皇图。","紫垣北极帝所居，太微天市邻京都。","十二次舍罗交衢，二十八宿为蘧庐。","五行五纬随居诸，黄道赤道相驰驱。","有时累累如贯珠，有时落落分方隅。","群分类聚岂有殊，声应气求良不孤。","昨宵星聚牛女墟，占星夜发天官书。","三台八座弘庙谟，连城合璧皆璠玙。","岁星乃是中大夫，太白曾为仙酒徒。","火南水北持两枢，镇星静镇番与禺。","文明应运交相孚，登高作赋谐笙竽。","明月皎皎藏冰壶，景星熠熠辉含誉。","昭回云汉澄江湖，璿玑错落光石渠。","赓歌逸韵追唐虞，天清地宁游以娱。","南皮宾从多应徐，谈天邹衍胡为乎。","众星拱北今何如，天门无路曳长裾。","噫欷歔，星辰在天人在涂，比肩接踵争先趋。","迟留伏逆数不诬，勾已芒角徵则符。","著明垂象会如此，何能怫郁长守株。","吾将以尻为轮，以神为马，六气之辨以为车。","追飞流，排彗孛，挟五曜而游乎六虚，身虽老矣心区区。","噫欷歔，大哉圆象齐方舆，身虽老矣心区区。"]},{"t":"送澹崖师归隐华封山","f":"古风","c":["大人之患不识时，小人之患好为师。","天花乱坠黦泥土，野干自谓师子儿。","江河日下失砥柱，慧命不绝如悬丝。","老僧老眼看一过，忍笑不住长歔欷。","休歔欷，眼前所见类如此，澹崖智者独不尔。","手持鈯斧出华林，入门敲出南樵髓。","南樵老人道眼高，识尽龙头与蛇尾。","肋下三拳?处亲，转怒回瞋作欢喜。","相呼相唤别华封，踏上黄山万念空。","九夏安居忙不彻，故山归去卖松风。","松风到处无人买，持赠鹅潭潭上翁。","莫草次，且从容。","酬君一柄锄云镬，耕遍千峰还万峰。"]},{"t":"拟忼慨歌送智泓禅者归北山旧隐","f":"古风","c":["丛林可住而不可住也，深山不可住而可住也。","丛林而可住者，粥饭次第，香花络绎，利养富庶。","其不可住者，人我山高，生死海阔，尘牢狱固。","去而入山，苦无闻见，胼手胝足以作务。","深山安可住也，然与鹿豕为徒，猿鹤为侣。","出则笠雨蓑风，耕田种芋。","入则息影松阴，安禅衡宇。","不知有名，焉知毁誉。","不知有利，焉知积聚。","深山不可不住也。","君不见智泓智者薄善知识而不为，向北山之北而归去。"]},{"t":"龙江黄桓思出秋诗见质赋此以赠","f":"古风","c":["秋诗唱自梁郁洲，一时作者争波流。","大为荐雷小叩缶，黄钟瓦釜相应求。","老人老矣心未休，无端河西皆善讴。","昨夜吟君十九秋，明月满天镫满楼。","照见五色花纹虬，此时此景谁同游。","人如其诗清更幽，诗如其人彫且修。","当今风雅徒汗牛，珷玞什袭矜琛球。","君有嘉谷方播耰，良田早种须晚收。","幸不揠苗助长如宋人者，与君努力耕春畴。"]},{"t":"话雨堂英石歌","f":"古风","c":["主人爱石如好友，坐卧与俱行与耦。","花边竹底倍关情，苍苔白石长居守。","新辟閒园结草堂，万象森罗莫须有。","巨灵无计补虚空，五丁奔命穷罗搜。","深山大泽到交衢，神物韬光混尘垢。","选奇罄解杖头钱，转运凭将河曲叟。","云头雨足飞上船，壁立崖崩惊纳牖。","主宾握手快平生，珍重客尘频抖搜。","觌面昂藏七尺躯，旁观下拜如俯首。","本来面目铁肝肠，岂肯折腰徇五斗。","却愁圭角不囊藏，未免伤锋还犯手。","君不见孔嘉三命循墙走，直道难容聊曲就。","落草盘桓待点头，九年面壁牢缄口。"]},{"t":"赠李善藏入学","f":"七言古诗","c":["揭阳先生生季子，聪明不与群儿比。","东郡趋庭侍绛帷，取次学诗还学礼。","学诗压倒元白翁，学礼笑杀叔孙通。","出风入雅写情性，左揖右让何从容。","院公一见大欢喜，首簪金胜肩拖红。","妙龄释褐人所羡，千夫百口声相同。","太胥击鼓催发箧，五经如日朝出东。","过眼一过辄成诵，罢琴舍瑟归横宫。","大人刮目小聛睨，才高礼下犹温恭。","我在隔江望云物，江城佳气何葱郁。","鹏雏飞上九万程，鸴鸠斥鴳偷心失。","寄言同类谩相猜，寥廓高翔畴与匹。"]},{"t":"丁亥元旦示徒","f":"古风","c":["生恨不生空劫边，亲见藏海生红莲。","此身岂有八万四千岁，过现当来在眼前。","半生枉学道，问著总茫然。","学道不学儒，学道不学仙。","学道不学律，学道不学禅。","学道不学魔与外，学道不学圣与贤。","止学自家真面目，娘胎透脱金刚圈。","也不参究，也不攀缘。","也不入保社，也不赴经筵。","一口无底钵，一个破蒲团。","尽人与我皆有分，饥来吃饭困来眠。","此是新年新佛法，珍重逢人莫浪传。"]},{"t":"王屋山人琢砚歌和徐琶洲作","f":"七言古诗","c":["弘农陶泓大叫笑，山人凿破混沌窍。","崖崩峡坼端水乾，出实入虚穷窈窱。","载魂抱魄顽不顽，次第运转涳濛閒。","飞光耀目动权贵，明驼领取出梅关。","一卷礧砢见遗掷，山人得之深赏识。","大璞不琢由天然，天君独运非人力。","紫羊迎刃露肝胆，鸲鹆披沙偷觑眼。","青花绚采烟雾霾，黄龙吐气卿云烂。","三瞻四顾几经营，一圆一方胥有情。","婆娑火蜡发光怪，皮肤剥落存晶瑩。","琢成贮以流黄锦，出入与俱瞑与寝。","晴窗疏注娲皇书，炼石补天天敛衽。","琶洲高士徐铎愚，囊中倾出灵蛇珠。","一唱三叹尽刻画，山人持入山僧庐。","老眼摩挲观不足，随声答响呈幽独。","有人问我山人谁，陈子臣张号王屋。"]},{"t":"柬邑明府姚齐州索蜡石","f":"古风","c":["大通一室如斗大，芥子纳山山纳芥。","奇峰摄入夜明帘，远近搜罗遍空界。","昨暮山中买石归，朝来冷市携云卖。","金银生像戒悭贪，爱石成痴甘破戒。","番禺主人如水清，扁舟过我春风生。","自誇有石立堂下，俯视一切殊峥嵘。","光明皎洁天下士，巉岩礧砢山中僧。","山僧见说神气爽，欲见未见心先倾。","朱门慵作曳裾客，白屋聊为倒屣迎。","缄书致语谷城叟，静中久坐须经行。","我闻三山之下有五石，五仙骑羊成幻形。","古今变化不可测，神物或复通精灵。","仙令丹砂煮将熟，一饱挟取随登瀛。","不妨过我欢十日，兴尽任尔还仙城。"]},{"t":"赠周贲新茂才","f":"古风","c":["最初识君何处边，云窝万仞孤峰巅。","我方强壮君盛年，高视阔步相后先。","客来入室大欢喜，拂拭几榻相周旋。","乃云治食当入市，举手揖客姑流连。","所居去城二十里，左右前后无人烟。","草鞋奋迅过奔马，提筐往返如飞仙。","须臾楗椎起速客，市中所有盈斋筵。","我时饱食方洗钵，合掌赞叹居亭贤。","高才疾足事云水，何难撞破三禅天。","善财慧眼马驹脚，君乎君乎胡不然。","君阳谦虚阴自许，注目相视心相怜。","别来今昔各殊世，风尘回首成天渊。","三衣卸却改缝掖，万里风云高著鞭。","老人独钓鹅潭水，潭水水清清见底。","大鱼小鱼夜不眠，飞入芦花明月里。","何人买棹一相寻，牢锁重关净如洗。","主宾款洽异当年，惆怅出门留片纸。","姓字传来忆未真，须眉说著疑相似。","似不似，昨日云窝求寂人，今竹杏坛门弟子。","灵山一会记得无，莫忘瞿昙亲嘱累。","君家古佛坐道场，直裰承当建宗旨。","归去分明举似翁，父母未生何者是。","要识那吒骨肉无，问取金刚周大士。"]},{"t":"邑明府姚齐州致政纪事","f":"七言古诗","c":["他人在官门如市，我公在官门如水。","他人去官门如水，我公去官门如市。","借问公门近若何，喧声动地黄埃起。","士夫释业农辍耕，黄童白叟肩相比。","山陬海澨走若狂，攀辕卧辙无遐迩。","邻封比邑有同情，越陌度阡何彼此。","里杵宵春将授粲，村灯夜织承筐篚。","小儿竹马野人芹，迎送交加均赤子。","千人万人通一心，大声疾呼盈百里。","九重高高唤不闻，四野萧条失怙恃。","我公大笑出县门，停车谓众且莫喧。","县官为国抚群盗，盗弭官閒勿复论。","心劳计拙愿休假，仔肩暂息皆君恩。","前官于民聊尔尔，后人似我来源源。","殷勤父老早归去，及时教子还弄孙。","父老承风尽稽首，天上天下闻此言。","口碑载道见遗爱，公论在人名不谖。","野史近添廉吏传，先数齐州姚炳坤。"]},{"t":"送张子白明府归里","f":"古风","c":["长安贵人骑大马，清远清官归邺下。","水陆销支买鹤钱，糇粮罄尽修琴价。","奚囊转重宦囊轻，手版长抛歌板罢。","周行如砥直如弦，一路吟诗到家舍。","道旁送者谁与谁，白发山人来劝驾。","君不见绥山李雪樵，解印归田事耕稼。","又不见番禺姚令公，计拙心劳快休假。","同声相应好相求，同病相怜不相借。","寂寞东林旧主宾，惆怅莲花自开谢。","有缘聚似露珠团，无缘散若瓶水泻。","清风留作岭头春，棠阴蔽芾无冬夏。","野老空馀去后思，古道至今成话把。","归去来，归去来，天路仔肩猛然卸。","濯足临清漳，振衣登太华。","名山有约待同游，向平未老须婚嫁。","不用重寻忼慨歌，廉吏不可为而可为也。"]},{"t":"观乐块然作指头画却赠","f":"古风","c":["天地之大一指也，造物化工成造化。","山川草木露精神，风云雷雨供挥洒。","混沌初开假即真，大地平沉真复假。","高悬一指在虚空，留与人閒作图画。","先生先生人也天，自称块然非块然。","手灵心敏破常格，指头揭出拈花禅。","爪生甲长一粟许，函盖乾坤三大千。","扁舟过我坐未稳，大惊小怪呈空拳。","空拳竖起无名指，一阖一辟机锋圆。","须臾索纸见技痒，管城老矣甘归田。","甲端点墨指点水，浓澹浅深皆至理。","溟濛云气自空来，兀突孤峰从地起。","老眼旁观得未曾，天工人代难思议。","大哉伟丈夫，善哉奇男子。","耳目迥尘根，肝胆无渣滓。","浩气横空亘古今，万象森罗方寸里。","区区一指何足多，指天指地须如此。"]},{"t":"挽毛明府","f":"七言古诗","c":["岁星本是金门客，化作阳春布膏泽。","丹徒盘错试牛刀，导窾批虚罄心力。","羞将聚敛博循良，宁拙催科受迁谪。","一曲长歌归去来，大小山堂花正开。","芝兰并挹天雨露，丛桂同根月殿栽。","齐年卫武犹好学，读书万卷反说约。","名言高咏破群蒙，象帝空王添注脚。","当涂束帛来戋戋，桃李无言玄又玄。","相逢笑我木偶佛，我笑先生烟火仙。","烟火神仙难久住，乘风羽化登瀛去。","空留木偶在人间，带水沾泥日西暮。"]},{"t":"丁亥生日自首","f":"七言古诗","c":["山穷水尽日西暮，老景无多罪无数。","文逋笔债积如林，多半引年兼誉墓。","乖张名实点清虚，破犯初篇成妄语。","自甘拔舌入泥犁，不免刀山还剑树。","此身九死一可生，赖有羞惭及疑惧。","同是世閒无智人，四大假合成幻身。","遭逢贤劫佛住世，使我得作伽蓝民。","不耕不织不冻馁，无礼无义无尊亲。","白毫一分人天供，饕饕虚消不自重。","何况重添粪上花，制锦徵诗耀徒众。","一时举国走若狂，狸奴白牯胡厮閧。","头会箕敛通贤愚，香花得钱铙钹送。","舍曰欲之为之辞，高坐道场说春梦。","世间寿者悉如斯，自称等觉原等痴。","小人之痴痴到骨，大人痴在毛与皮。","学道年过七十一，腼颜空腹为人师。","身口意业忏不净，虚生浪死徒增悲。","不须说著母难日，人命无常知未知。"]},{"t":"即席急就寄题王领军澹宁堂","f":"古风","c":["澹宁主人洵澹宁，雄才大略今干城。","眼前台阁有山水，胸中仁义为甲兵。","偶来卜筑就羊石，开池留月涵虚明。","月明写影近桐树，枝高风爽来秋声。","秋声吹入月窗里，夜静天阶凉似水。","轻裘缓带掀紫髯，饮酒赋诗追大李。","诗成徐步绕花行，四面香风袭衣袂。","兴来坐石藉芳茵，长啸清歌皆至理。","却嫌城市无好山，买石连云归袖底。","横堆叠树拟蓬莱，旁观抚掌称奇哉。","天台雁宕不足数，嵩华衡岱遥相猜。","玲珑八面供指顾，行住坐卧堪徘徊。","山僧本是爱山者，闻之神爽心先写。","欲到城中试一看，紫陌红尘畏车马。","伸纸挥毫一赠诗，更须借重块然先生为作指头画。"]},{"t":"再续前题备述园林花石之胜兼送领军入觐","f":"七言古诗","c":["块然之指迹删笔，澹宁主人神仙骨。","眼中之石意中山，地上之花天上物。","三人相对成一人，奇花怪石遥相亲。","未曾品花先品石，巉岩磊落通精神。","英峰苍翠宣峰洁，大理黑白湖山皴。","主人兼爱无彼此，搜罗合作席上珍。","五丁拔山出远岫，千夫飞挽归城闉。","安排布置得宜称，低昂俛仰由天真。","选工追琢备众巧，床屏几案光鳞鳞。","砚北古松出天目，白石堆盘美如玉。","拳枝侧干类风斜，虬鬣龙鳞映华屋。","屋边凿石作清池，类聚群分饶水族。","金鬐吹沫槿花红，银甲摇波莎草绿。","绿莎红槿互婆娑，掩映池中双芰荷。","亭亭独立群芳表，中虚外直无偏颇。","远风吹香满四座，芝兰同室葆天和。","黄花翠竹写情性，蜀茶仙杏连根科。","古桂含香待明月，腊梅先雪凌高柯。","百花丛里桐花实，大树门庭玉树多。","玉树高承仙掌露，南天桢干标铜柱。","汉台待筑上林春，主人骑马朝天去。","临川磨剑逐风云，华亭返棹随烟雾。","沉吟三笑别居亭，前路云泥怅延伫。","许留花石与山人，相伴衡门慰迟暮。"]},{"t":"寿诗","f":"七言律诗","c":["九天雨露桃花肥，行地老仙行若飞。","飞上桃花最高树，连花带子盈筐归。","归来分与儿孙吃，满腹文章光陆离。","老仙一饱一万岁，拍掌笑杀丁令威。"]},{"t":"华亭张北山过大通见赠赋答","f":"七言古诗","c":["隔江闻有北山翁，如雷灌耳心先通。","曾从卷帙见佳句，百尺寒冰洗尘虑。","出闻儒者讲理学，同声合喙推先觉。","为访程朱似续人，游遍八方周五岳。","轻车指北还指南，直到仙羊方驻脚。","席不暇煖突不黔，延伫二樵神跃跃。","与来杖策入朱明，四百峰头啸一声。","更寻七十二峰去，信宿云端吟月明。","行吟更问江门道，白沙祠墓生荒草。","登堂一拜一题诗，银榜贞珉传丽藻。","归来过我大通禅，袖出新诗见怀抱。","诗中许我王老师，是则是矣非亦非。","老师不打鼓与笛，大通鼓笛全不识。","诗中许我如澹公，似则似矣同不同。","澹公无可无不可，大通有可有不可。","诗中许我为忠孝，教外何曾涉名教。","先生名教有住著，大通名教无住著。","早来池上看莲花，莫放莲花自开落。"]},{"t":"贺圆老师主席庆云","f":"古风","c":["三年不飞飞冲天，搅混世界旋乾坤。","三年不鸣鸣惊人，狮子丧胆狐窜奔。","老师本具菩萨心，无边刹土随现身。","撑住门庭春又春，刍卢掩室修正因。","宝华王座生埃尘，幺么领出诸波旬。","野干据室天地昏，藏身北斗甘隐沦。","龙蛇掩蛰云雷屯，久默斯要屈复信。","黑风吹散魔家民，慧日天光重发新。","百川赴海星拱辰，高踞大雄持庆云。","打开宝藏皆家珍，四凡十圣归陶甄。","钱贯井索左右陈，罩篱木杓上下根。","一时煅炼成精金，洪炉跃出光鳞鳞。","大通白发老声闻，举手加额珠江滨。","愿师法量如海垠，愿师道眼如月轮。","包荒云水无主宾，辨别龙蛇谁假真。","八十不须更行脚，直向毗卢顶?行。"]},{"t":"寿丁宪使刘太夫人","f":"楚辞体","c":["巍乎高哉，中条之山多列仙。","佳气南与星峰连，豸袍彩服来翩翩。","潘舆到处萱花妍，三郡一州咸管弦。","康衢鼓腹歌遐年，跻堂介寿初月圆。","火树银灯辉玳筵，麻姑劝酒相周旋。","瑶池远致青鸾笺，开缄墨沈流霞鲜。","玉书金简文昭宣，大哉坤德静以专。","康哉母寿贞且坚，青松翠柏相后先。","履霜傲雪凌苍烟，两间一气无偏全。","春花秋实瓜瓞绵，九天雨露如醴泉。","群仙共醉和风前，乐莫乐兮玄又玄。","见者闻者皆垂涎，山中猿鹤诚颛颛。","圣凡悬隔殊天渊，长歌翘首崧台边。","随风飞出朱明天，愿母寿，亿千千。","方瞳绿髓神炯然，伫看冠雀衔三鳣。"]},{"t":"答连山李礼山明府见寄","f":"古风","c":["美人为政心如水，百尺澄潭清彻底。","洪纤灵蠢总包荒，游泳潜沦胥托体。","阳春有脚不留行，大道为公无彼此。","邃初槃瓠长儿孙，伏莽负嵎均赤子。","自从单父静鸣弦，猺獠苗蛮争侧耳。","八排六峒风气开，昔时顽梗今廉耻。","罢琴隐几看青山，宦情摄入诗情里。","目送蜚鸿远兴生，一路吟诗赴郡城。","秋风过我松寮下，话别林间片月明。","重来有约理归棹，公事曾迂几日程。","挂帆夜渡珠江浦，海潮有信风无情。","我时西望发长啸，几欲寄书迟雁征。","腊尽冰消春水长，烟雨濛濛荡双桨。","何来远札款荆扉，拂袖清风快幽赏。","开缄三复一沉吟，劳君千里虚提奖。","自笑不如鲁仲连，坐看东海成桑田。","天下车书归正统，借地开池种白莲。","自笑不如夷与叔，普天何地非周粟。","北俱卢洲长粳米，饱食无瞋亦无欲。","自笑不如缠涧民，怀沙未是解空人。","一片蒲团趺两膝，寂莫东风过耳轮。","置书怀袖中，奚啻什袭珍。","索居非所惜，古处通精神。","山中莫问松年纪，惟问桃花几度春。"]},{"t":"题张北山太极行乐之图","f":"古风","c":["游遍东西南朔，究竟关闽濂洛。","淹贯典坟丘索，镕铸精华糟粕。","驱役风云电雹，成就文章著作。","静似澄潭碧落，动若枢机橐籥。","清比朱霞白鹤，高等泰山乔岳。","悟到先天天不言，坐断湖山山一角。","手持一卷太极图，默与濂溪添注脚。","五行一，阴阳也，诚无为，机善恶。","阴阳一，太极也，入一门，闭六凿。","太极本无极，也领真如归寂莫。","用之则行舍则藏，此是北山真行乐。","遥寻竺土契参同，直溯横渠绍家学。"]},{"t":"送石广文赴西粤分考","f":"七言古诗","c":["香山广文石娥啸，学究谈禅穷典要。","斋珠缀领作朝珠，古调希声成别调。","麟经领荐是何年，走马金台正英妙。","抟风奋起北溟鹏，开笼放出新罗鹞。","蹉跎几度上公车，抱玉还山赋遂初。","谢公久注苍生望，陶令先回白社车。","寻师亲入圆通室，契道参同教外书。","虚空打破作明镜，窠臼掀翻擎智珠。","智珠系在儒巾角，抛却簿书徇木铎。","手握金篦入铁城，净刷嚣尘归澹薄。","苜蓿盘中谁送钱，棂星门外堪罗雀。","诸生屏迹萧生来，说有谈无差不恶。","先生本是佛仙儒，萧生自号古之愚。","师资针芥良不偶，问奇载酒徒区区。","山僧近住鹅潭上，钓得锦江双鲤鱼。","静山冷署见宾主，烟雨空林念索居。","索居室迩人不远，出岫云心自舒卷。","断科使者一纸书，撮合神交来早晚。","三生石上一相寻，半月扁舟频往返。","坐消暑气散尘襟，又赋西征趋棘院。","漫说閒官閒似僧，捧檄驱车去不停。","才经五里又千里，行过山程更水程。","临岐欲赠难为赠，一抱无弦弹月明。","曲终我亦还山去，云水茫茫空复情。"]},{"t":"朝天行赠王固山裕公入觐还粤见过","f":"古风","c":["天气清宁疑蘸碧，天象穹窿如屋极。","天家近在五云边，天威不违颜咫尺。","小人望天天九重，大人格天天一德。","凤皇振响仪天庭，啼鴂鸣鸠胥屏息。","大鹏奋翼抟天风，鹪鹩斥鴳低颜色。","人生大小各有天，天上天下宁悬隔。","我翁本是天上人，身骑天马乘天驿。","朝天到日天门开，朝天归来天路直。","天衣出箧带天香，天书开卷承天泽。","建牙吹角天鼓鸣，驻节维舟问良觌。","昨日领军今固山，回首天衢旧相识。","山人乃是天下人，头带高天忘帝力。","日中见斗天宇宽，蔀屋窥天虚室白。","王乔一别去朝天，今来重见朝天舄。","朝天归去当何如，巩固山河比磐石。","我作朝天行，持赠朝天客。","天阙重重指顾间，延伫天南望天北。"]},{"t":"题漆振伯赠言卷后","f":"七言古诗","c":["忆我始识壮士时，西江水决横塘陂。","长官顺流放巨舸，平通竹岸穿花篱。","入门便问水深浅，出定老僧茫不知。","须臾壮士剌船去，历尽千村还万户。","田高田下费商量，江北江南归指顾。","从容返命借箸筹，话到前川日西暮。","老僧揖客问姓名，旁人欲语先低声。","此翁不是寻常客，卑视郭解齐荆卿。","儿时不乐戏俎豆，揭竿斩木驱群英。","十三便笑舞阳怯，十五能请终军缨。","身骑竹马谒幕府，抵掌谈笑销戎兵。","结发辞家佩长剑，吴越山川游已遍。","驱车燕赵访佳人，寂莫金台人不见。","肝胆相从国士知，须眉岂逐风尘变。","美人为政怀古欢，旧游万里偷弹冠。","行縢结束岭南去，大道宁忧行路难。","赋就长杨思狗监，栖迟安邑馈猪肝。","猎心每逐烽烟动，侠骨那堪短褐宽。","升平日久休兵革，腥风飙起萑苻泽。","匣里芙蓉试一鸣，飞光褫取鲸鲵魄。","卖刀买犊为何人，革心革面伊谁力。","长歌归去不施劳，风雨连床无愧色。","当局旁观知未知，此翁不是寻常客。","善刀不肯杀痴顽，读书不屑循行墨。","结交不用盟鸡坛，论功不作鸱鸮嚇。","要识此翁姓与名，江西漆郎字振伯。"]},{"t":"赠张樵叟","f":"五言古诗","c":["堂上青云客，壶中白发年。","置身三对策，娱老七条弦。","自薄雕虫技，言耕养鹤田。","渔樵同去住，烟火作神仙。","得意诗中画，无心酒后禅。","曲江风度古，博望子孙贤。","海国悬弧早，梁园授简先。","露滋丛桂发，秋晓碧梧坚。","有客山中至，寻君世外缘。","倘能爱狂简，应许闯华筵。"]},{"t":"寿佟方伯","f":"五言古诗","c":["川岳钟贤哲，风云起壮猷。","经纶天可补，带砺国同休。","铁券传三锡，金门觐九旒。","恩波随扈跸，霖雨遍瀛洲。","率土河均润，殊方泽未周。","帝心专简在，天眷属怀柔。","连帅今方伯，屏藩古列侯。","秉衷何简简，敷政独优优。","中泽鸿初集，卷阿凤暂留。","阳春开寿域，煦日照遐陬。","槐省三公树，微垣百尺楼。","高山长在望，野老漫凝眸。","杕杜难为致，甘棠可共游。","愿言思召伯，敢望识荆州。"]},{"t":"舟过南海神祠纪胜五十二韵","f":"五言古诗","c":["方舆会有极，元气混无涯。","四大水轮住，千江海印持。","昆崙接云汉，溟渤潴天池。","万派宗南澥，群峰巩北维。","祝融熙帝载，习坎答南离。","庙貌崇今古，明禋洽岁时。","堂皇依岛屿，制度出班倕。","波影摇银壁，霞光罥玉墀。","周垣丹以雘，夏木蔽还亏。","朱凤翔阿阁，雕龙绕绣帷。","神君端黼黻，像教肃威仪。","徽号丝纶锡，恭文碣石垂。","金题悬日月，铜鼓列雄雌。","邃寝齐眉媛，回廊斫额夸。","纲珠交掩映，香篆互参差。","花雨承珠靸，晨风满桂旗。","百灵纷总总，群动信熙熙。","帝力夫何有，神心予所知。","溯洄由夙昔，俯仰在今兹。","浮海身将老，轻舟晚更移。","潮平黄木港，花发谷王祠。","越陌寻芳径，磨崖读故碑。","鸿文推哲匠，弘构仰成规。","土木因时革，沧桑任运为。","槃谈遵世谛，慷慨有遐思。","延伫看山色，沉吟续楚辞。","飘零悲泛梗，珍重荐江蓠。","工祝传神语，征人指路岐。","禅心通陟降，逸兴入逶迤。","隔壁寻僧话，沿阶引鹤随。","海光钟寂寞，旦过客栖迟。","香积浑薰莸，蒲团厕菉葹。","太虚宁轸域，周道岂平陂。","怅别东林社，裴回古殿基。","亭高名浴日，海阔见朝曦。","石磴缘苔藓，雕甍枕碧漪。","兴难辞跋涉，行不厌孤危。","历巘舒清啸，凭栏咏古诗。","坡公留墨沈，词客叶埙篪。","蜗篆明还灭，龟趺仆更欹。","摩挲瞪两睫，取次策双眉。","蜃气呈真幻，鲛宫集瑰奇。","虎门天锁钥，鱼石郡藩篱。","螮蝀穿云脚，凫鹥浴水湄。","渔家收蚬米，田舍足粳糜。","几处烽烟熄，三春士女嬉。","神人胥庆快，老少自扶携。","俗俭芹堪美，年丰酒可酾。","桑麻仍旧业，鸡黍订前期。","莲国程伊迩，桃源路不迷。","欲随江燕住，却恐野鸥疑。","明发乘虚舫，洞天寻圣师。"]},{"t":"寄郑珠江给谏","f":"五言古诗","c":["天上金门客，林间白社人。","风云供吐纳，鸾凤露精神。","近识潜龙跃，宁同尺蠖伸。","文章超哲匠，出处迈群伦。","拾芥科名早，登瀛物望新。","履声绳祖武，砖影轶前尘。","董笔推良史，潘舆有老亲。","木天曾注籍，桂浦暂閒身。","举世为形役，惟公得性真。","杯棬方爱日，风树忽经春。","怀古今犹昨，匡时德有邻。","报恩终报国，忧道不忧贫。","握手相知晚，论心惜别频。","上方留笑语，北阙返词臣。","山静宜孤鹤，时清见一麟。","封章欣入直，飞札笑逃秦。","拜命嘉平腊，题诗上巳辰。","求声中宿应，学步少陵陈。","点检溪桥约，沉吟粤海滨。","问年吾老矣，七十尚迷津。"]},{"t":"寿庞明经","f":"五言古诗","c":["南海衣冠盛，东山物望专。","鹿门绳祖武，虎观仰前贤。","古道江河下，清风水石边。","中流凭砥柱，薄俗仰陶甄。","白首明经日，青云卷翮年。","还童丹九转，娱老易三编。","举案庞眉并，趋庭彩服翩。","门无题凤客，溪有钓鱼船。","绕径栽红药，开池种白莲。","閒寻宗炳社，来问远公禅。","鸠杖时安步，蓝舆或比肩。","山林今宰相，烟火老神仙。","玄鹤传云笈，青鸾寄彩笺。","蓬莱曾有约，弧矢正高悬。","谷旦日初曙，中秋月渐圆。","主人誇矍铄，宾客舞蹁跹。","锦绣华封祝，觥筹梓泽筵。","半酣人似玉，高咏笔如椽。","愧我游方外，因君念昔缘。","野芹惭献曝，钟鼎懒垂涎。","一见频惊老，相逢畏问年。","风尘归未得，松柏老弥坚。","杖国春秋富，空门岁月偏。","愿随鸿鹄后，翘首彩云天。"]},{"t":"答李明府礼山见过韵","f":"五言古诗","c":["久向连山宰，清风迥出尘。","舞干苗可格，振铎欲还淳。","夙契神交远，今来道味亲。","寻僧閒半日，留客话清晨。","野果聊将供，茶经欠讨论。","疏慵难恕己，豁略在当人。","归咏贻新句，开缄拜下陈。","思君似明月，冰影接霜筠。"]},{"t":"呈樊学院晦庵三十二韵","f":"五言古诗","c":["圣治法唐虞，明良协典谟。","股肱隆委任，声教务覃敷。","五岭承天眷，三台耀斗枢。","九重申简命，多士仰鸿儒。","閒气钟蚕僰，清风溯马湖。","尚书诒燕翼，继体执金吾。","报国惟忠孝，传家有范模。","文孙绳祖武，国士起天衢。","释褐琼林宴，传胪玉殿趋。","木天凭起草，渠阁属操觚。","道德踪伊雒，文章绍董狐。","两衔丹凤诏，重佩玉麟符。","丙岁持衡鉴，秋闱起滞濡。","重离欣继照，万汇快昭苏。","返命天颜喜，闻风物望孚。","居诸俄十稔，往复载前驱。","士习由师帅，文风赖植扶。","輶轩专节钺，冰檗绝苞苴。","憩茇留棠荫，旬宣极海隅。","殷雷争启蛰，合浦罕遗珠。","藉藉驰清誉，谦谦逊硕肤。","咨询穷草泽，拂拭遍泥涂。","两返巡方棹，言寻出世徒。","维舟问农圃，戒仆却传呼。","握手怜僧老，谈心到日晡。","交从文字密，禅爱性情孤。","我本同枯木，生涯但守株。","披来三事衲，赢得半生愚。","天上青骢马，山中白首猪。","云泥随去住，车笠且须臾。","知有重来约，宁忘去路迂。","明朝到韶石，曾记大通无。"]},{"t":"贫儿诗","f":"五言古诗","c":["微生返自然，从不慕肥鲜。","怀古发长啸，师心空复怜。","五金曾跃冶，百炼始成绵。","故旧休通款，交游耻胁肩。","回车遵道路，绝粒事神仙。","俛首甘人后，翻身走马前。","清臞形似鹤，皎洁净于莲。","管带蒲团话，忘炊曲突烟。","流尘生破甑，飞辔跃征鞭。","短景催年老，斋居免业牵。","卑栖宜矮屋，高咏薄贪泉。","孤竹常枵腹，长江懒索钱。","缊衣云片片，缀钵日悬悬。","草屩将身去，香珠信手揎。","野榸随地斸，苦茗带渣煎。","忽讶隙风冷，宁知土壁穿。","竹疏成鼓吹，松老落钗钿。","菌枕纹依榻，莎茵绿胜毡。","菜根邀上客，粪芋享时贤。","捲幔山光满，窥池日晕圆。","虚空高放眼，浓厚息垂涎。","雅俗随丰俭，人天任促延。","二时行处办，十万梦中缠。","香国原无饭，陶琴岂有弦。","衣珠藏自富，竿影正还偏。","审能甘澹薄，何用更雕镌。","寄语诸方道，来参一味禅。","寒温三事衲，风雨七条椽。","虚室空诸有，全身剩一拳。","步行骑水牯，袖手看鞦韆。","野老焚刍狗，村童放纸鸢。","人由人去就，我与我周旋。","衣褐休怀璧，书空代写笺。","海潮消复长，山月望还弦。","物理应如此，吾宗妙不传。","休粮修白业，因地种黄连。","苦趣成真乐，灵根秀识田。","无心乘化往，何事抱愁思。","道在箪瓢外，閒非水石边。","形骸同土木，蓑笠亦貂蝉。","真见须离见，生缘讵有缘。","本来无欠剩，谁复较偏全。","细入微尘界，高登自在天。","瓶盘终有漏，溪壑不须填。","幻寄随漂梗，浮生等逝川。","光阴销艳骨，风烛散歌筵。","好去参云水，归来磨■砖。","腰间舂米石，江上钓鱼船。","珍重惟今日，蹉跎又一年。","漫将儿女见，逐物起狂颠。"]},{"t":"九秋杂咏 其一 秋云","f":"五言律诗","c":["太虚本无质，幻迹偶因风。","日月涳濛外，星河淡荡中。","影边消伏暑，天际失奇峰。","莫讶人情薄，炎凉到处同。"]},{"t":"九秋杂咏 其二 秋蓬","f":"五言律诗","c":["繁华难久住，摇落得轻身。","远近随风力，高低逐日轮。","纸鸢云外线，野马路旁尘。","悟得循环理，相逢总未真。"]},{"t":"九秋杂咏 其三 秋籁","f":"五言律诗","c":["落叶树边屋，树边人独行。","远风一萧瑟，林响自鏦铮。","入耳吾将老，无心鸟不惊。","从来知此意，南郭古先生。"]},{"t":"九秋杂咏 其四 秋钟","f":"五言律诗","c":["寂寞秋原寺，霜钟韵最幽。","数声生殿角，一夜白人头。","皛皛月当枕，萧萧风满楼。","何能此时节，还起景阳愁。"]},{"t":"九秋杂咏 其五 秋磬","f":"五言律诗","c":["泗滨一片石，万古知音难。","野老无心击，西风过耳寒。","韵高泉并落，声冷叶先乾。","历历谁相委，蒲团夜正阑。"]},{"t":"九秋杂咏 其六 秋藓","f":"五言律诗","c":["霜色满庭莎，青青奈若何。","渐看蜗篆少，唯有鹤行多。","晚步痕添屐，朝眠绿上蓑。","野情閒不厌，车辙莫频过。"]},{"t":"九秋杂咏 其七 秋田","f":"五言律诗","c":["生涯在南亩，早晚及西成。","旧业蒹葭外，新凉袯襫轻。","自牛眠露草，黄雀啄香粳。","共有丰年庆，家家社鼓鸣。"]},{"t":"九秋杂咏 其八 秋汀","f":"五言律诗","c":["远浦霜天晚，寒江浅浅宜。","荻花螺女折，渔火射工吹。","有鹤量沙碛，无鱼上钓丝。","棹歌人独往，凉月浸涟漪。"]},{"t":"九秋杂咏 其九 秋瀑","f":"五言律诗","c":["秋色净如练，秋潭泻似雷。","霜威从地起，花雨自天来。","激石喧云碓，分流入茗杯。","谁知空谷里，有客探泉回。"]},{"t":"八影 其一 梨影","f":"五言律诗","c":["满院春光薄，阴晴不自持。","色香无着处，高下总低枝。","古月当中见，天风匝地吹。","与君同寂寞，疏雨闭门时。"]},{"t":"八影 其二 柳影","f":"五言律诗","c":["不辨劳亭色，谁知远别心。","大堤多近水，斜日渐移阴。","叠浪生平地，新条暗旧林。","东风太无赖，摇曳碧阶深。"]},{"t":"八影 其三 莲影","f":"五言律诗","c":["一片横塘月，芙蓉镜里看。","参差栖鹭迹，掩映钓鱼竿。","叶覆青油幕，花擎白玉盘。","涉江归去晚，北斗正阑干。"]},{"t":"八影 其四 竹影","f":"五言律诗","c":["何用直干霄，低垂近寂寥。","閒窗添个个，虚室静萧萧。","白日心先远，青云路转遥。","此君不可见，形影两无聊。"]},{"t":"八影 其五 菊影","f":"五言律诗","c":["秋色与心清，秋花剌眼明。","南山天一角，沧海月三更。","爱此孤光合，因之逸兴生。","翛然陈迹外，相对两忘名。"]},{"t":"八影 其六 桐影","f":"五言律诗","c":["古桐高百尺，全体含宫商。","偶尔见孤影，要之非所长。","疏枝凋玉露，片月堕银床。","我亦和光者，相期在善藏。"]},{"t":"八影 其七 梅影","f":"五言律诗","c":["我爱洞天树，花开正岁寒。","真香无可得，留影与人看。","骨格空还傲，尘根净到乾。","繁华非所羡，息荫且盘桓。"]},{"t":"八影 其八 松影","f":"五言律诗","c":["去天无咫尺，映地有千寻。","已近桑榆景，犹存冰雪心。","秦封云羃羃，龙卧息深深。","不见赤松子，韬光惟陆沉。"]},{"t":"秋村十二咏 其一 新寒","f":"五言律诗","c":["渐觉山衣薄，因知物候更。","水边凉意早，林下病身轻。","爽气来虚室，远风吹太清。","明朝别纨扇，珍重故人情。"]},{"t":"秋村十二咏 其二 剩暑","f":"五言律诗","c":["出伏仍消渴，经旬尚饮冰。","寒斋留热客，阳燄逐秋蝇。","卉木伤迟暮，炎凉变爱憎。","惟馀天畔月，冷魄挂枯藤。"]},{"t":"秋村十二咏 其三 烹葵","f":"五言律诗","c":["野葵堪采采，零露湿交加。","老爱无情物，迟开护足花。","清斋留上客，佳味出贫家。","晚食流匙滑，莼羹未足誇。"]},{"t":"秋村十二咏 其四 煨芋","f":"五言律诗","c":["山厨拨牛粪，宿火出蹲鸱。","犹带烟霞气，难教鼎鼐知。","懒禅分各半，野客朵双颐。","饱食频扪腹，何妨代晚炊。"]},{"t":"秋村十二咏 其五 邻砧","f":"五言律诗","c":["何处鸣双杵，声声隔短墙。","贫家刀尺冷，田舍宿春忙。","断续微情寄，分明远思长。","授衣时节近，瓜代未还乡。"]},{"t":"秋村十二咏 其六 社鼓","f":"五言律诗","c":["村童挝破鼓，野老祝丰年。","社日陈鸡黍，秋声杂应田。","蜗喧分两部，牛饮快三千。","何待渔阳弄，山花上鬓先。"]},{"t":"秋村十二咏 其七 萤灯","f":"五言律诗","c":["秉烛何为者，微光近夕晖。","远兼渔火乱，低并野燐飞。","腐草成形小，空囊识字稀。","平生怀古意，不羡借馀辉。"]},{"t":"秋村十二咏 其八 蛩语","f":"五言律诗","c":["我家徒四壁，闭户不闻喧。","深夜有虫语，幽人无所言。","细微通寂寞，亲切语寒温。","会得希声理，知音许共论。"]},{"t":"秋村十二咏 其九 蘋风","f":"五言律诗","c":["秋水澄澄碧，河洲面面风。","白蘋留不住，吹入蓼花丛。","就岸维舟近，回樯挂席同。","棹歌何处所，人在晚凉中。"]},{"t":"秋村十二咏 其十 菊雨","f":"五言律诗","c":["晚花开烂熳，宿雨滞淋漓。","且蜡黄桑屐，难抛白接䍦。","南山空怅望，秋色半离披。","可笑餐英客，阴晴两不知。"]},{"t":"秋村十二咏 其十一 履霜","f":"五言律诗","c":["晓霜漙露草，缓步一沉吟。","知有坚冰至，难为迟暮心。","板桥微见迹，红树不成阴。","白足归来晚，青山何处寻。"]},{"t":"秋村十二咏 其十二 筑圃","f":"五言律诗","c":["瓜熟已除架，苋乾无复蔬。","何当灌园罢，又是筑场初。","晴日迟收稻，中田早结庐。","自来勤动惯，不敢废耕锄。"]},{"t":"韦溪八咏 其一 樵山返照","f":"五言律诗","c":["山色远复远，日光微更微。","当窗见云岫，倒影入书帏。","老眼频回首，遥情欲振衣。","所思在寒瀑，向晚几人归。"]},{"t":"韦溪八咏 其二 石壁环峰","f":"五言律诗","c":["群峰如列嶂，万壑凌苍烟。","云日有深浅，古今无变迁。","绕楼开半面，窥枕近孤眠。","十里溪山路，相寻待放船。"]},{"t":"韦溪八咏 其三 月衣朝梵","f":"五言律诗","c":["一庵临古岸，初日出幽林。","是处有人住，静中闻梵深。","清声宜水鹤，馀响答风琴。","直入红尘去，知音不可寻。"]},{"t":"韦溪八咏 其四 莲池夜月","f":"五言律诗","c":["旧是长松地，今来但一池。","野花开菡萏，秋色蘸涟漪。","水殿邻芗国，犀渠洞藕丝。","何当见形影，独立夜深时。"]},{"t":"韦溪八咏 其五 东溪丹荔","f":"五言律诗","c":["长夏离支熟，东皋胜事多。","赤城通水国，红树拟霜柯。","人有十年计，官无五月科。","隔溪看未饱，欲买奈贫何。"]},{"t":"韦溪八咏 其六 南园榕荫","f":"五言律诗","c":["往往南园去，榕阴坐寂寥。","清谈方半日，落叶已齐腰。","树老不知岁，枝高还荫桥。","散人如散木，相过不须招。"]},{"t":"韦溪八咏 其七 西畴晚穫","f":"五言律诗","c":["亦知耕种苦，所愿在秋成。","预作轮租计，方将剥稻声。","潮田多稔岁，云碓有香粳。","自悔为农拙，西畴空复情。"]},{"t":"韦溪八咏 其八 北海渔歌","f":"五言律诗","c":["北海潮初上，渔歌下夕阳。","远风吹渐近，短曲听来长。","浩荡波千顷，沉吟水一方。","芦中人不见，倚处问沧浪。"]},{"t":"新晴八咏 其一 花气","f":"五言律诗","c":["乱蕊雨中尽，馀香晴后来。","春光正骀宕，芳意为徘徊。","襆被当轩曝，薰笼傍架开。","东君爱岑寂，风味到茶杯。"]},{"t":"新晴八咏 其二 柳烟","f":"五言律诗","c":["绿杨初见日，云树两参差。","落絮飞仍湿，轻烟淡亦垂。","拂墙千嶂曙，隔水数家炊。","可笑柴桑老，朝眠起独迟。"]},{"t":"新晴八咏 其三 蛙鼓","f":"五言律诗","c":["日出群动见，雨馀春草幽。","怒蛙发深蛰，鼓吹出芳洲。","真籁无喧寂，微声自唱酬。","何人洗双耳，默坐钓鱼舟。"]},{"t":"新晴八咏 其四 鸟声","f":"五言律诗","c":["雨后百花低，花边鸟韵齐。","物情方自喜，相唤出晴堤。","老鹤独无语，流莺飞更啼。","我心正求友，閒步过峰西。"]},{"t":"新晴八咏 其五 访僧","f":"五言律诗","c":["久雨晴偏好，寻僧兴不穷。","衲衣为社主，驴背识诗翁。","话倒三竿日，谈生四座风。","偶然发清啸，飞出石桥东。"]},{"t":"新晴八咏 其六 曝衣","f":"五言律诗","c":["吾家无长物，弊布与生蕉。","抖擞及时晒，清明能几朝。","纫针当昼影，开匣近松寮。","肯羡朱门客，花间曝锦貂。"]},{"t":"新晴八咏 其七 散步","f":"五言律诗","c":["林香迎霁日，一路落橙花。","孤杖扶吾往，千山是我家。","青苔沿旧路，白鸟印晴沙。","物理堪乘兴，春光未有涯。"]},{"t":"新晴八咏 其八 葺篱","f":"五言律诗","c":["一径入花村，天晴花正繁。","近嫌车马迹，编竹护苔痕。","隙地搴萝补，深根任雨翻。","叮咛语鸡犬，从此掩重门。"]},{"t":"閒居十咏 其一 埽地","f":"五言律诗","c":["隙风如橐籥，野马互驰驱。","转盼为陈迹，无心事埽除。","苍头朝拥彗，白发老摊书。","即此离尘鞅，清閒绰有馀。"]},{"t":"閒居十咏 其二 净几","f":"五言律诗","c":["隐几成枯寂，风埃任蔽亏。","滞形如土偶，觌面笑元规。","拂拭浑无事，跏趺空复为。","谁知尘世上，此座有閒时。"]},{"t":"閒居十咏 其三 焚香","f":"五言律诗","c":["博山爇沉水，矮屋笼高烟。","枯木发光怪，寒灰待火传。","众芳閒里过，一味静中禅。","空印真消息，深宵坐默然。"]},{"t":"閒居十咏 其四 试茗","f":"五言律诗","c":["多谢雪中炭，言烹雨后泉。","茶经无定法，老衲有真传。","破壁孤烟直，虚堂细响圆。","何人携茗椀，来问赵州禅。"]},{"t":"閒居十咏 其五 饲鸟","f":"五言律诗","c":["忘机狎群鸟，朝去暮还回。","饮啄得无惧，樊笼不待开。","鹤田分滞穗，燕语下香台。","独有山梁雉，长饥唤不来。"]},{"t":"閒居十咏 其六 灌花","f":"五言律诗","c":["种花临水际，花发水添香。","抱瓮不辞倦，溪深杓柄长。","雨馀容我懒，春老教人忙。","自得閒生理，荣枯感众芳。"]},{"t":"閒居十咏 其七 洗砚","f":"五言律诗","c":["介石为良友，端溪忆旧游。","相逢在云水，聊与濯清流。","黑白静中见，烟霞深处收。","不辞频拂拭，尘世共沉浮。"]},{"t":"閒居十咏 其八 品琴","f":"五言律诗","c":["静理匣中琴，传将弦外音。","翛然如有寄，弹者本无心。","山月下枯木，松风吹素襟。","何人为此曲，无乃水龙吟。"]},{"t":"閒居十咏 其九 观奕","f":"五言律诗","c":["天下原无事，人间局未空。","战酣残日下，声乱落花中。","退步思黄老，当机笑狡童。","旁观方袖手，何暇辨雌雄。"]},{"t":"閒居十咏 其十 临池","f":"五言律诗","c":["偶然看舞剑，聊尔学临池。","草圣予私淑，长沙素律师。","逢山留墨沈，卜地葬毛锥。","写尽芭蕉叶，春风总不知。"]},{"t":"闻雁杂咏 其一 霜林闻雁","f":"五言律诗","c":["繁霜变危绿，叶叶作秋声。","绕树一为听，长空数雁鸣。","飘零无定所，远近自分明。","共有坚冰戒，高飞惬野情。"]},{"t":"闻雁杂咏 其二 客舍闻雁","f":"五言律诗","c":["终岁长为客，秋风早闭门。","哀鸿频入耳，羁旅易销魂。","矰缴满天下，菰蒲即故园。","所思葭菼外，烦汝问寒温。"]},{"t":"闻雁杂咏 其三 雪晴闻雁","f":"五言律诗","c":["初日映残雪，负暄何处翁。","千山尚凝素，万里见征鸿。","我欲蹈东海，好音来远风。","无由生羽翼，相伴出樊笼。"]},{"t":"闻雁杂咏 其四 雨夜闻雁","f":"五言律诗","c":["高虹收宿雨，宾鸟下斜阳。","振羽云犹湿，求声兴转长。","风轻常近影，天迥易成行。","相唤芦中去，伊人水一方。"]},{"t":"闻雁杂咏 其五 月下闻雁","f":"五言律诗","c":["秋光何皛皛，天际来嗈嗈。","不辨镜中影，应迷雪后踪。","芦花深夜语，桂殿五更钟。","知有归期在，家山已万重。"]},{"t":"闻雁杂咏 其六 阁夜闻雁","f":"五言律诗","c":["旷怀观物理，何者最相宜。","高阁月明后，孤灯雁过时。","海风吹不断，天路去多岐。","拟作秋鸿操，知音更有谁。"]},{"t":"闻雁杂咏 其七 舟中闻雁","f":"五言律诗","c":["我本钓鱼客，秋江晚候潮。","雁归芦苇岸，人倚木兰桡。","细语互相答，野情如见招。","隔波听未彻，云水两迢迢。"]},{"t":"闻雁杂咏 其八 城楼闻雁","f":"五言律诗","c":["落叶古城秋，遥声起百忧。","惊禽来绝塞，寒月下南楼。","高不及星汉，卑惟恋荻洲。","玉关人未入，应悔觅封侯。"]},{"t":"闻雁杂咏 其九 山间闻雁","f":"五言律诗","c":["渺矣冥鸿迹，逢山得自如。","片云随去住，孤鹤互相于。","出谷为求友，闻声独起予。","凭君寄消息，白首老樵渔。"]},{"t":"闻雁杂咏 其十 溪边闻雁","f":"五言律诗","c":["清溪流湱湱，枕石日耽眠。","翻笑云中翼，偏惊物外禅。","一音分众籁，微响杂高蝉。","直入蒹葭去，秋风又一年。"]},{"t":"闻雁杂咏 其十一 过桥闻雁","f":"五言律诗","c":["咫尺虎溪水，危桥著屐过。","旅禽知此意，留语入烟萝。","天路难如此，秋云薄较多。","稻粱非所羡，相戒慎风波。"]},{"t":"闻雁杂咏 其十二 病起闻雁","f":"五言律诗","c":["强起倚书愰，冷虫喧四围。","多情惟旅雁，相劝授寒衣。","久病独无绪，远书来更稀。","留君慰岑寂，江燕任先归。"]},{"t":"闻雁杂咏 其十三 孤灯闻雁","f":"五言律诗","c":["枯禅如木石，深坐对银缸。","静极乃闻雁，声高犹到窗。","履霜心自苦，带月影俱双。","莫怪焚膏客，秋怀老未降。"]},{"t":"闻雁杂咏 其十四 驴背闻雁","f":"五言律诗","c":["独策蹇驴去，东郊踏雪花。","遥遥见蜚雁，一一入晴霞。","过耳边声近，惊心暮影斜。","归鞭吟正好，诗兴寄平沙。"]},{"t":"闻雁杂咏 其十五 欹枕闻雁","f":"五言律诗","c":["侧枕拥残絮，日高犹未兴。","似闻天半语，遥唤雪中僧。","万物尽形役，几人能曲肱。","相怜为漂泊，应不羡飞腾。"]},{"t":"闻雁杂咏 其十六 拥炉闻雁","f":"五言律诗","c":["斗室煖如纩，堆堆坐到晨。","翰音遥聒耳，枯木为伤神。","明月下沧海，全家住白蘋。","谁将雪中炭，空忆上林春。"]},{"t":"闻雁杂咏 其十七 东篱闻雁","f":"五言律诗","c":["三径久不埽，篱根长绿苔。","秋声随雁入，花意待人开。","予亦自知老，宾从何处来。","水边频寄宿，鸥鸟或相猜。"]},{"t":"闻雁杂咏 其十八 西畴闻雁","f":"五言律诗","c":["郭外纵横亩，秋田远近山。","三农方待穫，一雁下庾关。","似诉风霜苦，焉知稼穑艰。","躬耕与行役，相视未能閒。"]},{"t":"闻雁杂咏 其十九 倚杖闻雁","f":"五言律诗","c":["植杖倚晴雪，长天来好音。","双禽听未稳，孤策意何深。","肃肃云霄羽，悠悠湖海心。","一条瘦筇竹，期汝共浮沉。"]},{"t":"闻雁杂咏 其二十 抱膝闻雁","f":"五言律诗","c":["枯禅长抱膝，兀坐到更阑。","何处双飞翼，频惊五夜寒。","繁音归碧落，馀响入蒲团。","为语嗷嗷者，微生寄迹难。"]},{"t":"借园杂咏 其一 寻幽","f":"五言律诗","c":["偶来非久住，所得乃无穷。","树浅频移鹤，天高任转蓬。","自誇双足健，不觉一瓢空。","又复寻幽去，春光处处同。"]},{"t":"借园杂咏 其二 访旧","f":"五言律诗","c":["白社曾游处，朱门今几重。","云峰仍故态，水镜变衰容。","地主闻虚席，山人许寄踪。","鹿门知可托，垂老愿相从。"]},{"t":"借园杂咏 其三 卜筑","f":"五言律诗","c":["小补成新筑，能閒拟乐邦。","墙低山入榻，池浅月摇窗。","开径惭非诩，居亭恰是庞。","了无鹰兔见，随意守枯桩。"]},{"t":"借园杂咏 其四 安居","f":"五言律诗","c":["九夏安居近，閒房得便宜。","本来无破漏，何用更修治。","雨细泉先入，风轻暑不知。","叮咛语僮仆，从此息驱驰。"]},{"t":"借园杂咏 其五 闭门","f":"五言律诗","c":["举世为形役，吾生愿息机。","相逢无半语，惟劝掩重扉。","同病怜孤鹤，将閒博一饥。","绳枢牢缚定，遑问是邪非。"]},{"t":"借园杂咏 其六 谢客","f":"五言律诗","c":["却防佳客至，先寄数行书。","但愿存真契，无劳念索居。","风埃盈几案，藤蔓碍轩车。","要识东樵否，迎逢近不如。"]},{"t":"借园杂咏 其七 课圃","f":"五言律诗","c":["入门先学圃，隙地垦榛芜。","一雨喧童稚，双畦逐老夫。","充厨先野菜，虚架代新瓠。","爱此同生意，何曾计有无。"]},{"t":"借园杂咏 其八 探泉","f":"五言律诗","c":["圣泉清且冽，乃在此峰西。","久别频相念，重寻定不迷。","杖藜聊独往，茗椀且教携。","但得驱烦渴，何须入品题。"]},{"t":"借园杂咏 其九 栽莲","f":"五言律诗","c":["小池荒已久，春藕种来佳。","尘世能无染，真香静入怀。","浅深随所托，清浊岂相垂。","物理信如此，吾生未有涯。"]},{"t":"借园杂咏 其十 种菊","f":"五言律诗","c":["清明分善种，谷雨及时栽。","即事堪怀古，长歌归去来。","人无终岁力，花仅一秋开。","莫怪东篱下，沉吟日几回。"]},{"t":"借园杂咏 其十一 删竹","f":"五言律诗","c":["箐篁三亩宅，落箨四无邻。","枝叶删将尽，萧条乃见真。","去留惟便我，疏密不因人。","恰好存孤干，风前倚病身。"]},{"t":"借园杂咏 其十二 移橙","f":"五言律诗","c":["每怜橙荫好，端坐挹清芬。","近树安茶灶，移根傍水云。","八风深浩荡，一气自氤氲。","莫漫伤憔悴，繁华不似君。"]},{"t":"借园杂咏 其十三 护梅","f":"五言律诗","c":["古梅枝亚地，春老子偏繁。","惜绿斜开径，怜黄镇掩门。","虫饥防钻核，蚁语诫伤根。","物我同生理，经年总避喧。"]},{"t":"借园杂咏 其十四 刈草","f":"五言律诗","c":["地宽榛莽遍，天迥露珠漙。","早出衣从湿，归来日已乾。","长镵聊自托，被灶笑相看。","识得新州老，刍荛未可瞒。"]},{"t":"借园杂咏 其十五 濯足","f":"五言律诗","c":["清泉供濯足，休笑道人顽。","等觉原平等，閒身岂有閒。","鹤归云外步，僧踏水中山。","两脚俱无著，相随且闭关。"]},{"t":"借园杂咏 其十六 振衣","f":"五言律诗","c":["曾上飞云去，今来水石边。","临风振衣袂，回首忆当年。","千仞何为者，七斤殊不然。","老人新浴罢，抖擞息诸缘。"]},{"t":"借园杂咏 其十七 午斋","f":"五言律诗","c":["儒门洵澹薄，吾道不萧条。","午食喧群雀，春蔬盈一瓢。","闻钟炊玉粒，洗钵闭松寮。","差胜陶彭泽，长饥为折腰。"]},{"t":"借园杂咏 其十八 晚霁","f":"五言律诗","c":["閒园过宿雨，野水浸堂坳。","渐觉多忙事，商量葺破茅。","远天收螮蝀，斜日织蟏蛸。","最羡云中鹤，高飞不定巢。"]},{"t":"借园杂咏 其十九 趺坐","f":"五言律诗","c":["兀兀成吾是，悠悠笑尔曹。","自从来此住，坐久不辞劳。","一榻空诸有，双趺送二毛。","偶然舒两足，窗外月轮高。"]},{"t":"借园杂咏 其二十 经行","f":"五言律诗","c":["闭门事行脚，当下息奔波。","一日能千里，诸方如我何。","跛牂誇迅疾，夸父逊蹉跎。","三匝清池去，香风吹芰荷。"]},{"t":"借园杂咏 其二十一 微吟","f":"五言律诗","c":["本欲成高咏，低吟背落花。","隔樯人久立，多恐是诗家。","风细不关树，泉轻微漾沙。","此情俱寂寞，馀响送流霞。"]},{"t":"借园杂咏 其二十二 清啸","f":"五言律诗","c":["偶然发清啸，飞出水云乡。","天籁一时寂，山风万里长。","苏门心自远，竹里老偏狂。","谁是知音者，斯人未可忘。"]},{"t":"借园杂咏 其二十三 步月","f":"五言律诗","c":["人间天所忌，久雨阻经行。","不放终宵月，空馀半夜明。","自来还自去，谁送复谁迎。","顾影无相识，唯闻屐齿声。"]},{"t":"借园杂咏 其二十四 迎风","f":"五言律诗","c":["草屋近南亩，远风来渺冥。","披襟纳凉驶，觌面识居亭。","虚室静生白，孤灯长自青。","封姨许相过，从此撤疏棂。"]},{"t":"借园杂咏 其二十五 拥书","f":"五言律诗","c":["所贵遮吾眼，方将理葛藤。","谁知斲轮处，犹有读书僧。","三冬无俗物，千古得良朋。","翻笑东林老，逢人说上乘。"]},{"t":"借园杂咏 其二十六 高枕","f":"五言律诗","c":["年来惟善病，高枕水西楼。","独宿同孤鹤，閒眠笑老牛。","云阴山被薄，月满竹床幽。","竟夜不成寐，无言自唱酬。"]},{"t":"借园杂咏 其二十七 顾影","f":"五言律诗","c":["频频相管带，处处惜光阴。","此意无人会，唯君知我深。","孤明虚一盼，静夜息三心。","少小为形役，劳劳直至今。"]},{"t":"借园杂咏 其二十八 书空","f":"五言律诗","c":["高视薄云汉，书空止自谙。","眼边无怪事，指下有清谈。","真易何须画，圆伊不待三。","玄珠归罔象，持此报同参。"]},{"t":"借园杂咏 其二十九 述嘲","f":"五言律诗","c":["有客频相劝，言师道过严。","蝇屯偏择秽，蜂聚却因甜。","苦节多成病，长饥为矫廉。","殷勤谢来意，鱼掌岂能兼。"]},{"t":"借园杂咏 其三十 纪梦","f":"五言律诗","c":["昨夜梦行脚，茫然失圣凡。","有人坐盘石，云是补陀岩。","明月下沧海，长风吹布衫。","觉来舒老眼，红日上松杉。"]},{"t":"十九秋 其一 秋寺","f":"五言律诗","c":["寂寞蒹葭外，微茫见佛灯。","数株红树下，一个白头僧。","露冷先藏鹤，林虚静爱鹰。","西风动幡影，无语问南能。"]},{"t":"十九秋 其二 秋原","f":"五言律诗","c":["落叶不到地，远风时在林。","有人骑瘦马，终日拍鞍吟。","草色惊心老，霜痕刺眼深。","如何行路客，容易说登临。"]},{"t":"十九秋 其三 秋瀑","f":"五言律诗","c":["空谷无人处，高泉间落霞。","寒光投涧直，悬影入云斜。","八月山有雪，二时天雨花。","老僧观不足，飞沫湿袈裟。"]},{"t":"十九秋 其四 秋屋","f":"五言律诗","c":["一所尖头屋，千山落木风。","日斜葭菼外，人在寂寥中。","倚树见归鸟，开轩闻草虫。","转嫌邻舍近，隔水结茅篷。"]},{"t":"十九秋 其五 秋社","f":"五言律诗","c":["村童喧北里，野老报西成。","掩豆豚肩小，吹豳羯鼓鸣。","神鸦飞食肉，社鼠坐分羹。","醉舞黄花下，巫阳象版轻。"]},{"t":"十九秋 其六 秋楼","f":"五言律诗","c":["我亦有仙骨，高居远俗尘。","不因吹笛处，谁识倚楼人。","山色开三面，秋空无四邻。","超然群动外，日月逐閒身。"]},{"t":"十九秋 其七 秋塘","f":"五言律诗","c":["下流不可处，众浊难为清。","最爱荒塘水，能留孤月明。","烟波秋潋滟，荇藻夜纵横。","取次坚冰近，春来草又生。"]},{"t":"十九秋 其八 秋戍","f":"五言律诗","c":["白草经年戍，黄花万里情。","秋风度天堑，落叶满边城。","壮士犹编伍，将军未厌兵。","主人恩尚浅，七尺为谁轻。"]},{"t":"十九秋 其九 秋镜","f":"五言律诗","c":["爱尔本无我，逢秋识故人。","滞形还偶影，顾笑复怜颦。","虚室自生白，太空谁写真。","所嗟承弁鬓，一见一回新。"]},{"t":"十九秋 其十 秋帘","f":"五言律诗","c":["白蘋红桕岸，孑孑幔旗高。","沉醉归吟客，凉风吹毙袍。","长卿新酒保，公瑾旧醇醪。","相见芭蕉道，枯禅笑我曹。"]},{"t":"十九秋 其十一 秋渔","f":"五言律诗","c":["华亭人去后，湖海几经秋。","留得一竿竹，閒来坐钓舟。","百年参水鹤，一笑狎沙鸥。","相劝桐江老，青蓑换黑裘。"]},{"t":"十九秋 其十二 秋烟","f":"五言律诗","c":["不道秋烟浅，山光淡几重。","晓来看远岫，飞去最高峰。","月恨冰壶小，云添水墨浓。","渺然闻见外，清籁散疏钟。"]},{"t":"十九秋 其十三 秋菜","f":"五言律诗","c":["瓜蔬秋未晚，姜桂老偏宜。","物理洵如此，吾生定不疑。","根苗凭地力，烹瀹在人为。","莫漫遗黄叶，随流自不知。"]},{"t":"十九秋 其十四 秋灯","f":"五言律诗","c":["檐前凉雨过，灯下落花频。","万古无穷事，三更不寐人。","秋光成一片，老景自相亲。","寂寞消难得，平分与隔邻。"]},{"t":"十九秋 其十五 秋琴","f":"五言律诗","c":["大地同明月，一人弹素琴。","秋声入枯木，馀响在空林。","偶尔写情性，翛然无古今。","钟期如可作，犹恐未知音。"]},{"t":"十九秋 其十六 秋猎","f":"五言律诗","c":["处处鸟声稀，秋风动杀机。","将军初命驾，寥廓已高飞。","犬带重鋂出，鹰饕一饱归。","鹪鹩方自喜，何幸此身微。"]},{"t":"十九秋 其十七 秋衫","f":"五言律诗","c":["莫笑山衣破，偏能代负暄。","公然对狐貉，各自话寒温。","九秋霜露重，一衲水云屯。","閒与儿童道，无衣早闭门。"]},{"t":"十九秋 其十八 秋簟","f":"五言律诗","c":["新得蕲阳簟，秋来布石床。","有时自舒卷，无地不潇湘。","雨过籧篨润，风高薤叶凉。","莫誇人并倚，幽独兴偏长。"]},{"t":"十九秋 其十九 秋蝶","f":"五言律诗","c":["物外形兼影，花边弟与昆。","翱翔入秋草，迟莫忆王孙。","好梦迷乌足，前身是漆园。","御风人未返，何处可招魂。"]},{"t":"十放诗 其一 放云","f":"五言律诗","c":["携云下暝岫，两腋生寒光。","中道一为别，故山归兴长。","升沉无定所，咫尺遥相望。","行矣勿复道，秋高天淼茫。"]},{"t":"十放诗 其二 放萤","f":"五言律诗","c":["懒惰已成性，与君相见稀。","括囊乾欲死，腐草忍同归。","好去度星汉，休来点客衣。","破除文字障，何处不高飞。"]},{"t":"十放诗 其三 放鹰","f":"五言律诗","c":["独立倚秋风，猎心知汝雄。","臂鞲聊为解，宇宙一何空。","俦侣情偏洽，山林兴不穷。","举头天外望，谁复出樊笼。"]},{"t":"十放诗 其四 放鸭","f":"五言律诗","c":["天寒犹下水，日暮自呼名。","爱尔无泥滓，托身随浊清。","归来风雨后，放出羽毛轻。","莫逐双凫去，丹霄不易行。"]},{"t":"十放诗 其五 放猿","f":"五言律诗","c":["怜尔受羁绁，逢僧解玉环。","独归千嶂外，长啸一声閒。","静躁难同住，猕猴莫共山。","殷勤挥手别，相望白云间。"]},{"t":"十放诗 其六 放鹤","f":"五言律诗","c":["山中有高士，共住一年年。","短榻寒连影，孤灯夜立禅。","神交天地外，怅别秋风前。","大笑出门去，閒云何处边。"]},{"t":"十放诗 其七 放牛","f":"五言律诗","c":["三农胥有役，一隙即閒身。","以此均劳逸，安能长苦辛。","溪山随所适，水草自相亲。","白石歌残后，应无扣角人。"]},{"t":"十放诗 其八 放驴","f":"五言律诗","c":["蹇驴欺我老，出郭故蹒跚。","尽日行吟苦，长风吹面寒。","归来语童仆，从此解鞯鞍。","相送秋田去，焉知世路难。"]},{"t":"十放诗 其九 放鱼","f":"五言律诗","c":["隔江老渔父，收钓细鳞肥。","问市提筐入，逢僧托钵归。","从容苏涸辙，谈笑得生机。","极目沧浪外，烟霞静可依。"]},{"t":"十放诗 其十 放蝶","f":"五言律诗","c":["翩翩双凤子，来自古罗浮。","好客难为别，飞仙不可留。","遐心返初服，归路指丹丘。","共有逍遥梦，相期在石楼。"]},{"t":"东林七问 其一 问天","f":"五言律诗","c":["碌碌今如此，冥冥非所知。","胜人宁有定，于我或无私。","劫火焚刍狗，青云变素丝。","杞忧诚罔极，深信转成疑。"]},{"t":"东林七问 其二 问影","f":"五言律诗","c":["屏迹茅檐下，追随日以疏。","偶然到城市，未免识侬渠。","造物静相对，此身常有馀。","何时谢形役，不敢惜离居。"]},{"t":"东林七问 其三 问津","f":"五言律诗","c":["古道接桑麻，仙源入望赊。","避秦人去后，无复种桃花。","岐路伤萍梗，逢溪问钓槎。","隔江何处所，或恐是吾家。"]},{"t":"东林七问 其四 问岁","f":"五言律诗","c":["老去懒耕田，秋来愿有年。","每从桥下卜，频解杖头钱。","南地三冬雪，西畴万井烟。","农谈昨如此，曾否不虚传。"]},{"t":"东林七问 其五 问夜","f":"五言律诗","c":["高枕得无事，出门胥有营。","红尘骑马客，白发听鸡声。","茅屋閒将老，蒲团坐到明。","相看同此意，谁浊更谁清。"]},{"t":"东林七问 其六 问字","f":"五言律诗","c":["相知无厚薄，相见有疏亲。","偶尔逢新识，悠然思古人。","阅穷千载事，赢得半生贫。","何似秦灰后，金张早致身。"]},{"t":"东林七问 其七 问剑","f":"五言律诗","c":["往往难平事，烦君几濯磨。","风尘频抖擞，岁月易蹉跎。","钟虡消兵器，铅刀当太阿。","不知三寸管，谁较杀人多。"]},{"t":"后七问 其一 问天","f":"五言律诗","c":["我有千古恨，高高将听卑。","亦知曾补后，不似未分时。","得气清何少，流光照或私。","可能空阔外，容我管中窥。"]},{"t":"后七问 其二 问影","f":"五言律诗","c":["不辨谁宾主，何因有往还。","怜君时一顾，笑我未能閒。","世态胶难合，前尘迹可删。","终当事韬晦，相待掩重关。"]},{"t":"后七问 其三 问津","f":"五言律诗","c":["扰扰役车尘，悠悠失路人。","九衢多覆辙，一往几埋轮。","我亦自兹去，相逢笑有因。","别寻林下叟，回指故山春。"]},{"t":"后七问 其四 问岁","f":"五言律诗","c":["空瓶无俗物，破甑久生尘。","比日事田圃，占年拜水神。","审能免沟壑，不敢慕陈因。","愿得长如此，终身作野人。"]},{"t":"后七问 其五 问夜","f":"五言律诗","c":["孤灯坐终夕，坐久灯力微。","晓漏知多少，邻鸡闻庶几。","病躯慵下榻，花气促披衣。","笑问儿童道，晨星稀未稀。"]},{"t":"后七问 其六 问字","f":"五言律诗","c":["自从闻鬼哭，不复更摊书。","渐觉乌成马，无心獭祭鱼。","偶来观越绝，相失半秦馀。","稽首空王问，三伊如不如。"]},{"t":"后七问 其七 问剑","f":"五言律诗","c":["举世争雄日，何妨独守雌。","冤亲平等视，风雨寂寥为。","浩气销能否，全身付与谁。","一弹三太息，惟许湛卢知。"]},{"t":"十闰诗 其一 闰元夕","f":"五言律诗","c":["北里休蚕绩，西畴罢耦耕。","又来看灯市，相伴入春城。","好月光仍满，清宵昼欲平。","旧时按歌地，犹有绕梁声。"]},{"t":"十闰诗 其二 闰花朝","f":"五言律诗","c":["花发朝还暮，花时去复回。","方将踏青候，又逐看花来。","所惜韶华老，频教羯鼓催。","春风如有待，不放刺桐开。"]},{"t":"十闰诗 其三 闰上巳","f":"五言律诗","c":["采兰人散后，折柬又相招。","老去仍添闰，江边更弄潮。","韨除尘欲尽，枕漱兴偏饶。","难得长如此，留春慰寂寥。"]},{"t":"十闰诗 其四 闰佛日","f":"五言律诗","c":["佛日薄虞渊，真风空寂然。","再来行七步，一闰即千年。","天上僧祇劫，人閒昼夜缘。","犹存增减见，惭汗沐金仙。"]},{"t":"十闰诗 其五 闰端阳","f":"五言律诗","c":["中天回北陆，馀闰继南离。","至朔盈虚定，朱明日月迟。","涧蒲添节节，榴火足枝枝。","昨有灵均约，重来此一时。"]},{"t":"十闰诗 其六 闰七夕","f":"五言律诗","c":["计日近中秋，星河澹欲流。","可怜上弦月，犹挂旧针楼。","巧自前宵得，欢从两度留。","笑将离合意，重叠问灵修。"]},{"t":"十闰诗 其七 闰中秋","f":"五言律诗","c":["天上同明月，争怜再闰难。","山中无历日，虚作九秋看。","木落光初满，霜深影较寒。","清辉曾不异，莫惜重盘桓。"]},{"t":"十闰诗 其八 闰九日","f":"五言律诗","c":["往往龙山去，频频笑孟嘉。","更寻前月约，还问隔篱花。","雪近霜侵鬓，风高帽侧纱。","几回登望意，一半惜年华。"]},{"t":"十闰诗 其九 闰除夕","f":"五言律诗","c":["闰馀已成岁，春入不知年。","老长三旬腊，穷多一月缘。","痴呆先待价，粥饭后还钱。","明发开新历，生涯十二篇。"]},{"t":"十闰诗 其十 闰生日","f":"五言律诗","c":["事事不如人，蹉跎又一春。","浮生易知足，馀闰苦随身。","对客徵前梦，逢僧话昔因。","赢来三十日，输却落花晨。"]},{"t":"山居杂咏 其一 垦荒","f":"五言律诗","c":["爱此无租税，荒田自在耕。","土膏深更出，混沌凿还生。","鈯斧悬腰重，长欃著手轻。","偶来问农圃，大地几时平。"]},{"t":"山居杂咏 其二 种树","f":"五言律诗","c":["十年生计在，此意与谁论。","取次青垂槛，方将绿映门。","无心藤倚树，转盼叶归根。","留得庭前柏，清阴付子孙。"]},{"t":"山居杂咏 其三 编篱","f":"五言律诗","c":["所居无四壁，聊复借藩篱。","芳槿环三匝，春风时一披。","人声灯火外，门掩月光迟。","莫惜重重隔，墙东知是谁。"]},{"t":"山居杂咏 其四 葺茅","f":"五言律诗","c":["诛茅补茅屋，乃在西峰西。","但恐风雨至，不知云日低。","宽惟客膝坐，高仅与眉齐。","何事居庵主，沿山辞蒺藜。"]},{"t":"山居杂咏 其五 摘茶","f":"五言律诗","c":["草木得真性，无人也自芳。","下山才半日，采撷已盈筐。","剩有烟霞气，归来衣带香。","留僧酣茗战，看尔展旗鎗。"]},{"t":"山居杂咏 其六 芟草","f":"五言律诗","c":["石上草根浅，日高朝露晞。","荷锄惟独往，翘楚刈将归。","物理有代谢，吾心无杀机。","所思在空谷，迟暮惜芳菲。"]},{"t":"山居杂咏 其七 灌园","f":"五言律诗","c":["飞泉不到地，疏雨未成霖。","努力事朝汲，长歌怀汉阴。","露葵刚覆足，霜芥欲抽心。","珍重灌园叟，平施无浅深。"]},{"t":"山居杂咏 其八 牧牛","f":"五言律诗","c":["与子周旋久，无心得便安。","溪山随分纳，苗稼不相干。","春草閒眠稳，秋田纵步宽。","笑看披绣者，骍角太无端。"]},{"t":"山居杂咏 其九 枧泉","f":"五言律诗","c":["众流归绝壑，一线下阶除。","结束云閒瀑，飞腾屋角鱼。","入门无别路，应物贵中虚。","何用西江汲，长空水到渠。"]},{"t":"山居杂咏 其十 负薪","f":"五言律诗","c":["清晨随众出，薄暮负薪归。","渐觉钟磬近，远看云树稀。","长林连野烧，落木带霜威。","忆昔樵苏地，不知今是非。"]},{"t":"山居杂咏 其十一 拥炉","f":"五言律诗","c":["石火爇枯木，地炉生湿烟。","阳和回冻谷，风雪过残年。","世事自冰炭，吾心殊冷然。","无人知此意，使我忆南泉。"]},{"t":"山居杂咏 其十二 补衲","f":"五言律诗","c":["十年成一片，计日累千针。","重叠水云态，绸缪岁月深。","揩磨非著意，寒暑失偷心。","渐觉无痕迹，衣珠不用寻。"]},{"t":"山居杂咏 其十三 制笠","f":"五言律诗","c":["搴藤编箬叶，迎刃解霜筠。","新制平头笠，能遮扑面尘。","影边无别物，世外有閒身。","多谢乘车者，何劳揖故人。"]},{"t":"山居杂咏 其十四 织屦","f":"五言律诗","c":["老来生计拙，织屦学于陵。","拨草明朝路，编蒲昨夜灯。","过桥逢孺子，度岭识归僧。","从此狞如虎，孤峰可共登。"]},{"t":"山居杂咏 其十五 斸笋","f":"五言律诗","c":["落箨带残霜，新苞出旧房。","浅深俱有得，遍界不曾藏。","所贵无枝叶，何须较短长。","此君知此意，相赠独盈筐。"]},{"t":"山居杂咏 其十六 餐菊","f":"五言律诗","c":["楚客有佳味，山僧非酒人。","醉嫌陶靖节，颦效屈灵均。","无复盐梅想，偏宜姜桂辛。","东篱花满眼，霖雨任经旬。"]},{"t":"山居杂咏 其十七 折藕","f":"五言律诗","c":["浮生聊寄迹，决绝复奚辞。","一洗尘根净，方知涅不缁。","可堪盈手赠，偏与素心宜。","大地同饥渴，于君有所思。"]},{"t":"山居杂咏 其十八 啖斋","f":"五言律诗","c":["白首无兼味，黄斋只数茎。","不知牙齿落，还与菜根争。","发瓮醢鸡笑，行堂热椀鸣。","辛酸赢一饱，多谢楗椎声。"]},{"t":"山居杂咏 其十九 采蕨","f":"五言律诗","c":["晨出采薇蕨，暮归逢隐沦。","殷勤频借问，夷叔是何人。","粳米卢州饭，迷阳大地春。","我心无不可，饱食报能仁。"]},{"t":"山居杂咏 其二十 茹芝","f":"五言律诗","c":["茅堂烟火后，云外采芝归。","紫玉流匙滑，银丁入馔微。","神仙宁绝粒，吾道本忘饥。","却笑商山老，驴年未息机。"]},{"t":"十二声诗 其一 涧声","f":"五言律诗","c":["浩然长独往，万古无知音。","纵与烟霞别，终存水石心。","幽人通语默，相得在高深。","寂寞笙歌外，闻声不可寻。"]},{"t":"十二声诗 其二 杖声","f":"五言律诗","c":["隔溪微送响，一一入徘徊。","声向静中得，客从何处来。","谷兼山屐应，路带楚吟回。","渐觉过桥疾，多应落日催。"]},{"t":"十二声诗 其三 叶声","f":"五言律诗","c":["古亭抱秋树，秋意失婆娑。","畟畟下凉吹，萧萧鸣远柯。","渐知声应少，止觉别离多。","未敢随流默，知音谓我何。"]},{"t":"十二声诗 其四 车声","f":"五言律诗","c":["安步吾将老，驰驱世共频。","枕边倾只耳，门外过双轮。","一往忘喧寂，同声互主宾。","文轩齐荜辂，俱是未閒人。"]},{"t":"十二声诗 其五 茶声","f":"五言律诗","c":["几欲清烦虑，闻薰便爽然。","圆音知活火，微响辨新泉。","想到希声处，消归七椀边。","邻翁听总彻，宁待隙风传。"]},{"t":"十二声诗 其六 棋声","f":"五言律诗","c":["竹楼新雨过，馀响杂楸枰。","静到无言处，悠然感物情。","子疏机转密，手重敌还轻。","历历虚窗入，须臾几战争。"]},{"t":"十二声诗 其七 梵声","f":"五言律诗","c":["此声满天下，止有一人能。","万籁寂还寂，孤峰层又层。","无情堪说法，离句即传灯。","流布人间遍，浮生听未曾。"]},{"t":"十二声诗 其八 榜声","f":"五言律诗","c":["风便扬帆去，潮生荡桨回。","此时欹枕听，何处榜歌来。","击楫情偏远，叩舷声转催。","归心似流水，三老莫徘徊。"]},{"t":"十二声诗 其九 柝声","f":"五言律诗","c":["戍楼频击柝，中夜旅魂惊。","梦鹤回千里，晨鸡破五更。","明明围伏枕，一一绕愁城。","回首孤峰宿，何曾得此声。"]},{"t":"十二声诗 其十 舂声","f":"五言律诗","c":["饥来心计诎，静极耳尘空。","何处频相杵，邻家事宿舂。","腰间留片石，庑下寄高踪。","寂寂千秋后，闻声怀此公。"]},{"t":"十二声诗 其十一 杼声","f":"五言律诗","c":["促织吟东壁，清音入耳微。","家家喧杼轴，札札出蓬扉。","积缕知成疋，停梭想授衣。","闻声还报语，风雪正霏霏。"]},{"t":"十二声诗 其十二 蛙声","f":"五言律诗","c":["鼓吹近清晨，招呼洽比邻。","殷雷初发蛰，眢井亦知春。","世网难容物，心声疑动人。","泥涂堪溷迹，缄结莫逡巡。"]},{"t":"雪中杂咏六首 其一 煮雪","f":"五言律诗","c":["钻取槐檀木，烹将云母芽。","凝冰与焦火，相待过年华。","茗椀吹阳律，银山翻浪花。","却怜苏属国，持节未还家。"]},{"t":"雪中杂咏六首 其二 凿雪","f":"五言律诗","c":["山径积复积，洞门开未开。","持将鈯斧子，剖出蕊珠胎。","寒月光转阔，冷风吹又来。","凌阴方可纳，宁待玉山颓。"]},{"t":"雪中杂咏六首 其三 埽雪","f":"五言律诗","c":["寒斋朝拥彗，触破玉壶冰。","借问侯门客，生涯见未曾。","埽除非草草，堆叠自层层。","挥手下阶去，纵横兴可乘。"]},{"t":"雪中杂咏六首 其四 踏雪","f":"五言律诗","c":["疲马暮失足，芒鞋朝请缨。","冻云光匝地，衰草白无情。","鹤步随吟迹，牛涔引杖声。","悠悠灞陵道，今古几人行。"]},{"t":"雪中杂咏六首 其五 拥雪","f":"五言律诗","c":["我有辟寒玉，青州布一围。","何曾羡狐貉，差胜掩牛衣。","曝背癯形露，充绵瘦骨肥。","蒙头过残腊，忘却六花飞。"]},{"t":"雪中杂咏六首 其六 积雪","f":"五言律诗","c":["千山迟解冻，三月不知春。","谁信看花候，还来送炭人。","冰壶藏白发，火宅笑红尘。","褦襶门前客，无劳剥啄频。"]},{"t":"与谢邺门还山同赋","f":"五言律诗","c":["便与所亲别，终年拟闭关。","如何此时节，亦复到人间。","急雨移新路，痴云恋旧山。","归逢林下叟，笑我未能閒。"]},{"t":"又","f":"五言律诗","c":["何人排闼入，来客与归僧。","昨日山下路，苍苔没几层。","怒蛙喧废井，饥鼠啮枯藤。","莫厌荒凉地，分吟古佛灯。"]},{"t":"山中寒雨答友人","f":"五言律诗","c":["山云作山雨，问山山不知。","我心正如此，君子复何辞。","雪色侵长薄，鸡声过短篱。","见闻俱寂寞，何处更寻师。"]},{"t":"夜发汾江寄山中诸子","f":"五言律诗","c":["故山在何处，乃在白云端。","今夜孤舟宿，方知海气寒。","潮声欹枕听，月色隔船看。","此际谁堪语，持归寄所欢。"]},{"t":"陶握山还山喜赠","f":"五言律诗","c":["梦想所不到，见时仍梦中。","可怜双鬓改，只有寸心同。","无足为君道，前尘过眼空。","故山茅屋在，归兴复何穷。"]},{"t":"野人","f":"五言律诗","c":["野人有真性，对客不通名。","赤脚驱黄犊，山田事耦耕。","桑麻存古道，水石足平生。","我欲同沮溺，终身免到城。"]},{"t":"晚发石龙","f":"五言律诗","c":["昨枉故人信，无端事远游。","山城何日到，江水正东流。","身老难为客，心閒易觉秋。","最怜今夜月，孤棹别罗浮。"]},{"t":"晚泊赤岭","f":"五言律诗","c":["残日还归海，馀光更上天。","中流千嶂合，断岸一镫悬。","旧路成生路，前船是后船。","客心无可道，回首但茫然。"]},{"t":"过七里湖","f":"五言律诗","c":["尽日舟中住，江声静入怀。","昼眠宜浅水，宿雨避丹崖。","渐觉乡音异，惟闻鸟语佳。","旁人那辨此，幽兴与谁偕。"]},{"t":"泊煎湖","f":"五言律诗","c":["近识舟居乐，波涛渐不惊。","临流谙水性，随地问山名。","樵径通牵路，松风杂棹声。","兴来履危石，为爱草虫鸣。"]},{"t":"示同舟","f":"五言律诗","c":["举目同为客，何人似我閒。","舟中安笔砚，到处写溪山。","大道无拘束，吾生任往还。","终当清颍上，洗耳听潺湲。"]},{"t":"舟中寄同学诸子","f":"五言律诗","c":["为语操舟者，中流好着篙。","微风生浦溆，一水尽波涛。","彼岸渺无际，予心郁以陶。","何时群动息，轻棹过江皋。"]},{"t":"晚泊临水驿","f":"五言律诗","c":["同舟拾枯竹，钻火作盘餐。","晚食推篷坐，秋风隔浦寒。","山亭临水驿，旧吏送新官。","独有沧浪叟，年年倚棹看。"]},{"t":"泊浮鹅石登大悲阁","f":"五言律诗","c":["孤棹去呕哑，千山暝色遮。","牛羊归古渡，鸥鹭下晴沙。","久客思寻寺，逢僧便当家。","劳师相指点，前路水三叉。"]},{"t":"昼雨书事","f":"五言律诗","c":["昼雨洗山骨，溪云覆涧毛。","悬崖花气近，出谷鸟声高。","选石临清濑，当风振敝袍。","船头见黄菊，秋思更萧骚。"]},{"t":"雨中晚泊","f":"五言律诗","c":["出门方八月，中道已深秋。","去国一千里，长江日夜流。","浓阴生绝壑，疏雨在孤舟。","自是无家客，逢山便可留。"]},{"t":"上滩","f":"五言律诗","c":["华发生秋色，青山惜暮年。","艰难行路客，留滞上滩船。","远水分孤屿，中流见逝川。","客心正摇落，吟遍夕阳边。"]},{"t":"舟中寄李苍水广文","f":"五言律诗","c":["一夜千峰雨，江声怒似雷。","青山频北望，白雁正南来。","为客伤迟暮，伊人愿溯洄。","秋风肯相待，到日菊花开。"]},{"t":"舟中见新月","f":"五言律诗","c":["大江流■㶁，初月如悬弓。","独坐鉴孤影，清光思不穷。","兼烟笼夜色，杂树摇秋风。","回忆故山际，此心谁与同。"]},{"t":"过河源","f":"五言律诗","c":["二水分山县，东西别渭泾。","前峰消积雨，流潦下沧溟。","晴日睡方足，江风吹复醒。","看看老渔父，一曲过寒汀。"]},{"t":"过二峡","f":"五言律诗","c":["是处有人家，停舟见落花。","黄茅沽酒肆，红蓼钓鱼槎。","社古榕阴阔，山高石径斜。","东南车马路，何地得如他。"]},{"t":"泊龙川","f":"五言律诗","c":["一日一停船，长歌落照边。","孤城连雁塔，古道入龙川。","山出烟中髻，薇舒雨后拳。","冥心观物理，初月不成眠。"]},{"t":"投通衢店","f":"五言律诗","c":["倦客寻山店，随人入郭门。","短檐低白日，细雨又黄昏。","伫立知何处，徐行渐到村。","不辞频问讯，恐或是桃源。"]},{"t":"清溪店","f":"五言律诗","c":["东去清溪水，水清能照人。","我来住行脚，独立见閒身。","红桕当孤店，青山在隔邻。","风尘暗前路，谁复是知津。"]},{"t":"种梅 其一","f":"五言律诗","c":["选树斸山骨，托根宜土膏。","荷锄聊独往，抱瓮不辞劳。","引客吟官阁，教人恨楚骚。","寒柯时一抚，白发且频搔。"]},{"t":"种梅 其二","f":"五言律诗","c":["大地直如寄，天机祇自全。","新知丰乐老，能识藐姑仙。","在世了无梦，与僧长有缘。","何人从此去，参得大梅禅。"]},{"t":"种梅 其三","f":"五言律诗","c":["门心俱似水，到处即罗浮。","侧径堪旋马，新阴未蔽牛。","江城吹■篥，山月照襟裯。","莫怪参横候，花前忆故丘。"]},{"t":"种梅 其四","f":"五言律诗","c":["绿英逢李白，佳句似阴铿。","叶底吟诗遍，花时太瘦生。","尘根当下尽，心目一齐清。","自谓山凡异，拈来愧老兄。"]},{"t":"种梅 其五","f":"五言律诗","c":["落叶满空林，花边好独吟。","十年非过计，七日本无心。","虚室含朝白，閒阶布夕阴。","夜来三尺雪，谁复更相寻。"]},{"t":"种梅 其六","f":"五言律诗","c":["出林生内热，移树就新寒。","夜坐当三五，朝眠过一竿。","雨肥争影瘦，吟苦觉诗酸。","即此忘饥得，应同井李看。"]},{"t":"种梅 其七","f":"五言律诗","c":["抚物吾当老，东风度度春。","如何枯树下，犹有守株人。","灵谷花无赖，孤山鹤作邻。","低枝君莫损，留挂接䍦巾。"]},{"t":"种梅 其八","f":"五言律诗","c":["未有还童术，言寻萼绿华。","高天回白首，平地发黄芽。","丰骨独殊众，荣枯一任他。","长镵三尺柄，凭尔作生涯。"]},{"t":"种梅 其九","f":"五言律诗","c":["枝叶删须尽，天根返太清。","枯禅与枯木，无地亦无生。","当下成空色，真宜作太羹。","谁能知此意，默默绕花行。"]},{"t":"种梅 其十","f":"五言律诗","c":["本来同木石，天性足烟岚。","老大惟留骨，扶疏自向南。","世人胥病渴，吾道莫空谈。","何日提筐去，归山掩破庵。"]},{"t":"舟发石湾奇别山中诸子","f":"五言律诗","c":["言从泷水去，忍与故山违。","帆影侵平楚，钟声隔翠微。","孤踪成独往，无梦见君稀。","早岁同袍者，何年携手归。"]},{"t":"送吕耕山从李广文之澄迈 其一","f":"五言律诗","c":["却笑耕山子，翻为渡海人。","个中知者少，此事与谁陈。","游藉儒官重，交从古道亲。","行行慎岐路，彼岸淼无垠。"]},{"t":"送吕耕山从李广文之澄迈 其二","f":"五言律诗","c":["我将入山去，君复事南征。","海国人稀到，东风自送行。","滞形同在客，问道愧称兄。","知有归来日，愁予白发生。"]},{"t":"送吕耕山从李广文之澄迈 其三","f":"五言律诗","c":["山间有明月，珍重赠临岐。","后夜遥相望，清光知为谁。","当中无影象，独立见须眉。","正是飞云外，千峰一日时。"]},{"t":"示罗定水受室","f":"五言律诗","c":["此日乘龙客，当年竹马儿。","漫惊年纪大，陡觉汝翁衰。","琴瑟调今夕，杯棬感昔时。","莫将江氏笔，持去画张眉。"]},{"t":"留别罗颢甫","f":"五言律诗","c":["老母发垂白，痴儿口尚黄。","苍茫就岐路，感激问行藏。","别绪通幽隐，贫交在久长。","海天无处所，惆怅一相望。"]},{"t":"留则陶握山","f":"五言律诗","c":["只合住山老，胡为复有今。","此行难自问，何况是知音。","物外得无累，稠中见素心。","悠悠岐路意，沧海未为深。"]},{"t":"用韵留别庞鸿侣","f":"五言律诗","c":["斲取爨中烬，被弦成五音。","为君弹一曲，举世少知心。","满载孤云去，言观大海深。","到时无可寄，惟有水龙吟。"]},{"t":"用韵留别胡大灵","f":"五言律诗","c":["舟楫送羁客，门闾倚老亲。","分明眼前事，疑杀意中人。","大海载孤月，单车转只轮。","我心正如此，惭叹可谁陈。"]},{"t":"途中口占","f":"五言律诗","c":["望望知何去，悠悠不定家。","泥深九折坂，尘冒只轮车。","斜日闻归鸟，回风见落花。","不堪回首处，几片赤城霞。"]},{"t":"宿那旦","f":"五言律诗","c":["日入山欲暝，我行聊启居。","三閒破茅屋，一宿即吾庐。","砧急秋声外，月光人定初。","今宵且高枕，来日复何如。"]},{"t":"晓发太平","f":"五言律诗","c":["轻舟胜驽马，周道似盘蛇。","不为披星往，何由见月华。","野风吹白草，零露湿黄花。","谁念悲秋客，长歌怀宋家。"]},{"t":"陆公泉","f":"五言律诗","c":["此老去云远，茶经渐不传。","如何荒徼外，亦有陆公泉。","一勺还刍牧，千流及稻田。","纷纷行路子，谁与共潺湲。"]},{"t":"过韩公堤","f":"五言律诗","c":["精卫填沧澥，虹蜺贯石梁。","崎岖如鸟道，曲折胜羊肠。","旷野人烟渺，平原客路长。","无端过桥去，归目滞雷阳。"]},{"t":"十月朔英利道中作","f":"五言律诗","c":["去国正重九，中途逢小春。","水喧争渡客，山静过桥人。","岂效枯鱼泣，言随野马尘。","明朝潮汛好，行矣莫逡巡。"]},{"t":"寄李苍水广文","f":"五言律诗","c":["濠梁相见后，一别一回春。","知尔非干禄，微官聊称贫。","仕途容傲吏，僧外作閒人。","莫远高凉席，天边有隐沦。"]},{"t":"故友梁腾虎困死朱崖，就地藁葬。九月登高望远，凄然有存亡之感","f":"五言律诗","c":["白日孤光尽，英雄志气衰。","瀰天皆宿草，何处葬要离。","蜗国人休战，橘中谁斗棋。","漫将成败理，持语髑髅知。"]},{"t":"寄西宁张明府 其一","f":"五言律诗","c":["不到泷中久，难忘最胜缘。","梅砰城外寺，龙井石间泉。","白日供身老，青山待我禅。","还思寻旧隐，闻说长官贤。"]},{"t":"寄西宁张明府 其二","f":"五言律诗","c":["旧识罗浮子，西归惠好音。","一官清似水，四野沛为霖。","游刃良庖技，挥毫郢匠心。","殷勤出佳句，留与老僧吟。"]},{"t":"寄西宁张明府 其三","f":"五言律诗","c":["吏习久不振，斯人方起衰。","循良追古道，儒雅式今兹。","政洽看鹰化，心閒有鹤知。","何当弦诵地，容我结茅茨。"]},{"t":"寄西宁张明府 其四","f":"五言律诗","c":["佳气郁葱葱，琴台日出东。","五弦弹解愠，六月来薰风。","闻者饮馀善，与人存大公。","谁能为此曲，无乃是文翁。"]},{"t":"寄西宁张明府 其五","f":"五言律诗","c":["五岭丹砂窟，神仙作令多。","文章鸿渐陆，枳棘凤巢阿。","高缀赤松实，旁分泷水波。","五云如可赠，借我护藤萝。"]},{"t":"送岑金纪游珠崖五首 其一","f":"五言律诗","c":["海外曾归客，春来复送人。","相看同去住，临别且逡巡。","去以初弦月，行当渐满轮。","不应惟独照，凭尔辨疏亲。"]},{"t":"送岑金纪游珠崖五首 其二","f":"五言律诗","c":["壮志销磨尽，孤云独自飞。","平生远游意，多半与心违。","五岳我将去，三年君始归。","何时更来此，同采粤山薇。"]},{"t":"送岑金纪游珠崖五首 其三","f":"五言律诗","c":["江海未云远，山川宁阻长。","遥情寄溟渤，高咏别沧浪。","榻下青毡地，兰生古桂旁。","悠悠浮海意，千里忆同堂。"]},{"t":"送岑金纪游珠崖五首 其四","f":"五言律诗","c":["郭外灵泉寺，精蓝隐半峰。","僧惟多异主，人有合溪翁。","扣石千山应，闻香百和同。","为君先指注，到日好追从。"]},{"t":"送岑金纪游珠崖五首 其五","f":"五言律诗","c":["我爱海潮胜，层岩亲手开。","此身难久住，三载许重来。","曲磴丹梯入，高窗碧嶂回。","劳君老词客，拂拭旧莓苔。"]},{"t":"关中绝粒寄陶握山","f":"五言律诗","c":["一月不相见，三年当远行。","路难凭忍力，别久识交情。","绝粒惭僮仆，空函报友生。","谁怜桑扈病，风雨正霖瓴。"]},{"t":"观云海","f":"五言律诗","c":["岳顶半閒屋，终朝云满林。","千峰无远近，一气自高深。","老眼随烟雾，浮生任陆沉。","松风吹不尽，化作海潮音。"]},{"t":"题吴琬若新楼","f":"五言律诗","c":["旧隐经游地，新楼结构工。","谁知读书处，仍在落花中。","渐觉苔痕浅，难教茗椀空。","请君下孤榻，借我息征蓬。"]},{"t":"泊西南渡口与马山诸子分赋","f":"五言律诗","c":["萧条葭菼外，孤棹与君期。","山月初圆夜，江潮正上时。","远峰晴后见，幽兴静中知。","隔岸沧浪叟，长歌应为谁。"]},{"t":"与卢雁林宿本庵留别弛赝师","f":"五言律诗","c":["暂此息劳生，劳生空复情。","寒风吹老树，竟夕作秋声。","明发我当去，夜深人独行。","蒙师爱吟客，一事笑无成。"]},{"t":"山中女松短者及肩长可荫屋青阴绕垣葱茜可爱偶为樵苏剪伐殆尽诗以惜之","f":"五言律诗","c":["如此孤高性，应难免俗人。","有心成琥珀，无计护龙鳞。","日月空双影，风涛静四邻。","生平牢落意，持尔问芳春。"]},{"t":"盘中小松","f":"五言律诗","c":["小松不满尺，来自南山陲。","劲节苦相屈，高踪聊自卑。","风涛随物化，形影与僧宜。","但适鹪鹩性，何妨借一枝。"]},{"t":"瓶中桃花","f":"五言律诗","c":["野径春芳早，夭桃放小红。","东君留不住，飞入玉壶中。","有水皆成浪，无香岂借风。","灵云亲见后，折赠意何穷。"]},{"t":"春夜诸子过集马山听卢雁林弹琴","f":"五言律诗","c":["故人抱枯木，过我南山陲。","开匣理新曲，君心如旧时。","指边灯影乱，弦外雨声随。","静者匪徒默，幽怀谁得知。"]},{"t":"送玉泉师还匡庐","f":"五言律诗","c":["玉泉不识面，识得玉泉心。","暂作还乡客，终当返旧林。","万杉寻路入，五老闭门深。","我亦孤峰宿，无由共一岑。"]},{"t":"题卢雁林弹琴小影","f":"五言律诗","c":["明月满天下，一人弹素琴。","元音发枯木，馀响出疏林。","静极须眉冷，渺然闻见深。","谁能写空影，相对助长吟。"]},{"t":"珠江月夜泛舟","f":"五言律诗","c":["生平湖海客，薄暮钓鱼船。","回首见孤月，严城夜悄然。","波摇江上寺，云净水中天。","一曲沧浪外，知音何处边。"]},{"t":"送陈王屋还五羊","f":"五言律诗","c":["囊轻奇石重，之子未全贫。","挥手别良友，归心缘老亲。","城中为客久，海外得交新。","我欲从兹住，重来有主人。"]},{"t":"和马专城卧仙来韵","f":"五言律诗","c":["青云出高岫，倦鸟独归林。","影入清池去，相看无浅深。","爱僧成久坐，即事每长吟。","野客容疏散，唯公知我心。"]},{"t":"和刘明府仰山来韵","f":"五言律诗","c":["从此苍苔上，知难免屐痕。","竹风频埽榻，松月静开门。","要识宾中主，须寻郭外村。","新诗题满壁，相对两无言。"]},{"t":"和程公玉来韵 其一","f":"五言律诗","c":["所居非一一，随地足平生。","吾志在山水，因之移性情。","不材人共弃，何幸老无成。","愿得长如此，终身住铁城。"]},{"t":"和程公玉来韵 其二","f":"五言律诗","c":["高人叩我户，白板暂时开。","好句袖中出，清风天上来。","微吟动琴瑟，寒色入茶杯。","为问蹇驴上，敲推曾几回。"]},{"t":"杨凌霜郑秉渊衍源诸子过宿东林 其一","f":"五言律诗","c":["高人抱幽独，薄暮款松关。","坐久为予说，城中无此閒。","孤灯堪引兴，清论不离山。","更有微言在，明朝莫便还。"]},{"t":"杨凌霜郑秉渊衍源诸子过宿东林 其二","f":"五言律诗","c":["衰鬓惊年暮，閒心与地偏。","对君何所似，春近夕阳边。","短烛照无梦，寒灰拨有烟。","知音爱禅寂，默坐岂徒然。"]},{"t":"缪西泠雨中见寄用韵赋答","f":"五言律诗","c":["柴门连日雨，且得暂时关。","风入如无树，云来不碍山。","隔城通一水，为屋各三间。","好句劳相寄，于君见一斑。"]},{"t":"冬日缪西泠杨式卿见过值予他出留诗于壁既归用韵答之","f":"五言律诗","c":["爱此池上屋，无人也自佳。","出门刚半日，落叶满空阶。","过客留新句，归僧及午斋。","红尘暗城市，踪迹愧吾侪。"]},{"t":"立春日和缪西泠韵","f":"五言律诗","c":["里鼓喧残腊，东风吹落梅。","土牛迎气出，青鸟报春来。","城市嚣尘满，园林老景催。","蓬山如可到，东海事浮杯。"]},{"t":"元日友人见过和缪西泠韵","f":"五言律诗","c":["寸阴同隙驶，今古一蘧庐。","新岁几时到，三更见日初。","多情难久别，高咏近何如。","莫惜频相过，繁星向晓疏。"]},{"t":"元日柬杨式卿和缪西泠","f":"五言律诗","c":["谷风初解冻，衣线渐生春。","不觉纸窗白，方知曙色新。","味君怀里字，饮我杯中醇。","珍重草玄子，如何酬故人。"]},{"t":"夏日偕诸子舟泛虎溪望涯而返归舟分赋","f":"五言律诗","c":["旧识虎溪路，今从溪上行。","一乘青雀舫，重订白鸥盟。","何必践斯境，应知惬野情。","渺然发归兴，遥寄棹歌声。"]},{"t":"泊江口","f":"五言律诗","c":["江上月初上，潮头风更清。","隔船闻夜语，停棹待天明。","倦鹤得无梦，远鸡如有情。","生平浪游意，支枕计纵横。"]},{"t":"端午与诸子再泛虎溪分赋","f":"五言律诗","c":["东林非久住，爱此一溪深。","隔水见云树，扁舟何处寻。","蒲香仍旧节，荔重亚新阴。","不见沧浪叟，谁为楚客吟。"]},{"t":"缪西泠失意还山以诗见寄赋答","f":"五言律诗","c":["偶然乘兴往，兴尽便当归。","云鹤有奇翼，碧天无定飞。","故人悬宿诺，前路愿多违。","明日期君去，孤峰一振衣。"]},{"t":"还东林社中诸子见过赋此","f":"五言律诗","c":["依旧去年人，还山自主宾。","瘦藤支病骨，老树倚吟身。","懒惰成吾癖，交游知我真。","倘能恕迎送，来往不嫌频。"]},{"t":"答何赤木见赠","f":"五言律诗","c":["草堂聊寄宿，到处即吾庐。","推枕见明月，隔窗闻读书。","冥心契玄理，即事成真如。","最爱任公子，临渊不羡鱼。"]},{"t":"观音石","f":"五言律诗","c":["山色无今古，居然清净身。","一真常不动，万象自相亲。","云过天衣白，花开宝髻春。","夜来南海月，长照点头人。"]},{"t":"童子石","f":"五言律诗","c":["唤尔作顽石，旁观为不甘。","轩渠忘语默，匍匐学槃谈。","人事有雕琢，童心无二三。","百城烟水外，相望在同参。"]},{"t":"天台岩","f":"五言律诗","c":["同游成异物，旧约忆当年。","寂寞天台路，临风一怆然。","石梁通破屋，野火烧荒田。","便欲从兹住，空山磨瓶砖。"]},{"t":"答顿惺师韵","f":"五言律诗","c":["我爱此山久，来时秋已冬。","閒身如病鹤，清影寄寒松。","磊磊涧中石，遥遥天际峰。","相看云水意，何日信孤筇。"]},{"t":"小西山阻雨赠石光静主","f":"五言律诗","c":["雨过西山寺，栖迟夜雨天。","不知归路远，多谢主人贤。","一夕家常话，三心物外禅。","兹游殊草草，重订再来缘。"]},{"t":"马卧仙榜其堂曰乔松用韵题赠","f":"五言律诗","c":["所托自高远，悠然思岱宗。","审能存劲节，何用寄孤峰。","带砺齐铜柱，风云迈赤松。","大夫安足似，千古有犹龙。"]},{"t":"残漏","f":"五言律诗","c":["群动寂以寂，此声微更微。","幽人一为听，终夜独披衣。","日月有代谢，风尘渐息机。","永怀归白社，无梦到黄扉。"]},{"t":"舟入鼎湖赠同舟居士","f":"五言律诗","c":["何幸识高贤，同舟岂偶然。","暮山长带雨，秋水远浮天。","归路征帆外，禅心落叶边。","相期携手处，遥指鼎湖巅。"]},{"t":"风琴","f":"五言律诗","c":["金石发清响，隔窗知有风。","五弦非所借，一气自潜通。","流水不归梦，钧天时下空。","倚檐独无语，閒杀老梧桐。"]},{"t":"社集香莲庵同赋初秋野望用酡字","f":"五言律诗","c":["车笠偶相过，香台胜事多。","凭高感摇落，秋色满林阿。","霁景连云薄，霜痕带叶酡。","宗雷初到社，吟望更如何。"]},{"t":"病中答徐铎愚韵","f":"五言律诗","c":["护懒因成病，求閒遂厌身。","三竿欹枕日，一线破窗尘。","药饵增形役，文章损性真。","郡人徐孺子，高咏若为邻。"]},{"t":"种柳 其一","f":"五言律诗","c":["昨日是寒食，今朝蓺植初。","言寻彭泽传，细读郭驼书。","立处不妨密，行边正欲疏。","春光眠复起，青眼为谁舒。"]},{"t":"种柳 其二","f":"五言律诗","c":["种就宅边柳，朝来野趣新。","渐闻莺语近，不与马蹄亲。","力弱偏临水，心孤懒送人。","东风为培植，宁羡六桥春。"]},{"t":"夕霞 其一","f":"五言律诗","c":["暝色入返照，馀光何陆离。","晦明互迭代，云物交蔽亏。","玄黄战龙血，煜爚渐鸿仪。","我欲匿光影，长歌天一涯。"]},{"t":"夕霞 其二","f":"五言律诗","c":["一片桑榆色，化为天文章。","太虚互明灭，二气交玄黄。","不逐赤鸟没，将随飞鹭行。","野人驱犊返，暝色何苍苍。"]},{"t":"石云山晚渡","f":"五言律诗","c":["暝色渐迷津，招招唤渡频。","烟横石云路，柳暗塔坡春。","见月知潮汐，登舟辨主宾。","芦中有穷士，应是未归人。"]},{"t":"南雪","f":"五言律诗","c":["炎乡曾未见，一见一咨嗟。","越犬吠篱落，村童扑柳花。","十年知可卜，九穗愿非奢。","莫更分南北，乾坤总一家。"]},{"t":"秋鹰","f":"五言律诗","c":["正好乘风去，樊笼未可留。","商声遍原野，归思在高秋。","白草藏狐兔，青骹耻臂鞲。","泬寥须纵目，遮莫类胡愁。"]},{"t":"题画","f":"五言律诗","c":["一片涳濛色，平生水石心。","天空云出岫，山静鸟依林。","远近神俱往，登临兴转深。","无弦志有在，终古待知音。"]},{"t":"壬午重阳后一日初住大通古寺罗戒轩黄葵村霍西牛陈臣张过宿同赋同葵村韵 其一","f":"五言律诗","c":["已有重阳约，前期不待招。","别君才几日，留客在今宵。","宿草初漙露，新钟复应潮。","晨兴事园圃，野菜及时挑。"]},{"t":"壬午重阳后一日初住大通古寺罗戒轩黄葵村霍西牛陈臣张过宿同赋同葵村韵 其二","f":"五言律诗","c":["未能舍良友，不觉出山扉。","竹岛来筇杖，松梢挂衲衣。","江城无事到，乡梦有时归。","明发鹅潭北，群鸥各自飞。"]},{"t":"答郭殿邦见过韵","f":"五言律诗","c":["犬吠知有客，客从何处来。","我心似柴栅，相见一为开。","索句吟幽砌，看花上古台。","东篱秋意尽，留兴待寻梅。"]},{"t":"卜居","f":"五言律诗","c":["仙老拔宅去，驱鸡飞上天。","如何种桃处，鸣吠尚依然。","我欲问往事，翁来殊少年。","此中山可买，愿解腰閒缠。"]},{"t":"双桂天公见过用韵赋答 其一","f":"五言律诗","c":["江城朝放棹，冲破沧浪烟。","辍棹入林去，春风相后先。","焚香煨芋火，拾菜种花田。","恰好留嘉客，斋钟正午前。"]},{"t":"双桂天公见过用韵赋答 其二","f":"五言律诗","c":["独立红尘外，低垂白发新。","松高云里影，僧老佛边身。","出处输前辈，蹉跎愧好春。","却凭双桂主，一一指迷津。"]},{"t":"旱 其一","f":"五言律诗","c":["途穷生计拙，临老事躬耕。","不谓三春雨，翻为百日晴。","火云乾木叶，斥卤入茶铛。","吾道今如此，凭谁寄一声。"]},{"t":"旱 其二","f":"五言律诗","c":["耕凿全无赖，萧条又日曛。","秧针黄荏苒，草脚绿缤纷。","近水难成润，远山时有云。","不堪禅定处，野哭静中闻。"]},{"t":"旱 其三","f":"五言律诗","c":["自笑东樵拙，长饥不废禅。","墦閒无冻馁，烟火有神仙。","舍此不肯住，咄哉空复然。","良田多旱岁，敢望又逢年。"]},{"t":"花田寒食","f":"五言律诗","c":["出郭望村烟，村烟朝寂然。","偶逢卖鱼者，相引过花田。","有人怨长夜，无语忆当年。","惆怅幽芳外，伊人何处边。"]},{"t":"答徐琶洲来韵","f":"五言律诗","c":["我心渺无际，独向沧洲来。","隐几舒双睫，坳堂覆一杯。","美人隔江水，野径生莓苔。","珍重池上约，莲花谁为开。"]},{"t":"答卢雁林来韵","f":"五言律诗","c":["近水识潮信，盈盈时复消。","所思半城市，相望一迢遥。","好月不终夕，孤灯难竟宵。","故山有丛桂，行矣不须招。"]},{"t":"答韩纬五来韵","f":"五言律诗","c":["长夏读佳句，冷然冰雪寒。","轻车驰峻阪，孤棹下危滩。","自得风人旨，何须作者坛。","有怀待君语，相见语应难。"]},{"t":"答崖口谭耿章来韵","f":"五言律诗","c":["世界大如此，何妨容一僧。","风曾留老叶，月不厌孤灯。","空谷十年梦，寒山几度冰。","因君思旧隐，云树渺层层。"]},{"t":"除夕前一日杨式公舟次大通阻风信宿同赋","f":"五言律诗","c":["借问汾江路，经旬几往还。","客途逢爆竹，归思在斓斑。","烟雨云笼寺，风涛雪簸山。","留君连夕话，诗兴正相关。"]},{"t":"春日双桂天公偕何孟门过访归后唱和见寄用韵赋答 其一","f":"五言律诗","c":["囊中剩有钱，频买渡江船。","共载孟门叟，遥冲古渡烟。","溪回松影直，林静鸟声圆。","即此堪留语，何须杜撰禅。"]},{"t":"春日双桂天公偕何孟门过访归后唱和见寄用韵赋答 其二","f":"五言律诗","c":["古道寂还寂，真风微更微。","不因来杖履，终拟掩柴扉。","閒身乘化往，冷眼见花飞。","识得华亭老，长歌怀钓矶。"]},{"t":"和何孟门韵 其一","f":"五言律诗","c":["久默得良晤，清言尽入微。","殷雷发深蛰，烟雨辟重扉。","独鹤沉冥住，高云远近飞。","不妨青白眼，观物到渔矶。"]},{"t":"和何孟门韵 其二","f":"五言律诗","c":["谁知钟板外，也有懒残禅。","一钵甘匏系，三衣抱影眠。","无人知此意，吾道失真传。","莫怪何居士，招呼不上船。"]},{"t":"和圣冶师来韵","f":"五言律诗","c":["久向樵西寺，伊人在翠微。","几时归旧社，高咏寄蓬扉。","隔水空延伫，临风欲奋飞。","还山如有约，书札报渔矶。"]},{"t":"答张子白 其一","f":"五言律诗","c":["独住非无谓，出门仍独行。","何来天上客，偏有野人情。","谷静闻莺早，官閒爱鹤清。","不妨烟雨地，相过及晴明。"]},{"t":"答张子白 其二","f":"五言律诗","c":["桂棹木兰船，相将待济川。","朝来风力便，北上锦帆悬。","捩舵迂江路，迥樯问水田。","猛然发清啸，声出四禅天。"]},{"t":"答张子白 其三","f":"五言律诗","c":["欲去更徘徊，维舟向晚开。","别僧留白粲，归客踏苍苔。","古道得如此，今人何有哉。","微言难草草，相待隔年来。"]},{"t":"答张子白 其四","f":"五言律诗","c":["村童歌竹枝，吟得长官诗。","白社思宗炳，黄金铸子期。","河清容吏隐，山静与僧宜。","中宿曾游处，归耕及此时。"]},{"t":"答张子白 其五","f":"五言律诗","c":["别路雪纷纷，远天多白云。","好音须继响，无语亦相闻。","雪曲追三叠，银钩仿八分。","归吟劳远寄，开卷见鹅群。"]},{"t":"答杨鬯侯 其一","f":"五言律诗","c":["偶识珠江老，吟诗一送行。","有人旁著眼，于我独深情。","古寺高歌入，真风出袖清。","冰壶贮秋月，相对总虚明。"]},{"t":"答杨鬯侯 其二","f":"五言律诗","c":["脉脉临江浒，朝朝见逝川。","懒腰三篾束，慧命一丝悬。","病鹤投深树，羸牛耕瘠田。","劳君指生计，春近大寒天。"]},{"t":"答杨鬯侯 其三","f":"五言律诗","c":["花径久不埽，蓬门今始开。","自从来此地，门径积层苔。","老病已如此，先生何壮哉。","相逢忘主客，何处是归来。"]},{"t":"答杨鬯侯 其四","f":"五言律诗","c":["持戒非因律，逃禅未废诗。","言前无可荐，悟后与君期。","省事翻添设，多閒失便宜。","二禺凭寄语，迟我耦耕时。"]},{"t":"答杨鬯侯 其五","f":"五言律诗","c":["孤舟载孤月，行客逐行云。","真籁寂还寂，斯人闻未闻。","诗篇酬唱得，语默主宾分。","应念空山里，归猿独恋群。"]},{"t":"和张子白来韵 其一","f":"五言律诗","c":["于人何落落，在我本如如。","就树因鸣鸟，临渊不羡鱼。","江清涵寺影，云白洞窗虚。","以此遥相见，真交澹有馀。"]},{"t":"和张子白来韵 其二","f":"五言律诗","c":["官衙清且远，猿鹤许为邻。","与世无多涉，逢僧偶一亲。","百城聊自富，五斗未为贫。","好句劳相赠，吟来字字新。"]},{"t":"和张子白来韵 其三","f":"五言律诗","c":["别来曾几日，又是大除天。","枕畔闻虫语，灯边抱鹤眠。","梦中逢傲吏，醒后笑枯禅。","无事还生事，将诗和一篇。"]},{"t":"和张子白来韵 其四","f":"五言律诗","c":["过时容我懒，开岁阅人忙。","容屦已盈户，僧禅犹踞床。","馀閒可相假，持赠也何妨。","报语泔鱼者，吾宗在奥藏。"]},{"t":"和张子白来韵 其五","f":"五言律诗","c":["春水渐盈科，清溪近若何。","美人阻迢递，旧路想经过。","且喜青山近，都忘白发多。","二禺读书处，迟尔答狂歌。"]},{"t":"和张子白来韵 其六","f":"五言律诗","c":["瘦藤扶病骨，老树息閒身。","客去无多久，春光分外新。","再来成熟路，相戒护重茵。","莫讶江天迥，回车近北辰。"]},{"t":"和张子白来韵 其七","f":"五言律诗","c":["清风来瓮牖，斜日射横塘。","晚食客须饱，园蔬味倍长。","铅刀磨更钝，枯木爇来香。","相对明松火，邻灯懒借光。"]},{"t":"和张子白来韵 其八","f":"五言律诗","c":["野花开簇簇，江岸曲隈隈。","此地人稀到，仙郎首重回。","莺声初睍睆，云影自徘徊。","借问朝天客，何时许再来。"]},{"t":"和张子白来韵 其九","f":"五言律诗","c":["不谓行藏异，相期共入林。","胶中空色相，弦外有知音。","潭虚云写影，天静月当心。","珍重临岐意，清江未当深。"]},{"t":"和张子白来韵 其十","f":"五言律诗","c":["有声因有响，无响更何如。","空谷闻人语，此间非我庐。","云嫌茅舍浅，风笑竹篱疏。","莫怪嵇生懒，经旬未报书。"]},{"t":"和张子白来韵 其十一","f":"五言律诗","c":["美人弹玉轸，声彻承明庐。","使我侧双耳，与君游六虚。","欲写山水志，其如心手疏。","何时刺船去，就尔松皋居。"]},{"t":"苦雨和杨鬯侯见寄 其一","f":"五言律诗","c":["积雨鹅潭阔，烟波入渺冥。","风蓑疑鹤影，云盖想山形。","抱瓮得无事，淋瓴不可听。","非关春梦短，缊被湿频醒。"]},{"t":"苦雨和杨鬯侯见寄 其二","f":"五言律诗","c":["鼁从灶底出，尘向甑边生。","歌哭怜桑扈，猖狂笑弥平。","山飞云黯澹，海立雨砰訇。","不少迷津客，停车问耦耕。"]},{"t":"用张子白韵寄姚齐州十首 其一","f":"五言律诗","c":["暂离兜率院，现作宰官身。","红雨家家遍，青苗处处新。","涉江维彩鹢，就地布文茵。","犹胜陶彭泽，攒眉过此辰。"]},{"t":"用张子白韵寄姚齐州十首 其二","f":"五言律诗","c":["簿书无暇日，琴鹤有閒身。","古道寂寥久，今来闻见新。","野棠初税驾，莎草藉为茵。","留得清风在，枯禅坐竟辰。"]},{"t":"用张子白韵寄姚齐州十首 其三","f":"五言律诗","c":["珠江一片月，留影在横塘。","高下遥相见，清辉分外长。","春融鱼在藻，花发水添香。","贮向冰壶里，萤灯逊夜光。"]},{"t":"用张子白韵寄姚齐州十首 其四","f":"五言律诗","c":["衰年辞石洞，匿影近江隈。","蜗壳庐三折，羊肠路九回。","无人恕疏懒，静者独徘徊。","薄暮抱琴去，明朝许再来。"]},{"t":"用张子白韵寄姚齐州十首 其五","f":"五言律诗","c":["见说河阳县，春来花满林。","桑麻依保障，弦诵想清音。","老我躬耕计，劳君抚字心。","江皋时极目，云树一何深。"]},{"t":"用张子白韵寄姚齐州十首 其六","f":"五言律诗","c":["新巢鸣巧妇，借得一枝安。","多谢阳和力，都忘雪霰寒。","春明花外影，群动镜中看。","自是栖心法，持将问鹖冠。"]},{"t":"用张子白韵寄姚齐州十首 其七","f":"五言律诗","c":["神仙多吏隐，山水独关情。","一与閒云遇，悠然逸兴生。","有人倚丹嶂，招手入朱明。","知是葛洪子，重来寄一声。"]},{"t":"用张子白韵寄姚齐州十首 其八","f":"五言律诗","c":["野鹤依林静，池鱼戏水浑。","萧条三亩宅，烟火数家村。","辍棹过亭午，登舟已夕曛。","郎官何处所，双阙一星存。"]},{"t":"用张子白韵寄姚齐州十首 其九","f":"五言律诗","c":["美人抱明月，挂在禺山西。","城里一峰见，天边群岫低。","望来心自远，欲去路还迷。","罢钓将双鲤，缄书索品题。"]},{"t":"用张子白韵寄姚齐州十首 其十","f":"五言律诗","c":["耳闻中宿语，心赏隔江禅。","恕我逢人懒，多君地主贤。","蒲团分客座，竹榻待谁悬。","后夜如相念，芦花宿钓船。"]},{"t":"姚齐州有爱子之戚书闷诗见示依韵赋慰 其一","f":"五言律诗","c":["椿龄齐菌朔，倏忽八千春。","昨日非前日，今人成古人。","白驹空隙影，明月失家珍。","尘世关心事，东林好问津。"]},{"t":"姚齐州有爱子之戚书闷诗见示依韵赋慰 其二","f":"五言律诗","c":["白日一修短，黄河几浊清。","磨来成慧剑，持去破愁城。","泡影归无朕，蜉蝣笑此生。","莫将离合意，看作宓琴声。"]},{"t":"姚齐州有爱子之戚书闷诗见示依韵赋慰 其三","f":"五言律诗","c":["荠苨浑甘苦，调剂任吐吞。","得知无味味，方信不存存。","珠去光还在，尘来镜不昏。","长歌过赢博，何用赋招魂。"]},{"t":"姚齐州有爱子之戚书闷诗见示依韵赋慰 其四","f":"古风","c":["一息成长夜，三呼唤不来。","慈鸦难恋乳，鸣鹤易增哀。","疋练横空去，?骝接踵回。","秋风生筦簟，丛桂又花开。"]},{"t":"李雪峰过寺约游中宿老病为辞别后见寄用韵赋答并寄张子白 其一","f":"五言律诗","c":["别去情何限，今来意倍亲。","隔江须我友，大地更无人。","白首嗟岐路，青云据要津。","不知鸡犬外，何处可逃秦。"]},{"t":"李雪峰过寺约游中宿老病为辞别后见寄用韵赋答并寄张子白 其二","f":"五言律诗","c":["渐与烟霞密，都忘城市疏。","浮生寄云水，一宿即蘧庐。","似有安身地，还同借宅居。","行藏劳见读，风急鹤飞徐。"]},{"t":"李雪峰过寺约游中宿老病为辞别后见寄用韵赋答并寄张子白 其三","f":"五言律诗","c":["坚谢名山请，翛然逸兴高。","息肩弛重担，闭户补方袍。","抚景身先老，看云首重搔。","殷勤问埏埴，今有几人陶。"]},{"t":"李雪峰过寺约游中宿老病为辞别后见寄用韵赋答并寄张子白 其四","f":"五言律诗","c":["翘首归猿洞，怀人水一方。","鸟啼诵经处，花落读书堂。","密约知难践，久要宁敢忘。","空劳枉书札，相劝理舟航。"]},{"t":"李雪峰过寺约游中宿老病为辞别后见寄用韵赋答并寄张子白 其五","f":"五言律诗","c":["晚年惟善病，高卧当登临。","近得偷安法，无心事苦吟。","嗒然吾丧我，慨独古成今。","为报禺君道，何时共入林。"]},{"t":"初秋晚望","f":"五言律诗","c":["凉飔送残暑，薄暮一登台。","天地无门户，秋声何处来。","白衣变苍狗，紫陌生黄埃。","翘首云边鹤，高飞独不回。"]},{"t":"秋日寓中宿华严精舍舍后有树名九里香花叶并茂李东园赋诗六章予至而和之亦触物写怀之意云尔 其一","f":"五言律诗","c":["爱此秋窗静，窗前花发时。","偶来快幽赏，别去有遐思。","城市迹如寄，烟霞性不移。","连林非所羡，独树乃为奇。"]},{"t":"秋日寓中宿华严精舍舍后有树名九里香花叶并茂李东园赋诗六章予至而和之亦触物写怀之意云尔 其二","f":"五言律诗","c":["东园老词客，一见一摩挲。","密约迟云水，新诗留薜萝。","故山成久别，此地偶同过。","珍重岁寒意，后凋良不磨。"]},{"t":"秋日寓中宿华严精舍舍后有树名九里香花叶并茂李东园赋诗六章予至而和之亦触物写怀之意云尔 其三","f":"五言律诗","c":["所居城里寺，如在雨花中。","密荫迎斜日，馀香散远风。","上膏窍混沌，天籁契参同。","犹胜连昌竹，萧萧生故宫。"]},{"t":"秋日寓中宿华严精舍舍后有树名九里香花叶并茂李东园赋诗六章予至而和之亦触物写怀之意云尔 其四","f":"五言律诗","c":["丰乐有真诀，善生良不殊。","护根如韫玉，惜叶似藏珠。","形影不相假，斧斤何处无。","偶来芳树下，迟尔立须臾。"]},{"t":"秋日寓中宿华严精舍舍后有树名九里香花叶并茂李东园赋诗六章予至而和之亦触物写怀之意云尔 其五","f":"五言律诗","c":["散木已如此，交衢顾亦稀。","谁能别薰莸，徒自惜芳菲。","九里远复远，一香微更微。","默然吾与子，相视在忘机。"]},{"t":"秋日寓中宿华严精舍舍后有树名九里香花叶并茂李东园赋诗六章予至而和之亦触物写怀之意云尔 其六","f":"五言律诗","c":["悠悠行路客，折尽岭头梅。","怜尔得真性，何天可借培。","隔墙人踯躅，薄暮鹤徘徊。","点尽苍苔色，明朝花又开。"]},{"t":"秋杪徐琶洲谭耿章梁止山韩纬五过寺值予远游留诗于壁归而和之 其一","f":"五言律诗","c":["故人理孤棹，冲破秋云根。","独鹤竟飞去，双松空候门。","此间无主在，底事与谁论。","想到吟诗虚，归来见屐痕。"]},{"t":"秋杪徐琶洲谭耿章梁止山韩纬五过寺值予远游留诗于壁归而和之 其二","f":"五言律诗","c":["蘧芦时一宿，云水日三迁。","顾我只如此，伊人胡不然。","重来难逆料，旧约且高悬。","篱落花开遍，相思何处边。"]},{"t":"罗浮山过访值予远游留诗而去既归复来出荷锄图索题用韵赋赠 其一","f":"五言律诗","c":["昨日别东林，客来烟雨深。","主人不可见，谁见主人心。","独鹤云中语，枯桐弦外音。","遥情当良觌，秋水碧千寻。"]},{"t":"罗浮山过访值予远游留诗而去既归复来出荷锄图索题用韵赋赠 其二","f":"五言律诗","c":["吾志在山水，君心无去来。","重来秋未晚，相对菊初开。","人写荷锄影，僧閒带月回。","何曾有离合，萍梗亦浮杯。"]},{"t":"中宿归舟赋得落日放船好和张子白韵 其一","f":"五言律诗","c":["落日放船好，好歌冽水湄。","偶来成独往，不复问前期。","近水观鱼乐，投林动鸟疑。","有怀殊未吐，默默许谁知。"]},{"t":"中宿归舟赋得落日放船好和张子白韵 其二","f":"五言律诗","c":["落日放船好，江声引兴长。","客途霜露白，归计菊花黄。","云薄秋山老，星微晓月光。","不堪回首处，香冷诵经堂。"]},{"t":"中宿归舟赋得落日放船好和张子白韵 其三","f":"五言律诗","c":["落日放船好，青天回白头。","乾坤双冷眼，沧海一虚舟。","百宝喧鼍市，千花簇蜃楼。","名山徒在望，惭叹为谁留。"]},{"t":"中宿归舟赋得落日放船好和张子白韵 其四","f":"五言律诗","c":["落日放船好，秋江色色新。","岸花低有影，霜叶净无尘。","岚气侵衣湿，山容觌面真。","入林空有约，吾已厌吾身。"]},{"t":"中宿归舟赋得落日放船好和张子白韵 其五","f":"五言律诗","c":["落日放船好，连宵宿钓矶。","渔灯分猎火，弦月接斜晖。","懒性逢时拙，虚名与愿违。","终当灌园去，抱瓮事忘机。"]},{"t":"中宿归舟赋得落日放船好和张子白韵 其六","f":"五言律诗","c":["落日放船好，閒鸥且共亲。","到家登彼岸，何处问迷津。","白发应怜我，青山不负人。","琅玕劳见赠，归橐未全贫。"]},{"t":"中宿归舟赋得落日放船好和张子白韵 其七","f":"五言律诗","c":["落日放船好，风波也自如。","虚君徐濡榻，还我伯英书。","三水逢官舫，千山走驿胥。","归来有新句，未惜报樵渔。"]},{"t":"中宿归舟赋得落日放船好和张子白韵 其八","f":"五言律诗","c":["落日放船好，西风拂面寒。","山光呈甸线，潭影静鲵桓。","篱薄千丛菊，阶除九畹兰。","还家秋未晚，忘却路行难。"]},{"t":"中宿归舟赋得落日放船好和张子白韵 其九","f":"五言律诗","c":["落日放船好，晴烟豁眼开。","名山无少分，兹意未全灰。","白首伤岐路，黄金待筑台。","水边三亩宅，长啸独归来。"]},{"t":"中宿归舟赋得落日放船好和张子白韵 其十","f":"五言律诗","c":["落日放船好，明朝到广州。","少閒思谢病，多默恐招尤。","浅水影还见，深山愿未酬。","武陵无可问，归向梦中求。"]},{"t":"中宿归舟赋得落日放船好和张子白韵 其十一","f":"五言律诗","c":["落日放船好，山川草草过。","未能舍良友，聊复答高歌。","世网关心切，山缘失意多。","祇应留傲骨，终老葬烟萝。"]},{"t":"中宿归舟赋得落日放船好和张子白韵 其十二","f":"五言律诗","c":["落日放船好，江城半掩门。","远风飘叶尽，近水飐花繁。","月魄销灯燄，霜痕浸发根。","掩篷时强寐，怀抱古人恩。"]},{"t":"中宿归舟赋得落日放船好和张子白韵 其十三","f":"五言律诗","c":["落日放船好，蹉跎计未成。","独怜归鸿晚，遥听乱鸦惊。","戍柝萦诗思，江声入旅情。","明明天上月，多半照浮生。"]},{"t":"中宿归舟赋得落日放船好和张子白韵 其十四","f":"五言律诗","c":["落日放船好，篷窗向月扃。","永怀在泉石，无梦到郊坰。","槐火烧香篆，松灯对梵经。","生涯吾已足，不用赋榛苓。"]},{"t":"中宿归舟赋得落日放船好和张子白韵 其十五","f":"五言律诗","c":["落日放船好，枯形与影连。","风轻催挂席，衣冷待装绵。","造物有分子，劳生或未偏。","将寻洗耳处，遑问定心泉。"]},{"t":"中宿归舟赋得落日放船好和张子白韵 其十六","f":"五言律诗","c":["落日放船好，天空雁阵长。","三禅同木石，一气任炎凉。","自分稽生懒，谁知点也狂。","隔江愁过涉，招手慎搴裳。"]},{"t":"中宿归舟赋得落日放船好和张子白韵 其十七","f":"五言律诗","c":["落日放船好，秋光尚有馀。","世由拘世谛，吾自返吾庐。","过眼千峰瘦，澄怀万象虚。","侯门难得到，何以曳长裾。"]},{"t":"中宿归舟赋得落日放船好和张子白韵 其十八","f":"五言律诗","c":["落日放船好，所思园绮俦。","汉芝柔可茹，周粟饱当休。","福地从猿住，天君与我游。","遐心如铁石，何处不相投。"]},{"t":"中宿归舟赋得落日放船好和张子白韵 其十九","f":"五言律诗","c":["落日放船好，归帆卸晚霞。","村童迎竹杖，溪鸟出芦花。","蜡屐时行脚，蒲团长在家。","凭谁辨劳逸，良晤阻天涯。"]},{"t":"游阳春作 其一","f":"五言律诗","c":["自笑不知老，人前便说山。","昨来逢好友，云自富春还。","许以方丈地，分将一半閒。","翛然生羽翼，飞出白云间。"]},{"t":"游阳春作 其二","f":"五言律诗","c":["孤棹发江口，连樯宿浅沙。","同人皆有役，于我独无他。","夜水闻争渡，春山梦到家。","所思老渔父，高枕对芦花。"]},{"t":"游阳春作 其三","f":"五言律诗","c":["岂有关心事，披衣坐到晨。","鸡声前浦日，鸟语隔山春。","多病凭僮仆，无成愧故人。","忘机吾已矣，鸥鹭或相亲。"]},{"t":"游阳春作 其四","f":"五言律诗","c":["高秋别中宿，二月下阳春。","未尽登临兴，终为寂莫人。","虚名难隐世，文字苦随身。","独立千峰外，长歌怀道真。"]},{"t":"泊洞口赠张雪崖","f":"五言律诗","c":["计程趋洞口，旧路忆筠城。","采药逢高士，班荆识姓名。","论交年谊密，问道世缘轻。","明发挂帆去，相思何限情。"]},{"t":"泊河头经同参故居","f":"五言律诗","c":["河头曾宿处，风景已全非。","旧社僧牢落，虚堂人到稀。","草深车辙断，烟冷佛灯微。","怅望同巢鹤，长空去不归。"]},{"t":"过竹步赠居亭谢处士","f":"五言律诗","c":["奇峰环碧落，乔木倚云根。","犬吠初来客，莺啼何处村。","池塘曾梦草，桃李欲无言。","许我陪皋座，主人无轾轩。"]},{"t":"题富春山房 其一","f":"五言律诗","c":["入林见修竹，竹色何苍苍。","旧是乌衣地，今为讲学堂。","谷风洞虚牖，山月照禅床。","留得孤僧住，悠然逸兴长。"]},{"t":"题富春山房 其二","f":"五言律诗","c":["山以富春名，春山富现成。","断金卑梓泽，介石薄连城。","姜桂堪调鼎，芝兰自荐馨。","翻嫌钓鱼叟，临老入东京。"]},{"t":"张子白舟过大通值予远游留诗而去归而和之 其一","f":"五言律诗","c":["借问阳春道，芒鞋费几文。","计程难计日，行脚即行云。","归客无消息，虚堂静见闻。","如何三径外，人迹乃纷纷。"]},{"t":"张子白舟过大通值予远游留诗而去归而和之 其二","f":"五言律诗","c":["久别还相问，重门偶不开。","烦君留好句，笑我未归来。","风过花移架，天空月印台。","春光正如此，兹意倩谁猜。"]},{"t":"初归大通张子白杨鬯侯过赠用韵赋答 其一","f":"五言律诗","c":["昨暮问津去，仙源意可通。","但寻流水入，不见桃花红。","归路日将夕，逢君话未穷。","东风莫相待，挥手别兰丛。"]},{"t":"初归大通张子白杨鬯侯过赠用韵赋答 其二","f":"五言律诗","c":["世路成胶柱，我心如转环。","腰包无一物，脚板有千山。","独鹤归来晚，片云飞去閒。","何由逐春雨，潇洒到人间。"]},{"t":"答罗萝石见过韵","f":"五言律诗","c":["门径久不埽，何人问懒禅。","来寻烟雨寺，高咏泬寥天。","古调对流水，清谈如涌泉。","野情信狂简，于尔独缠绵。"]},{"t":"梅雨","f":"五言律诗","c":["处处黄梅熟，轻雷布密阴。","田衣潮气入，山屐藓痕深。","溽暑移床榻，淋瓴溉釜鬵。","谁怜桑扈病，来此听高吟。"]},{"t":"秋阳","f":"五言律诗","c":["白雁来何暮，赤乌飞上天。","凉飙不到处，炎势尚依然。","倒影穿云薄，流黄濯锦鲜。","秋光分一半，留作月轮圆。"]},{"t":"秋居","f":"五言律诗","c":["黄叶满斋厨，金风为埽除。","人皆感摇落，吾独赋閒居。","地坼虫迁蛰，萤乾月照书。","闭门秋事好，霜后足园蔬。"]},{"t":"秋荷","f":"五言律诗","c":["倾盖水云乡，蒹葭各一方。","美人空解佩，楚客已无裳。","静贮三秋色，寻思十里香。","晚来涉江处，明月堕横塘。"]},{"t":"秋虫","f":"五言律诗","c":["也有凄清意，不知鸣向谁。","秋声愁并入，宵枕听还疑。","感物成吾老，卑栖宁尔为。","相思何处所，泥壁破柴篱。"]},{"t":"秋露","f":"五言律诗","c":["风霜因有色，草木自为家。","不去承仙掌，偏来湿桂花。","山光流沆瀣，秋色老烟霞。","寄语求仙者，琼浆未足誇。"]},{"t":"秋山","f":"五言律诗","c":["空林初落木，远岫可跻攀。","昨日涳濛际，今来几席间。","风高樵语近，天迥鹤飞还。","采采东篱菊，悠然心自閒。"]},{"t":"秋浪","f":"五言律诗","c":["秋水净如练，秋风漾縠纹。","萍踪何所寄，鸥鸟自为群。","放眼波涛阔，澄怀清浊分。","芦花与明月，相对白纷纷。"]},{"t":"秋雁","f":"五言律诗","c":["所畏风霜迫，遂于俦侣亲。","艰难长作客，飘泊不依人。","岳色回寒影，秋声起塞尘。","奋飞如可学，吾亦愿轻身。"]},{"t":"送人北上","f":"五言律诗","c":["高车辞矮屋，白马饰金羁。","风假鹏方便，天随人指挥。","故山老薇蕨，上苑醉芳菲。","翻笑灌园叟，傲然甘息机。"]},{"t":"春树 其一","f":"五言律诗","c":["老树不知老，无文也有文。","托根深处稳，生意静中分。","红绽花朝雨，青留叶底云。","荣枯今已定，何必问东君。"]},{"t":"春树 其二","f":"五言律诗","c":["携手入林去，新莺处处闻。","好春正如此，随地得逢君。","一色远复远，群芳分不分。","独留庭际影，高挂往来云。"]},{"t":"和诸子郊行见过","f":"五言律诗","c":["此老兴不浅，朝朝起振衣。","屐随吟客去，花送醉人归。","得句寻僧和，馀酲扣竹扉。","何妨茶当酒，留话到斜晖。"]},{"t":"泊琶洲寺访徐铎愚不遇","f":"五言律诗","c":["辍棹琶洲寺，洲边访隐沦。","相闻老词客，一去动经春。","鹤并云心远，鸥兼野色匀。","明朝洞天上，高咏与谁人。"]},{"t":"望罗浮怀旧隐","f":"五言律诗","c":["罗浮殊有情，久别若平生。","知我旧宾主，隔江遥送迎。","片云开石洞，高鹤下朱明。","是处有人在，半空闻笑声。"]},{"t":"舟次明月寺访远律师不遇闻师同日至大通也","f":"五言律诗","c":["昨夜见明月，所思疑在中。","今来明月寺，不与见时同。","一室宾亦主，片云西复东。","愿留烟雨宿，待我转飞蓬。"]},{"t":"借庵即事 其一","f":"五言律诗","c":["蒲团生两翼，飞出水云中。","水浅难留月，云行不待风。","亦知非久住，暂得免雷同。","翘首家山路，洞门东复东。"]},{"t":"借庵即事 其二","f":"五言律诗","c":["自古能閒少，求閒未易閒。","被人知住处，移屋入深山。","黄叶随流去，桃花送客还。","至今成口实，陈迹待谁删。"]},{"t":"借庵即事 其三","f":"五言律诗","c":["空手把锄锸，师心学老农。","护生耕熟地，挥汗种新松。","梅厌饶酸气，花憎带冶容。","客心何所寄，窗外绿阴浓。"]},{"t":"借庵即事 其四","f":"五言律诗","c":["藩篱原不有，草木自成围。","坚癖牢难破，閒心静入微。","鼠依贫屋瘦，犬傍懒人肥。","近得轻身法，无营但忍饥。"]},{"t":"借庵即事 其五","f":"五言律诗","c":["日涉须成趣，窥园见物情。","屋随蛙背住，蓑覆鹤身轻。","鹊为鸠藏拙，花先蜜治生。","贫儿多活计，从此息经营。"]},{"t":"借庵即事 其六","f":"五言律诗","c":["群动静中见，孤心物外降。","繁花蝇亦采，飞絮蚁能扛。","拔地藤千尺，摩空鹤一双。","野人非待兔，何事守枯桩。"]},{"t":"借庵即事 其七","f":"五言律诗","c":["高枕得无梦，朝眠胜坐驰。","蚊雷饶寸舌，虱阵朵双颐。","寂寂原非我，惺惺却是谁。","吾宗无此义，持去问希夷。"]},{"t":"借庵即事 其八","f":"五言律诗","c":["大地一孤僧，僧孤却有朋。","雨师供茗椀，风伯致薪蒸。","细语虫相答，求声鸟所能。","未应嫌拣择，褦襶是苍蝇。"]},{"t":"借庵即事 其九","f":"五言律诗","c":["雨后远天清，阶前异草生。","焦芽才甲柝，败种亦勾萌。","菌桂春芳歇，蕣花朝露荣。","桑榆吾老矣，努力事归耕。"]},{"t":"借庵即事 其十","f":"五言律诗","c":["昨得山中信，园荒宿雨馀。","虚堂旋野马，悬釜涸游鱼。","风入翻书乱，云来借宅居。","所闻快如此，所见复何如。"]},{"t":"宿胡宪公署中作 其一","f":"五言律诗","c":["久不到城市，胡为为此行。","主人真好道，知我本无情。","坐久月光满，茶香峡水清。","老来有深契，一笑足平生。"]},{"t":"宿胡宪公署中作 其二","f":"五言律诗","c":["大道难久默，澹交宁羡浓。","官衙初下榻，虚室自鸣钟。","此地有生客，故山无老农。","夜来作归梦，飞上最高峰。"]},{"t":"署中赠周季鹰刘山铭","f":"五言律诗","c":["罢弹冯煖铗，言伴净名禅。","真宰互相答，大虚中寂然。","醇醪推大雅，藜火绍前贤。","许我成三笑，相逢何处边。"]},{"t":"留别胡宪公","f":"五言律诗","c":["兴尽我当返，无劳怅路岐。","田家新米熟，岁晚涤场时。","此外复何事，怀人或有诗。","相闻许相过，计日补茅茨。"]},{"t":"初春姚明府见过即事六首 其一","f":"五言律诗","c":["久懒不埽径，春风生绿苔。","乍闻檐鹊语，知有贵人来。","赤脚陪仙舄，黄童递茗杯。","深言难草草，归棹莫频催。"]},{"t":"初春姚明府见过即事六首 其二","f":"五言律诗","c":["元日至谷日，高天无片云。","野情逐农圃，努力事耕耘。","城市远未远，春光分不分。","荷锄待膏雨，搔首问东君。"]},{"t":"初春姚明府见过即事六首 其三","f":"五言律诗","c":["吏隐如禅隐，琴书当簿书。","持将怀古意，来就野人居。","竹老迟抽笋，泉寒未决渠。","明朝春雨足，花下待篮舆。"]},{"t":"初春姚明府见过即事六首 其四","f":"五言律诗","c":["野寺山厨供，煎茶折露葵。","清风生两腋，迂论解双颐。","晚食君应饱，大烹吾岂知。","莫嫌如水澹，冰檗恰相宜。"]},{"t":"初春姚明府见过即事六首 其五","f":"五言律诗","c":["忆著去年别，曾将此日期。","感君无宿诺，出我未呈诗。","阳雪惭知己，岭云持赠谁。","奚囊倾未尽，留待再来时。"]},{"t":"初春姚明府见过即事六首 其六","f":"五言律诗","c":["皎皎云边鹤，铮铮壁上琴。","幽人称幽独，知己贵知心。","许我一片石，随僧共入林。","隔江招手处，相望在高深。"]},{"t":"南园梁又罙凌晨舟过大通留诗而去未及迎送即韵和之","f":"五言律诗","c":["万事易知足，馀閒反类贪。","僧犹甜鹤梦，客已渡鹅潭。","柳暗不成五，径荒无复三。","多君发归咏，留在破伽蓝。"]},{"t":"咏莲漏限韵 其一","f":"五言律诗","c":["圆音入清梵，池上有人来。","刻作千华漏，承将九品台。","细微通白业，馀润及青苔。","莫道无源委，坳堂水一杯。"]},{"t":"咏莲漏限韵 其二","f":"五言律诗","c":["脉脉割昏晓，明明无往来。","土圭停昼影，钟乳滴华台。","八水金沙地，千丝石发苔。","凭谁问消息，沧海一浮杯。"]},{"t":"答高裕公邑佐见寄韵","f":"五言律诗","c":["隔水遥相见，清风若许长。","全凭诗酒力，消遣簿书忙。","大雅崇昭代，新声薄晚唐。","野人扣牛角，为尔和康浪。"]},{"t":"答梁弋云见过韵","f":"五言律诗","c":["不于城市见，乃在水云边。","我欲狂歌去，君来且驻船。","雾深知豹变，泽媚识珠圆。","珍重闻诗者，阳春莫浪传。"]},{"t":"罗浮山三十咏 其一","f":"七言律诗","c":["閒身初住铁桥东，回忆家山事事同。","就树选藤增健仆，入林逢药慰衰翁。","峰高岂碍当中日，谷静常来正面风。","谁信岭云犹可赠，不堪持赠但长空。"]},{"t":"罗浮山三十咏 其二","f":"七言律诗","c":["洞门不掩有云封，土面灰头学老农。","野菜盈筐因长笋，枯柴充担为怜松。","地炉自种经旬火，水碓长留隔宿舂。","莫道此间寡邻并，午斋风送远山钟。"]},{"t":"罗浮山三十咏 其三","f":"七言律诗","c":["安居原不涉思惟，莫道吾宗也大奇。","夙习未能遵世谛，虚名偏喜少人知。","水边黄叶随流去，树里青山背日移。","拾得一枝无孔笛，前人吹破不堪吹。"]},{"t":"罗浮山三十咏 其四","f":"七言律诗","c":["年来得力是忘机，物外孤心渐入微。","虫惜清声终夜语，鸟因昭质榜林飞。","凭他风雨能侵席，到处晴阴不掩扉。","半角好山谁作主，自怜临老始知归。"]},{"t":"罗浮山三十咏 其五","f":"七言律诗","c":["宿雨初晴策短藜，看云行到乱峰西。","眼前图画无人绘，皮里诗囊且自携。","果熟静观连蒂落，松高曾记与眉齐。","分明一簇香风过，开遍山楂又木樨。"]},{"t":"罗浮山三十咏 其六","f":"七言律诗","c":["六时禅诵又斜曛，童子烧香礼愿文。","向晚也须迟掩户，前峰犹有未归云。","岩猿宿树仍留果，社鼠依山亦断荤。","莫怪痴心爱狂黠，相逢尽道不如君。"]},{"t":"罗浮山三十咏 其七","f":"七言律诗","c":["清晨客至暮方还，问我何心住此间。","在世但知聊寄迹，旁人都说是居山。","近嫌路有樵人识，渐觉门须侍子关。","他日与君相见处，断崖移屋不堪攀。"]},{"t":"罗浮山三十咏 其八","f":"七言律诗","c":["云头雨足楚姓腰，特地奇峰出汉霄。","微路暗通行石腠，把茅牢结凭松寮。","灶边泉号孤僧井，屋角田供一岁瓢。","个是老夫归宿处，时人惊弃幸相招。"]},{"t":"罗浮山三十咏 其九","f":"七言律诗","c":["终朝役役叹吾曹，络马穿牛共一牢。","野茧结成空自缚，文蛾飞去不堪缫。","重楼变幻随孤蜃，大地浮沉仗六鳌。","何处藏身没踪迹，华亭船子自家操。"]},{"t":"罗浮山三十咏 其十","f":"七言律诗","c":["一日能閒一日过，山中幽事岂须多。","风前众窍呈庄籁，月下群猴学楚歌。","土掬丹炉泥破灶，叶收仙篆补残蓑。","外边凭语应难信，曾记儿时讶橐驼。"]},{"t":"罗浮山三十咏 其十一","f":"七言律诗","c":["大地全安曲录床，尚馀閒隙置皮囊。","三间破屋难留客，一个孤僧亦过堂。","纳得须弥无芥子，持来赝药有真方。","闭门刈取庭除草，归去炉头较短长。"]},{"t":"罗浮山三十咏 其十二","f":"七言律诗","c":["昨夜灯前细雨声，晓来林鸟报新晴。","日乘风势排窗入，云写山光对枕横。","莲房未落兼花供，芋屋初开带叶烹。","二六时中且如此，明朝依旧可怜生。"]},{"t":"罗浮山三十咏 其十三","f":"七言律诗","c":["飞云天半碧层层，万仞孤峰不易登。","行遇断崖看撒手，去当无路莫牵藤。","一茎细草皆成药，方寸閒田可住僧。","多少懦顽难到处，程途终日问南能。"]},{"t":"罗浮山三十咏 其十四","f":"七言律诗","c":["经旬铜片一开奁，静处窥形敢自嫌。","任运去留今面目，因人颦笑旧须髯。","山风浩浩云归岫，天宇澄澄月到帘。","独往独来还独语，我生何幸老穷檐。"]},{"t":"客珠崖怀罗浮寄山中诸子三十韵 其一","f":"七言律诗","c":["隔水看山东复东，片云无住寸心同。","出逢岐路谁家子，钓尽江波何处翁。","覆顶千丝难禁雪，当门两齿不关风。","身閒投老知何日，独倚孤筇问碧空。"]},{"t":"客珠崖怀罗浮寄山中诸子三十韵 其二","f":"七言律诗","c":["海涛近枕夜淙淙，旅梦乡心未易降。","乘月一归云里洞，挂帆犹记寺临江。","三身衣覆枯僧榻，四壁灯明古佛幢。","香印半销人定后，飞虫何事触明窗。"]},{"t":"客珠崖怀罗浮寄山中诸子三十韵 其三","f":"七言律诗","c":["何须领众复匡徒，无事天真佛一躯。","飏下屠刀知广额，策开眉睫见宝卢。","宋人什袭藏顽石，胡贾千金市世珠。","大地有禅吾亦老，故山归去作樵夫。"]},{"t":"客珠崖怀罗浮寄山中诸子三十韵 其四","f":"七言律诗","c":["大好随身五尺藜，临行遗落石房西。","青山久客不归去，白发老僧凭借携。","忆昨破鞋乘月往，有时高笠与云齐。","秋来胜事知多少，辜负堂前古木樨。"]},{"t":"客珠崖怀罗浮寄山中诸子三十韵 其五","f":"七言律诗","c":["洞里主人去不来，好山抛向白云堆。","岩花落尽空中雨，野火烧残劫外灰。","虚室岂宜终日闭，重门相待及时开。","悬知开后仍虚室，寄语同参莫见猜。"]},{"t":"客珠崖怀罗浮寄山中诸子三十韵 其六","f":"七言律诗","c":["溪山非舌亦非身，久去重来见益亲。","四百峰中开别院，三千里外结芳邻。","苔生碧砌青如染，镜锁明窗净不尘。","为报诸方参学者，罗浮深处近无人。"]},{"t":"客珠崖怀罗浮寄山中诸子三十韵 其七","f":"七言律诗","c":["海气苍茫日色曛，客窗谁与细论文。","蹉跎别路连风雪，惆怅家山隔水云。","地足槟榔无菜茹，门饶鹳鹤厌腥荤。","几回欲寄南中信，底事何堪举似君。"]},{"t":"客珠崖怀罗浮寄山中诸子三十韵 其八","f":"七言律诗","c":["野老经年别古坛，东林岑寂叶重丹。","鹤藏雪里微窥顶，鸡斗蓬中自正冠。","月满铁城人过少，腊残琼琯客归难。","春来拟补尖头屋，去拾松花就地餐。"]},{"t":"客珠崖怀罗浮寄山中诸子三十韵 其九","f":"七言律诗","c":["当时一入便忘还，分得云房屋半閒。","笑我住来仍渡海，输他飞去不离山。","抛将松竹无田地，领取生涯有死关。","庵主纵归难得见，孤峰从此绝跻攀。"]},{"t":"客珠崖怀罗浮寄山中诸子三十韵 其十","f":"七言律诗","c":["岁暮方思住洞天，斧冰临涧煮寒泉。","半閒茅屋连朝雨，品字柴头一缕烟。","山色去心无咫尺，路岐回首已三千。","他时得遂投閒计，不拟将心更学禅。"]},{"t":"客珠崖怀罗浮寄山中诸子三十韵 其十一","f":"七言律诗","c":["三条篾束十四腰，渐远尘寰近碧霄。","云水相投因系屋，蕨薇将罄便移寮。","人间未易开双眼，林下还思挂一瓢。","早晚閒身定归去，小山丛桂不须招。"]},{"t":"客珠崖怀罗浮寄山中诸子三十韵 其十二","f":"七言律诗","c":["九十春秋强半过，住山时节苦无多。","海滨自顾垂垂老，林下还思踏踏歌。","云壑晚烟笼瀑布，石门晴日晒藤蓑。","主人何事不归去，笑杀南村郭橐驼。"]},{"t":"客珠崖怀罗浮寄山中诸子三十韵 其十三","f":"七言律诗","c":["一钵雕胡七椀茶，衲僧随分有生涯。","摩醯顶上开新眼，香象云中瘗旧牙。","结社更思修白业，还山不拟煮黄芽。","庵西道者如相问，宕子年来解破家。"]},{"t":"客珠崖怀罗浮寄山中诸子三十韵 其十四","f":"七言律诗","c":["止有云霞覆短床，不留馀物在空囊。","因探泉脉移茶灶，为爱松风结草堂。","一日别山同隔世，经年高枕当参方。","老来渐觉无筋力，归路争如归兴长。"]},{"t":"客珠崖怀罗浮寄山中诸子三十韵 其十五","f":"七言律诗","c":["多谢山翁远寄声，别来林下几阴晴。","阶前埽叶云容乱，树底窥花雀尾横。","拾得仙砂无法煮，种成鬼芋待时烹。","知君笑我长为客，归日何曾面目生。"]},{"t":"客珠崖怀罗浮寄山中诸子三十韵 其十六","f":"七言律诗","c":["洞门流水碧泠泠，经过人间不暂停。","溪舌广长当下见，雷声浩大静中听。","逶迤入海成波澜，迢递看山隔杳冥。","独有庵西泉一线，夜来涵月浸空庭。"]},{"t":"客珠崖怀罗浮寄山中诸子三十韵 其十七","f":"七言律诗","c":["孤峰云外有千层，竹杖扶身独自登。","绝壁诛茅成矮屋，当门红树挂枯藤。","森森棘布三叉路，密密囊藏一个僧。","算定生涯归欲早，人前惟谢百无能。"]},{"t":"客珠崖怀罗浮寄山中诸子三十韵 其十八","f":"七言律诗","c":["独木桥边水自流，閒鸥野鹤目相投。","垂杨未识青骢马，细草遍宜白牯牛。","海日射开新病眼，晨钟惊起老枯髅。","山中事事堪相忆，昨夜松窗月一钩。"]},{"t":"客珠崖怀罗浮寄山中诸子三十韵 其十九","f":"七言律诗","c":["桐树千岁孤根深，蒙君斲作囊中琴。","旁观一唱复三叹，静听七弦成五音。","得意失意岂真性，有声无声皆苦心。","何如生长峄阳谷，风雨潇潇龙自吟。"]},{"t":"客珠崖怀罗浮寄山中诸子三十韵 其二十","f":"七言律诗","c":["饮光未是识瞿云，关吏何曾见老聃。","四十九年无一字，五千言下尽虚谈。","岳边万派全归海，岛外千峰自向南。","一个孤僧天畔立，不知谁与盍朋簪。"]},{"t":"客珠崖怀罗浮寄山中诸子三十韵 其二十一","f":"七言律诗","c":["癯形衰态笑窥奁，世眼相逢岂免嫌。","自有天生穷骨格，不须人羡美髭髯。","林间得病常欹枕，海外无寒亦下帘。","正忆故山此时节，梅花和雪压重檐。"]},{"t":"客珠崖怀罗浮寄山中诸子三十韵 其二十二","f":"七言律诗","c":["细写新诗寄岭南，区区谁识是空函。","止啼黄叶从君玩，无口匏瓜且自缄。","风转谷声鸣众籁，日回竿影下长杉。","何人领取居山去，脱却平生鹘臭衫。"]},{"t":"马山杂咏三十韵 其一","f":"七言律诗","c":["来牛去马任西东，云月溪山各异同。","莲社久虚清论地，槐花多笑白头翁。","前窗破梦三更雨，隔案翻书六月风。","群动自喧吾自寂，时人休道是顽空。"]},{"t":"马山杂咏三十韵 其二","f":"七言律诗","c":["青门何处觅侯封，占得荒山老此农。","云气有时遮矮屋，风涛无故响高松。","肩泉自拟寻源入，腰石还思索米舂。","人世欲閒閒不得，鸡声啼破五更钟。"]},{"t":"马山杂咏三十韵 其三","f":"七言律诗","c":["高泉过雨自淙淙，独坐无心外境降。","断送浮云归八极，止留孤月印千江。","野狐队里燃华表，顽石中閒建法幢。","惭愧有情偏识我，十年前已掩蓬窗。"]},{"t":"马山杂咏三十韵 其四","f":"七言律诗","c":["升沉何用更图惟，道在能贫数合奇。","冻澈冰河宁有底，花开枯木不相知。","门因避地重重闭，屋仅容身度度移。","本是钓鱼船上客，往来不惮八风吹。"]},{"t":"马山杂咏三十韵 其五","f":"七言律诗","c":["閒从物外识真机，会得希夷更入微。","鹏鴳总教乘化往，鹪鹩宁羡控天飞。","过桥车马黄金勒，隔竹人家白板扉。","久住东林僧渐老，旧游何日许同归。"]},{"t":"马山杂咏三十韵 其六","f":"七言律诗","c":["明知水到便成渠，夙习难忘未废书。","痴想筌蹄得鱼兔，贪看标指失蟾蝫。","人间岂有憨于我，世路应无懒似予。","几度欲抛文字去，坳堂添水学栽渠。"]},{"t":"马山杂咏三十韵 其七","f":"七言律诗","c":["乘车戴笠总吾徒，衣锦披缁等幻躯。","尘世交驰看野马，猎心腾跃笑韩卢。","庶人自爱怀中璧，稚子争探颔下珠。","老我闭门无一事，日持高论著潜夫。"]},{"t":"马山杂咏三十韵 其八","f":"七言律诗","c":["隔林烟火晚蒸藜，寂寞茅堂返照西。","送客懒从桥上过，爱琴閒向石边携。","老来少事贫偏好，静到无心物也齐。","却笑当年黄太史，花时犹自说闻樨。"]},{"t":"马山杂咏三十韵 其九","f":"七言律诗","c":["经年不挂放参牌，自拟将身活活埋。","病后止存真面目，梦中无复旧恢谐。","白云共住寒分榻，红树当门影接街。","蛙鼓未终虫韵继，知音何处觅同侪。"]},{"t":"马山杂咏三十韵 其十","f":"七言律诗","c":["长与红尘断往来，茅堂移在白云堆。","发同木叶逢秋改，心似炉烟向晚灰。","老树偏宜孤鹤立，幽花止为一人开。","溪翁本是忘机者，珍重群鸥莫见猜。"]},{"t":"马山杂咏三十韵 其十一","f":"七言律诗","c":["局外输赢物外身，闭门猿鹤自相亲。","风摇竹影侵虚幌，雨过山光在隔邻。","鼠堕空瓶惊绝粒，蛩鸣冷甑笑生尘。","年来识得贫中乐，一盗高悬懒向人。"]},{"t":"马山杂咏三十韵 其十二","f":"七言律诗","c":["倚杖柴门送夕曛，长歌三复北山文。","了无痴梦投青琐，止有閒身伴白云。","沙市晚喧饶笋蕨，村童久住厌辛荤。","斋厨午后无烟火，自把茶瓯对此君。"]},{"t":"马山杂咏三十韵 其十三","f":"七言律诗","c":["日出东林众壑暄，野花开遍小桃源。","行吟不负孤筇力，独坐偏宜老树根。","顽铁转身成俗物，名山到处有田园。","生平乐事唯知足，莫怪閒人妄自尊。"]},{"t":"马山杂咏三十韵 其十四","f":"七言律诗","c":["一片蒲团覆石坛，枫林垂荫映眉丹。","新知不羡腰缠玉，往事休论发指冠。","满地征尘生计拙，弥天荒草路行难。","时人莫笑西山饿，周粟繇来不易餐。"]},{"t":"马山杂咏三十韵 其十五","f":"七言律诗","c":["牧笛樵歌日往还，近嫌住处逼人间。","年丰雀鼠犹争食，果熟猿猴不共山。","老去机心聊自息，贫来米价复相关。","罗浮旧隐宁忧此，绝顶孤峰更拟攀。"]},{"t":"马山杂咏三十韵 其十六","f":"七言律诗","c":["谷口晴阴别有天，夜来新雨长红泉。","湿云不放冰河燄，破屋全销冷灶烟。","隔浦远香生杜若，长林寒色老君千。","繁华寂寞秋风里，消得山僧半日禅。"]},{"t":"马山杂咏三十韵 其十七","f":"七言律诗","c":["却缘不折督邮腰，老鹤腾身上九霄。","绿水青山新地主，黄冠白发旧同寮。","顽砖拘去磨为镜，大瓠栽成剖作瓢。","惆怅故交多已贵，隔江相见谩相招。"]},{"t":"马山杂咏三十韵 其十八","f":"七言律诗","c":["懒似林间五白猫，日高犹自卧堂坳。","草鞋久别因耽坐，布被长蒙为病哮。","废尽桔槔甘我拙，抛残棋局倩谁饶。","安居已过门犹闭，何处秋声上竹梢。"]},{"t":"马山杂咏三十韵 其十九","f":"七言律诗","c":["别畛分疆笑尔曹，百年幻宅不坚牢。","蒸沙作饭终难饱，独茧抽丝未易缫。","天际雨声喧石燕，江潮月色满车螯。","閒来渐觉虚舟稳，平浪轻风且自操。"]},{"t":"马山杂咏三十韵 其二十","f":"七言律诗","c":["漫劳车马枉经过，僧老空门胜事多。","入座山花争解语，隔林幽鸟自能歌。","翻嫌谢传留双屐，却恨严光欠一蓑。","万法本閒人自闹，此心吾欲问仙陀。"]},{"t":"马山杂咏三十韵 其二十一","f":"七言律诗","c":["独上孤楼杖古茶，泬寥秋色在天涯。","赤城日落如悬鼓，紫逻峰高拟建牙。","草泽有人歌麦秀，风霜无地护兰芽。","看谁得似云边翼，来往虚空处处家。"]},{"t":"马山杂咏三十韵 其二十二","f":"七言律诗","c":["云中高枕石为床，万事无如静括囊。","人到老年閒悄悄，月当中夜露堂堂。","纸衣补就云千片，铁笛吹残水一方。","多少旧游许相过，出门无那路迂长。"]},{"t":"马山杂咏三十韵 其二十三","f":"七言律诗","c":["一般啼鸟两般声，半日浓阴半日晴。","马麦满盘随饮啄，雀罗当径任纵横。","閒身懒就三台舞，瘦骨那堪五鼎烹。","何事不抛文字去，尚留夙习送馀生。"]},{"t":"马山杂咏三十韵 其二十四","f":"七言律诗","c":["閒门秋水日清泠，万竹交加抱一亭。","过客未须寻路入，高歌谁许隔墙听。","坐看精卫填东海，翻笑鲲鹏化北冥。","老去渐知生意少，夜来添火读黄庭。"]},{"t":"马山杂咏三十韵 其二十五","f":"七言律诗","c":["占得孤峰最上层，断崖绝壁少人登。","黄猿独坐啼清昼，白鸟群飞立古藤。","借地百年聊作客，出门千里不逢僧。","老来空有名山约，拨草瞻风愧未能。"]},{"t":"马山杂咏三十韵 其二十六","f":"七言律诗","c":["浊水滔滔不住流，寸胶珍重莫轻投。","僧眠冷榻旁栖鹤，人老荒村静牧牛。","金马风云销肮脏，铜驼荆棘枕骷髅。","门前大道如弦直，日久行多曲似钩。"]},{"t":"马山杂咏三十韵 其二十七","f":"七言律诗","c":["睡起空山夜正深，茅堂寂寞静风琴。","满床明月连孤影，隔壁寒螀惠好音。","老去有身聊寄迹，閒来无处可徵心。","冷灰爆出星星火，拥鼻何忍更苦吟。"]},{"t":"马山杂咏三十韵 其二十八","f":"七言律诗","c":["自从屋里种优昙，不愿函关见李聃。","近与宗雷开净社，岂知五谢善清谈。","蛰虫未雨争辞穴，宾雁先寒尽向南。","物理如然吾亦尔，故人相劝早抽簪。"]},{"t":"马山杂咏三十韵 其二十九","f":"七言律诗","c":["贯珠叠翠作妆奁，归去金堂未免嫌。","香阁但知誇粉黛，藁砧相见笑须髯。","朦胧好梦愁欹枕，寂寞寒灯懒下帘。","何似阿姨贫不字，长斋甘老破茅檐。"]},{"t":"马山杂咏三十韵 其三十","f":"七言律诗","c":["相逢何用更喃喃，新得金人肘后函。","至道本来唯一默，吾生从此愿三缄。","曾无恶浪欺顽石，岂有惊涛下秃杉。","我纵不言君也会，是非留在七斤衫。"]},{"t":"过芙蓉溪访梁孝廉","f":"七言律诗","c":["独木桥边溪水清，扁舟来往早潮生。","就园尝果逢僧至，下榻看山引鹤行。","高士一身皆道骨，大儿九岁有诗名。","此中莫道无征战，家养莎鸡教用兵。"]},{"t":"芙蓉溪避暑赠欧阳伟人","f":"七言律诗","c":["千家雨过巷人稀，近竹开门见翠微。","静处有风消烈暑，病中无日释寒衣。","溪翁坐对吴牛喘，山鸟低同野马飞。","辛苦西归老词客，不知曾否忆渔矶。"]},{"t":"雨夜怀家山诸子","f":"七言律诗","c":["小楼深坐一镫微，风雨凄清影自依。","乡国别来无只字，天涯相念各重扉。","病思就岳求苓术，梦喜还山见蕨薇。","一事无成君莫讶，章缝今已易三衣。"]},{"t":"早起书怀","f":"七言律诗","c":["晴光初散鸟声匀，病客眠多坐及晨。","风引村烟生曲突，水涵窗日上承尘。","发当短后从依佛，身到穷时重许人。","十里家山千里目，出门无地不迷津。"]},{"t":"秋夜怀罗颢甫","f":"七言律诗","c":["不到山中月再弦，夜来重忆住山缘。","身依好友乡心断，眼见时人道力坚。","露下草虫闻细语，风前巢鹤解安禅。","思君又是凉秋候，拟就漫溪半榻眠。"]},{"t":"欧铁泉过赠赋答","f":"七言律诗","c":["拟向空山老此身，一庵风雨四无邻。","閒门隙处临秋水，清磬声中见故人。","红树忽增秋后色，高花愁裛路旁尘。","闻君道我为僧好，自顾须眉恐未真。"]},{"t":"赠王彝渐","f":"七言律诗","c":["篱落秋深感昔游，故人相见笑汤休。","与君莲社同花甲，羡尔桩堂尚黑头。","沧海迢遥生远梦，青萝咫尺隔丹丘。","何堪世难还同病，弹遍西风旧蒯缑。"]},{"t":"鬻剑诗","f":"七言律诗","c":["老去逢场渐息心，床头辜负不祥金。","开将古匣霜盈手，博得山厨饭一鬵。","从此星辰虚著眼，谩劳风雨废长吟。","还君故物犹堪把，曾记延平遂至今。"]},{"t":"留别诸子还山 其一","f":"七言律诗","c":["行行且莫怅离群，笑指前山日欲曛。","此际谁为当去客，及时犹得少迟君。","归僧箬笠全冲雪，老我茅堂半住云。","别后故交劳远梦，夜钟无计遣相闻。"]},{"t":"留别诸子还山 其二","f":"七言律诗","c":["七斤破衲五条衣，结束閒身上翠微。","满地风尘成老丑，一天雨雪独来归。","江山未辨谁宾主，今昨何曾有是非。","从此孤僧似孤鹤，出门长与白云飞。"]},{"t":"山中除夕与诸子同赋","f":"七言律诗","c":["日暮方思早入林，残除镫火住山心。","寒斋有客先春到，孤榻留僧彻夜吟。","老向邻鸡啼处过，坐从檐雨听时深。","蹉跎一夕成今古，宇宙茫茫涕自涔。"]},{"t":"山居与霍宾辉孝廉园亭相近漫题其壁","f":"七言律诗","c":["行遍千峰得此村，结茅况复近高轩。","相闻爱客时开径，应许閒人来叩门。","半角好山谁作主，一溪流水自同源。","老僧昨暮鸣清磬，曾否因风到耳根。"]},{"t":"送本师入云门","f":"七言律诗","c":["老来翻喜病身閒，正好随师远闭关。","留得馀生在尘世，定寻归路入名山。","溪声过耳成流转，云影无心自往还。","到日若从深处隐，松寮多结两三间。"]},{"t":"寄绿园庵主人","f":"七言律诗","c":["江门江水水漫漫，未得轻舟下急湍。","袖里一缄寻便寄，书中唯道息机难。","世从善病忘应得，春似孤心老更寒。","莫遣绿围围不住，东风吹入楚云端。"]},{"t":"过市门贻社中诸子","f":"七言律诗","c":["兀坐空林远思兴，閒心时复在高朋。","重经旧路成生客，笑向旁人认老僧。","沧海偶来甜鹤梦，青山归去忆渔灯。","相逢况是论心地，莫怪频频说上乘。"]},{"t":"闰上巳社集片檀庵赏菊","f":"七言律诗","c":["乱来何幸得同堂，野寺频过逸兴长。","视历两回逢上巳，看花三月似重阳。","时宜不合如孤客，秋意无端出众芳。","归去石桥桥畔笑，问君谁是古柴桑。"]},{"t":"题片檀庵壁","f":"七言律诗","c":["谁把旃檀作梵宫，清溪曲曲径斜通。","经年老衲坐当壁，几度大江流向东。","阶燕啄泥停宿雨，窗绳触纸引微风。","休心更说观心法，石室绳床笑懒融。"]},{"t":"赠吕耕山","f":"七言律诗","c":["逢人唯劝作真儒，此事如君谅不辜。","但解青莲生火宅，何妨浊水得玄珠。","道存琴瑟调应好，心向蒲团坐亦枯。","我已出家君罢道，相看无计赠区区。"]},{"t":"送铁城诸子还邑寄题曹调仲读书堂","f":"七言律诗","c":["谩从尘籍问三馀，试听山僧说太初。","仓颉未生先有字，庖羲才画已无书。","江城习静门长闭，海日当空室自虚。","归去致声曹处士，高秋迟我子云居。"]},{"t":"雨中寄罗戒轩","f":"七言律诗","c":["莫嫌寒雨打孤篷，添得新泉听不穷。","昨夜分流栽药地，今朝閒杀灌园翁。","空山风雪逢人少，到处晴阴与子同。","几度欲来寻旧约，数探书札出怀中。"]},{"t":"黄连江口怀旧","f":"七言律诗","c":["曾从严武此登台，旧路经过首重回。","兵革几年孤鹤去，风尘满地一僧来。","雪边老树含生理，乱后新畬有劫灰。","遂使居人厌征战，相逢不敢说行枚。"]},{"t":"冬日与铁城诸子游小岭同赋 其一","f":"七言律诗","c":["望山方悔出山迟，去去看山信所之。","空谷乍闻孤屐响，寒岩初与老僧期。","更无烟火通尘世，祇有云霞覆短篱。","便欲结茅从此住，夙心难遣外人知。"]},{"t":"冬日与铁城诸子游小岭同赋 其二","f":"七言律诗","c":["杖头标笠五铢轻，扶上孤峰四望平。","沧海东西浮岛屿，白云朝暮暗江城。","鸟逢吟客声相引，鹿认林僧路共行。","我是即山山即我，相看何用更知名。"]},{"t":"冬日与铁城诸子游小岭同赋 其三","f":"七言律诗","c":["同游亦复爱清狂，出郭招携逸兴长。","坐石听泉衣带冷，就山尝茗齿牙香。","断崖路转冲晴雪，老树寒生透夕阳。","一度登临应不偶，閒云来往本无乡。"]},{"t":"题西山寺","f":"七言律诗","c":["此山得似故山无，城上閒凭景物殊。","半面高窗临睥睨，千峰晴雪见浮图。","旌旄影接幡幢动，钟磬声随鼓角孤。","登望正逢多垒日，问僧何地结双趺。"]},{"t":"铁城长至","f":"七言律诗","c":["殊方风日八方同，到处天心静处同。","海国千家通赤县，沧溟一气应黄钟。","南来渐返羲和驭，老去难追夸父踪。","从此不愁山路远，昼长容我信孤筇。"]},{"t":"留别铁城诸公还山","f":"七言律诗","c":["閒身随地得徘徊，雪尽南天一鹤回。","白首论交难远别，青春有约许重来。","归寻旧路家应近，行遇名山眼便开。","后夜故人相忆否，月明何处不登台。"]},{"t":"与衣石师同住小漫山赋赠","f":"七言律诗","c":["经年一室掩重扉，白首逢君共息机。","但解馀生聊寄迹，何妨随地暂相依。","天寒埽雪煎香茗，日暮栽云补衲衣。","此外山中了无事，数声清磬鹤飞归。"]},{"t":"春日寄本师","f":"七言律诗","c":["恨不从师岁又徂，东风吹雨满长途。","袖中珍重三年札，静处寻思半字无。","冷榻朝眠新梦少，名场久别寸心枯。","春来若问山中事，篱隙初栽五石瓠。"]},{"t":"答古冈易兼人","f":"七言律诗","c":["倦鸟归飞只此林，逢人那敢说幽深。","劳君远示山中札，使我难为别后心。","青镜览多增老态，孤桐枯尽得元音。","有怀欲问江门叟，烟棹春来试一寻。"]},{"t":"谒先孝廉墓","f":"七言律诗","c":["谷风习习水潺潺，记得儿时此往还。","忽作閒僧投宿草，正逢寒雨暗前山。","当年孤柏曾经植，近日低枝渐可攀。","学道无成恩未报，自惊憔悴鬓毛斑。"]},{"t":"送罗戒轩讲学郡城","f":"七言律诗","c":["东林林下送西宾，独木桥头指去津。","白社旧游成远别，碧峰回首已无邻。","乡僧入梦谁为主，山月辞家倍照人。","想到穗城逢上巳，不妨重周舞雩春。"]},{"t":"答庞卯君见寄兼柬雷季传","f":"七言律诗","c":["借得青山小结庐，槿篱渐密客来疏。","多情最是庞居士，远札难忘楚接舆。","老去烟霞成痼疾，近从眠食识真如。","凭君寄语同袍友，别后枯禅已废书。"]},{"t":"与陶握山订住山之约","f":"七言律诗","c":["相逢头发各丝丝，久别青山老可悲。","在世了无投足地，入林应是息肩时。","身依云水心何住，早种坑田晚共炊。","从此便归归便得，未须南面肃蓍龟。"]},{"t":"将之铁城舟次平山宿简岐山斋与谢散木话别","f":"七言律诗","c":["无端来就草堂眠，有约维舟柳渡边。","行脚但知从此去，芒鞋休问几时穿。","一围暑气难侵夜，半晕寒光亦满天。","莫漫灯前动离思，南来原是旧山川。"]},{"t":"舟中作","f":"七言律诗","c":["閒身能得几时閒，行遍千峰好闭关。","孤棹偶来重渡海，片云何处不逢山。","鸥迎野客忘宾主，鹤过长空纵往还。","惭愧同舟枉相问，老僧何事到人间。"]},{"t":"重过铁城作","f":"七言律诗","c":["雪边曾记此登临，归卧松寮直至今。","最是高深难久别，不分寒暑辄相寻。","炎方近海饶云物，客舍移床就樾阴。","欣对悠然信来往，南山殊有故人心。"]},{"t":"铁城道中夜归口占","f":"七言律诗","c":["山客下山何太频，荒城十里半荆榛。","青燐熠熠萤依草，白眼当当虎伺人。","老畏交驰思缓步，行随孤影识全身。","夜深谁是同归者，大地茫茫月一轮。"]},{"t":"客中晚晴","f":"七言律诗","c":["郭外疏钟郭内听，夕阳归鸟下空庭。","暑欺老病侵尘榻，雨过新凉隔纸屏。","山县闭门群动息，女墙当牖数峰青。","此时正好披襟坐，莫学閒眠唤不醒。"]},{"t":"铁城晚发留别诸子","f":"七言律诗","c":["片帆南下水悠悠，归路分明记昔游。","西照入江疑晓日，晚风吹暑当凉秋。","閒身自断同孤鹤，世事无劳问野鸥。","莫笑还山生计拙，君看禾黍满西畴。"]},{"t":"送戴明府还柳州","f":"七言律诗","c":["自斲枯桐被七丝，孤音何处问钟期。","下山正值弹琴宰，岐路聊为别鹤辞。","青嶂一枰仙客奕，黄柑千树使君祠。","归来定卜愚溪住，迟我他年访戴逵。"]},{"t":"送客晚归微月在林漫赠以诗","f":"七言律诗","c":["山南水北送山翁，野兴逢秋更不穷。","古道客归禾黍外，隔桥人语蓼萧中。","溪光远近潮通月，林影参差叶答风。","何事适来还适去，笑看閒者亦飞蓬。"]},{"t":"耳聋","f":"七言律诗","c":["从前消息愧多闻，一笑相逢岂足云。","大麓风雷随帝子，严营鼙鼓卧将军。","物齐蜩翼冥天籁，渊处鲵桓见地文。","昨夜秋声何处所，晓看红树叶纷纷。"]},{"t":"晚发龙津","f":"七言律诗","c":["暝烟初捲一帆轻，晚渡逢人问水程。","去国便为千里别，寻山还有几年行。","鹤当静夜横空过，月到澄江彻底明。","心似孤舟无所繫，乡关回首白云平。"]},{"t":"夜过韦涌寄弟","f":"七言律诗","c":["浮生冉冉陌閒尘，一过丘园一怆神。","白首独为行路客，黄昏谁是倚闾人。","灯前绕膝喧童稚，梦里还家识比邻。","惆怅乡关诸弟隔，桑榆鸡黍莫辞贫。"]},{"t":"抵循州泊白鹤峰","f":"七言律诗","c":["白鹤孤峰旧识名，今来一倍借劳生。","日斜山寺临秋水，木落寒皋见古城。","有客扁舟过渡口，何人高枕听江声。","相逢海阔天空处，莫向飞蓬问去程。"]},{"t":"游西湖遇一株师","f":"七言律诗","c":["兵时曾此一维舟，重过园林续胜游。","八月芙蓉犹出水，六桥杨柳不胜秋。","湖光静漾花边日，塔势平分竹里楼。","自笑閒名埋未得，天涯相识有汤休。"]},{"t":"湖口避风寄李苍水广文","f":"七言律诗","c":["中流风急驻征舠，一夕浮生梦亦劳。","空负故山好薇蕨，始知人世足波涛。","云霾海腹鱼龙乱，石出城根雉堞高。","我友剌船何处去，援琴聊作水仙操。"]},{"t":"中道泊石公城书事","f":"七言律诗","c":["十日才过五日程，六时聊得一时停。","老夫行路常携药，稚子悬崖学采苓。","雨脚乍收千树碧，船头遥见数峰青。","山城咫尺河源近，伸纸低回写地形。"]},{"t":"宿老龙邸","f":"七言律诗","c":["村烟远近绕晴堤，碧嶂东迦白日西。","久宿寒江同倦鹤，暂来孤店得闻鸡。","身随云水心兼远，梦入家山路已迷。","明发何堪更回首，秋风不到武陵溪。"]},{"t":"赠李苍水广文生日","f":"七言律诗","c":["与子论交已十春，每从出处见天真。","山中好友初通籍，堂下狂夫老斲轮。","到处一倾元亮酒，醉来还忆季鹰莼。","何妨作客逢生日，吟遍秋风有故人。"]},{"t":"观乐人迎春","f":"七言律诗","c":["閒身到处得閒游，人物看看似故丘。","金胜满头挝社鼓，采鞭随手逐泥牛。","闻歌始觉乡音异，越陌都忘世路悠。","草色未青春又到，不知谁上仲宣楼。"]},{"t":"客中元夕有怀山中诸子","f":"七言律诗","c":["谩将行乐逐儿童，坐破良宵兴不穷。","自把閒心拟明月，独留清影在屏风。","寒城久客多新识，灯市归人半老翁。","正忆故山此时节，隔窗吟咏与谁同。"]},{"t":"留别李苍水广文","f":"七言律诗","c":["东风吹雨下江城，千里溪山半月程。","有客到来逢九日，无端归路又清明。","行添怪石腰包重，暂别官衙脚板轻。","我自往还君自住，宦游宁比浪游情。"]},{"t":"归路再经罗浮不能游焉赋此留别","f":"七言律诗","c":["曾与洞天成密约，今来归路复何言。","青山当面又虚度，白首盟心永弗谖。","万壑有风皆到海，一溪无水不通源。","几回领略罗浮遍，莫笑粗人空过门。"]},{"t":"寄长乐尉廖声玉","f":"七言律诗","c":["吏隐如君得自然，多生曾结衲僧缘。","春风怅别同为客，故国言归老此禅。","前路一投孤店宿，居人尽说长官贤。","自从识得齐昌尉，始信梅生是人仙。"]},{"t":"旋风","f":"七言律诗","c":["南箕噫气下南州，幻出焚轮撼不周。","有客步虚逢禦寇，何人闻籁过商丘。","九天路直鹏嗤鴳，四野尘生马逐牛。","我作断蓬君更驾，不知谁指复谁鳅。"]},{"t":"急雨","f":"七言律诗","c":["浓阴转壑乍翻盘，静会溪山响百般。","得罢丈人三日灌，旁分热客片时寒。","槁梧倚壁商弦浊，曲录当檐木理宽。","相识却怜桑户病，书来重叠劝加餐。"]},{"t":"秋山","f":"七言律诗","c":["商天最好是清泠，减却云林一半青。","久在此中知此理，偶凭真宰得真形。","霜凋丰草成丹壑，风散高梧下翠屏。","莫向寒岩赋摇落，年来衰鬓也星星。"]},{"t":"寒月","f":"七言律诗","c":["冷魄照心成一片，定僧开眼见孤明。","方诸自向怀中取，顾兔何由指上生。","琪树风高坛桂落，玉壶霜重水田轻。","当时木客惟知此，一抖嚣尘别市城。"]},{"t":"戏赠曹茂才","f":"七言律诗","c":["谁家才子骋神騧，半月池头当渥洼。","赤汗散蹄如脱兔，青丝垂鬓似雏鸦。","董帷早下从生草，硎谷今来不种瓜。","有约到城重问讯，蓝袍遮莫笑袈裟。"]},{"t":"喜衣石上人再入山同住","f":"七言律诗","c":["抖擞生衣两袖尘，上山原是下山人。","祗缘踏著来时路，聊复寻思去后因。","老眼岂存三日见，孤心又得一回新。","明朝更有樵西约，中道凭师辨主宾。"]},{"t":"题先辈何子明先生读书处","f":"七言律诗","c":["昔人曾此作经生，不复书声但水声。","百尺瀑泉谁识主，千秋崖石独知名。","丹梯有路通丹壑，赤脚无尘下赤城。","更欲假君弦诵地，胡床塞默谢逢迎。"]},{"t":"登大科峰绝顶","f":"七言律诗","c":["爱山登陟不辞劳，直上嵚岑振敝袍。","老去始知行脚稳，年来惟恐置身高。","青天有路随孤鹤，沧海无根仗六鳌。","閒倚西风发清啸，下方谁识是吾曹。"]},{"t":"寒瀑洞怀旧","f":"七言律诗","c":["山翁住向人间久，冷落云林直至今。","磴道尚堪重著屐，石床谁复更横琴。","千章古木经残烧，一线清泉下浊涔。","剩有风流在樵牧，隔桥吹笛学长吟。"]},{"t":"题李子长先生墓","f":"七言律诗","c":["谁把高名榜翠微，先师亲笔写泉扉。","白沙门下多牙笏，黄叶堆中一布衣。","古道静观宜往复，大贤遗泽尚依稀。","清风留在山南北，社日儿郎荐蕨薇。"]},{"t":"过白沙先生祠故址","f":"七言律诗","c":["荒祠不复布琴尊，往事惟凭故老言。","东海日高开讲席，西樵山色接江门。","石房细语虚闻响，庭树无枝老见根。","独有枯禅经过此，问君谁是好儿孙。"]},{"t":"舟次黄鼎泊岸二日临崖坐石北风怒号江水豗激远兴翛然","f":"七言律诗","c":["红蓼洲边枫叶丹，满船风雪一僧閒。","言寻密约盟明水，先寄孤心到远山。","行似奔波年共逝，坐当磐石性同顽。","及时吸取西江去，得入泷中便掩关。"]},{"t":"西行阻兵复归小漫山霍西牛过宿诉别","f":"七言律诗","c":["行脚出门归亦客，閒身到处主中宾。","萍踪未定逢知己，蜡烛无多别故人。","江水长流寒不冱，云山弥望远生皴。","临岐指点泷西路，君但能来莫问津。"]},{"t":"过崧台感旧 其一","f":"七言律诗","c":["百川曾此一朝宗，荒殿犹存碧藓封。","野渡水寒朝饮马，江城云起昨从龙。","千秋离黍歌三阕，半夜苍梧梦九重。","自是六朝僧去后，逋臣多少作山农。"]},{"t":"过崧台感旧 其二","f":"七言律诗","c":["趋庭记说崧台事，应诏曾瞻十二旒。","焚草再陈忧国疏，吟诗多上阅江楼。","手存旧泽惟鸲鹆，心有殊恩但蒯缑。","谁念夕阳风在树，有人持钵过端州。"]},{"t":"抵西宁宿翠林庵与秋霜本源二师乡人冼云中夜话","f":"七言律诗","c":["閒云西并片帆飞，路入东林为蕨薇。","曲径日斜行子至，隔山斋罢老僧归。","班荆有客同乡水，洗钵何人话翠微。","今夜无弦弹得好，月轮刚照十三徽。"]},{"t":"将入下城信宿翠林庞卯君以诗见招用韵次答","f":"七言律诗","c":["拟向青山作老樵，晚投孤寺宿松寮。","遥知地主曾悬榻，难别林僧为过桥。","拾得偶来劳见讯，八公能隐不须招。","明朝结束寻君去，稳系腰间五石瓢。"]},{"t":"至下城赠庞卯君","f":"七言律诗","c":["今来见面胜闻名，不枉泷西十日程。","得与王生初结袜，却教任子独沾缨。","玄谈每喜当前席，生计悬知在下城。","但得半间茅屋住，荷锄言就鹿门耕。"]},{"t":"下城洞晚眺","f":"七言律诗","c":["云路千岐水一涯，诸峰合作青莲花。","檐低远荫迎斜日，门对奔流送断槎。","石窦自舂临瀑碓，坑田长转出云车。","山翁招手溪桥去，指点寒皋好种瓜。"]},{"t":"过梅砰赠湛慈老师","f":"七言律诗","c":["远公卜筑得幽奇，削取巉岩作坦夷。","碧甃牵泉通一线，青山邻郭阻千岐。","石门高峻人稀到，梅子酸甜独自知。","手植万松将荫屋，想君从此撤籓篱。"]},{"t":"游云窝赠中介大师","f":"七言律诗","c":["平阳师子高高坐，万仞峰头一个僧。","引水入房分绕药，磨刀临涧不饶藤。","枯椿谷冷花先雪，冻雨檐孤溜易冰。","却笑昨宵低处望，也将残烧作禅灯。"]},{"t":"寄本师","f":"七言律诗","c":["本师眠食今安否，某甲行藏别有因。","堂下肯容担板汉，山中甘作结茅人。","一卷怪石顽成癖，两角肥牛牧渐驯。","惭向罗浮寻旧约，年年空负洞门春。"]},{"t":"长至日与诸公集翠林寺晚过香雪庵分赋","f":"七言律诗","c":["沉沉钟鼓动微阳，山寺逢君即故乡。","未满百年常苦短，才添一线便为长。","林间留客环深翠，雪里寻僧得妙香。","何用吹灰发天籁，笛中无孔有宫商。"]},{"t":"宿西竺禅院与僧夜话","f":"七言律诗","c":["閒身随处息征蓬，静掩禅扉话不穷。","百结水田孤烛底，一区金地万山中。","潭光洞牖呈初月，竹韵垂檐答响风。","几欲诛茅深谷去，芒鞋踏破不如公。"]},{"t":"归途宿龙华寺与无尽六如师滋庄居士夜话","f":"七言律诗","c":["经过此地许重来，旧路依然十日回。","一片閒云归暝岫，千峰圆月印香台。","心同石溜寒偏细，目与松窗夜并开。","独拥孤衾对玄度，山风吹雪下庭梅。"]},{"t":"宿龙井庵与博峰师夜话师欲留予住弥勒阁","f":"七言律诗","c":["难得高僧对茗谈，石林不惜此重探。","火分破灶烟犹湿，泉入斋厨味转甘。","到处泥牛随分纳，他年木佛许同参。","夜堂莫讶无言说，月满长空水满潭。"]},{"t":"立春漫兴","f":"七言律诗","c":["那可逢春未有诗，好春况与客心宜。","泥牛直去无寻处，水鹤何当得见时。","老眼生花书渐废，新毫添雪镜先知。","朝来欲就东风问，芳草年年忆著谁。"]},{"t":"初春偶成寄泷中诸子","f":"七言律诗","c":["莫倚幽居耳目清，难消山色与溪声。","忍辜良晤长依寺，那得馀閒更入城。","野水渡牛微见迹，春风啼鸟不知名。","分明一幅诗中画，只恐僧繇邈不成。"]},{"t":"尘","f":"七言律诗","c":["太虚一气自溟濛，野马终朝只御风。","群动无端成辐辏，微躯难免处樊笼。","窗通彼阕常生白，路入长安便觉红。","古镜不劳频拂拭，个中原有梵王宫。"]},{"t":"烟","f":"七言律诗","c":["热不因人浊处清，积空成色自分明。","嵩山破灶当机堕，古庙香炉觌面呈。","宿火传将微有燄，轻风随去本无情。","年年二月逢寒食，消息还归折脚铛。"]},{"t":"烧","f":"七言律诗","c":["南村野老祠刍狗，山鸟衔灰自爇林。","半壁电光深入石，一星槐火竟流金。","白牛假道归涔黑，玄鹤摩空落影沉。","谁识枯桐心已死，独蒙尘土待知音。"]},{"t":"影","f":"七言律诗","c":["世外枯禅物外身，阴晴随地别疏亲。","相期白首为知己，共对青山只此人。","好客不来嫌我懒，侍儿多去为僧贫。","最怜孤烛幽窗底，寂寞因君见主宾。"]},{"t":"响","f":"七言律诗","c":["屐齿过桥轻的的，石棱斗水碧潺潺。","就林说籁谁倾耳，入谷闻声独破颜。","比竹自鸣凭自和，清商随去复随还。","松风满地无人买，化作洪涛出万山。"]},{"t":"迹","f":"七言律诗","c":["草色青青与胫齐，终年不过远公溪。","重拈旧话参驴脚，未得閒身逐马蹄。","山径用来微有路，桃花开日渐成蹊。","凭他检点经行处，白足分明不到泥。"]},{"t":"翠林除夕即事 其一","f":"七言律诗","c":["推倒虞渊赤羽鸟，晚堂钟鼓报年徂。","村童爝竹惊憨犬，野鼠偷灯嫁小姑。","寒绽水田三尺线，坐深檐雨一团蒲。","山中自了无庚甲，夜夜胡床火满炉。"]},{"t":"翠林除夕即事 其二","f":"七言律诗","c":["去腊郡斋今野寺，半生萍梗似蘧庐。","住山未觉寒将尽，为客方知岁易除。","野老索偿文字债，乡僧劝习佛陀书。","明年得遂投閒计，土面灰头学运锄。"]},{"t":"翠林元旦","f":"七言律诗","c":["云里开门四望低，早莺啼遍乱峰西。","远钟出郭仍归寺，宿雨添泉尽赴溪。","心树渐枯同古桂，鬓花潜长逐新荑。","春来莫道无筋力，一日还应灌百畦。"]},{"t":"走马灯","f":"七言律诗","c":["来时衮衮去匆匆，结束狂心付化工。","大火聚边多跃冶，只轮车上一征蓬。","圆机静会当方寸，冷眼旁观笑热中。","今古交驰争似此，纷纷人在纸屏风。"]},{"t":"归韦涌答龙媒兄韵","f":"七言律诗","c":["辞家千里远寻师，行脚归来只暂时。","久去弟兄成主客，重经乡路改平陂。","青山有约宁相赚，白首能来尚未迟。","闻说欲酬男女债，待完婚嫁与君期。"]},{"t":"送何不偕再入吴门","f":"七言律诗","c":["老大登临兴未阑，吴门风物去重看。","青春作伴三千里，白发行吟十八滩。","乡月到江成独照，家山背岭失孤峦。","前途夷险君应熟，莫更临岐说路难。"]},{"t":"送林向超还北流幕因柬谢合脚公明府","f":"七言律诗","c":["归时上巳去春深，怅别前山日又沉。","黑土久增凋弊叹，青油空负治安心。","棋当斗劫须留谱，琴到更张始辨音。","自古神仙多吏隐，丹砂勾漏不忍寻。"]},{"t":"送罗喜人行商交南","f":"七言律诗","c":["嗟君岂合老风尘，一曲骊歌勿复陈。","自挽役车投黑齿，更资章甫适文身。","萍蓬正值干戈地，书剑难消寂寞春。","到处若逢阳翟贾，不知奇货属何人。"]},{"t":"从泷西还亦庵庞卯君见赠赋答","f":"七言律诗","c":["看看宝主太难分，千里长空不住云。","多谢居亭曾爱客，无端归路又逢君。","违山几日思新蕨，到处深春长野芹。","旧业泷西好回首，早抛城市伴耕耘。"]},{"t":"归隐罗浮留别陶握山罗戒轩","f":"七言律诗","c":["入山踪迹恐人知，一笑相逢是别时。","苦海看谁先到岸，长途怜我始分岐。","贫惭轵里能将母，老怪柴桑亦恋儿。","底事累君良不浅，未应还索赠行诗。"]},{"t":"初入罗浮寄呈石洞本师","f":"七言律诗","c":["万事皆休岂复疑，美中不足但违师。","眼前耕凿无关道，心在耰锄渐废诗。","坐对潺湲通语默，历穷岑巘得平夷。","主人欲问罗浮事，荆棘当门花满篱。"]},{"t":"寄家山诸子","f":"七言律诗","c":["当时梦见醒来说，今日罗浮是昔渠。","在世可堪成孟浪，入山方解惜居诸。","高窗临树床头鸟，细石通泉屋角鱼。","旦夕到来观不足，依稀忘却八行书。"]},{"t":"答天藏大师送行之作","f":"七言律诗","c":["谩从世外惜离群，百八声钟到处闻。","去路晓冲沧海日，计程东指洞门云。","三家村里呈新话，品字柴头检旧文。","安得支公似明月，石楼吟望便逢君。"]},{"t":"赠钝庵师","f":"七言律诗","c":["梦里初醒勿复云，水边林下恰逢君。","溪深杓柄长如许，路远芒鞋费几文。","竟发大心成佛见，不留细语遣人闻。","相期共指孤峰宿，莫旷閒房半住云。"]},{"t":"补衲","f":"七言律诗","c":["粪埽周遮体自亲，当时宜称总前尘。","纫将弱线长三尺，绽得生衣重七斤。","祗有水田知夏腊，更无寒暑管冬春。","一池荷叶家风在，漫对儿孙说古人。"]},{"t":"过华首台","f":"七言律诗","c":["人生那得四百岁，一岁罗浮住一峰。","去日转多来日少，南山游遍北山同。","倚檐双瀑晴天雨，夹路千松暑月风。","地主不收僧借去，古台移向洞门东。"]},{"t":"老人石","f":"七言律诗","c":["坚性何妨高处蹲，閒身归去总无村。","风云月露酿元气，草木昆虫依本根。","大地几回成昼夜，诸峰相见即儿孙。","当时曾笑生公石，不点顽头更囫囵。"]},{"t":"寄茎鉴二子","f":"七言律诗","c":["白云西望数峰青，咫尺家山在户庭。","蜾赢嘱儿当类我，猕猴怜子谓宁馨。","物情痴绝堪长叹，诗句吟来只自听。","身健报恩终有分，此间随地得参苓。"]},{"t":"里正索租戏赠","f":"七言律诗","c":["闻说罗浮好住禅，我来恰恰是荒年。","少生坑稻多生药，饥杀山僧饱杀仙。","枵腹难偿行脚债，空囊还欠入官钱。","思量更欲移居去，只种黄精不种田。"]},{"t":"博罗晚眺","f":"七言律诗","c":["天外高风扑面吹，花黄草白动秋思。","寒城西望空斜日，逝水东流无尽时。","游子重来还问路，閒僧一过便留诗。","罗浮何事不归去，笑杀道旁驱犊儿。"]},{"t":"寄下城庞卯君时予将有朱崖之行","f":"七言律诗","c":["终日怀人在翠微，下城云树想依稀。","江通锦水凭鱼寄，路入青山鹤纵飞。","三顷秫田临古岸，数椽茅屋对斜晖。","明朝我向朱崖去，回首泷中便当归。"]},{"t":"归自罗浮过铁城诸子述洞天之胜","f":"七言律诗","c":["年来莫讶到城稀，才别罗浮昨日归。","渡海呈山云出袖，当人说瀑冷侵衣。","礼随筋力容疏放，心似颠毛渐细微。","良晤未知频得否，秋风孤鹤又南飞。"]},{"t":"题曹茂才新筑","f":"七言律诗","c":["一个閒身去复还，读书声里款重关。","江城旧别人三载，隙地新添屋半閒。","草自离披应任长，竹凭疏密不须删。","眼前真乐凭郡取，窗外明蟾郭外山。"]},{"t":"归韦涌宿月衣庵与谢邺门话别","f":"七言律诗","c":["近时诗句少人弹，未惜逢君语夜阑。","高阁重来寻旧梦，危襟初拥试新寒。","去随云水家何在，共老风尘别亦难。","他夕朱崖相忆否，一天星月路漫漫。"]},{"t":"别弟","f":"七言律诗","c":["远亲几岁阻承欢，又作孤鸿渡海澜。","学道蹉跎闻道晚，负恩容易报恩难。","高堂娱老荆花茂，客路逢秋布被单。","贫贱弟兄无可嘱，各将薇蕨劝加餐。"]},{"t":"宿月衣庵留别家山诸子","f":"七言律诗","c":["参遍诸方便掩扉，浮生多恐与心违。","言寻海岳终难住，暂寄僧房便当归。","独鹤去时天浩渺，群鸥宿处水依微。","茫茫大地同为客，莫笑秋蓬远近飞。"]},{"t":"赠罗戒轩为子湛娶妇","f":"七言律诗","c":["相看老大忆儿童，记得当筵蜡烛红。","在世与君皆有子，故人先我已称翁。","三心未了閒堪惜，五岳能游计许同。","他日云山携手处，不知谁早得痴聋。"]},{"t":"九日发汾水","f":"七言律诗","c":["纸鸢夹岸走儿郎，正好登高又别乡。","南地授衣逢九月，西风移棹过重阳。","远书到日愁无雁，衰鬓经秋渐有霜。","家在罗浮归不得，年年空负菊花黄。"]},{"t":"登灵山寺汲泉试茗","f":"七言律诗","c":["三年两过灵山寺，今日初尝峡口泉。","井脉但凭岩叟说，茶经曾记岳僧传。","一身病肺嗟岐路，千里归心向洞天。","自笑不如清涧水，时时流傍碧峰前。"]},{"t":"江上秋晓","f":"七言律诗","c":["天光云影两参差，江上推篷见日迟。","霁色千峰明剑戟，秋风一枕对涟漪。","寒岩危绿兼霜坠，野水低花杂果垂。","何事故山憔悴客，冷吟终日忆东篱。"]},{"t":"经旧战场望海怀泰山道士","f":"七言律诗","c":["高凉兵后见荒榛，赵璧犹存汉帜新。","东海蹈来秦自帝，扶馀归去国无人。","丹须久伏胎方圣，龙在能藏用乃神。","欲向蓬山寻旧隐，天风吹路暗征尘。"]},{"t":"宿惮长驿即事","f":"七言律诗","c":["惮长长路少人行，斥卤西连锦伞城。","灶客煮盐分野烧，田家炊黍馌秋成。","海涛近枕偏相聒，山月离乡分外明。","倦客耽眠天又曙，门前咿喔役车声。"]},{"t":"梅录道中","f":"七言律诗","c":["何堪毂击复肩摩，一片閒云此地过。","乡国别来风土异，市门开处里儿多。","青山路夹黄茅店，黑齿人披绿箬蓑。","添得吟僧诗兴好，晚凉无那扣轮歌。"]},{"t":"宿梅录江上有怀","f":"七言律诗","c":["旧游回首似风萍，留得閒鸥占浅汀。","云鸟阵存沙碛暗，水犀军散野燐青。","溪翁钓罢潮初上，市客歌残酒未醒。","怀抱此时消不得，又随孤月下沧溟。"]},{"t":"自英利抵徐闻一径迂回延袤百里万木蓊蔚百卉错绣身入其中如处翠幕从林隙见日已及亭午道俗殊情匪欣则怖古称仙源辽邈人境隔绝武陵之后未曾有也诗以纪胜","f":"七言律诗","c":["二时天气异寒温，百里人烟隔晓昏。","涧底转雷车错毂，林端见日叶归根。","兰侵蔓草香偏满，藤冒高柯子并繁。","可惜桃花鸡犬地，一通人境失仙源。"]},{"t":"会同客夜寄山中诸子","f":"七言律诗","c":["故国离居动几旬，他乡两见月华新。","灯前细读怀中字，雪后频归梦里人。","宾雁未来秋已过，朔风不到海先春。","却怜华发催年暮，独向南天寄一身。"]},{"t":"珠崖除夕与吴谓远广文守岁有怀山中诸子","f":"七言律诗","c":["烛边吟苦县更催，画尽炉头欲冷灰。","马齿一年随腊去，鸡声半夜送春来。","孤衾笑就青毡宿，明镜愁缘白发开。","今夕故山应共讶，岁残不见寄书回。"]},{"t":"癸亥珠崖元旦漫兴","f":"七言律诗","c":["不寐频看斗柄移，客星何事滞天涯。","西窗尚秉除年烛，隔座閒收去岁棋。","海日未生鸡早报，春风初度鸟先知。","自来绝岛饶云物，乘兴佳游孰可期。"]},{"t":"赠多异山玄达师","f":"七言律诗","c":["占得孤峰最上层，林间留客话三乘。","春风收拾閒田地，夜雨商量旧葛藤。","泉为有灵知冷煖，山缘多异绝跻登。","他时归去逢人说，千里珠崖半个僧。"]},{"t":"点头石","f":"七言律诗","c":["高高不与众为邻，日炙风吹自主宾。","四大本空成幻质，三生能了即前因。","立当沧海如无地，坐老青山不见人。","莫把虚名强相谓，点头终是一顽身。"]},{"t":"周茂才二有筑室山中谈经受徒从之游者皆邑名士书舍鳞集振铎篝灯络诵达旦予游山还时日已西夕留宿斋中睹其规模恍若丛席北方学者未尝有也因赋以赠","f":"七言律诗","c":["居山无事不幽清，面面茅堂结构精。","归路一寻中道主，隔林遥有读书声。","远钟出寺千峰应，高铎先鸡半夜鸣。","惊起枯禅眠不稳，自携孤影月边行。"]},{"t":"访冯昌孝居士禅室士呈所见云从溪山因缘悟入示此","f":"七言律诗","c":["千竿修竹杂槟榔，十亩閒园旧辟疆。","是处便为参佛地，隔篱还有读书堂。","身前见色原清净，舌外闻声自广长。","却笑东坡太饶舌，无山无水也何妨。"]},{"t":"重游多异岭赠灵泉达公","f":"七言律诗","c":["此山容我再来否，聊复寻师嗣昔游。","云外遥知僧在定，门前依旧水长流。","凉生殿角停挥麈，月满林閒静牧牛。","却笑閒人閒未得，天明荷锸出西畴。"]},{"t":"喜王君祈至自粤","f":"七言律诗","c":["风尘驿路二千馀，一月方停只毂车。","去国便为浮海客，入山持得寄僧书。","亭阴转砌经行晚，夜雨焚膏共话初。","到处不妨生计在，未须长铗赋无鱼。"]},{"t":"题槟榔图寄山中诸子","f":"七言律诗","c":["曾从乡国早闻名，海外相逢感物情。","凉月入怀孤影直，好风当面细香生。","叶沉旧绿呈丹颗，甲迸新黄长碧茎。","眼见枝头花又实，归心狂写数株横。"]},{"t":"谢冯合溪惠黄犊","f":"七言律诗","c":["牵来三岁彪文犊，相约閒云上翠微。","水草不妨随分纳，眉毛惟许与僧依。","歌残白石人将老，踏遍红尘客未归。","何似空山伴行脚，冷吟终日趁晴晖。"]},{"t":"送成其超还里","f":"七言律诗","c":["去岁河梁君送我，今年海外我逢君。","到来两见初圆月，归去还同不住云。","林下覆棋人未散，夜中饯酒客仍醺。","如何便上轻车别，前路砧声次第闻。"]},{"t":"立秋","f":"七言律诗","c":["当时秋尽别家园，莫怪逢秋便怆魂。","海外凉风生白发，眼前归计在青门。","云容渐薄呈山态，井干新飘见月痕。","残暑未消心早冷，不知人世有寒温。"]},{"t":"山行日暮宿龙楼山庄","f":"七言律诗","c":["万壑消声归大海，千峰积翠隐流霞。","偶乘黄犊寻源入，贪看青山到日斜。","溪上不曾遗菜叶，岸旁无复种桃花。","从他来往从他住，野水閒云总一家。"]},{"t":"送王君祈还里","f":"七言律诗","c":["与君同作断蓬飞，绝徼相逢又送归。","一十四州为客久，二千馀里见人稀。","梦回沧海心兼远，路入青萝兴不违。","想到家山秋正好，菊花盈把酌晴晖。"]},{"t":"客夜中秋怀吴谓远广文在郡未返","f":"七言律诗","c":["苜蓿先生久不归，西风吹叶拥柴扉。","海蟾过雨当中见，皋鹤凌秋独自飞。","远水一镫青入榻，隔花微露白侵衣。","郡斋今夜吟诗否，只恐当筵和者稀。"]},{"t":"珠崖秋夜怀罗浮旧隐","f":"七言律诗","c":["孤灯黯黯篆烟销，久客归心付寂寥。","半枕家山天易曙，一窗风雨夜无聊。","北鸿阻海书难寄，南树逢秋叶未凋。","谁念朱明最深处，有人重负菊花朝。"]},{"t":"送周生携儿归省","f":"七言律诗","c":["秋风迢递雁南飞，前路家山入望微。","片席挂随羊角去，轻车载得凤毛归。","北堂娱老熊将和，东阁招欢蜡并辉。","想到园林多乐事，解装先理旧莱衣。"]},{"t":"海外苦寒","f":"七言律诗","c":["漫说朱崖地轴偏，腊时依旧大寒天。","槟榔落尽风中实，榆荚抛残雪后钱。","天外片云虚白日，炉边宿火度除年。","旁人冷暖休相问，自纫金銊缀水田。"]},{"t":"甲子人日将游东山留别吴谓远广文","f":"七言律诗","c":["违山久似辞巢鹤，渡海深惭陷井蛙。","北顾未忘遵旧路，南行先上踏春车。","草鞋分得儒官俸，箬笠簪残野寺花。","挥手不须怅离索，市城云壑各生涯。"]},{"t":"发嘉积渡口","f":"七言律诗","c":["暖风晴日早春天，海外佳游不偶然。","隔水人看争渡客，入山僧上趁墟船。","溪光倒接孤峰势，云影平分两岸烟。","前路莫愁无旧识，虚舟移月就枯禅。"]},{"t":"万州道中作","f":"七言律诗","c":["朝随飞鸟暮归鸦，野鹤閒云不定家。","万里黑风吹白浪，一双赤脚踏黄沙。","望山渐喜东林近，去国都忘北岭赊。","粥饭主人何处是，驱鸟遥指路三叉。"]},{"t":"游龙池庵赠慧朗师","f":"七言律诗","c":["林无杂树水无波，长有云霞护薜萝。","池点小荷春意早，庭垂古柏老僧多。","西山不似东山浅，归路思寻别路过。","借问昔年老行脚，前程夷险更如何。"]},{"t":"约慧朗师筑室池上为终老计","f":"七言律诗","c":["冷淡门头锦绣堆，银山铁壁势崔嵬。","结成茅屋从师住，留得荷香待我来。","不定海珠明似月，无声石鼓响如雷。","临岐指点经行处，牢锁重关未许开。"]},{"t":"赠棋僧守愚","f":"七言律诗","c":["八百枯棋解纵擒，尚留馀习在空林。","閒中悟得楸枰理，眼底全无甲胄心。","淝水只今逢劲敌，浮山终古有知音。","道人本是忘机者，一局残灯话夜深。"]},{"t":"留别冯合溪","f":"七言律诗","c":["几度春风过鹿池，木棉花落怅临岐。","悠悠世路逢宗炳，往往人前说项斯。","黄犊还家添一齿，青山随地解双颐。","我将行脚君将老，白首重来未可期。"]},{"t":"题怀素千文帖留别王晋予","f":"七言律诗","c":["拾得长沙字满千，临岐珍重赠高贤。","三伊已落空王后，一画须知象帝先。","文采未彰书咄咄，太虚同体道玄玄。","吾家故物无文字，珍重逢人莫浪传。"]},{"t":"留别吴谓远广文","f":"七言律诗","c":["南来重上北来船，二月回思九月天。","眼见隙驹行易过，心同征雁去争先。","诗中旧路题曾遍，袖里名山写未全。","何事速归还速别，罗浮梅雨想高眠。"]},{"t":"留别陈次伯用前韵","f":"七言律诗","c":["呈桡舞棹学撑船，直入朱明第七天。","独往自惭归路晚，同游翻羡到家先。","短衣掩胫行方绽，破钵随身缀复全。","剩有残书将不去，留君窗下枕头眠。"]},{"t":"留别郑昭庵广文","f":"七言律诗","c":["尝恐还山与愿违，抉笼孤鹤纵高飞。","二千馀里空平楚，四百名峰在翠微。","棋敌出门谁对局，衲僧临别索留衣。","閒官未必閒于我，乘兴能来兴尽归。"]},{"t":"留别海外诸师","f":"七言律诗","c":["结束三衣共一囊，轻车辘辘载轻装。","快哉渐与家山近，行矣都忘旧路长。","临别商量同啐啄，从前语默尽秕糠。","御风何事归来早，却恐人先馈五浆。"]},{"t":"归途口占","f":"七言律诗","c":["尘外轻身身外尘，随风飘忽若为邻。","三年乐事惟今日，一路吟诗送好春。","远水度钟知古寺，隔桥闻语识乡亲。","相逢莫讶僧归晚，马首南来更有人。"]},{"t":"雨后宿琉璃庵","f":"七言律诗","c":["常时车马去腾腾，水尽山穷有佛灯。","云气簇来成骤雨，路人行过见孤僧。","一畦旧绿添新藚，半角閒房挂古藤。","乘此吃茶休歇去，两条寒涕任垂膺。"]},{"t":"访化州李广文苍水斋中话旧","f":"七言律诗","c":["东风归路借高凉，写访先生讲学堂。","官舍一清如传舍，与乡相见当家乡。","灯前细雨留僧话，花底新寒解客装。","惆怅旧游身已老，不堪回首忆齐昌。"]},{"t":"与李苍水何古钱放舟罗江登立石矶晚过黄茂才山庄同赋","f":"七言律诗","c":["背城临水冷官衙，立石当门处士家。","细雨登舟閒半日，晴江移棹过三叉。","一窗山色藤萝月，满地春风豆蔻花。","赢得舞雩归咏好，章缝丛里有袈裟。"]},{"t":"赠周胜濂校尉","f":"七言律诗","c":["三尺干邪照眼新，看看跃出古延津。","龙伸蠖屈无双士，燕颔虬髯未老人。","已有轻裘同昼锦，还将大树比灵椿。","赠君一柄棕榈拂，留待功成抖战尘。"]},{"t":"归途寄李苍水何古钱","f":"七言律诗","c":["信道尘中不见尘，波波犹自说閒身。","故山未返同为客，中道何堪更别人。","几欲兼程将禁夏，因贪良晤忽经春。","归装剩有诗篇在，吟向轻车字字新。"]},{"t":"送十洲师还南岳","f":"七言律诗","c":["已透云门最上关，偶将馀习托高閒。","大师未易鸣孤掌，全豹何妨见一斑。","圆月浅深同湛水，片云来往不离山。","君归若遇衡中老，应恨罗浮未尽攀。"]},{"t":"寄丹徒毛中庵明府","f":"七言律诗","c":["仙郎出宰近金山，正好寻僧日往还。","道在何妨兼吏隐，才优宁惜济时艰。","烟霞老我终成癖，雨露随君未许閒。","欲抱无弦远相访，秋风孤鹤度庾关。"]},{"t":"与陶握山岑金纪何不偕诸子重游濂泉怀旧","f":"七言律诗","c":["乱馀何幸得閒身，来往林泉自主宾。","冷局已无争道客，高山还有听琴人。","风生静树秋初入，月近枯禅夜独亲。","十载旧游零落尽，暮年相见莫辞频。"]},{"t":"重游濂泉赠友松师","f":"七言律诗","c":["曾向东林共种莲，新僧重结旧僧缘。","溪声山色垂垂老，翠竹黄花的的禅。","滴水渐穿崖下石，开池分贮涧中泉。","近来诗草焚将尽，拾得馀灰似瘦权。"]},{"t":"放雁","f":"七言律诗","c":["年年踪迹类飘蓬，同病相怜乃与公。","南海到来无鹤米，北溟归去有鹏风。","新翎未长飞犹倦，旧侣重寻兴岂穷。","几度举头天外望，不知谁早出樊笼。"]},{"t":"题异山高蹈图寄海南冯合溪","f":"七言律诗","c":["立处高高行处深，灵泉一别到于今。","太虚偶借丹青手，古调难为白雪音。","四海真交同水乳，百年归计在云林。","期君料理还童药，迟我重来策杖寻。"]},{"t":"送潘亦庶游珠崖","f":"七言律诗","c":["珠崖旧路我曾过，指点君行胜事多。","随地看山移店宿，停车得句扣轮歌。","东林长者名支遁，南国佳人字梦婆。","到日相逢应见讯，为言行脚尚蹉跎。"]},{"t":"白云飞瀑","f":"七言律诗","c":["因寻绝胜问山翁，指点泉声万壑中。","花雨影微银地迥，水晶帘捲玉壶空。","林间宿雾多藏豹，石上晴光总化虹。","千古一僧看不尽，随风飞出白云东。"]},{"t":"涅槃台","f":"七言律诗","c":["到处溪山尽解颐，一台终日对崔嵬。","閒身静坐三生石，老眼频看八字碑。","饮水自知无冷暖，磨砖谁复见须眉。","涅槃道者今何去，龙卧澄潭似旧时。"]},{"t":"挽张处士","f":"七言律诗","c":["一束生刍一纸书，殷勤寄语老龙舒。","乐邦好好还家去，尘世休休借宅居。","角里只今虚棐几，虎溪无复过篮舆。","相逢尽有同归钓，谁似先生得自如。"]},{"t":"送说泉师参方","f":"七言律诗","c":["祇嫌吾道太支离，裹足偷閒且后期。","万里孤筇人独往，一声长笛自家吹。","相随拨草瞻风日，不是游山玩水时。","为报诸方参学者，年来慧命似悬丝。"]},{"t":"送圣箭师参方","f":"七言律诗","c":["羡君云水正当时，老我烟霞不厌迟。","高步自誇双足稳，深心唯许一人知。","金能跃冶顽应少，箭贵全锋用乃奇。","閒抱瓶砖磨一片，待他归日照须眉。"]},{"t":"送庞西牟公车","f":"七言律诗","c":["三年前记别君时，袖取奇香寄所思。","我友尚存怀里字，故人犹是社中儿。","花明上国看千树，春满家山老一枝。","从此东林归不得，纵归多恐笑攒眉。"]},{"t":"送李尚卿公车","f":"七言律诗","c":["清晨有客款重扉，笑把行藏问衲衣。","似我索居何忍别，随人劝驾与心违。","海风不禁溟鱼化，天路难兼斥鴳飞。","行矣青云好乘兴，未应蓬荜借光辉。"]},{"t":"铁树","f":"七言律诗","c":["閒从大冶识灵根，荏苒柔柯百鍊身。","冷面铸来成直性，顽心销尽过芳春。","凌霄好似金辞矿，蘸水还同剑跃津。","我亦不材如散木，铮铮空自对时人。"]},{"t":"归韦涌与诸子分赋","f":"七言律诗","c":["一年一度一还乡，又是西风落叶黄。","身外镇随三事衲，鬓边新点数茎霜。","诗因见猎心仍动，月自逢秋夜未央。","今夕旧游枉相过，高歌曾记咏沧浪。"]},{"t":"挂搭支提精舍诸子见过分赋","f":"七言律诗","c":["牢锁重关秋复秋，无端移住此峰头。","一双白鸟啼红树，两角肥牛饮碧流。","叶上新诗风肆好，花间残局雨初收。","乘潮莫更乘潮去，芋饭藜羹似可留。"]},{"t":"秋日诸子过支提分赋兼订莲社之约","f":"七言律诗","c":["千山围著一禅房，一片茅茨覆短墙。","词客往来须及早，閒云去住本无乡。","桥头不觉成三笑，邻舍何劳馈五浆。","从此篮舆好乘兴，白莲花后菊花黄。"]},{"t":"韦涌诸子中秋见怀用韵赋答","f":"七言律诗","c":["过眼秋光又一年，西风吹倒半池莲。","老夫怕见青铜镜，稚子争收白玉钱。","愁似坚城攻未破，诗逢大敌战谁先。","相思未敢遥相忆，却恐晴阴各一天。"]},{"t":"送画师","f":"七言律诗","c":["曾修白业礼圭峰，竿木何妨此寄踪。","岂有丹青同画虎，却缘水墨会成龙。","篮舆随地堪乘兴，紫石为田且作农。","前路云山与人物，一重深又一重重。"]},{"t":"挽陈章甫居士","f":"七言律诗","c":["借得嚣尘作道场，偶从难弟识元方。","是非于我休相管，去住如君且不妨。","水上葫芦浮逼逼，天中云月露堂堂。","种松道者今何去，好好重来觌面商。"]},{"t":"和南岳僧雪庵来韵兼订入山之约","f":"七言律诗","c":["十载罗浮不下山，古藤缘壁绝跻攀。","自从一别孤峰去，独掩重扉万境閒。","渐老更思依岳麓，此身难免住人间。","闻师细说南衡事，莫怪相逢更解颜。"]},{"t":"竹尊者","f":"七言律诗","c":["不著繁华不落枯，当阳壁立见清癯。","休誇淇水多君子，岂独西山有丈夫。","高竖刹竿曾作祖，广开筹室任匡徒。","青青总是真如体，借问香严会得无。"]},{"t":"飞水潭观瀑","f":"七言律诗","c":["白凤啄冰翔碧落，玉龙带雪下瑶台。","天花不断四时雨，地轴长奔万壑雷。","茗椀试将新石乳，山衣湿透古莓苔。","重来记得曾游处，顾影澄潭日几回。"]},{"t":"祝李母","f":"七言律诗","c":["春风吹老北堂萱，霜入菱花鹤鬓繁。","课子躬耕方寸地，抱孙亲授五千言。","馀餐留作斋僧饱，重纩旁分冻谷温。","愿得此山长有主，不妨持钵日登门。"]},{"t":"圆瘏黎住锡华林览揆日诗以祝之","f":"七言律诗","c":["久住湖山老律师，钝根曾感授毗尼。","重来旧社逢生日，一到新城只暂时。","多窦塔中分半座，杂华林里策双眉。","自惭门外羊车客，未敢当人正眼窥。"]},{"t":"半閒兄弟双寿","f":"七言律诗","c":["沉醉东风羡二难，参差黄发映酡颜。","相看八十与七十，应是大山还小山。","华萼楼边春草碧，紫荆材下舞衣斑。","一门已得同居乐，百岁宁分各半閒。"]},{"t":"华林客夜送僧十影还里","f":"七言律诗","c":["到日便为归日计，别来还有再来缘。","流光似箭垂垂老，慧命如丝兀兀悬。","冷局已无争道客，空囊难赠买鞋钱。","送君一片东林月，相伴閒云处处圆。"]},{"t":"华林除夕与诸子守岁赋得山中无历日寒尽不知年得无字","f":"七言律诗","c":["病骨支离七尺躯，不堪长作寺家奴。","别山渐觉人将老，入世方知岁易徂。","岂有樊笼宜野鹤，更无寒暑管樵夫。","隔年未信春先入，借问梅花开也无。"]},{"t":"元夕后一夜与诸子话别","f":"七言律诗","c":["三城细雨散春灯，半榻疏钟对好朋。","岐路恰逢青眼客，故山将返白头僧。","光摇冷幌风欺烛，响落层崖夜堕冰。","回首林泉发幽兴，一声长啸忆孙登。"]},{"t":"将返马山答诸子见招来韵","f":"七言律诗","c":["珍重缄书报所欢，得盘桓处且盘桓。","烟霞密约终当践，城市嚣尘去不难。","老鹤随身云一片，春莺饶舌日三竿。","明朝料理还山棹，月满松窗好共看。"]},{"t":"初春还马山，静语师归自丹霞，十影、化声二子各还故里，赋此","f":"七言律诗","c":["流水行云各有因，乾坤容我老閒身。","移花买石堪晨夕，送往迎来自主宾。","远近杖头三事衲，东南鼎足数家春。","同参欲挽知难住，相劝还山作懒人。"]},{"t":"初冬卢雁林过宿马山寺有怀云庵上人","f":"七言律诗","c":["偶寻荒寺拥孤衾，难得良朋话夜深。","凿牖引山归冷榻，开帘延月出疏林。","寒花渐改高秋色，流水长怀太古音。","惆怅旧游成寂寞，影堂空挂薜萝阴。"]},{"t":"卢雁林过庵见赠赋答","f":"七言律诗","c":["红树黄花覆槿藩，一庵秋色数家村。","僧閒自笑驴窥井，客至唯教鹤应门。","短烛话深通语默，旧游见惯失寒暄。","与君早有居山约，双鬓无端雪渐繁。"]},{"t":"送梁晋煌适珠崖省墓","f":"七言律诗","c":["孤儿十载已无家，又逐飞蓬渡海涯。","分室我应惭郈伯，下车谁复问西华。","桑榆日暮频怜影，杕杜春深自放花。","此去定知防墓近，白杨犹有未归鸦。"]},{"t":"初春何古钱过宿马山分赋","f":"七言律诗","c":["野老入山殊草草，旧游留话未匆匆。","半窗萝月三更梦，万壑松涛一夜风。","高韵独吟清漏永，孤灯分照寸心同。","殷勤致语东林炳，莫漫逢人说懒融。"]},{"t":"与李远霞卢雁林诸子分赋","f":"七言律诗","c":["故人笑我住人间，指点云林共掩关。","隔竹閒门新白板，满楼春色旧青山。","眼前有句频拈出，物外无心且放顽。","乘兴更探泉脉去，一溪流水碧潺潺。"]},{"t":"喜毛中庵明府归自丹徒 其一","f":"七言律诗","c":["道情平澹世知稀，一奏良刀便入微。","官似澄江清见底，心同高鹤倦思归。","春栽荷芰成初服，晚脱华簪伴衲衣。","閒上竹楼楼上望，青山依旧对玄晖。"]},{"t":"喜毛中庵明府归自丹徒 其二","f":"七言律诗","c":["草鞋正拟参方去，却喜金山有主人。","北道未通怀里刺，东篱重理瓮头巾。","朱弦静谱当时曲，白社言寻昨日春。","分卫偶来劳见讯，长官争似衲僧贫。"]},{"t":"题郑停莪新筑","f":"七言律诗","c":["负郭依山结筑牢，到门唯见一峰高。","翚飞轮奂饶云物，凤食琅玕足羽毛。","东阁书声喧彩服，西轩茗色醉方袍。","主人本是忘机者，肯向春田事桔槔。"]},{"t":"分卫铁城贻社中诸子","f":"七言律诗","c":["好春早有名山约，稔岁偏宜托钵僧。","自买草鞋来海岳，遍将米价问庐陵。","莲塘旧社归难得，桂岭孤峰到未能。","多谢同参屡招隐，蹉跎深愧久要朋。"]},{"t":"雷峰寺观潮","f":"七言律诗","c":["廿年曾过潮边寺，今日初观寺外潮。","万马直奔鱼腹浦，一鸥閒立虎溪桥。","前村云树连空碧，隔岸菰蒋入望遥。","犹胜西湖二三月，风光多半属渔樵。"]},{"t":"秋郊观猎","f":"七言律诗","c":["霜天晓角出长楸，选队从禽逐胜游。","高鸟欲飞聊戢羽，饥鹰将击尽凝眸。","东门黄犬缨金锁，南国青蛾控玉骝。","大笑守株林下叟，雀罗深巷鹿呦呦。"]},{"t":"月夜李东园诸子过宿马山赋得身閒数得上方眠","f":"七言律诗","c":["物外身閒几个能，入山居士住山僧。","孤衾独抱来何暮，短榻高悬下未曾。","古月照残尘外梦，新虫吟破壁閒灯。","殷勤报语侵晨客，莫把浮云换曲肱。"]},{"t":"春日偕诸子过东园别业分赋古梅","f":"七言律诗","c":["昨日梅花村里回，偶寻高士见庭梅。","最怜老干棱棱瘦，不似群芳草草开。","硕果岂供嘉客赏，孤根曾见太平来。","春风吹醒閒人梦，长笛一声诗兴催。"]},{"t":"初入东湖谒契如和尚 其一","f":"七言律诗","c":["久向东湖十载前，遐心长寄水云边。","偶来隔竹闻清磬，为爱新凉上小船。","生计百年三事衲，名山到处一家禅。","从师乞得閒房住，愿执巾瓶侍法筵。"]},{"t":"初入东湖谒契如和尚 其二","f":"七言律诗","c":["祖翁旧业未荒芜，赖有西乾古丈夫。","白社一灯悬太白，湖光千顷接天湖。","林间趺坐花香满，水际閒行鹤影癯。","珍重清光似明月，长留孤棹在菰蒲。"]},{"t":"初入东湖谒契如和尚 其三","f":"七言律诗","c":["万象森罗一鉴中，化城今在莞城东。","波光倒插千峰影，暑气潜消五月风。","翠竹晚凉丹荔熟，白莲朝映槿花红。","罗浮咫尺家山近，细把程途问主翁。"]},{"t":"客夜与林叔吾湖上话旧","f":"七言律诗","c":["棋罢花边覆局难，灯前一笑太无端。","坐残溽暑心犹热，话到深宵胆亦寒。","酒力驱君投寺宿，月华留客过湖看。","别来学得无弦曲，草草相逢未易弹。"]},{"t":"舟中阻风","f":"七言律诗","c":["寒江信宿类孤鸿，一日归程五日风。","入梦家山明月外，满船疏雨乱流中。","秋声夜半闻飘叶，浪迹年来笑转蓬。","但得沧波似平地，不妨长作钓鱼翁。"]},{"t":"圆瘏黎住仙掌岩却寄","f":"七言律诗","c":["孤峰顶上数閒屋，仙掌岩边一个僧。","高处看人明了了，老来无事冷冰冰。","漫劳法社虚前席，亲见威音绍祖灯。","十载步趋惭我后，门庭高峻拟先登。"]},{"t":"九日登仙掌岩谒圆阇黎","f":"七言律诗","c":["郡城咫尺旧皇州，仙掌嵯峨控上游。","金马铜驼空落日，珠林琪树不凋秋。","登高望远凭青眼，坐石看山到白头。","师若肯留予肯住，世间无地可藏舟。"]},{"t":"听卢生弹琴","f":"七言律诗","c":["静者能琴不易弹，一弹一曲一盘桓。","繁弦按月孤心细，枯木生风十指寒。","天籁去人无咫尺，广陵终古有波澜。","吟君好句知难和，谁信希声和更难。"]},{"t":"厓门怀古","f":"七言律诗","c":["海滨头白老渔翁，今古兴亡在眼中。","罢钓一过沉玉浦，挂飘犹畏覆舟风。","珊瑚树底瞻龙衮，鹓鹭行边想贝宫。","惆怅翠华何处所，一声长啸动高穹。"]},{"t":"和毛明府中庵见赠","f":"七言律诗","c":["十载经过万木森，今来祗树又成林。","閒僧到处青山在，廉吏还家白发侵。","老病渐思寻活计，虚名多恐负初心。","自从识得陶彭泽，一度相逢一度深。"]},{"t":"和梁茂才磐重见赠","f":"七言律诗","c":["朝来抱瓮过横塘，冬后偏宜灌药房。","待我未能容我懒，劳生何敢笑人忙。","野芹采去肥因雨，老苋烹来脆有霜。","佳客不嫌滋味淡，明年多种待君尝。"]},{"t":"和方壶洲见过赋赠","f":"七言律诗","c":["此生那得两閒身，聊复停居避市尘。","止水月深三五尺，过桥云隔数由旬。","忙拖象屐迎佳客，偶著鹑衣见故人。","炉火正红茶正熟，留君差胜瓮头春。"]},{"t":"答萧明经邻翼见赠","f":"七言律诗","c":["古木新篁共一林，草堂如在碧山岑。","过桥送客无宾主，隔水看云有浅深。","露柱日中停昼影，风琴寒定失清音。","城中好友曾知否，寂寞生涯为许寻。"]},{"t":"和区木参来韵","f":"七言律诗","c":["浪迹似萍浮泛泛，枯形如鹤瘠栾栾。","旁观笑我棋先罢，饱食逢人铗懒弹。","暂借名园为地主，拟留佳客畏天寒。","夜来好月谁同见，紧闭柴门独自看。"]},{"t":"和何太占来韵 其一","f":"七言律诗","c":["渐老渐知行处偏，忍抛朋侣泥林泉。","有人问我此中事，荅道山僧不会禅。","疏雨隔墙添夜色，冷云穿牖透孤烟。","相过独有何公子，世外神交岂偶然。"]},{"t":"和何太占来韵 其二","f":"七言律诗","c":["爱此幽居水石偏，閒门临沼沼通泉。","鸂鶄饱食朝收钓，鹳鹤长饥夜立禅。","冷灶静添煨芋火，破窗时有煮茶烟。","君归尚忆东林否，乘兴重来亦偶然。"]},{"t":"和萧志三见赠","f":"七言律诗","c":["借得名园东郭东，清溪曲曲小桥通。","千寻碧树鹤巢顶，四面青山人在中。","映水波分双橘绿，经霜风散半林红。","劳君诗句频相过，吟旁斜阳答远钟。"]},{"t":"广州江楼阻雪荅家峻山峋山","f":"七言律诗","c":["出门多与此心违，几日浓阴半撞扉。","冷榻不堪愁里坐，故山频向梦中归。","江声过雨成空润，风势兼寒入细微。","南阮老来贫更甚，劳君重叠劝添衣。"]},{"t":"夜泊遇雪","f":"七言律诗","c":["严城吹角晚栖鸦，野客扁舟归兴赊。","隔岸冻云迷浦溆，满船寒雨湿袈裟。","萍踪自断随风力，蓬鬓知难避雪花。","便把生涯问渔父，明年相继学浮家。"]},{"t":"同住东林，有厌清苦者相继辞去。时值小除，与诸子守岁，示此以坚其志","f":"七言律诗","c":["山厨破甑久生尘，笑拨寒灰事火神。","冷灶已无黔突客，居亭犹有刻舟人。","橘因易地春为枳，姜自经冬老更辛。","大尽到来能几几，暂留同住守庚申。"]},{"t":"壬申元旦谩兴示诸子","f":"七言律诗","c":["一夜春风洗病颜，乾坤容我老痴顽。","新知如故花边日，暂别能来雨后山。","竹径有风朝罢扫，松门无客晚休关。","等閒指出閒生理，慎勿将心更觅閒。"]},{"t":"游墺门宿普济禅院赠云胜师","f":"七言律诗","c":["珠林遥隔水云村，百里寻僧日欲昏。","行逐鲛人趁番市，渐闻鴃舌杂华言。","山钟近接三巴寺，海气晴分十字门。","到处不妨吾道在，岛夷今识法王尊。"]},{"t":"墺门阻风","f":"七言律诗","c":["绝徼到来曾几日，故山回首已千重。","归从旧路常忧雨，去逐春潮却滞风。","拜浪江豚随上下，忘机鸥鸟自西东。","偶来识得居夷叟，浮海乘桴兴不穷。"]},{"t":"送李广文方水掌教筠城，兼寄潘明经圆子","f":"七言律诗","c":["同游回首各升沉，往事那堪数至今。","两度川山仍旧路，三年风木负初心。","大儒到处多虚席，古道由来有盍簪。","白首故人如见讯，祖庭秋冷待相寻。"]},{"t":"杨孝廉明度出宰宣平，其昆玉江度旻度送至官舍，归途遍历西湖、天台诸胜，辄有题咏，出以示予，赋此以致欣赏之意，因寄宣平明府 其一","f":"七言律诗","c":["诗情偏重宦情轻，谁似杨家好弟兄。","风雅一门分鼎足，纵横七字筑长城。","逢僧说瀑眉毛冷，随地看山耳目清。","多谢新篇劳见示，把吟终日忆宣平。"]},{"t":"杨孝廉明度出宰宣平，其昆玉江度旻度送至官舍，归途遍历西湖、天台诸胜，辄有题咏，出以示予，赋此以致欣赏之意，因寄宣平明府 其二","f":"七言律诗","c":["梦想西湖二十年，输君先我祖生鞭。","六桥花信供诗笔，四面山光上画船。","歌馆醉吟翻艳曲，精林来往悟真禅。","还家已过春三月，犹欲开池自种莲。"]},{"t":"杨孝廉明度出宰宣平，其昆玉江度旻度送至官舍，归途遍历西湖、天台诸胜，辄有题咏，出以示予，赋此以致欣赏之意，因寄宣平明府 其三","f":"七言律诗","c":["七体雄篇推哲匠，千寻飞瀑下天台。","吟成好句敲推久，忘却危梁经过来。","蜡屐岂应遗雁宕，奚囊无计逐龙媒。","相闻更有名山约，抖擞閒身为许陪。"]},{"t":"泊端州","f":"七言律诗","c":["几过端州逢九日，水边三见菊花新。","秋风江上同为客，凉月天涯识故人。","渐老自知佳梦少，乍寒先与敝袍亲。","何堪倦鹤睡方足，遥听鸡声起白蘋。"]},{"t":"晓发长江寺","f":"七言律诗","c":["长江古寺数声钟，催起船头白发翁。","初日渐高群象外，轻烟不尽乱流中。","微吟自拾沿流叶，清啸遥迎破衲风。","秋色重重山又水，不知何处息征篷。"]},{"t":"龙山国恩寺谒卢祖影堂","f":"七言律诗","c":["群峰西峙水流东，旧路分明见祖翁。","白日渐低祗树影，青山空冷桂花风。","当时不合分南北，后世何因说异同。","一瓣真香为谁爇，镜台无像日当中。"]},{"t":"题卢祖父母暮","f":"七言律诗","c":["列嶂嵯峨逼太清，百千龙象拥佳城。","一家共住无生国，异世经过何限情。","教子直须成佛祖，显亲谁得似宁馨。","北邙多少累累冢，寂寞泉扉昧姓名。"]},{"t":"归舟夜泊峒口","f":"七言律诗","c":["秋江何处不清泠，近浦维舟远思兴。","野烧入船添夜色，岸萤依草乱村灯。","看山记得来时路，顾影还同昨日僧。","岁暮归心似流水，一随风力便成冰。"]},{"t":"宿佛径庵，赠迈往师，怀开山故人","f":"七言律诗","c":["千峰行尽水迢迢，日暮寻师过断桥。","僧老不闻翻贝叶，身閒惟爱种芭蕉。","山藏绝壑人稀少，秋入空林夜寂寥。","惆怅居亭何处所，满庭黄叶落萧萧。"]},{"t":"赠平山庵主兼贻谭氏诸阮","f":"七言律诗","c":["千家烟火隐云岚，一个真僧守破庵。","行脚不妨随我住，枯禅还喜有人参。","竹林诸阮分南北，莲社群贤数二三。","咫尺乌衣门巷近，出墙红树间黄柑。"]},{"t":"癸酉元旦书怀","f":"七言律诗","c":["衮衮两九三百六，看看五十七年春。","青阳有主身为客，白发无情老近人。","欲买北山虚旧约，偶寻东墅得佳邻。","风光不厌频流转，一度移居一度新。"]},{"t":"开元寺探泉","f":"七言律诗","c":["停舟偶过开元寺，就地还寻最胜泉。","石甃久荒苔藓外，茶瓢犹挂薜萝边。","当时一滴成花雨，终古馀波及稻田。","老衲不知陵谷变，殷勤挹注奉金仙。"]},{"t":"过何太占南塘","f":"七言律诗","c":["南塘春雨客来稀，一个閒僧到竹扉。","乔木不随沧海变，野鸥长傍水亭飞。","榄峰晚色青千叠，槐岸新阴绿一围。","便向居亭问祗树，隔溪遥指钓鱼矶。"]},{"t":"宿何赤木西园","f":"七言律诗","c":["数年有约兴初乘，一宿西园快寝兴。","柳色齐檐临水阁，花光摇槛隔桥灯。","鱼笺重叠曾招隐，鹤米平分许饭僧。","多谢主人能爱客，相门虽峻不妨登。"]},{"t":"泊江门","f":"七言律诗","c":["东风挂席下江门，江上维舟晚渡喧。","日脚乍收云外雨，潮头遥失水边村。","年来浮海心偏远，老去看山眼未昏。","极目沧桑更怀古，崖山回首一销魂。"]},{"t":"过白沙先生祠故址","f":"七言律诗","c":["大儒出处见高风，遗搆依稀想像中。","皋座春来莎草遍，石楼兵后玉书空。","偶然消息成吾是，静里端倪忆我公。","咫尺江门江上水，扁舟来往此谁同。"]},{"t":"访杨敏叔不遇，时敏叔归崖门故宅","f":"七言律诗","c":["来从古寺问西墩，隔水遥知处士门。","陋巷僦居徒四壁，故园归棹有孤村。","青山浪迹聊舒愤，白首论心未报恩。","何事先生难得见，一年强半在慈元。"]},{"t":"登玉台寺呈雪玻长老","f":"七言律诗","c":["玉台半壁削天根，金地巍峨古佛尊。","万里山川供指顾，二时钟磬辨朝昏。","往来烟水疑无路，出入云霞别有门。","欲向孤峰问禅律，自伤迟暮不堪论。"]},{"t":"归舟过大悦滘，访屈无倦、无极二子","f":"七言律诗","c":["春风门巷薜萝阴，大悦溪边水石深。","久别乍惊儿女长，老来犹见弟兄心。","残枰懒向花间覆，旧梦多从醒后寻。","草草相过殊未快，归舟一路托枯吟。"]},{"t":"客西园赠陈东崖","f":"七言律诗","c":["回首嬉游似断篷，可堪相见各成翁。","童心掷向红尘外，壮志销归白业中。","短榻夜禅陪病鹤，閒阶春望送孤鸿。","西园宾从多新识，争羡先生有祖风。"]},{"t":"初秋七日集容尘轩分赋","f":"七言律诗","c":["一轩秋色净无尘，幕府烹葵召野人。","躐等不知宾礼密，过中多感主情真。","閒题丽句酬仙侣，笑指灵槎忆汉臣。","翘首客星何处所，晚来风雨暗天津。"]},{"t":"中秋夜与诸子归舟泊港口，玩月分赋","f":"七言律诗","c":["海气连云送落晖，远寻渔火宿渔矶。","四围夜色凉衾枕，一晕寒光浸衲衣。","异地同舟非偶偶，中秋见月亦稀稀。","明年此夕重来否，多恐还山各掩扉。"]},{"t":"送杨勉斋北上公车","f":"七言律诗","c":["一回见面一回新，不觉相逢是贵人。","未敢久留三笑侣，近须忙趁百花春。","梦游海岳身先老，道合风云曾有因。","君去选官予选佛，局中谁为辨疏亲。"]},{"t":"病中荅人","f":"七言律诗","c":["不知身寄在东城，屋角青山惬野情。","竹榻笑人长卧病，杖藜扶我且经行。","花边独鹤迎嘉客，池上群鸥订夙盟。","珍重新诗劳见赠，沉疴初起见枚生。"]},{"t":"甲戌春偕诸子游鼎湖，雨中晚泊 其一","f":"七言律诗","c":["渡头古树半栖鸦，树底维舟近浅沙。","风势北来潮带雨，海门南望水如花。","閒身随地堪乘兴，老眼逢山便当家。","明发挂帆云外去，鼎湖春色在天涯。"]},{"t":"甲戌春偕诸子游鼎湖，雨中晚泊 其二","f":"七言律诗","c":["同游有约兴腾腾，信宿寒江寝复兴。","假寐耦将孤鹤影，苦吟分得钓鱼灯。","春多滞雨愁为客，老厌风尘愧作僧。","何事洞天归不得，此心多恐负良朋。"]},{"t":"三入天湖呈契和尚","f":"七言律诗","c":["细路入云通曲曲，乱山回首失层层。","有人独上最高顶，长啸一声何处僧。","胜友新知如旧识，名山三过俨初登。","殷勤问讯天湖主，挂角羚羊见也曾。"]},{"t":"答郯城明府家二兄蒙章","f":"七言律诗","c":["老年兄弟久离居，物外衰慵近不如。","马齿渐加牙齿落，道情偏密世情疏。","胸中只有难成事，袖里长怀未报书。","我未参方君滞宦，不堪回首赋归与。"]},{"t":"荅陈惟深","f":"七言律诗","c":["年来踪迹类飞蓬，道与时违莫强同。","晚市放歌逢郢客，春城扶病问壶公。","高谈直泻千山瀑，清啸遥来四座风。","林下为君悬一榻，松门终日候双童。"]},{"t":"初秋夜梦入罗浮，得诗一律，醒后仅忆登高望远之句，援笔续成","f":"七言律诗","c":["一夕新凉枕簟清，秋风送客入朱明。","登高却恐日欲尽，望远方知云有情。","乘兴偶来嫌梦短，步虚归去觉身轻。","何须更跨杨州鹤，当挟仙飞万里行。"]},{"t":"初秋舟泊小金山，宿妙高台，与僧话旧","f":"七言律诗","c":["江上西风一放舟，暮云飞去见灵洲。","古台落叶初归鸟，野渡停桡不避鸥。","白社重来寻旧约，青山无恙忆同游。","灯前细语人难会，顽石何因更点头。"]},{"t":"宿双桂洞","f":"七言律诗","c":["丛桂枝高古洞门，远风吹叶叶归根。","祖庭频到长为客，往事空惭未报恩。","病骨依灯嫌有影，瘦藤卓月了无痕。","城中莫道嚣尘满，一闭閒房是故园。"]},{"t":"挽萧明经邻翼 其一","f":"七言律诗","c":["净名示疾已多时，消息传闻信复疑。","岂有适来还适去，不堪成喜又成悲。","二毛始悔参禅晚，五岳偏嫌遣嫁迟。","岐路分携多未惜，惜哉岐路更多岐。"]},{"t":"挽萧明经邻翼 其二","f":"七言律诗","c":["昨日人窥董傅园，今朝客散翟公门。","羞将雉性求田宅，止有萤灯付子孙。","郢匠岂堪还斲鼻，楚些无复更招魂。","劳生欲别非难别，忍泪相辞勿复言。"]},{"t":"挽萧明经邻翼 其三","f":"七言律诗","c":["空中野马路旁尘，去住无端自主宾。","扪馆便为乘驿客，过桥还是隔溪人。","多生未了三生愿，万事惟馀一事真。","君已盖棺予亦老，相期牢记续前因。"]},{"t":"市中传奇僧俗杂观，诗以戏之 其一","f":"七言律诗","c":["旷野歌声杂管弦，市儿灯火闹争先。","蛮姬幻作天魔舞，开士慵参獦獠禅。","老逐少来争接踵，閒随忙去任挨肩。","道人本是无心者，拨尽寒灰夜似年。"]},{"t":"市中传奇僧俗杂观，诗以戏之 其二","f":"七言律诗","c":["三叠清商一笑休，旁观容我豁双眸。","御风羽客隳神足，出定高僧过酒楼。","野老醉归霜点鬓，佳人歌罢锦缠头。","无情独有长天月，不与风光管去留。"]},{"t":"再过西园赠何赤木","f":"七言律诗","c":["绮阁茅亭水石边，客来多爱主人贤。","重寻旧约过残腊，一别西园动隔年。","龙竹倚窗寒势直，凤山缭屋夕光圆。","閒身到处堪乘兴，回首当时更宛然。"]},{"t":"南塘泛舟赠何太占","f":"七言律诗","c":["我本钓鱼船上客，偶随鸥鹭下南塘。","长空放鹤不留影，野水侵花长带香。","屈子牢骚庄旷达，稽生懒惰阮猖狂。","相逢大笑各归去，明日抱琴来此堂。"]},{"t":"西园雨后","f":"七言律诗","c":["新雨添流涨一溪，落花和雪踏成泥。","山如野客携云入，鸟爱高朋借树栖。","霁色偏宜舒眼阔，短墙恰好与肩齐。","暂来便作居亭计，自脱荷衣理药畦。"]},{"t":"过李子将鸥次昆玉","f":"七言律诗","c":["榄峰南去一溪横，元礼门高简送迎。","花底罢棋群动息，琴边抄谱万缘清。","僧来白社无宾主，诗祖青莲有弟兄。","回首旧游如昨日，不妨相见尽平生。"]},{"t":"挽胡甘滩","f":"七言律诗","c":["石羊山下识初平，仙去惟怜鹤驭轻。","楚些拟招魂不返，滩声流恨水无情。","仪廷待凤迟三稔，杖国支鸠失五更。","莫负高秋星月夜，归来重与话三生。"]},{"t":"李远霞过宿夜话分赋","f":"七言律诗","c":["野水閒云共一池，池边借地结茅茨。","远风不断疏疏竹，清磬难藏密密篱。","门外雀罗无别客，阶前鹤立有新知。","烦君过我连宵话，明月当轩照向谁。"]},{"t":"赠置荅师隐山","f":"七言律诗","c":["投老空山计未能，偏将好事让良朋。","开云觅路闻啼鸟，就树营居畜俊鹰。","分得田园凭地主，望来烟火有邻僧。","何堪别后思君处，独立螺峰最上层。"]},{"t":"送孙长发护其叔氏仁化明府旅衬还京，是冬长发应选诠部","f":"七言律诗","c":["自从叶县去瀛洲，谁挟双凫返故丘。","锦水丹山逢谢客，素车朴马识孙谋。","云随黻翣回仙驭，风送霓旌指帝州。","领海凭君作霖雨，金台归去莫淹留。"]},{"t":"舟发汾水，时同舟汝得、豁大、无我、而卓诸师皆入丹霞，舟中分赋","f":"七言律诗","c":["同舟载得数家禅，江上潮声促放船。","老大出山如出世，去留由我不由天。","一生活计从今日，五岳归来定几年。","前路莫愁风浪恶，顺流施桨逆流牵。"]},{"t":"舟中雨况","f":"七言律诗","c":["江分四会水三叉，才听滩声见浅沙。","满眼波流思砥柱，一天风雨过芦巴。","减将午食添鱼米，待得新晴埽雪花。","劳动同舟远相示，白云深处是丹霞。"]},{"t":"过浈阳峡","f":"七言律诗","c":["轻舟冲破一江风，路转浈阳去不穷。","南陆渐低云影外，西峰半落水声中。","松高恰好宜幽独，壁立何曾碍太空。","识得真山真面目，品题泉石入诗筒。"]},{"t":"晓过英州","f":"七言律诗","c":["寒生襆被雪初晴，一路吟诗过古城。","隔水看白空有影，殊方闻鸟不知名。","品茶泉向船头汲，选石云从袖里生。","胜事渐多心渐远，不妨随地一迂程。"]},{"t":"谒憨祖肉身","f":"七言律诗","c":["借路还家识故乡，重来顶相露堂堂。","天花散满楞伽室，祖席平分曲录床。","白氎不留身后线，黄冠休问旧时装。","门前溪水西来意，流入空庭味更长。"]},{"t":"曹溪谒祖","f":"七言律诗","c":["却缘松竹引清风，路入曹源识祖翁。","衣钵有山皆拱北，袈裟无水不流东。","镜台影露云千叠，碓觜花开桂一丛。","莫与溪声斗长舌，知音人在月华中。"]},{"t":"呈泽萌和尚 其一","f":"七言律诗","c":["片云閒逐断篷飞，路转寒山入翠微。","十八破家人已老，一声长啸客方归。","别峰相见谁招手，绝顶频登独振衣。","万境总閒留不住，住来惟爱蕨芽肥。"]},{"t":"呈泽萌和尚 其二","f":"七言律诗","c":["偶来原不为登临，借得閒房慰夙心。","云水随缘无去住，烟霞投分有高深。","林閒度岁如增劫，梦里还家当陆沉。","珍重海螺吹一曲，孤峰翘首待知音。"]},{"t":"呈泽萌和尚 其三","f":"七言律诗","c":["云深山路失高低，足快身轻定不迷。","占断云根晞白发，望穷山色上丹梯。","空生却被岩花笑，庄叟难将物论齐。","长老峰头相见后，钵囊高挂不须携。"]},{"t":"呈泽萌和尚 其四","f":"七言律诗","c":["林光亭午日当中，定出无心笑懒融。","片石似云争远近，双松连影失雷同。","南车直指千峰北，西水长流万派东。","从此丹霞无别客，不妨识得主人翁。"]},{"t":"丹霞十二咏 其一 紫台爽气","f":"七言律诗","c":["玉台半壁锁松筠，地接西山爽气新。","褦襶不来无热客，袈裟频上有閒人。","凉兼草色归眉睫，风递江声过耳轮。","咫尺夕阳山下路，是谁挥汗走红尘。"]},{"t":"丹霞十二咏 其二 锦水滩声","f":"七言律诗","c":["山光历历水涓涓，十里滩声绕法船。","碧石无心成背触，清溪何事独潺湲。","涨添宿雨迷孤屿，响驾长风下百川。","却笑沧浪老渔父，急流收钓竟忘筌。"]},{"t":"丹霞十二咏 其三 螺顶浮图","f":"七言律诗","c":["四楞匝地逼虚空，拾级齐云迩梵宫。","宝铎希声风在下，鬓珠无影日当中。","鸟窠直上窥天险，雁塔频登识化工。","夜半金轮峰顶月，清光还与此山同。"]},{"t":"丹霞十二咏 其四 虹桥环翠","f":"七言律诗","c":["何事天台访石梁，断虹斜日两苍苍。","乱峰过雨青如染，疏柳经春翠不黄。","浅碧有时成藓阵，绿沈何处觅茶鎗。","名山久住忘衰老，惟爱桥头笋蕨长。"]},{"t":"丹霞十二咏 其五 竹坡烟雨","f":"七言律诗","c":["旧竹低垂新竹高，淡烟疏雨两萧骚。","笋根童子窥泉脉，林下閒人罢桔槔。","绿玉倚檐摇翠幌，冷云和梦湿缁袍。","何堪更忆潇湘夜，剔尽寒灯闻百劳。"]},{"t":"丹霞十二咏 其六 松涧涛风","f":"七言律诗","c":["一种孤高不易攀，此身只合住深山。","养成鳞甲为龙去，化作云涛待鹤还。","声入空林人寂寂，响归幽涧水潺潺。","叮宁莫把松风卖，留在千岩万壑间。"]},{"t":"丹霞十二咏 其七 镜沼荷花","f":"七言律诗","c":["春雨迟开白藕花，看花人早入丹霞。","磨砖作镜成双沼，习坎兼山总一家。","十丈如船归玉井，半空和月印金沙。","老僧久在山中住，待剪荷裳度岁华。"]},{"t":"丹霞十二咏 其八 丹梯铁锁","f":"七言律诗","c":["凿壁扪萝上翠微，老僧见惯步如飞。","朝随林鸟排云去，暮逐岩猿带月归。","自恨丹梯延俗客，谁攀铁锁到山扉。","何当截断红尘路，独占孤峰饱蕨薇。"]},{"t":"丹霞十二咏 其九 乳泉春溜","f":"七言律诗","c":["石乳岩边长绿苔，水帘高捲洞门开。","溪云入谷成山雨，崖溜添泉助茗杯。","抱瓮春深机事息，挈瓶林下野人来。","清泠莫逐桃花去，流入尘寰不复回。"]},{"t":"丹霞十二咏 其十 舵石朝暾","f":"七言律诗","c":["上方明相下方同，林影参差辨梵宫。","海印光生华藏界，天鸡啼向舵盘东。","云迎霁色先沉壑，鹤趁朝暄早出笼。","莫道日高僧未起，阳乌曾不恕衰翁。"]},{"t":"丹霞十二咏 其十一 杰阁晨钟","f":"七言律诗","c":["嵯峨高阁晓钟深，下界闻声不可寻。","枕上一醒朝市梦，天边三答海潮音。","曲高不入时人耳，韵苦遥传古佛心。","一片蒲团半轮月，枯禅何事独沉唫。"]},{"t":"丹霞十二咏 其十二 片鳞秋月","f":"七言律诗","c":["片月分明属片鳞，天边何处别疏亲。","磨成破镜为圆镜，照见今人失古人。","指上不堪存幻见，空中无可着纤尘。","老僧老眼常如此，一度逢秋一度新。"]},{"t":"长者峰","f":"七言律诗","c":["久响高峰老古锥，名山随地见威仪。","天花过眼能无着，霜雪盈头总不知。","稳坐枯禅同木石，长留古镜照须眉。","海螺吹落千山月，正是无情说法时。"]},{"t":"锦石岩","f":"七言律诗","c":["洞门开处石堂幽，咫尺丹霞在上头。","山色一家无向背，水声千派自分流。","云生锦石寒侵榻，风过霜林叶满楼。","借问主人何处去，秋成时节半西畴。"]},{"t":"送无我师还里，兼柬里中诸子","f":"七言律诗","c":["同游几日复离居，赠别无多意有馀。","白发淹留非所惜，红尘归去欲何如。","新诗近欠名山债，密约凭将故里书。","岐路转多心转惑，从来儿女会牵裾。"]},{"t":"寄马卧仙","f":"七言律诗","c":["寄语东林十八贤，寻思旧约过新年。","青山一入归无梦，白首重来待有缘。","僧似行云閒未得，官如传舍久应迁。","何当岐路逢君处，戴笠乘车各爽然。"]},{"t":"送顿惺师分化龙护园","f":"七言律诗","c":["下山原是住山翁，谩把行藏说异同。","别院去开梅岭北，孤峰回首海螺东。","手擎香饭千僧饱，梦破红尘万境空。","到日不妨悬一榻，明年迟我去瞻风。"]},{"t":"丹霞除夕与诸子守岁","f":"七言律诗","c":["閒心到处不须安，借得岩居学懒残。","拥被早为虮虱计，废书留作蠹鱼餐。","梅妻梦里将春信，鼠妇灯边语夜阑。","大地一时人尽老，独留孤影在蒲团。"]},{"t":"丹霞元旦","f":"七言律诗","c":["天外三更来鹤神，老翁白发参差新。","明知昨日有今日，同是一人非两人。","海印乍生虚室白，谷风不动明窗尘。","兴来策杖入云去，极目莽苍何处春。"]},{"t":"送汝得师住静龙爪岩","f":"七言律诗","c":["峰前峰后一家春，暂得移居事事新。","水石平分凭地主，云霞多散与山邻。","篅瓢小结宽容膝，曲录閒眠稳称身。","他日寻师过龙尾，半天招手是何人。"]},{"t":"懒诗 其一","f":"七言律诗","c":["雪顶鬣鬖一半灰，蒲团长日委尘埃。","二时钟板催难起，千里书筒置不开。","屐齿经春生白醭，杖头过雨着青苔。","有人问客家何处，荅道俱卢洲上来。"]},{"t":"懒诗 其二","f":"七言律诗","c":["贝叶长抛不省翻，弊袍和带度寒暄。","蠹鱼饱食成家舍，虮虱安居长子孙。","一枕可能消白日，八行无复到朱门。","閒云未必閒于我，来往长空不惮烦。"]},{"t":"懒诗 其三","f":"七言律诗","c":["绩凫断鹤太无端，识性同居总便安。","窗外猿猴凭窃果，铛边猫犬任争餐。","云连屋底和衣卧，月到床头隔被看。","剩有多生馀习在，诗书堆里过严寒。"]},{"t":"懒诗 其四","f":"七言律诗","c":["不近人情不问天，涅槃轮转且随缘。","两条寒涕何因拭，七尺枯形任自然。","有口只堪长挂壁，无心不拟更参禅。","耽閒转觉多忙事，笑杀西来竺土仙。"]},{"t":"丹霞秋况 其一","f":"七言律诗","c":["独住孤峰计未成，暂时安稳闭柴荆。","移床就瀑晴还雨，倚杖看云陡亦平。","山意送寒催老景，禅心兼懒入诗情。","从抛笔墨烟霞外，何暇缄书寄友生。"]},{"t":"丹霞秋况 其二","f":"七言律诗","c":["跳丸踯躅去匆匆，借得岩居任岁穷。","山与太虚分树色，石嫌孤立倩烟笼。","高柯坠果惊寒露，病鹤移巢避朔风。","久住不知秋已老，却缘身在桂花丛。"]},{"t":"寄山中诸子","f":"七言律诗","c":["山缘渐密世缘疏，敢望良朋远寄书。","地僻不知曾有雁，水清宁复叹无鱼。","梦回冷榻闻钟后，僧老空林落叶初。","一盏孤灯伴禅定，岂知人世有乘除。"]},{"t":"九日与丹霞诸子登海螺峰绝顶，同赋用咸韵","f":"七言律诗","c":["共携短策与长镵，采得茱萸手自缄。","山路细通多宝塔，秋风先到七斤衫。","蝉声断续吟红叶，鹤语差池下碧杉。","岁岁重阳得如此，终身不拟别螺岩。"]},{"t":"秋夜","f":"七言律诗","c":["叶落天空月印江，牧牛人自守枯桩。","蜗涎带壳粘墙壁，虫臂随声触纸窗。","静坐不知山雨过，徐行直到寺钟撞。","置身物外原无物，形影何须觅一双。"]},{"t":"早起","f":"七言律诗","c":["寂寂空林睡起时，竹窗灯火影离离。","非关露冷披衣早，多是山高见日迟。","种药岂为衰病计，采芝曾与老僧期。","朝来策杖入云去，猿鹤相逢知我谁。"]},{"t":"招隐","f":"七言律诗","c":["难将礼数律疏慵，自是知音不易逢。","拟结茅庵居绝顶，别寻山路上孤峰。","心兼世远来千里，目与天游去万重。","笑抚长松劝招隐，未应回首忆秦封。"]},{"t":"螺峰晚望","f":"七言律诗","c":["岫云高去雁低飞，竹杖扶身上翠微。","带露摘茶香湿袖，入林收栗棘牵衣。","经旬鸟道生苔藓，昨夜螺岩老蕨薇。","独立孤峰人不见，一声吹角老僧归。"]},{"t":"写影","f":"七言律诗","c":["拟写閒身入画图，明明幻我即真予。","清霜点鬓三分白，老树兼藤一半枯。","云外独归梅女送，花边缓步竹孙扶。","山中不减人间乐，借问僧繇貌得无。"]},{"t":"舟发仁阳","f":"七言律诗","c":["身老偏惊物候新，买山多恐失佳邻。","寻僧记得扶溪约，移棹初逢锦水春。","极目逝川悲泛梗，隔江残雪见垂纶。","相逢相问还相笑，笑我无成学隐沦。"]},{"t":"雪麓梅花西乾山同赋","f":"七言律诗","c":["十里闻香到此间，花时留客不知还。","飘残六出见五出，开遍南山又北山。","满地月明春梦短，半空云影道心閒。","何须皓首伤迟暮，雪麓重来共掩关。"]},{"t":"仙牛岭作","f":"七言律诗","c":["为访仙牛不计程，千峰迢递入峥嵘。","望穷树色见山色，行遍水声闻鸟声。","猿鹤多情留客住，烟霞无主有谁争。","老人正是休心日，屋角閒田瘦亦耕。"]},{"t":"青龙山作","f":"七言律诗","c":["合取千峰作一园，竹边茅屋半开门。","雪晴冻壑留云影，花落閒阶见屐痕。","冷榻梦回三丈日，春田忙杀数家村。","不嫌老㹀无筋力，相伴耕犁敢惮烦。"]},{"t":"泥湖山赠石珍师","f":"七言律诗","c":["但得心空境即空，此生甘作住山翁。","种桃临涧防流水，放鹤排云信远风。","辟谷有时煨芋米，卓锥无地结茅篷。","孤峰独宿寻常事，百鸟何须识懒融。"]},{"t":"登青龙绝顶有怀罗浮","f":"七言律诗","c":["往往凭高忆洞天，朱明回首隔苍烟。","山连楚越人为险，水注东南地转偏。","云外拾菰喧稚子，溪囗囗药笑顽仙。","道人别有生涯在，借地开池自种莲。"]},{"t":"山中即事","f":"七言律诗","c":["读易才通遁五爻，兴来观物出林坳。","断槎过雨蒸成菌，矮屋依藤合作巢。","十里水云无路入，半空钟磬有人敲。","旧游回首天壤甚，不用驰书报绝交。"]},{"t":"蒲竹山阻雨赠方照静主","f":"七言律诗","c":["蒲竹山中昼掩扉，苔痕青染薜萝衣。","浮云蔽日人将老，宿雨连天客未归。","久懒不堪耕稼苦，忘机还笑灌园非。","从师乞取三条篾，结束閒身住翠微。"]},{"t":"雨中宿香山寺与僧话旧","f":"七言律诗","c":["浪游忘却路行艰，百里归程十日还。","白石乍迷云外岭，丹霞遥失雨中山。","孤峰暝色留僧话，满院春风解客颜。","回忆旧游半城市，不知能有几人閒。"]},{"t":"送孙禹尚还京","f":"七言律诗","c":["桃花零落滞河阳，玉树联翩返帝乡。","卫玠丰仪年独富，苏门清啸韵偏长。","因逢北阮思南阮，更藉元方识季方。","怅别溪桥无可赠，片云孤鹤自相将。"]},{"t":"送罗山甫入京","f":"七言律诗","c":["锦江流水接通津，野老长歌送远人。","古道论交君仅见，新诗盈箧客非贫。","登临记得曾游路，匡济偏宜未老身。","挥手不须怅离别，重来应及岭头春。"]},{"t":"赠万欲曙","f":"七言律诗","c":["一辞城市动经年，世外逢人不偶然。","丛桂久无招隐客，绿萝今有住山缘。","孤峰垦出栽花地，宝剑酬将买石钱。","我欲似君难得似，春来惟少种芝田。"]},{"t":"宿寒梅寺","f":"七言律诗","c":["大笑下山寻古寺，半岩明月且盘桓。","人声渐远滩声近，上界全空下界宽。","石榻无尘留客住，蒲团有脚寄人难。","长江此去无多路，应许重来共岁寒。"]},{"t":"宿水南梁茂才斋中","f":"七言律诗","c":["秋光满眼菊花同，暂息閒身落叶中。","野寺散镜窥枕月，江城吹角振衣风。","世途渐老三分厌，山气冲寒一半空。","劳动居亭问飘泊，片云西去水流东。"]},{"t":"谢马校尉国祥有施","f":"七言律诗","c":["老来空负住山心，日暮凭谁溉釜鬵。","借得好风生幕府，送将孤鹤入云林。","交情恰似青萍合，愿力还兼紫水深。","从此伏波坛上月，清光长照伯牙琴。"]},{"t":"赠锦岩主人","f":"七言律诗","c":["云岩石榻迥无尘，野客初来见主宾。","锦石日高长至后，寒梅花发小阳春。","住山难到能閒地，学道偏宜未老身。","看取赵州行脚日，相期容有百年人。"]},{"t":"寓锦石岩寄丹霞诸子 其一","f":"七言律诗","c":["太上忘情愧未能，下山还忆住山僧。","写将一句无生话，寄向三岩最上层。","孤影自应怜夜月，馀光不用借邻灯。","凭君细问匡庐路，取次春风兴可乘。"]},{"t":"寓锦石岩寄丹霞诸子 其二","f":"七言律诗","c":["一度移居一度新，寒梅花发锦岩春。","却缘久住成欣厌，不敢重来问主宾。","云水与君同浪迹，虚空嫌我著纤尘。","近来学得安身法，只对青山不见人。"]},{"t":"寓锦石岩寄丹霞诸子 其三","f":"七言律诗","c":["衲僧随地足生涯，粥后蒿汤饭后茶。","临老有缘依锦石，连宵无梦到丹霞。","猕猴挂处曾栖鹤，鶗鴂声中见落花。","最是不堪更回首，冷风寒日竹交加。"]},{"t":"寓锦石岩寄丹霞诸子 其四","f":"七言律诗","c":["不堪随众且随缘，垂手何妨一入廛。","簦笠出逢车马客，钵盂分得俸薪钱。","滩声过耳滔滔逝，云影无心处处禅。","白发数茎非所惜，秪林秋晚独凄然。"]},{"t":"寓寒梅古寺，荅凌稚圭明经见寄来韵","f":"七言律诗","c":["古寺閒田未尽荒，寒梅冲雪透春光。","僧眠冷榻能无梦，鸟啄岩花却有粮。","密约久迟莲社炳，奇书曾借漆园庄。","何时过我东林下，共爇松灯读让王。"]},{"t":"锦石新晴望远有感","f":"七言律诗","c":["浓阴开处见微阳，病骨支离倚石床。","松老受风涛韵减，竹疏承瀑雨声长。","身随朔雁同为客，心似南针尽指乡。","极目山川如传舍，行云流水两茫茫。"]},{"t":"寓锦石寒梅寺，有怀罗戒轩、胡大灵","f":"七言律诗","c":["珠林绀宇信无缘，石室移居又一年。","破衲拥床钟板后，残书堆阁药炉边。","入山岂有红尘路，驻世应无白发仙。","待子不来身渐老，寒梅花下独栖禅。"]},{"t":"挽李?霁先辈 其一","f":"七言律诗","c":["识得斯人玄又玄，真儒驻世是真仙。","文章不落空王后，性命全归象帝先。","穗帐衣冠如昨日，鼎湖弓剑忆当年。","青山一觉希夷梦，更拟骑箕觐九天。"]},{"t":"挽李?霁先辈 其二","f":"七言律诗","c":["一入金门便隐沦，曲江回首见垂纶。","沧桑阅尽人间世，岁月销磨物外春。","丹诀有灵龙蜕骨，碧天无际鹤翻身。","浮生日促仍多病，拟拾遗薪逐后尘。"]},{"t":"挽李?霁先辈 其三","f":"七言律诗","c":["曾借名园受一经，频来犹记旧池亭。","为僧不敢通年谱，隔世还思见典型。","风树几回悲坠叶，摄提初转散晨星。","老成凋谢今如此，一曲长歌问渺冥。"]},{"t":"还山答人","f":"七言律诗","c":["拚此馀生住翠微，重来多与夙心违。","出逢亲友休相讶，暂到家园不当归。","霜缀帽檐惊岁暮，雪深门巷过人稀。","萍踪恰似云边雁，才见南飞又北飞。"]},{"t":"寓双照庵除夕与笑溪师同赋","f":"七言律诗","c":["三更残腊五更春，当局旁观总一身。","半榻平分宾主地，孤灯双照往来人。","修成白业家全富，买得青山道不贫。","何事天津桥上客，水边烧纸送穷神。"]},{"t":"元日漫兴用前韵","f":"七言律诗","c":["纵然有历不知春，是处堪容懒惰身。","饥馑田园丰稔食，乱离时节太平人。","鸠巢旧树因藏拙，鸟下生台未厌贫。","岁序任迁僧任老，头颅添雪倍精神。"]},{"t":"题种槐堂壁","f":"七言律诗","c":["久别重来未厌频，旧游无那鬓毛新。","紫峰当面成生客，银榜留题识贵人。","移树近庭存手泽，种槐垂荫识芳邻。","孟家学士如相过，应卸峨冠换角巾。"]},{"t":"初归东林过容尘轩分赋","f":"七言律诗","c":["锦水潮生挂席回，春城处处百花开。","柳营细雨酣诗战，铃阁清风递茗杯。","渐老不堪成久别，此身难得去还来。","主人爱客容疏放，莫怪频频谒上台。"]},{"t":"和社中诸子","f":"七言律诗","c":["何堪白发入红尘，一往蹉跎六十春。","空谷去寻耕凿伴，东林无复荅歌人。","故山梦断霜钟冷，好友书来丽句新。","未免有情非独我，相思同在锦江滨。"]},{"t":"寒螀","f":"七言律诗","c":["声声清切似悲秋，半入虚堂半上楼。","人在定中常不寐，物从空外复何求。","百年草色身先老，一夕松灯话未休。","万虑此时消歇尽，西风吹过白蘋洲。"]},{"t":"寒塘","f":"七言律诗","c":["方池近接礼经堂，风递寒光上小廊。","霜树坠红低蘸碧，岸花摇影静浮香。","鱼吹细沬冰将合，月印澄潭夜正长。","惆怅伊人何处所，蒹葭回首已苍苍。"]},{"t":"残荷","f":"七言律诗","c":["涉江多与此心违，何事兰桡未放归。","摇落可能甜鹤梦，寂寥宁负钓鱼矶。","浮云过去深深见，倾盖相逢处处稀。","小叠红笺寄秋雨，莫教滴破楚臣衣。"]},{"t":"赠林山人","f":"七言律诗","c":["每因梅鹤忆林逋，道骨仙风世不如。","石室启将丘索秘，金针传得越裳车。","青山到处开生面，黄石何年授异书。","炼就丹砂成九转，不如陵谷有乘除。"]},{"t":"寿春州杨明府封君","f":"七言律诗","c":["识得安阳捧檄心，趋庭乐事在鸣琴。","簿书不废晨昏节，菽水宁须暮夜金。","椿树八千开寿域，甘棠百里遍清阴。","朱明野老遥相忆，葛令丹砂更可寻。"]},{"t":"赠陈慊湖","f":"七言律诗","c":["老年经济盛年心，云水输君道力深。","白业去从莲幕办，青山归傍玉鞍吟。","仲弓有子堪娱老，元亮无弦自赏音。","暇日寻僧过桥去，东湖应不异东林。"]},{"t":"赠李石亭","f":"七言律诗","c":["宝安晴雪赋閒居，王谢风流迥不如。","玉匣锁将曾赐剑，牙签收得续藏书。","龙门容我高歌入，狮座留僧午饭初。","城市不妨饶野趣，片云孤鹤肯相于。"]},{"t":"赠李徵君","f":"七言律诗","c":["暮紫峰头别有春，百花开处接芳邻。","金鐏尽醉登龙客，世味宁消嚼蜡人。","竹杖看云容散诞，鬓毛添雪更精神。","愿君得似松间鹤，长伴閒僧作主宾。"]},{"t":"挽化城院觉阇黎","f":"七言律诗","c":["故山斜日迫桑榆，双树凋零鹤影孤。","物外老成同梦蝶，眼前人境半驱乌。","化城已入三禅定，大厦谁将一木扶。","夙愿未酬心未了，重来应记旧天湖。"]},{"t":"偕伍秋农游白云古刹","f":"七言律诗","c":["青山白发两相催，且伴宗雷访渡杯。","微雨乍过溪路湿，疏钟遥报洞门开。","暂辞城市人初到，久别家山客又来。","莫遣奚僮笑岑寂，诗囊携得岭云回。"]},{"t":"雨后观瀑送罗戒轩伍秋农还里","f":"七言律诗","c":["昨夜闻声今到来，三瞻四顾兴悠哉。","炎天忽下千山雪，晴日犹鸣万壑雷。","僧老行藏凭竹杖，道心浓淡寄茶杯。","无情最是云边瀑，流入人间不复回。"]},{"t":"寻黄帝铸鼎故处","f":"七言律诗","c":["咫尺卿云近鼎湖，寻思往事入虚无。","七星光接三台座，九转烟销八卦炉。","梦到华胥羞白发，归从赤水想玄珠。","顽金跃冶知多少，终古无人作范模。"]},{"t":"挽郑听轩 其一","f":"七言律诗","c":["高歌未阕泪先零，寄语听轩还自听。","老去二毛随我白，别来双眼为谁青。","风边烛影看生灭，酒后杯盘任醉醒。","前路茫茫同是客，不妨七日识居亭。"]},{"t":"挽郑听轩 其二","f":"七言律诗","c":["漫将呼吸辩存亡，一笑清风万古长。","野史近添高士传，里儿争识郑公乡。","心空止有愁肠在，身死犹闻侠骨香。","夙习破除除不尽，待君林下更商量。"]},{"t":"挽郑听轩 其三","f":"七言律诗","c":["浊河东去日西流，若个轻身占上游。","百里德星沉巨壑，一天明月载虚舟。","灯前叹逝空芸阁，泉下追欢有萼楼。","今日始知身是贵，醉乡不用觅封侯。"]},{"t":"挽郑听轩 其四","f":"七言律诗","c":["独宿孤峰起梦思，东林回首笑攒眉。","蹉跎前夏安居日，惆怅先生易箦时。","有骨犹堪逢伯乐，无弦宁禁忆钟期。","茂陵遗草休轻弃，付与床头七岁儿。"]},{"t":"送愚破师还匡庐同光省觐","f":"七言律诗","c":["同光雪色正齐腰，归去门庭未寂寥。","竹杖远寻庐岳寺，芒鞋重过虎溪桥。","生衣出匣搴云补，新笋开炉带箨烧。","想到故山多胜事，好将生计报东樵。"]},{"t":"送僧洞然参方","f":"七言律诗","c":["挥手红尘入翠微，相逢岐路两依依。","心存海岳难留住，家在湖山及早归。","霜锷磨成须什袭，箭锋留待出重围。","悬知冀北空群后，应笑驽骀未息机。"]},{"t":"定崖师住槐园赋赠","f":"七言律诗","c":["久客槐园未有诗，别来三径草离离。","赖君青眼重为挂，容我閒身再到时。","苦李不留当路实，新松须长拂云枝。","东林此去无多远，白犬驰书待寄谁。"]},{"t":"丁丑夏客墺门岛普济禅院赠剑平师","f":"七言律诗","c":["避暑真宜地轴偏，领将生计在林泉。","弟兄聚会惟今日，松竹阴森异昔年。","坐老青山添白发，吸乾沧海种红莲。","洛伽此去无多路，门外何须问钓船。"]},{"t":"寓普济禅院寄东林诸子","f":"七言律诗","c":["但得安居便死心，写将人物报东林。","番童久住谙华语，婴母初来学鴂音。","两岸山光涵海镜，六时钟韵杂风琴。","祇愁开禁年年密，未得閒身纵步吟。"]},{"t":"三巴寺","f":"七言律诗","c":["暂到殊方物色新，短衣长帔称文身。","相逢十字街头客，尽是三巴寺里人。","箬叶编成夸皂盖，槛舆乘出比朱轮。","年来吾道荒凉甚，翻羡侏离礼拜频。"]},{"t":"望海楼","f":"七言律诗","c":["高踞层楼瞰十洲，江山如画半沉浮。","岛夷计日迟青雀，海客临风盟白鸥。","帆到虎头皆北向，水归鳌背尽东流。","鲁连去后无消息，莫惜频频上此楼。"]},{"t":"青洲岛","f":"七言律诗","c":["突兀中流乱石隈，青洲咫尺拟蓬莱。","潮头撼岸晴还雨，屋角惊涛昼起雷。","猘犬吠花人迹断，饥鸢占树鸟声哀。","凭谁为语冯夷道，还与华亭作钓台。"]},{"t":"海镜石","f":"七言律诗","c":["昨夜扁舟宿海环，晓寻片石照衰颜。","孤蓬推出云中月，短棹移来鉴里山。","已判身心归物外，不留形影在人间。","一回相见一回老，共惜浮生未易顽。"]},{"t":"岛门秋雨与诸子同赋 其一","f":"七言律诗","c":["九夏安居为避喧，閒身到处是桃源。","秋声带雨摇幡影，野水浮阶没藓痕。","茶灶昨除桑柘火，蒲团长寄水云村。","明朝蓑笠还山去，何事风霜不闭门。"]},{"t":"岛门秋雨与诸子同赋 其二","f":"七言律诗","c":["海气连天日色昏，殊方羁客倍销魂。","新风坠叶填金井，宿雨兼云暗岛门。","稚子捲帘看石燕，估胡归舶避江豚。","故山一望堪惆怅，法社垂秋未忍论。"]},{"t":"赠华严院主","f":"七言律诗","c":["白莲开日往来频，谁识支公定力真。","长与烟霞为地主，不妨城市有閒人。","僧来借榻过三夏，客至停车动几旬。","峡路风波山路险，问师何以出嚣尘。"]},{"t":"赠天宁院主","f":"七言律诗","c":["门临古道塔凌空，山色西来水向东。","钟鼓不殊云顶寺，轮蹄争辏梵王宫。","禅心静印千江月，殿角凉生八面风。","花下留僧饱斋去，芒鞋无地避残红。"]},{"t":"刘明府仰山作宰行唐以外艰归里奉命焚黄赋此以赠","f":"七言律诗","c":["寒食东风郭外烟，仙郎归去罢鸣弦。","三梁素冕辞双阙，五色黄麻下九天。","读礼更吹藜杖火，诵诗曾废蓼莪篇。","官閒亦爱僧閒否，应过东林续旧缘。"]},{"t":"登写心亭怀马郡守","f":"七言律诗","c":["韶阳城外曲江边，独上皋亭思渺然。","入座奇峰铦似笔，当门周道直如弦。","琴鐏复古希前哲，堂构重新仰昔贤。","几树棠梨花落尽，西风吹冷半池莲。"]},{"t":"过碧山精舍赠印千师","f":"七言律诗","c":["碧山深处锁烟霞，近筑层台礼法华。","隙地遍栽黄阁老，清池多种白莲花。","凭高望远疑无地，入谷逢僧便当家。","静埽溪边坐禅石，与师谈到月光斜。"]},{"t":"佛桑花","f":"七言律诗","c":["篱落秋光静者知，槿花常早菊花迟。","灵山半写娑罗影，旸谷平分若木枝。","色相寂寥僧定后，繁华消歇日斜时。","何堪荣落伤朝暮，一笑相逢两不疑。"]},{"t":"落叶","f":"七言律诗","c":["秋声一夜过林西，旧绿新黄响未齐。","共是飘零难久住，何妨憔悴托卑栖。","归除白石迟明月，收拾红笺付小奚。","满地榆钱贫更甚，不堪持赠为儿啼。"]},{"t":"观刘东溪所藏吴虎泉晚槐栖鸦图","f":"七言律诗","c":["故人相失在京华，手泽犹存茂宰家。","宿草久荒迟挂剑，墨槐空见晚归鸦。","披图想像身前影，绝笔虚无梦后花。","惆怅旅魂招不得，旧游零落各天涯。"]},{"t":"送徐铎愚归五羊兼柬城中诸子时值宾兴","f":"七言律诗","c":["东书还问锦江津，霜入枫林叶叶新。","秋草渡头归病客，槐花时节送閒人。","儿童颇怪诗囊重，造物多嫌古道真。","寄语郡城车盖地，不知谁念马卿贫。"]},{"t":"荅崆峒主人张顽石招隐诗","f":"七言律诗","c":["劳君招隐寄诗筒，款款开缄拜好风。","老我独迟篱菊节，怀人长在桂花丛。","望遥云水心先往，梦入烟霞世亦空。","问道有期应不远，广成今已在崆峒。"]},{"t":"霍西牛归自春州除夕过寓见赠用韵赋答因寄崆峒主人","f":"七言律诗","c":["一别红尘便不如，出门往往避轩车。","故山未返春先入，老景无多岁又除。","鹿性似嫌莎草短，莺声无柰柳条疏。","凭君报语崆峒主，愿借岩西小结庐。"]},{"t":"病鹤诗寄社中诸子","f":"七言律诗","c":["谩道仙禽能住世，一春长与病相依。","卧残白日消朱顶，梦断红尘拥毳衣。","瘦骨正宜烟火绝，轻身宁羡稻梁肥。","凭谁解赠青田价，放出凌空一一飞。"]},{"t":"寄题隐泉新院","f":"七言律诗","c":["相闻结社锦江涯，七字长成自建牙。","款段远绳新息武，芭经重起隐泉家。","敲推静倚三珠树，鼓吹遥闻两部蛙。","稍待瘦权筋力健，与君吟到日西斜。"]},{"t":"咏隐泉新院并蒂莲花","f":"七言律诗","c":["玉井连枝出锦江，盍簪炎土即仙邦。","芙蓉并跃呈霜锷，蝴蝶交飞近绮窗。","倾盖联翩珠靸履，重乔掩映碧油幢。","麻姑总角今何在，青冢空留鹤一双。"]},{"t":"寄马卧仙","f":"七言律诗","c":["閒从世外识人豪，最喜先生道眼高。","花甲输君加四齿，冰霜欺我上三毛。","虚堂下榻迟留带，破衲生寒待赠袍。","愿借南薰消伏暑，抱琴应许过林皋。"]},{"t":"病中荅丘坡三见寄来韵","f":"七言律诗","c":["诗情病态转相因，贾瘦郊寒且自亲。","老去烟霞成痼疾，閒来风雨伴吟身。","药炉多累书辞架，蜡屐无声径积尘。","赖有东皋丘处士，新篇还许寄山邻。"]},{"t":"病中放言 其一","f":"七言律诗","c":["廿年曾记住朱明，饱食丹砂道未成。","暂到此间修白业，更无馀力种黄精。","烟霞久别休心住，药石应难与化争。","不见苧萝溪畔女，颦眉捧腹更倾城。"]},{"t":"病中放言 其二","f":"七言律诗","c":["频年多难逢寒食，怅望家山又一春。","青草久荒攀柏地，黄梅深愧种松人。","哀猿啼树将圆月，饥鸟眠花动隔旬。","辜负清明好时节，梦中犹忆蕨薇新。"]},{"t":"病中放言 其三","f":"七言律诗","c":["老来深悔不耕田，日暮方思嗣昔缘。","瓶底量留三日粟，枕边书破八行笺。","芰荷露重倾犹惜，榆荚风多落更偏。","赖有市南弄丸子，黄河挹住到西乾。"]},{"t":"病中放言 其四","f":"七言律诗","c":["三尺胡床七尺躯，横身无计笑区区。","清谈我不如夷甫，嫚骂谁能恕灌夫。","紫陌追风鸣叱拨，华堂秉烛醉屠苏。","茂陵多病曾知否，日夕吟呻独向隅。"]},{"t":"病中放言 其五","f":"七言律诗","c":["馀生何幸绝逢迎，任是沉疴也称情。","近识化人家裸国，新开别业远愁城。","穷来渐觉贫交少，病后犹夸瘦骨轻。","何事北窗眠不稳，枕边闻卖荔枝声。"]},{"t":"病中放言 其六","f":"七言律诗","c":["木绵花落刺桐乾，梅子添黄荔减酸。","拥被不知时节过，锁窗犹畏暑风寒。","滞霖十日如桑扈，尘甑经旬笑范丹。","多谢旧游枉车骑，相逢重叠劝加餐。"]},{"t":"病中放言 其七","f":"七言律诗","c":["夜行宁免泣途穷，自笑逢时术未工。","词赋何能消肺渴，文章终不愈头风。","芭蕉叶底偏多雨，芦苇花边任转蓬。","虫臂鼠肝吾岂惜，知音惟有信天翁。"]},{"t":"病中放言 其八","f":"七言律诗","c":["一息浮生一寸阴，閒观物理静披襟。","案头蜾蠃鸣筠管，壁上蟏蛸挂玉琴。","逝者如斯良有以，道人那得更无心。","朝来成就吉安法，始信嚬呻即咏吟。"]},{"t":"病中放言 其九","f":"七言律诗","c":["漫学招魂续楚些，出门须唱太平歌。","却嫌升屋三呼晚，转觉登堂七发多。","薤露未晞春睡足，草虫无那夜吟何。","浮生穿凿休相管，云散长空月在波。"]},{"t":"病中放言 其十","f":"七言律诗","c":["夙习难忘自不知，床头遗草有新诗。","尻神浸假为轮马，肘臂郎当见柳枝。","留骨岂堪逢伯乐，葬身何必迩要离。","昆冈玉石同灰烬，不是铅刀跃冶时。"]},{"t":"赋得山意冲寒欲放梅","f":"七言律诗","c":["空谷萧萧自主宾，南枝跃跃老风尘。","飘残六出见五出，过尽小春还早春。","白首半生归寂寞，青山一气露精神。","何堪花事从头说，月落参横未有人。"]},{"t":"冬夜友人过寓话旧分赋","f":"七言律诗","c":["浮生作客难留客，老病思归未即归。","何事故人来雪舫，乍惊邻犬吠柴扉。","情真味澹空葵藿，地僻山寒少蕨薇。","寂寞閒心随处写，夜来相对一灯微。"]},{"t":"答西粤冯作鹏来韵","f":"七言律诗","c":["壮游衰病各离居，旧约寻思一半虚。","去国声名夸肸蚃，入山滋味类泔鱼。","槐花閒却三秋半，菊蕊忙于九月初。","我未心空君未第，相思莫讶梦来疏。"]},{"t":"渔灯","f":"七言律诗","c":["光生浦溆夜潮平，江上推蓬远思盈。","两岸波光重叠见，一天星月浅深明。","分将松火炊菰米，移转银缸近酒盛。","翻羡浮家能继晷，漫穿邻壁笑匡衡。"]},{"t":"和黎广文过东林作","f":"七言律诗","c":["一别东林动隔年，茅堂岑寂闭荒烟。","壁间剩有琅玕字，物外难忘木石禅。","吟到天花遥入磬，思深春雨细通泉。","近来风雅凋零甚，愿与先生结此缘。"]},{"t":"还东林萧志三见赠用韵赋答 其一","f":"七言律诗","c":["烟波回首人微茫，归路何如归兴长。","两地云山无主客，半年风日各炎凉。","方池旧闻花添影，圆牖重开月借光。","莫笑别来贫更甚，榆钱将䞋遍斋堂。"]},{"t":"还东林萧志三见赠用韵赋答 其二","f":"七言律诗","c":["何事行藏偏落后，却缘筋力不如前。","虚堂久别从生草，旧社重开又种莲。","爱石谱将云里岫，引泉流出水中天。","老来识得荣公乐，只买青山不买田。"]},{"t":"雨中答双桂洞天公见寄兼柬同门兄弟 其一","f":"七言律诗","c":["浮阶春水漫苔衣，滞雨连旬不启扉。","桂洞老人劳见讯，华林穷子未曾归。","琴高岂用全抄谱，棋罢还当更息机。","闻说弟兄多胜事，悬知权教入深微。"]},{"t":"雨中答双桂洞天公见寄兼柬同门兄弟 其二","f":"七言律诗","c":["耿耿难忘为阿谁，却防一息不相知。","雪霜到处欺双鬓，粥饭今年减半匙。","月出便寻高枕地，日斜不是苦吟时。","吾家赖有真龙象，为报云门道未衰。"]},{"t":"寓鼎湖李天章过访拉游飞水潭试茗分赋因寄信安冯尔公广文","f":"七言律诗","c":["榕堂旧别忆何年，忽漫相逢古寺边。","白首不堪同草木，青云还许到林泉。","茶香静发烟霞气，诗句平分水石缘。","为报郡斋冯外史，隔江招手有枯禅。"]},{"t":"送伍秋农下山","f":"七言律诗","c":["微云疏雨入天湖，野客追陪兴不孤。","岂有风雷迷大麓，漫随龙象礼浮图。","莲花开日难为别，丛桂前期记得无。","我且暂留君暂去，可堪离合在须臾。"]},{"t":"博山剖公入天湖见赠用韵送行","f":"七言律诗","c":["芒鞋踏破岭头云，水石留题字字新。","遂有文殊来过夏，始知无著是家人。","天花夜静侵衣满，山雨朝晴振锡频。","别后孤峰翘首处，长空圆月俨师真。"]},{"t":"游飞水潭与诸子同赋限韵 其一","f":"七言律诗","c":["病躯未去心先去，筋力无加却有加。","七尺乌藤伴形影，一条白练入烟霞。","灵湫镇日倾盆雨，顽石当阳散宝花。","莫道银河隔尘世，迷津何处不通槎。"]},{"t":"游飞水潭与诸子同赋限韵 其二","f":"七言律诗","c":["山色溪声无远近，林光潭影互交加。","密云触石成疏雨，孤鹭迎风散落霞。","坐久三衣疑浣雪，凭高双眼易生花。","青猿也羡临渊乐，隔水呼儿上断槎。"]},{"t":"送僧还里省母","f":"七言律诗","c":["无成底事未閒身，回首门闾有老亲。","世外彩衣犹恋母，道傍青眼未逢人。","满船明月家将近，两袖清风客不贫。","归去北堂何所献，衣珠擎出是家珍。"]},{"t":"送黎大年入西宁","f":"七言律诗","c":["结束琴书怅索居，泷江西去欲何如。","方将京雒三陈策，且向河阳一曳裾。","九月水边逢旅雁，六都沙别见嘉鱼。","临邛买酒堪留醉，莫漫狂歌学接舆。"]},{"t":"采石矶怀古","f":"七言律诗","c":["维舟采石月华新，一曲狂歌吊逐臣。","仙籍骑鲸如昨夜，醉乡梦蝶已千春。","投荒未必关仪狄，玩世何须避永璘。","自古文章憎命达，汨罗还有独醒人。"]},{"t":"鹅潭渔父 其一","f":"七言律诗","c":["石门斜日柳波烟，钓得槎头缩项鳊。","小港溪桥沽酒去，大通渔火枕蓑眠。","山腰系带朝收网，水面生皴夜缆船。","羡尔浮家识风雨，自伤留滞一年年。"]},{"t":"鹅潭渔父 其二","f":"七言律诗","c":["通津津口钓鱼还，十里澄潭两岸山。","风便送归杨柳渡，月明留醉荔枝湾。","沧桑阅尽须眉古，波浪经多梦寐閒。","閒对白鹅搔白发，与君同寄水云间。"]},{"t":"鹅潭渔父 其三","f":"七言律诗","c":["沙角潮平地轴宽，多君浪迹胜严滩。","鹅潭倒影涵山郭，鸥侣将雏近钓竿。","烟雨南来云漠漠，牂牁东注水漫漫。","画船尽载沉香去，閒与儿孙倚棹看。"]},{"t":"泛珠江望白云山 其一","f":"七言律诗","c":["扁舟独渡珠江水，野客登临耳目宽。","绀殿钟声移棹听，白云山色隔城看。","遐心指点峰千叠，生计商量钓一竿。","今夜月明何处宿，梦魂应绕郑仙坛。"]},{"t":"泛珠江望白云山 其二","f":"七言律诗","c":["早潮暮潮时往还，大浪小浪波涛间。","一声呕哑涉江棹，十里涳濛回首山。","水寺无人僧定稳，仙岩有路鹤飞閒。","菖蒲花发便须去，居此不难凋玉颜。"]},{"t":"早春望燕","f":"七言律诗","c":["东风初拂柳花飞，旧垒新梁几夕晖。","白玉横钗留影住，乌衣深巷见人稀。","掌中妙舞何时入，塞外风尘及早归。","社日尚遥频怅望，别来红缕是邪非。"]},{"t":"赠僧","f":"七言律诗","c":["偶来城市得良朋，千佛楼中一个僧。","保福不须还拨草，汤休今已继传灯。","三生旧社高歌入，万仞孤峰信步登。","从此吾宗有文字，倩人书壁笑南能。"]},{"t":"题亦稼堂赠梁广生","f":"七言律诗","c":["人稼青苗汝稼书，三冬争似富三馀。","不随袯襫驱黄犊，宁向缣缃学蠹鱼。","东阁弦壶追洛诵，西畴蓑笠笑长沮。","何须更凿邻家壁，曾见藜灯照石渠。"]},{"t":"初晤杨式公","f":"七言律诗","c":["信道诗轻万户候，识君犹胜识荆州。","谈锋似剑双龙合，心细如丝独茧抽。","湖海多情容散诞，市朝无骨莫淹留。","相寻话到忘言处，野鹤归飞月满楼。"]},{"t":"答杨式公","f":"七言律诗","c":["红尘紫陌偶相期，蹑屐登龙快所思。","山径有云归路晚，市门斜日下楼迟。","漫劳轩盖遥相问，暂寄茅堂只在兹。","他日幽栖还有计，千峰平处一峰奇。"]},{"t":"蔡箕衍孝廉偕诸公过访分赋","f":"七言律诗","c":["病是权称懒是真，闭门风叶积成旬。","漫劳上国看花客，来问空山卧雪人。","别鹤传将流水操，饭牛分得建溪春。","殷勤净埽三生石，待与宗雷辨主宾。"]},{"t":"拟补春夜宴桃李园诗 其一","f":"七言律诗","c":["园林烟景快相亲，兄弟招欢自主宾。","银烛金樽长夜饮，夭桃秾李一家春。","盛年共惜同为客，明月从来不待人。","回首二毛搔渐短，不应辜负接䍦巾。"]},{"t":"拟补春夜宴桃李园诗 其二","f":"七言律诗","c":["群季追欢兴不孤，芳园娇鸟唤提壶。","名花自种还同赏，家酝新篘不待沽。","素魄影边添蜡烛，绿茵深处布氍毹。","可能后会频相觅，长愿高阳作酒徒。"]},{"t":"题英鸡黎国所画园林图","f":"七言律诗","c":["尺幅云林幻也真，无端闻见一番新。","丹青不是支那笔，花木还同震旦春。","弱水东流终到海，越裳南去即通津。","年来颇有居夷愿，莫怪披图数问人。"]},{"t":"与刘念兹","f":"七言律诗","c":["惺惺唤起主人公，万念消归一念中。","月影不随波影散，钟声寻与鼓声通。","世知有我山还浅，静到无人市亦空。","一路桃花带流水，刘郎何处不相逢。"]},{"t":"冯作鹏归自桂林过宿话旧分赋得窗字","f":"七言律诗","c":["何时书剑别西江，竹院寻僧兴未降。","得与旧游重款款，快闻新论一桩桩。","诗兼虫语吟幽砌，梦逐鸡声出破窗。","明发不堪怅离别，重来应讶碧油幢。"]},{"t":"留别亦庵","f":"七言律诗","c":["三年衰病借閒房，冷局无端作笑场。","迟我别峰凭地主，还他华屋与空王。","蟪蛄聒耳山犹浅，鶗鴂伤心草不芳。","多谢门前生耳树，重来应恐是迷阳。"]},{"t":"移居梅园","f":"七言律诗","c":["明知熟境最难忘，借得园林当宝坊。","长揖红尘归白社，暗移圆月入方塘。","鹿门旧识庞居士，兔径重游孟八郎。","荆棘满园须护笋，老来高节看谁长。"]},{"t":"移居示诸子","f":"七言律诗","c":["蛙声分部各开堂，自大何须不夜郎。","顽石座边挥玉麈，古梅花下布绳床。","闭门已得偷閒计，入世真难买笑方。","高挂钵盂待甘贽，休心还拟更休粮。"]},{"t":"挽刘东溪明府","f":"七言律诗","c":["六月飞霜天不知，贞魂浩气忽骑箕。","哀歌自挽陶彭泽，直道难容柳士师。","入社久虚三笑约，怀人空赋四愁诗。","东林寂寞吟庐闭，无复分题接席时。"]},{"t":"移居梅园答庞静庵来韵 其一","f":"七言律诗","c":["入林多恐负初心，一别名园遂至今。","地迥江山由我借，天空云月不相侵。","梅花老去偏宜雪，菊蕊秋来渐有金。","何幸鹿门能爱客，肯分乔木托幽禽。"]},{"t":"移居梅园答庞静庵来韵 其二","f":"七言律诗","c":["浪迹萍踪两不知，自来自去自寻思。","天能解语凭谁问，佛本无心是我师。","何用枯禅同木石，有时冷笑立阶墀。","吟诗报语陶彭泽，日暮篮舆过莫迟。"]},{"t":"移居梅园答庞静庵来韵 其三","f":"七言律诗","c":["偶因北院依南院，新辟梅园近竹园。","多谢居亭旁借径，试穿邻壁别开门。","云霞推里疑无地，鸡犬声中别有村。","但使榻边容鼾睡，置身何异古桃源。"]},{"t":"送黄鸣瑴宰梓潼","f":"七言律诗","c":["雄才岂合老征尘，暂借儒官作远臣。","但使文翁能化俗，应知蜀道即通津。","风云有命宁辞晚，琴鹤随身不厌贫。","我去入山君作宦，相逢那得下车人。"]},{"t":"初住大通寄华林法属","f":"七言律诗","c":["偶寻江介宿荒庵，回首城中见盍簪。","烟雨有时迷穗石，风波无路阻鹅潭。","木鸡老去慵司晓，白雁秋来早向南。","家在华林归未得，欲酬恩遇愧同参。"]},{"t":"寄城中诸友","f":"七言律诗","c":["淹留古寺爽归期，延伫江干寄所思。","野鹤高飞浑不住，沙鸥閒立静偏宜。","城中明月遥相见，海上孤云去独迟。","有约不来君莫讶，此心无异住山时。"]}]};